def _dblock_require_exact_int(value, label, *, minimum=None, maximum=None):
    """Require a JSON integer exactly; bool/float/string coercion is forbidden."""
    if type(value) is not int:
        raise ValueError(f"{label} must be an exact non-boolean JSON integer")
    if minimum is not None and value < int(minimum):
        raise ValueError(f"{label}={value} is below minimum {int(minimum)}")
    if maximum is not None and value > int(maximum):
        raise ValueError(f"{label}={value} exceeds maximum {int(maximum)}")
    return value


def _dblock_require_exact_int_list(value, label, length, *, minimum=0, maximum=None):
    if not isinstance(value, list) or len(value) != int(length):
        raise ValueError(f"{label} must be a length-{int(length)} list")
    return [
        _dblock_require_exact_int(
            item, f"{label}[{index}]", minimum=minimum, maximum=maximum
        )
        for index, item in enumerate(value)
    ]


def _dblock_require_finite_number(value, label, *, allow_none=False,
                                  minimum=None, strictly_positive=False):
    if value is None and allow_none:
        return None
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{label} must be a finite non-boolean JSON number")
    number = float(value)
    if not math.isfinite(number):
        raise ValueError(f"{label} must be finite")
    if strictly_positive and number <= 0.0:
        raise ValueError(f"{label} must be positive")
    if minimum is not None and number < float(minimum):
        raise ValueError(f"{label}={number} is below minimum {float(minimum)}")
    return number


def _dblock_validate_objective_float_map(value, label, B, *, scalar=False,
                                         strictly_positive=False):
    if not isinstance(value, dict) or not set(value).issubset({"ar", "sat", "nat"}):
        raise ValueError(f"{label} must contain only ar/sat/nat families")
    normalized = {}
    for family, raw in value.items():
        if scalar:
            normalized[family] = _dblock_require_finite_number(
                raw, f"{label}.{family}", strictly_positive=strictly_positive
            )
            continue
        if not isinstance(raw, list) or len(raw) != int(B):
            raise ValueError(f"{label}.{family} must be a length-{int(B)} list")
        normalized[family] = [
            _dblock_require_finite_number(
                item, f"{label}.{family}[{index}]", allow_none=True,
                minimum=0.0, strictly_positive=strictly_positive,
            )
            for index, item in enumerate(raw)
        ]
    return normalized


def _dblock_validate_counter_map(value, label, required_keys, *, maximum=None):
    required_keys = set(required_keys)
    if not isinstance(value, dict) or set(value) != required_keys:
        raise ValueError(
            f"{label} must contain exactly {sorted(required_keys)}"
        )
    return {
        key: _dblock_require_exact_int(
            value[key], f"{label}.{key}", minimum=0, maximum=maximum
        )
        for key in sorted(required_keys)
    }


def _dblock_validate_counter_list_map(value, label, required_keys, B, *,
                                      maximum=None):
    required_keys = set(required_keys)
    if not isinstance(value, dict) or set(value) != required_keys:
        raise ValueError(
            f"{label} must contain exactly {sorted(required_keys)}"
        )
    return {
        key: _dblock_require_exact_int_list(
            value[key], f"{label}.{key}", B, minimum=0, maximum=maximum
        )
        for key in sorted(required_keys)
    }


def _dblock_json_copy(value):
    """Return a finite, JSON-only copy suitable for checkpoint metadata."""
    raw = json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False)
    return json.loads(raw)


def _dblock_target_route_policy(args):
    return str(getattr(args, "dblock_target_route_policy", "legacy") or "legacy").lower()


_AGILLM44_REPO_DIRECT56_PARENT_RUNTIME_SHA256 = (
    "714ee71c440ba9e9699034d7ea5f1de6f73d65cc80caf9f9350cf30f11a33e28"
)
_AGILLM44_REPO_DIRECT56_CORE_SOURCE_SHA256 = (
    "1fa7dd08ed7cb8030361af6e740306012b3b1916563f7be8e41735a42363f49d"
)
_AGILLM44_REPO_DIRECT56_INTEGRATION_SOURCE_SHA256 = (
    "dad8ee8520c10203de2ad75fd0ce55f5568768ca880f490034b8b7fd4ca02292"
)


def _dblock_target_route_controller_source_sha256():
    """Return reviewed Direct56 identity across a RePo-only runtime change.

    The mature checkpoint binds Direct56 to the pre-RePo full-runtime SHA.
    RePo is allowed to preserve that identity only when both embedded Direct56
    source literals remain byte-identical to the reviewed parent. Any Direct56
    source drift fails closed instead of borrowing the parent's identity.
    """
    global _DBLOCK_TARGET_ROUTE_CONTROLLER_SOURCE_SHA256
    if _DBLOCK_TARGET_ROUTE_CONTROLLER_SOURCE_SHA256 is None:
        source_path = pathlib.Path(__file__).resolve()
        actual_runtime = hashlib.sha256(source_path.read_bytes()).hexdigest()
        digest = actual_runtime
        repo_active = str(os.environ.get("AGILLM43_REPO_ENABLED", "0") or "0").strip().lower() in {
            "1", "true", "yes", "on"
        }
        if repo_active:
            core_source = globals().get("_AGILLM_DIRECT56_CORE_SOURCE")
            integration_source = globals().get("_AGILLM_DIRECT56_INTEGRATION_SOURCE")
            if not isinstance(core_source, str) or not isinstance(integration_source, str):
                raise RuntimeError("RePo Direct56 compatibility sources are unavailable")
            core_sha = hashlib.sha256(core_source.encode("utf-8")).hexdigest()
            integration_sha = hashlib.sha256(integration_source.encode("utf-8")).hexdigest()
            if (core_sha != _AGILLM44_REPO_DIRECT56_CORE_SOURCE_SHA256
                    or integration_sha != _AGILLM44_REPO_DIRECT56_INTEGRATION_SOURCE_SHA256):
                raise RuntimeError(
                    "RePo Direct56 compatibility check failed; refusing parent controller identity")
            digest = _AGILLM44_REPO_DIRECT56_PARENT_RUNTIME_SHA256
            print("[repo-direct56] preserved reviewed controller identity " + digest, flush=True)
        if not re.fullmatch(r"[0-9a-f]{64}", digest):
            raise RuntimeError("target-route controller source SHA-256 is invalid")
        _DBLOCK_TARGET_ROUTE_CONTROLLER_SOURCE_SHA256 = digest
    return _DBLOCK_TARGET_ROUTE_CONTROLLER_SOURCE_SHA256


def _dblock_target_route_validate_legacy_activation(args, checkpoint_step):
    """Authorize the single legacy-to-XOR transition against one pointer record."""
    if int(getattr(args, "dblock_target_route_activate_from_checkpoint", 0) or 0) != 1:
        raise ValueError(
            "legacy continuation requires "
            "--dblock_target_route_activate_from_checkpoint 1"
        )
    expected_step = int(
        getattr(args, "dblock_target_route_activation_checkpoint_step", -1)
    )
    loaded_step = _dblock_require_exact_int(
        checkpoint_step, "target-route loaded checkpoint step", minimum=0
    )
    if expected_step < 0 or loaded_step != expected_step:
        raise ValueError(
            "legacy XOR-FOLD56 activation checkpoint step does not match its "
            "explicit one-time binding"
        )
    expected_pointer = str(
        getattr(
            args,
            "dblock_target_route_activation_parent_pointer_sha256",
            "",
        )
        or ""
    )
    actual_pointer = str(
        os.environ.get("AGILLM_PARENT_POINTER_SHA256", "") or ""
    )
    if (
        not re.fullmatch(r"[0-9a-f]{64}", expected_pointer)
        or actual_pointer != expected_pointer
    ):
        raise ValueError(
            "legacy XOR-FOLD56 activation parent pointer SHA-256 is missing or "
            "does not match the explicit one-time binding"
        )
    loaded_parent_runtime = str(
        getattr(args, "_dblock_target_route_loaded_parent_runtime_sha256", "")
        or ""
    )
    if loaded_parent_runtime != _DBLOCK_TARGET_ROUTE_PARENT_RUNTIME_SHA256:
        raise ValueError(
            "legacy XOR-FOLD56 activation checkpoint provenance is not bound "
            "to the reviewed v27.12 parent runtime"
        )
    return expected_pointer


def _dblock_xor_fold56_coordinates(route_index):
    """Pure canonical XOR-FOLD56 map for the 56 joint local-gradient targets."""
    t = _dblock_require_exact_int(route_index, "XOR-FOLD56 route index", minimum=0)
    k = t % 14
    q = (t // 14) & 3
    block = 2 * k if k < 7 else 27 - 2 * k
    bitreverse2 = 2 * (k & 1) + ((k >> 1) & 1)
    phase = q ^ bitreverse2
    layer_offset = phase & 1
    sublayer = "attn" if (phase >> 1) == 0 else "ffn"
    return {
        "canonical_index": int(t % 56),
        "k": int(k),
        "q": int(q),
        "block": int(block),
        "phase": int(phase),
        "layer_offset": int(layer_offset),
        "sublayer": sublayer,
        "target_id": int(4 * block + phase),
    }


def _dblock_xor_fold56_selftest():
    if (
        json.dumps(
            json.loads(_DBLOCK_TARGET_ROUTE_DESCRIPTOR),
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        )
        != _DBLOCK_TARGET_ROUTE_DESCRIPTOR
        or hashlib.sha256(
            _DBLOCK_TARGET_ROUTE_DESCRIPTOR.encode("utf-8")
        ).hexdigest()
        != _DBLOCK_TARGET_ROUTE_POLICY_SHA256
    ):
        raise RuntimeError("XOR-FOLD56 self-test failed: policy digest drifted")
    rows = [_dblock_xor_fold56_coordinates(t) for t in range(56)]
    if sorted(row["target_id"] for row in rows) != list(range(56)):
        raise RuntimeError("XOR-FOLD56 self-test failed: target coverage is not bijective")
    expected_blocks = [0, 2, 4, 6, 8, 10, 12, 13, 11, 9, 7, 5, 3, 1]
    if [rows[t]["block"] for t in range(14)] != expected_blocks:
        raise RuntimeError("XOR-FOLD56 self-test failed: folded block order drifted")
    for target_id in range(56):
        clocks = [t for t, row in enumerate(rows) if row["target_id"] == target_id]
        if len(clocks) != 1:
            raise RuntimeError("XOR-FOLD56 self-test failed: duplicate target")
    return True


def _dblock_target_route_topology(state):
    B = _dblock_require_exact_int(state.get("B"), "target-route B", minimum=1)
    assign = _dblock_json_copy(state.get("assign", []))
    expected = [[2 * block, 2 * block + 1] for block in range(14)]
    if B != 14 or assign != expected:
        raise ValueError(
            "xor-fold56-v1 requires the checkpoint-compatible 14x2 assignment "
            "[[0,1],...,[26,27]]"
        )
    return {
        "blocks": 14,
        "assign": assign,
        "physical_layers": 28,
        "principal_sublayers": ["attn", "ffn"],
        "target_count": 56,
    }


def _dblock_target_route_digest(value):
    raw = json.dumps(
        value, sort_keys=True, separators=(",", ":"), allow_nan=False
    ).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def _dblock_xor_fold56_target(state, route_commit_clock, route_offset):
    clock = _dblock_require_exact_int(
        route_commit_clock, "XOR-FOLD56 route commit clock", minimum=0
    )
    offset = _dblock_require_exact_int(
        route_offset, "XOR-FOLD56 route offset", minimum=0, maximum=55
    )
    coord = _dblock_xor_fold56_coordinates((clock + offset) % 56)
    topology = _dblock_target_route_topology(state)
    physical_layer = int(
        topology["assign"][coord["block"]][coord["layer_offset"]]
    )
    identity = dict(coord)
    identity.update({
        "route_commit_clock": int(clock),
        "route_offset": int(offset),
        "physical_layer": physical_layer,
    })
    identity["target_sha256"] = _dblock_target_route_digest(identity)
    return identity


def _dblock_xor_fold56_bridge_offset(state):
    """Choose a cyclic rotation from persisted legacy per-block phase residues.

    The continuation snapshot has no authoritative last joint target, and its
    last_seen values include rejected attempts.  Therefore the bridge deliberately
    does not invent a previous physical depth from the global clock.
    """
    counts = list(state.get("counts", []))
    if len(counts) != 14 or any(type(value) is not int or value < 0 for value in counts):
        raise ValueError("XOR-FOLD56 bridge requires 14 exact legacy committed counters")
    _dblock_require_exact_int(
        state.get("step"), "XOR-FOLD56 bridge committed step", minimum=0
    )
    residues = [value % 4 for value in counts]

    def bridge_key(offset):
        first = _dblock_xor_fold56_coordinates(offset)
        phase_mismatch = int(first["phase"] != residues[first["block"]])
        matches = sum(
            int(row["phase"] == residues[row["block"]])
            for row in (
                _dblock_xor_fold56_coordinates((offset + j) % 56)
                for j in range(14)
            )
        )
        return (phase_mismatch, -matches, offset)

    return min(range(56), key=bridge_key)


def _dblock_target_route_target_map_sha256(state, route_offset):
    topology_sha = _dblock_target_route_digest(_dblock_target_route_topology(state))
    cache_key = (topology_sha, int(route_offset))
    cached = _DBLOCK_TARGET_ROUTE_TARGET_MAP_CACHE.get(cache_key)
    if cached is not None:
        return cached
    rows = []
    for clock in range(56):
        target = _dblock_xor_fold56_target(state, clock, route_offset)
        rows.append({
            key: target[key]
            for key in (
                "canonical_index", "target_id", "block", "phase",
                "physical_layer", "sublayer",
            )
        })
    digest = _dblock_target_route_digest(rows)
    _DBLOCK_TARGET_ROUTE_TARGET_MAP_CACHE[cache_key] = digest
    return digest


def _dblock_target_route_validate_runtime_state(state, args):
    if _dblock_target_route_policy(args) != "xor_fold56_v1":
        return None
    route = state.get("target_route")
    if not isinstance(route, dict):
        raise ValueError("xor-fold56-v1 runtime route state is missing")
    expected_keys = {
        "schema", "policy_id", "policy_version", "policy_sha256",
        "parent_runtime_sha256", "controller_source_sha256",
        "activation_parent_pointer_sha256", "topology_sha256", "target_map_sha256",
        "activation_checkpoint_step", "origin_committed_step", "route_offset",
        "route_commit_clock", "route_attempt_clock", "pending_target",
        "last_committed_target",
    }
    if set(route) != expected_keys:
        raise ValueError("xor-fold56-v1 runtime route state keys drifted")
    if route["schema"] != _DBLOCK_TARGET_ROUTE_SCHEMA:
        raise ValueError("xor-fold56-v1 route schema mismatch")
    if route["policy_id"] != _DBLOCK_TARGET_ROUTE_POLICY_ID:
        raise ValueError("xor-fold56-v1 policy id mismatch")
    if route["policy_version"] != _DBLOCK_TARGET_ROUTE_POLICY_VERSION:
        raise ValueError("xor-fold56-v1 policy version mismatch")
    if route["policy_sha256"] != _DBLOCK_TARGET_ROUTE_POLICY_SHA256:
        raise ValueError("xor-fold56-v1 formula digest mismatch")
    if route["parent_runtime_sha256"] != _DBLOCK_TARGET_ROUTE_PARENT_RUNTIME_SHA256:
        raise ValueError("xor-fold56-v1 parent runtime binding mismatch")
    if (
        route["controller_source_sha256"]
        != _dblock_target_route_controller_source_sha256()
    ):
        raise ValueError("xor-fold56-v1 controller source digest mismatch")
    if not re.fullmatch(
        r"[0-9a-f]{64}", str(route["activation_parent_pointer_sha256"] or "")
    ):
        raise ValueError("xor-fold56-v1 activation pointer digest is invalid")
    topology = _dblock_target_route_topology(state)
    topology_sha = _dblock_target_route_digest(topology)
    if route["topology_sha256"] != topology_sha:
        raise ValueError("xor-fold56-v1 topology digest mismatch")
    offset = _dblock_require_exact_int(
        route["route_offset"], "xor-fold56-v1 route_offset", minimum=0, maximum=55
    )
    if route["target_map_sha256"] != _dblock_target_route_target_map_sha256(
        state, offset
    ):
        raise ValueError("xor-fold56-v1 target-map digest mismatch")
    origin = _dblock_require_exact_int(
        route["origin_committed_step"], "xor-fold56-v1 origin", minimum=0
    )
    clock = _dblock_require_exact_int(
        route["route_commit_clock"], "xor-fold56-v1 route clock", minimum=0
    )
    attempt_clock = _dblock_require_exact_int(
        route["route_attempt_clock"],
        "xor-fold56-v1 route attempt clock",
        minimum=clock,
    )
    if int(state.get("step", -1)) != origin + clock:
        raise ValueError(
            "xor-fold56-v1 route clock is not bound to committed DBlock clock"
        )
    _dblock_require_exact_int(
        route["activation_checkpoint_step"],
        "xor-fold56-v1 activation checkpoint",
        minimum=0,
    )
    pending = route["pending_target"]
    if pending is not None:
        if not isinstance(pending, dict):
            raise ValueError("xor-fold56-v1 pending target must be null or a mapping")
        attempts = _dblock_require_exact_int(
            pending.get("attempts"), "xor-fold56-v1 pending attempts", minimum=1
        )
        first_attempt = _dblock_require_exact_int(
            pending.get("first_attempt_step"),
            "xor-fold56-v1 first attempt",
            minimum=0,
        )
        last_attempt = _dblock_require_exact_int(
            pending.get("last_attempt_step"),
            "xor-fold56-v1 last attempt",
            minimum=first_attempt,
        )
        expected = _dblock_xor_fold56_target(state, clock, offset)
        immutable = {
            key: value for key, value in pending.items()
            if key not in {"attempts", "first_attempt_step", "last_attempt_step"}
        }
        if (
            immutable != expected
            or attempts != last_attempt - first_attempt + 1
            or last_attempt != attempt_clock - 1
        ):
            raise ValueError("xor-fold56-v1 pending target identity drifted")
    last_committed = route["last_committed_target"]
    if clock == 0:
        if last_committed is not None:
            raise ValueError(
                "xor-fold56-v1 last committed target must be null at clock zero"
            )
    else:
        if not isinstance(last_committed, dict):
            raise ValueError(
                "xor-fold56-v1 last committed target is missing after a commit"
            )
        expected_last = _dblock_xor_fold56_target(state, clock - 1, offset)
        bookkeeping = {
            "attempts", "first_attempt_step", "last_attempt_step",
            "committed_step_after",
        }
        if set(last_committed) != set(expected_last) | bookkeeping:
            raise ValueError("xor-fold56-v1 last committed target keys drifted")
        immutable_last = {
            key: value for key, value in last_committed.items()
            if key not in bookkeeping
        }
        if immutable_last != expected_last:
            raise ValueError("xor-fold56-v1 last committed target identity drifted")
        attempts = _dblock_require_exact_int(
            last_committed["attempts"],
            "xor-fold56-v1 last committed attempts",
            minimum=1,
        )
        first_attempt = _dblock_require_exact_int(
            last_committed["first_attempt_step"],
            "xor-fold56-v1 last committed first attempt",
            minimum=0,
        )
        last_attempt = _dblock_require_exact_int(
            last_committed["last_attempt_step"],
            "xor-fold56-v1 last committed last attempt",
            minimum=first_attempt,
        )
        committed_after = _dblock_require_exact_int(
            last_committed["committed_step_after"],
            "xor-fold56-v1 last committed step",
            minimum=1,
        )
        if (
            attempts != last_attempt - first_attempt + 1
            or last_attempt >= attempt_clock
            or committed_after != origin + clock
        ):
            raise ValueError("xor-fold56-v1 last committed bookkeeping drifted")
    return route


def _dblock_target_route_checkpoint_payload(state, args, checkpoint_step):
    if _dblock_target_route_policy(args) == "legacy":
        return None
    route = _dblock_target_route_validate_runtime_state(state, args)
    payload = {
        "schema": _DBLOCK_TARGET_ROUTE_SCHEMA,
        "checkpoint_step": _dblock_require_exact_int(
            checkpoint_step, "target-route checkpoint step", minimum=0
        ),
        "policy_id": _DBLOCK_TARGET_ROUTE_POLICY_ID,
        "policy_version": _DBLOCK_TARGET_ROUTE_POLICY_VERSION,
        "policy_sha256": _DBLOCK_TARGET_ROUTE_POLICY_SHA256,
        "controller_source_sha256": route["controller_source_sha256"],
        "activation_parent_pointer_sha256": route[
            "activation_parent_pointer_sha256"
        ],
        "topology_sha256": route["topology_sha256"],
        "target_map_sha256": route["target_map_sha256"],
        "state": _dblock_json_copy(route),
    }
    payload["sha256"] = _dblock_target_route_digest(payload)
    return payload


def _dblock_target_route_boot(state, args, payload=None, checkpoint_step=0):
    policy = _dblock_target_route_policy(args)
    if policy == "legacy":
        if payload is not None:
            raise ValueError(
                "checkpoint has XOR-FOLD56 state but legacy routing was requested"
            )
        state["target_route"] = None
        return None
    if policy != "xor_fold56_v1":
        raise ValueError(f"unsupported DBlock target route policy {policy!r}")
    if bool(getattr(args, "repair_mode", False)):
        raise ValueError(
            "xor-fold56-v1 is a continuation policy, not a repair topology migration"
        )
    if int(getattr(args, "dblock_train_layers_per_update", 0) or 0) != 1:
        raise ValueError(
            "xor-fold56-v1 requires --dblock_train_layers_per_update 1"
        )
    if int(getattr(args, "dblock_train_sublayers_per_update", 0) or 0) != 1:
        raise ValueError(
            "xor-fold56-v1 requires --dblock_train_sublayers_per_update 1"
        )
    if _dblock_sublayer_base_mode(args) not in {"off", "full"}:
        raise ValueError(
            "xor-fold56-v1 requires a complete attention+FFN forward path"
        )
    if _dblock_router_mode(args) != "shadow":
        raise ValueError(
            "xor-fold56-v1 requires the existing learned router to remain shadow-only"
        )
    if abs(float(getattr(args, "dblock_router_blend", 0.0) or 0.0)) > 1e-12:
        raise ValueError("xor-fold56-v1 requires --dblock_router_blend 0.0")
    if (
        int(getattr(args, "after_sft_steps", 0) or 0) > 0
        or str(getattr(args, "after_sft_source", "") or "").strip()
    ):
        raise ValueError(
            "xor-fold56-v1 continuation forbids post-pretraining SFT; the "
            "metadata-complete pretrain phase final must remain authoritative"
        )
    _dblock_xor_fold56_selftest()
    topology = _dblock_target_route_topology(state)
    topology_sha = _dblock_target_route_digest(topology)
    checkpoint_step = _dblock_require_exact_int(
        checkpoint_step, "target-route loaded checkpoint step", minimum=0
    )
    if payload is None:
        loaded_commit_step = _dblock_require_exact_int(
            state.get("step"), "xor-fold56-v1 activation committed step", minimum=0
        )
        continuing = loaded_commit_step > 0
        if not continuing:
            raise ValueError(
                "xor-fold56-v1 is continuation-only and cannot activate on a "
                "fresh/zero-step state"
            )
        activation_pointer = _dblock_target_route_validate_legacy_activation(
            args, checkpoint_step
        )
        requested_offset = int(
            getattr(args, "dblock_target_route_offset", -1)
        )
        if requested_offset < -1 or requested_offset > 55:
            raise ValueError(
                "--dblock_target_route_offset must be -1 (derived) or 0..55"
            )
        bridge_offset = _dblock_xor_fold56_bridge_offset(state)
        if requested_offset >= 0 and requested_offset != bridge_offset:
            raise ValueError(
                "explicit XOR-FOLD56 activation offset does not match the "
                f"checkpoint-derived bridge: {requested_offset} != {bridge_offset}"
            )
        route_offset = bridge_offset
        _dblock_require_exact_int(
            route_offset, "target-route activation offset", minimum=0, maximum=55
        )
        state["target_route"] = {
            "schema": _DBLOCK_TARGET_ROUTE_SCHEMA,
            "policy_id": _DBLOCK_TARGET_ROUTE_POLICY_ID,
            "policy_version": _DBLOCK_TARGET_ROUTE_POLICY_VERSION,
            "policy_sha256": _DBLOCK_TARGET_ROUTE_POLICY_SHA256,
            "parent_runtime_sha256": _DBLOCK_TARGET_ROUTE_PARENT_RUNTIME_SHA256,
            "controller_source_sha256": (
                _dblock_target_route_controller_source_sha256()
            ),
            "activation_parent_pointer_sha256": activation_pointer,
            "topology_sha256": topology_sha,
            "target_map_sha256": _dblock_target_route_target_map_sha256(
                state, route_offset
            ),
            "activation_checkpoint_step": int(checkpoint_step),
            "origin_committed_step": int(loaded_commit_step),
            "route_offset": int(route_offset),
            "route_commit_clock": 0,
            "route_attempt_clock": 0,
            "pending_target": None,
            "last_committed_target": None,
        }
        print(
            f"[dblock-target-route] activated {_DBLOCK_TARGET_ROUTE_POLICY_ID} "
            f"origin={state['target_route']['origin_committed_step']} "
            f"offset={route_offset} bridge_offset={bridge_offset} "
            f"policy_sha256={_DBLOCK_TARGET_ROUTE_POLICY_SHA256}",
            flush=True,
        )
        return _dblock_target_route_validate_runtime_state(state, args)
    if not isinstance(payload, dict):
        raise ValueError("xor-fold56-v1 checkpoint payload must be a mapping")
    expected_payload_keys = {
        "schema", "checkpoint_step", "policy_id", "policy_version",
        "policy_sha256", "controller_source_sha256",
        "activation_parent_pointer_sha256", "topology_sha256",
        "target_map_sha256", "state", "sha256",
    }
    if set(payload) != expected_payload_keys:
        raise ValueError("xor-fold56-v1 checkpoint payload keys drifted")
    supplied_sha = str(payload.get("sha256") or "")
    unsigned = {key: value for key, value in payload.items() if key != "sha256"}
    if supplied_sha != _dblock_target_route_digest(unsigned):
        raise ValueError("xor-fold56-v1 checkpoint payload digest mismatch")
    if payload.get("schema") != _DBLOCK_TARGET_ROUTE_SCHEMA:
        raise ValueError("xor-fold56-v1 checkpoint schema mismatch")
    if int(payload.get("checkpoint_step", -1)) != checkpoint_step:
        raise ValueError("xor-fold56-v1 checkpoint clock mismatch")
    state["target_route"] = _dblock_json_copy(payload.get("state"))
    route = _dblock_target_route_validate_runtime_state(state, args)
    requested_offset = int(getattr(args, "dblock_target_route_offset", -1))
    if requested_offset < -1 or requested_offset > 55:
        raise ValueError(
            "--dblock_target_route_offset must be -1 (restored) or 0..55"
        )
    if requested_offset >= 0 and requested_offset != int(route["route_offset"]):
        raise ValueError(
            "restored XOR-FOLD56 offset does not match the explicit supervisor "
            f"contract: {route['route_offset']} != {requested_offset}"
        )
    for key in (
        "policy_id", "policy_version", "policy_sha256",
        "controller_source_sha256", "activation_parent_pointer_sha256",
        "topology_sha256", "target_map_sha256",
    ):
        if payload.get(key) != route.get(key):
            raise ValueError(
                f"xor-fold56-v1 checkpoint duplicate binding mismatch: {key}"
            )
    print(
        f"[dblock-target-route] restored {_DBLOCK_TARGET_ROUTE_POLICY_ID} "
        f"clock={route['route_commit_clock']} offset={route['route_offset']}",
        flush=True,
    )
    return route


def _dblock_target_route_begin_attempt(state, args):
    if _dblock_target_route_policy(args) == "legacy":
        return None
    route = _dblock_target_route_validate_runtime_state(state, args)
    clock = int(route["route_commit_clock"])
    expected = _dblock_xor_fold56_target(
        state, clock, int(route["route_offset"])
    )
    pending = route.get("pending_target")
    # This policy-owned clock advances at attempt admission, before any CUDA
    # work.  Consequently an exception/OOM is still a durable rejected attempt,
    # while the independent committed route clock remains unchanged.
    attempt_step = int(route["route_attempt_clock"])
    if pending is None:
        pending = dict(expected)
        pending.update({
            "attempts": 0,
            "first_attempt_step": attempt_step,
            "last_attempt_step": attempt_step,
        })
    else:
        immutable = {
            key: value for key, value in pending.items()
            if key not in {"attempts", "first_attempt_step", "last_attempt_step"}
        }
        if immutable != expected:
            raise RuntimeError("xor-fold56-v1 retry target changed before commit")
    pending["attempts"] = int(pending.get("attempts", 0)) + 1
    pending["last_attempt_step"] = attempt_step
    route["route_attempt_clock"] = attempt_step + 1
    route["pending_target"] = pending
    _dblock_target_route_validate_runtime_state(state, args)
    return _dblock_json_copy(pending)


def _dblock_target_route_validate_precommit(
    state, args, block_idx, train_layers, train_sublayers
):
    if _dblock_target_route_policy(args) == "legacy":
        return
    route = _dblock_target_route_validate_runtime_state(state, args)
    pending = route.get("pending_target")
    if not isinstance(pending, dict):
        raise RuntimeError("xor-fold56-v1 commit attempted without a pending target")
    expected_sublayers = {
        int(pending["physical_layer"]): str(pending["sublayer"])
    }
    if (
        int(block_idx) != int(pending["block"])
        or [int(layer) for layer in train_layers]
        != [int(pending["physical_layer"])]
        or {int(key): str(value) for key, value in train_sublayers.items()}
        != expected_sublayers
    ):
        raise RuntimeError(
            "xor-fold56-v1 selected target drifted before optimizer commit"
        )


def _dblock_target_route_commit(state, args):
    if _dblock_target_route_policy(args) == "legacy":
        return
    route = state.get("target_route")
    pending = route.get("pending_target") if isinstance(route, dict) else None
    if not isinstance(pending, dict):
        raise RuntimeError(
            "xor-fold56-v1 successful optimizer update has no pending target"
        )
    prior_clock = int(route["route_commit_clock"])
    origin = int(route["origin_committed_step"])
    if int(state.get("step", -1)) != origin + prior_clock + 1:
        raise RuntimeError("xor-fold56-v1 commit clock did not advance exactly once")
    committed = _dblock_json_copy(pending)
    committed["committed_step_after"] = int(state["step"])
    route["last_committed_target"] = committed
    route["route_commit_clock"] = prior_clock + 1
    route["pending_target"] = None
    _dblock_target_route_validate_runtime_state(state, args)


def _dblock_resume_payload(state, checkpoint_step):
    if not isinstance(state, dict):
        raise ValueError("repair checkpoint requires live DBlock state")
    base_step = int(globals().get("_AGILLM43_REPAIR_BASE_STEP", 0) or 0)
    target_step = int(globals().get(
        "_AGILLM43_REPAIR_TARGET_STEP", 0
    ) or 0)
    checkpoint_step = _dblock_require_exact_int(
        checkpoint_step, "checkpoint_step", minimum=base_step,
        maximum=target_step if target_step >= base_step else None,
    )
    if checkpoint_step > base_step:
        for required_key in _DBLOCK_REQUIRED_SEMANTIC_RESUME_KEYS:
            if required_key not in state:
                raise ValueError(f"child repair DBlock state is missing {required_key}")
    snapshot = {}
    for key in _DBLOCK_RESUME_KEYS:
        if key in state:
            snapshot[key] = _dblock_json_copy(state[key])
    payload = {
        "schema": str(globals().get(
            "_AGILLM_DBLOCK_RESUME_SCHEMA", "agillm43.dblock.resume.v1")),
        "repair_base_step": base_step,
        "checkpoint_step": checkpoint_step,
        "committed_step": int(state.get("step", 0) or 0),
        "B": int(state.get("B", 0) or 0),
        "assign": _dblock_json_copy(state.get("assign", [])),
        "state": snapshot,
    }
    digest_raw = json.dumps(
        payload, sort_keys=True, separators=(",", ":"), allow_nan=False
    ).encode("utf-8")
    payload["sha256"] = hashlib.sha256(digest_raw).hexdigest()
    return payload


_AGILLM43_CONTINUATION_STATE_SCHEMA_V1 = "agillm43.continuation.state.v1"
_AGILLM43_CONTINUATION_STATE_SCHEMA = "agillm43.continuation.state.v2"
_CONTINUATION_DBLOCK_EXTRA_KEYS = ("sat_variable_gate_committed",)
_CONTINUATION_DBLOCK_RESUME_KEYS = _DBLOCK_RESUME_KEYS + _CONTINUATION_DBLOCK_EXTRA_KEYS


def _agillm43_validate_sat_variable_gate_aggregate(value):
    if not isinstance(value, dict):
        raise ValueError("SAT-variable committed aggregate must be a mapping")
    validated = copy.deepcopy(value)
    integer_keys = (
        "updates", "blocks", "stride2_labels", "predicted_stride2",
        "false_accepts", "correct",
    )
    for key in integer_keys:
        validated[key] = _dblock_require_exact_int(
            validated.get(key), f"SAT-variable aggregate.{key}", minimum=0
        )
    confusion = validated.get("confusion")
    if not (
        isinstance(confusion, list) and len(confusion) == 2
        and all(isinstance(row, list) and len(row) == 2 for row in confusion)
    ):
        raise ValueError("SAT-variable aggregate confusion must be exactly 2x2")
    checked_confusion = []
    for truth, row in enumerate(confusion):
        checked_confusion.append([
            _dblock_require_exact_int(
                item,
                f"SAT-variable aggregate.confusion[{truth}][{prediction}]",
                minimum=0,
            )
            for prediction, item in enumerate(row)
        ])
    validated["confusion"] = checked_confusion
    c00, c01 = checked_confusion[0]
    c10, c11 = checked_confusion[1]
    if c00 + c01 + c10 + c11 != validated["blocks"]:
        raise ValueError("SAT-variable aggregate confusion/block total mismatch")
    if c00 + c11 != validated["correct"]:
        raise ValueError("SAT-variable aggregate confusion/correct mismatch")
    if c10 + c11 != validated["stride2_labels"]:
        raise ValueError("SAT-variable aggregate true-stride2 mismatch")
    if c01 + c11 != validated["predicted_stride2"]:
        raise ValueError("SAT-variable aggregate predicted-stride2 mismatch")
    if c01 != validated["false_accepts"]:
        raise ValueError("SAT-variable aggregate false-accept mismatch")
    for key in ("loss_times_blocks", "mean_ce"):
        raw = validated.get(key)
        if isinstance(raw, bool) or not isinstance(raw, (int, float)):
            raise ValueError(f"SAT-variable aggregate.{key} must be numeric")
        validated[key] = float(raw)
        if not math.isfinite(validated[key]) or validated[key] < 0.0:
            raise ValueError(
                f"SAT-variable aggregate.{key} must be finite and nonnegative"
            )
    expected_mean = (
        validated["loss_times_blocks"] / validated["blocks"]
        if validated["blocks"] else 0.0
    )
    if not math.isclose(
        validated["mean_ce"], expected_mean, rel_tol=1.0e-12, abs_tol=1.0e-12
    ):
        raise ValueError("SAT-variable aggregate mean CE is inconsistent")
    return validated


def _continuation_dblock_state_payload(state, checkpoint_step):
    """Persist semantic DBlock clocks for ordinary production continuation."""
    if not isinstance(state, dict):
        return None
    checkpoint_step = _dblock_require_exact_int(
        checkpoint_step, "continuation checkpoint step", minimum=0
    )
    missing = [
        key for key in _CONTINUATION_DBLOCK_RESUME_KEYS if key not in state
    ]
    if missing:
        raise ValueError(
            "continuation DBlock state is incomplete: " + ", ".join(missing)
        )
    block_count = _dblock_require_exact_int(
        state.get("B"), "continuation DBlock block count", minimum=1
    )
    assignment = _dblock_json_copy(state.get("assign", []))
    if not isinstance(assignment, list) or len(assignment) != block_count:
        raise ValueError("continuation DBlock assignment is invalid")
    snapshot = {
        key: _dblock_json_copy(state[key])
        for key in _CONTINUATION_DBLOCK_RESUME_KEYS
    }
    snapshot["sat_variable_gate_committed"] = (
        _agillm43_validate_sat_variable_gate_aggregate(
            snapshot["sat_variable_gate_committed"]
        )
    )
    payload = {
        "schema": _AGILLM43_CONTINUATION_STATE_SCHEMA,
        "checkpoint_step": int(checkpoint_step),
        "committed_step": int(state.get("step", 0) or 0),
        "B": int(block_count),
        "assign": assignment,
        "state": snapshot,
    }
    digest_raw = json.dumps(
        payload, sort_keys=True, separators=(",", ":"), allow_nan=False
    ).encode("utf-8")
    payload["sha256"] = hashlib.sha256(digest_raw).hexdigest()
    return payload



def _continuation_migrate_14x2_to_28x1_snapshot(snapshot):
    """Project 14 two-layer DBlock bookkeeping onto 28 one-layer scheduler credits.

    Model/optimizer tensors are untouched. Integer per-block totals are split
    deterministically so global semantic clocks remain exact; per-block floating
    statistics are duplicated to both child layers because both layers shared the
    same historical local loss signal before the topology split.
    """
    if not isinstance(snapshot, dict):
        raise ValueError("single-layer migration requires a continuation snapshot")
    out = copy.deepcopy(snapshot)

    def split_ints(values, label):
        if not isinstance(values, list) or len(values) != 14:
            raise ValueError(f"{label} must be a length-14 list for 14x2->28x1 migration")
        result = []
        for value in values:
            if type(value) is not int or value < 0:
                raise ValueError(f"{label} contains an invalid counter")
            left = value // 2
            result.extend([left, value - left])
        return result

    def duplicate(values, label):
        if not isinstance(values, list) or len(values) != 14:
            raise ValueError(f"{label} must be a length-14 list for 14x2->28x1 migration")
        result = []
        for value in values:
            result.extend([copy.deepcopy(value), copy.deepcopy(value)])
        return result

    for key in ("counts", "attempt_counts"):
        out[key] = split_ints(out[key], key)
    for key in ("failure_streak", "loss_ema", "loss_best", "last_seen"):
        out[key] = duplicate(out[key], key)
    for key in ("loss_ema_by_objective", "spike_block_ema_by_objective"):
        mapping = out.get(key)
        if not isinstance(mapping, dict):
            raise ValueError(f"{key} must be a mapping for 14x2->28x1 migration")
        out[key] = {family: duplicate(values, f"{key}.{family}") for family, values in mapping.items()}
    local = out.get("local_spike_consecutive_by_objective_block")
    if not isinstance(local, dict):
        raise ValueError("local spike counters must be a mapping for 14x2->28x1 migration")
    out["local_spike_consecutive_by_objective_block"] = {
        family: duplicate(values, f"local_spike_consecutive.{family}")
        for family, values in local.items()
    }
    for key in ("supervised_targets_by_block", "committed_objective_steps_by_block"):
        mapping = out.get(key)
        if not isinstance(mapping, dict):
            raise ValueError(f"{key} must be a mapping for 14x2->28x1 migration")
        out[key] = {family: split_ints(values, f"{key}.{family}") for family, values in mapping.items()}

    if sum(out["counts"]) != int(out.get("step", -1)):
        raise ValueError("migrated committed scheduler credits do not match DBlock step")
    if sum(out["attempt_counts"]) != int(out.get("attempt_step", -1)):
        raise ValueError("migrated attempt scheduler credits do not match attempt step")
    return out


def _continuation_is_14x2_to_28x1(old_B, old_assign, new_B, new_assign):
    expected_old = [[i, i + 1] for i in range(0, 28, 2)]
    expected_new = [[i] for i in range(28)]
    return int(old_B) == 14 and int(new_B) == 28 and old_assign == expected_old and new_assign == expected_new


def _continuation_restore_dblock_state(
        state, payload, checkpoint_step, source_profile="", args=None):
    """Restore a hash-bound production DBlock snapshot, failing closed on drift."""
    source_profile = str(source_profile or "")
    if source_profile not in {
            "intelligence-v23", "intelligence-v25-satvar-pretrain"}:
        raise ValueError(
            f"unsupported continuation source profile {source_profile!r}"
        )
    if payload is None:
        if source_profile != "intelligence-v23":
            raise ValueError(
                "v25 continuation is missing its v2 semantic state snapshot"
            )
        state["sat_variable_gate_committed"] = (
            _agillm43_validate_sat_variable_gate_aggregate(
                state["sat_variable_gate_committed"]
            )
        )
        print(
            "[continuation-state] v23 checkpoint has no DBlock snapshot; "
            "starting the v25 gate aggregate at exact zero",
            flush=True,
        )
        return state
    if not isinstance(payload, dict):
        raise ValueError("continuation DBlock snapshot must be a mapping")
    supplied_schema = str(payload.get("schema") or "")
    if supplied_schema not in {
            _AGILLM43_CONTINUATION_STATE_SCHEMA_V1,
            _AGILLM43_CONTINUATION_STATE_SCHEMA}:
        raise ValueError("continuation DBlock snapshot schema mismatch")
    resume_keys = (
        _DBLOCK_RESUME_KEYS
        if supplied_schema == _AGILLM43_CONTINUATION_STATE_SCHEMA_V1
        else _CONTINUATION_DBLOCK_RESUME_KEYS
    )
    expected_schema = (
        _AGILLM43_CONTINUATION_STATE_SCHEMA_V1
        if source_profile == "intelligence-v23"
        else _AGILLM43_CONTINUATION_STATE_SCHEMA
    )
    if supplied_schema != expected_schema:
        raise ValueError(
            f"continuation schema {supplied_schema!r} is invalid for "
            f"source profile {source_profile!r}"
        )
    if int(payload.get("checkpoint_step", -1)) != int(checkpoint_step):
        raise ValueError("continuation DBlock snapshot checkpoint clock mismatch")
    supplied_digest = str(payload.get("sha256") or "")
    digest_payload = {key: value for key, value in payload.items() if key != "sha256"}
    digest_raw = json.dumps(
        digest_payload, sort_keys=True, separators=(",", ":"), allow_nan=False
    ).encode("utf-8")
    if supplied_digest != hashlib.sha256(digest_raw).hexdigest():
        raise ValueError("continuation DBlock snapshot digest mismatch")
    old_B = int(payload.get("B", 0) or 0)
    new_B = int(state.get("B", 0) or 0)
    old_assign = payload.get("assign")
    new_assign = state.get("assign")
    topology_migration = bool(getattr(
        args, "dblock_allow_forward_topology_migration", False
    )) and _continuation_is_14x2_to_28x1(
        old_B, old_assign, new_B, new_assign
    )
    if not topology_migration and old_B != new_B:
        raise ValueError("continuation DBlock block count changed")
    if not topology_migration and old_assign != new_assign:
        raise ValueError("continuation DBlock assignment changed")
    snapshot = payload.get("state")
    if not isinstance(snapshot, dict):
        raise ValueError("continuation DBlock state snapshot is missing")
    if topology_migration:
        snapshot = _continuation_migrate_14x2_to_28x1_snapshot(snapshot)
        print(
            "[continuation-state] topology migration 14x2 -> 28x1; "
            "model/optimizer preserved, per-block scheduler credits projected",
            flush=True,
        )
    missing = [key for key in resume_keys if key not in snapshot]
    if missing:
        raise ValueError(
            "continuation DBlock snapshot is incomplete: " + ", ".join(missing)
        )
    if int(snapshot.get("step", -1)) != int(payload.get("committed_step", -2)):
        raise ValueError("continuation DBlock committed clock mismatch")
    if supplied_schema == _AGILLM43_CONTINUATION_STATE_SCHEMA:
        snapshot["sat_variable_gate_committed"] = (
            _agillm43_validate_sat_variable_gate_aggregate(
                snapshot["sat_variable_gate_committed"]
            )
        )
    for key in resume_keys:
        state[key] = copy.deepcopy(snapshot[key])
    if supplied_schema == _AGILLM43_CONTINUATION_STATE_SCHEMA_V1:
        state["sat_variable_gate_committed"] = {
            "updates": 0, "blocks": 0, "stride2_labels": 0,
            "predicted_stride2": 0, "false_accepts": 0,
            "correct": 0, "loss_times_blocks": 0.0,
            "mean_ce": 0.0, "confusion": [[0, 0], [0, 0]],
        }
    state["last_update_trained"] = False
    print(
        f"[continuation-state] restored DBlock committed_step={state['step']} "
        f"attempt_step={state['attempt_step']}",
        flush=True,
    )
    return state


def _dblock_validate_resume_payload_legacy(payload, checkpoint_step, args=None, *,
                                           expected_assign=None):
    if not isinstance(payload, dict):
        raise ValueError("missing repair DBlock resume state")
    expected_schema = str(globals().get(
        "_AGILLM_DBLOCK_RESUME_SCHEMA", "agillm43.dblock.resume.v1"))
    if str(payload.get("schema") or "") != expected_schema:
        raise ValueError(
            f"DBlock resume schema {payload.get('schema')!r} != {expected_schema!r}")
    base_step = int(globals().get("_AGILLM43_REPAIR_BASE_STEP", 0) or 0)
    checkpoint_step = int(checkpoint_step)
    if int(payload.get("repair_base_step", -1)) != base_step:
        raise ValueError("DBlock resume base step does not match immutable repair base")
    if int(payload.get("checkpoint_step", -1)) != checkpoint_step:
        raise ValueError("DBlock resume checkpoint step does not match loaded checkpoint")
    committed = checkpoint_step - base_step
    if committed < 0:
        raise ValueError("repair checkpoint precedes immutable repair base")
    if int(payload.get("committed_step", -1)) != committed:
        raise ValueError(
            f"DBlock committed step {payload.get('committed_step')} != {committed}")
    supplied_digest = str(payload.get("sha256") or "")
    digest_payload = {k: v for k, v in payload.items() if k != "sha256"}
    digest_raw = json.dumps(
        digest_payload, sort_keys=True, separators=(",", ":"), allow_nan=False
    ).encode("utf-8")
    expected_digest = hashlib.sha256(digest_raw).hexdigest()
    if supplied_digest != expected_digest:
        raise ValueError("DBlock resume state digest mismatch")
    B = int(payload.get("B", 0) or 0)
    assign = payload.get("assign")
    if B <= 0 or not isinstance(assign, list) or len(assign) != B:
        raise ValueError("invalid DBlock resume B/assignment")
    if args is not None and B != int(getattr(args, "dblock_blocks", 0) or 0):
        raise ValueError(
            f"DBlock resume B={B} != configured B={int(getattr(args, 'dblock_blocks', 0) or 0)}")
    if expected_assign is not None and assign != expected_assign:
        raise ValueError("DBlock resume assignment differs from initialized model")
    snapshot = payload.get("state")
    if not isinstance(snapshot, dict):
        raise ValueError("DBlock resume state snapshot is missing")
    if int(snapshot.get("step", -1)) != committed:
        raise ValueError("DBlock snapshot committed clock mismatch")
    counts = snapshot.get("counts")
    attempts = snapshot.get("attempt_counts")
    if not isinstance(counts, list) or len(counts) != B:
        raise ValueError("DBlock committed counts have wrong length")
    if not isinstance(attempts, list) or len(attempts) != B:
        raise ValueError("DBlock attempt counts have wrong length")
    if any(isinstance(x, bool) or not isinstance(x, int) or x < 0 for x in counts + attempts):
        raise ValueError("DBlock counts must be non-negative integers")
    if sum(counts) != committed:
        raise ValueError(
            f"DBlock committed count sum {sum(counts)} != committed clock {committed}")
    attempt_step = int(snapshot.get("attempt_step", -1))
    if attempt_step < committed or sum(attempts) != attempt_step:
        raise ValueError("DBlock attempt clock/counts are inconsistent")
    if any(counts[i] > attempts[i] for i in range(B)):
        raise ValueError("DBlock committed count exceeds attempt count")
    for key in ("failure_streak", "loss_ema", "loss_best", "last_seen"):
        value = snapshot.get(key)
        if not isinstance(value, list) or len(value) != B:
            raise ValueError(f"DBlock {key} has wrong length")
    anchor_ema = snapshot.get("fullstack_anchor_spike_ema_by_family")
    if not isinstance(anchor_ema, dict) or not set(anchor_ema).issubset({"ar", "sat", "nat"}):
        raise ValueError("DBlock anchor spike EMA map is missing or has unknown families")
    if any(
        isinstance(value, bool) or not isinstance(value, (int, float))
        or not math.isfinite(float(value)) or float(value) <= 0.0
        for value in anchor_ema.values()
    ):
        raise ValueError("DBlock anchor spike EMA values must be finite and positive")
    anchor_skips = snapshot.get("fullstack_anchor_spike_skips_by_family")
    if not isinstance(anchor_skips, dict) or set(anchor_skips) != {"ar", "sat", "nat"}:
        raise ValueError("DBlock anchor spike skip map must contain exactly ar/sat/nat")
    if any(isinstance(value, bool) or not isinstance(value, int) or value < 0 for value in anchor_skips.values()):
        raise ValueError("DBlock anchor spike skip counts must be non-negative integers")
    anchor_consecutive = snapshot.get(
        "fullstack_anchor_spike_consecutive_by_family"
    )
    if (
        not isinstance(anchor_consecutive, dict)
        or set(anchor_consecutive) != {"ar", "sat", "nat"}
        or any(
            isinstance(value, bool) or not isinstance(value, int) or value < 0
            for value in anchor_consecutive.values()
        )
    ):
        raise ValueError(
            "DBlock anchor consecutive spike map must contain "
            "non-negative integer ar/sat/nat counters"
        )
    local_consecutive = snapshot.get(
        "local_spike_consecutive_by_objective_block"
    )
    if (
        not isinstance(local_consecutive, dict)
        or set(local_consecutive) != {"ar", "sat", "nat"}
    ):
        raise ValueError(
            "DBlock local consecutive spike map must contain ar/sat/nat"
        )
    for family, values in local_consecutive.items():
        if (
            not isinstance(values, list)
            or len(values) != B
            or any(
                isinstance(value, bool)
                or not isinstance(value, int)
                or value < 0
                for value in values
            )
        ):
            raise ValueError(
                f"DBlock local consecutive spike counters for {family} "
                "have invalid type/length/value"
            )
    if args is not None:
        anchor_limit = _dblock_anchor_spike_retry_limit(args)
        local_limit = _dblock_local_spike_retry_limit(args)
        if any(value >= anchor_limit for value in anchor_consecutive.values()):
            raise ValueError(
                "resumable DBlock state may not contain an exhausted "
                "anchor spike retry budget"
            )
        if any(
            value >= local_limit
            for values in local_consecutive.values()
            for value in values
        ):
            raise ValueError(
                "resumable DBlock state may not contain an exhausted "
                "local spike retry budget"
            )
    no_crop_consecutive = snapshot.get(
        "fullstack_nat_anchor_no_valid_crop_consecutive"
    )
    no_crop_total = snapshot.get("fullstack_nat_anchor_no_valid_crop_total")
    if any(
        isinstance(value, bool) or not isinstance(value, int) or value < 0
        for value in (no_crop_consecutive, no_crop_total)
    ):
        raise ValueError(
            "DBlock NAT no-valid-crop counters must be non-negative integers"
        )
    if no_crop_consecutive > no_crop_total:
        raise ValueError(
            "DBlock NAT consecutive no-valid-crop count exceeds total"
        )
    if args is not None:
        limit = _dblock_nat_no_valid_crop_limit(args)
        if no_crop_consecutive >= limit:
            raise ValueError(
                "resumable DBlock state may not contain an exhausted "
                "NAT no-valid-crop retry budget"
            )
    _dblock_json_copy(snapshot)
    return snapshot


def _dblock_validate_resume_payload(payload, checkpoint_step, args=None, *,
                                    expected_assign=None):
    """Strict v5 resume validation with zero JSON-number coercion."""
    base_step = int(globals().get("_AGILLM43_REPAIR_BASE_STEP", 0) or 0)
    target_step = int(globals().get(
        "_AGILLM43_REPAIR_TARGET_STEP", 0
    ) or 0)
    checkpoint_step = _dblock_require_exact_int(
        checkpoint_step, "loaded checkpoint_step", minimum=base_step,
        maximum=target_step if target_step >= base_step else None,
    )
    if not isinstance(payload, dict):
        raise ValueError("missing repair DBlock resume state")
    expected_payload_keys = {
        "schema", "repair_base_step", "checkpoint_step", "committed_step",
        "B", "assign", "state", "sha256",
    }
    if set(payload) != expected_payload_keys:
        raise ValueError(
            "DBlock resume payload keys must be exactly "
            f"{sorted(expected_payload_keys)}"
        )
    _dblock_require_exact_int(
        payload.get("repair_base_step"), "DBlock repair_base_step",
        minimum=base_step, maximum=base_step,
    )
    _dblock_require_exact_int(
        payload.get("checkpoint_step"), "DBlock checkpoint_step",
        minimum=checkpoint_step, maximum=checkpoint_step,
    )
    committed = checkpoint_step - base_step
    _dblock_require_exact_int(
        payload.get("committed_step"), "DBlock committed_step",
        minimum=committed, maximum=committed,
    )
    B = _dblock_require_exact_int(payload.get("B"), "DBlock B", minimum=1)
    assign = payload.get("assign")
    if not isinstance(assign, list) or len(assign) != B:
        raise ValueError("DBlock assignment must be a B-length list")
    normalized_assign = []
    for block_index, layers in enumerate(assign):
        if not isinstance(layers, list) or not layers:
            raise ValueError(
                f"DBlock assignment block {block_index} must be a nonempty list"
            )
        normalized_assign.append([
            _dblock_require_exact_int(
                layer, f"DBlock assign[{block_index}][{layer_index}]",
                minimum=0,
            )
            for layer_index, layer in enumerate(layers)
        ])
    flattened_assign = [
        layer for layers in normalized_assign for layer in layers
    ]
    if flattened_assign != list(range(28)):
        raise ValueError(
            "strict repair DBlock assignment must cover layers 0..27 exactly"
        )
    snapshot = payload.get("state")
    if not isinstance(snapshot, dict):
        raise ValueError("DBlock resume state snapshot is missing")
    missing = [
        key for key in _DBLOCK_REQUIRED_SEMANTIC_RESUME_KEYS
        if key not in snapshot
    ]
    if missing:
        raise ValueError(
            "DBlock resume state is missing training-semantic keys: "
            + ", ".join(missing)
        )
    unexpected = sorted(set(snapshot) - set(_DBLOCK_RESUME_KEYS))
    if unexpected:
        raise ValueError(
            "DBlock resume state contains non-contract keys: "
            + ", ".join(unexpected)
        )

    # Run the inherited digest/schema/assignment and retry-budget checks only
    # after every top-level clock has passed exact type validation.
    checked = _dblock_validate_resume_payload_legacy(
        payload, checkpoint_step, args=args, expected_assign=expected_assign
    )
    if checked is not snapshot:
        snapshot = checked

    step = _dblock_require_exact_int(
        snapshot.get("step"), "DBlock state.step",
        minimum=committed, maximum=committed,
    )
    attempt_step = _dblock_require_exact_int(
        snapshot.get("attempt_step"), "DBlock state.attempt_step",
        minimum=committed,
    )
    counts = _dblock_require_exact_int_list(
        snapshot.get("counts"), "DBlock counts", B,
        minimum=0, maximum=committed,
    )
    attempts = _dblock_require_exact_int_list(
        snapshot.get("attempt_counts"), "DBlock attempt_counts", B,
        minimum=0, maximum=attempt_step,
    )
    if sum(counts) != step or sum(attempts) != attempt_step:
        raise ValueError("DBlock exact step/count clocks are inconsistent")
    if any(counts[index] > attempts[index] for index in range(B)):
        raise ValueError("DBlock committed count exceeds attempt count")
    if B != 14:
        raise ValueError(f"strict repair DBlock B must equal 14, got {B}")
    expected_counts = [
        committed // B + (1 if index < (committed % B) else 0)
        for index in range(B)
    ]
    if counts != expected_counts:
        raise ValueError(
            f"DBlock counts do not match committed round-robin schedule: "
            f"{counts} != {expected_counts}"
        )

    failures = _dblock_require_exact_int_list(
        snapshot.get("failure_streak"), "DBlock failure_streak", B,
        minimum=0, maximum=B * 4,
    )
    if any(failures[index] > attempts[index] for index in range(B)):
        raise ValueError("DBlock failure_streak exceeds per-block attempts")
    last_seen = _dblock_require_exact_int_list(
        snapshot.get("last_seen"), "DBlock last_seen", B,
        minimum=-1, maximum=committed,
    )
    current_block = committed % B
    for index in range(B):
        if attempts[index] == 0 and last_seen[index] != -1:
            raise ValueError("DBlock never-attempted block must have last_seen=-1")
        if attempts[index] > 0 and last_seen[index] < 0:
            raise ValueError("DBlock attempted block must have non-negative last_seen")
        rejected_attempts = attempts[index] - counts[index]
        if failures[index] > rejected_attempts:
            raise ValueError(
                "DBlock failure_streak exceeds rejected attempts for block "
                f"{index}"
            )
        if index != current_block and failures[index] != 0:
            raise ValueError(
                "only the next round-robin block may retain a failure streak"
            )
        committed_last_seen = (
            -1 if counts[index] == 0
            else index + (counts[index] - 1) * B
        )
        expected_last_seen = (
            committed if index == current_block and failures[index] > 0
            else committed_last_seen
        )
        if last_seen[index] != expected_last_seen:
            raise ValueError(
                f"DBlock last_seen[{index}]={last_seen[index]} != pinned "
                f"round-robin value {expected_last_seen}"
            )

    loss_ema = snapshot.get("loss_ema")
    loss_best = snapshot.get("loss_best")
    if not isinstance(loss_ema, list) or len(loss_ema) != B:
        raise ValueError("DBlock loss_ema has wrong length")
    if not isinstance(loss_best, list) or len(loss_best) != B:
        raise ValueError("DBlock loss_best has wrong length")
    for index in range(B):
        ema = _dblock_require_finite_number(
            loss_ema[index], f"DBlock loss_ema[{index}]",
            allow_none=True, minimum=0.0,
        )
        best = _dblock_require_finite_number(
            loss_best[index], f"DBlock loss_best[{index}]",
            allow_none=True, minimum=0.0,
        )
        if counts[index] == 0 and (ema is not None or best is not None):
            raise ValueError("uncommitted DBlock block may not carry loss EMA/best")
        if counts[index] > 0 and (ema is None or best is None):
            raise ValueError("committed DBlock block requires loss EMA/best")
        if ema is not None and best is not None and best > ema + 1e-12:
            raise ValueError("DBlock loss_best may not exceed loss_ema")

    objective_keys = {"ar", "sat", "nat"}
    committed_steps = _dblock_validate_counter_map(
        snapshot.get("committed_objective_steps"),
        "DBlock committed_objective_steps", objective_keys,
        maximum=committed,
    )
    committed_by_block = _dblock_validate_counter_list_map(
        snapshot.get("committed_objective_steps_by_block"),
        "DBlock committed_objective_steps_by_block", objective_keys, B,
        maximum=committed,
    )
    for family in objective_keys:
        if sum(committed_by_block[family]) != committed_steps[family]:
            raise ValueError(
                f"DBlock committed objective counts disagree for {family}"
            )
        if any(
            committed_by_block[family][index] > counts[index]
            for index in range(B)
        ):
            raise ValueError(
                f"DBlock committed {family} count exceeds block commits"
            )
    if sum(committed_steps.values()) != committed:
        raise ValueError(
            "strict repair committed objective count must equal committed step"
        )
    expected_objective_by_block = {
        family: [0 for _ in range(B)] for family in objective_keys
    }
    committed_cycle = ("sat", "nat", "ar")
    for committed_index in range(committed):
        family = committed_cycle[committed_index % len(committed_cycle)]
        expected_objective_by_block[family][committed_index % B] += 1
    expected_objective_steps = {
        family: sum(values)
        for family, values in expected_objective_by_block.items()
    }
    if committed_steps != expected_objective_steps:
        raise ValueError(
            "DBlock committed objective totals do not match SAT/NAT/AR cycle"
        )
    if committed_by_block != expected_objective_by_block:
        raise ValueError(
            "DBlock per-block objective counters do not match pinned cycle"
        )

    supervised_keys = {
        "ar", "sat", "nat", "fullstack_ar", "fullstack_sat", "fullstack_nat"
    }
    supervised = _dblock_validate_counter_map(
        snapshot.get("supervised_targets"), "DBlock supervised_targets",
        supervised_keys,
    )
    supervised_by_block = _dblock_validate_counter_list_map(
        snapshot.get("supervised_targets_by_block"),
        "DBlock supervised_targets_by_block", objective_keys, B,
    )
    for family in objective_keys:
        if sum(supervised_by_block[family]) != supervised[family]:
            raise ValueError(
                f"DBlock supervised target counts disagree for {family}"
            )
        if committed_steps[family] == 0 and supervised[family] != 0:
            raise ValueError(
                f"DBlock {family} targets exist without a committed objective step"
            )
    local_target_caps = {"ar": 4096, "sat": 2048, "nat": 2048}
    for family, cap in local_target_caps.items():
        expected_by_block = [
            int(value) * int(cap) for value in committed_by_block[family]
        ]
        if supervised_by_block[family] != expected_by_block:
            raise ValueError(
                f"DBlock {family} target counters do not match pinned cap {cap}"
            )
        if supervised[family] != committed_steps[family] * cap:
            raise ValueError(
                f"DBlock {family} total targets do not match pinned cap {cap}"
            )

    loss_by_objective = _dblock_validate_objective_float_map(
        snapshot.get("loss_ema_by_objective"),
        "DBlock loss_ema_by_objective", B,
    )
    spike_global = _dblock_validate_objective_float_map(
        snapshot.get("spike_ema_by_objective"),
        "DBlock spike_ema_by_objective", B, scalar=True,
        strictly_positive=True,
    )
    spike_by_block = _dblock_validate_objective_float_map(
        snapshot.get("spike_block_ema_by_objective"),
        "DBlock spike_block_ema_by_objective", B,
        strictly_positive=True,
    )
    expected_local_families = {
        family for family in objective_keys if committed_steps[family] > 0
    }
    for label, mapping in (
        ("loss_ema_by_objective", loss_by_objective),
        ("spike_ema_by_objective", spike_global),
        ("spike_block_ema_by_objective", spike_by_block),
    ):
        if set(mapping) != expected_local_families:
            raise ValueError(
                f"DBlock {label} families {sorted(mapping)} != committed "
                f"families {sorted(expected_local_families)}"
            )
    for family in objective_keys:
        if committed_steps[family] <= 0:
            continue
        if family not in loss_by_objective:
            raise ValueError(f"DBlock missing committed {family} loss EMA family")
        if family not in spike_global or family not in spike_by_block:
            raise ValueError(f"DBlock missing committed {family} spike EMA family")
        for index, family_commits in enumerate(committed_by_block[family]):
            loss_value = loss_by_objective[family][index]
            block_spike = spike_by_block[family][index]
            if family_commits <= 0 and (loss_value is not None or block_spike is not None):
                raise ValueError(
                    f"DBlock {family} carries EMA state on uncommitted block {index}"
                )
            if family_commits <= 0:
                continue
            if loss_value is None:
                raise ValueError(
                    f"DBlock missing {family} loss EMA for committed block {index}"
                )
            if block_spike is None or block_spike <= 0.0:
                raise ValueError(
                    f"DBlock missing positive {family} spike EMA for block {index}"
                )

    anchor_skips = _dblock_validate_counter_map(
        snapshot.get("fullstack_anchor_spike_skips_by_family"),
        "DBlock fullstack_anchor_spike_skips_by_family", objective_keys,
        maximum=attempt_step,
    )
    anchor_consecutive = _dblock_validate_counter_map(
        snapshot.get("fullstack_anchor_spike_consecutive_by_family"),
        "DBlock fullstack_anchor_spike_consecutive_by_family", objective_keys,
        maximum=attempt_step,
    )
    local_consecutive = _dblock_validate_counter_list_map(
        snapshot.get("local_spike_consecutive_by_objective_block"),
        "DBlock local_spike_consecutive_by_objective_block", objective_keys, B,
        maximum=attempt_step,
    )
    if any(anchor_consecutive[name] > anchor_skips[name] for name in objective_keys):
        raise ValueError("DBlock anchor consecutive spike count exceeds total skips")
    current_failure_streak = failures[current_block]
    current_objective = committed_cycle[committed % len(committed_cycle)]
    for family, values in local_consecutive.items():
        for index, value in enumerate(values):
            if (family, index) != (current_objective, current_block) and value != 0:
                raise ValueError(
                    "DBlock local consecutive spike state may exist only for "
                    "the current objective/block"
                )
            if value > current_failure_streak:
                raise ValueError(
                    "DBlock local consecutive spike count exceeds current "
                    "failure streak"
                )
    for family, value in anchor_consecutive.items():
        if family != current_objective and value != 0:
            raise ValueError(
                "DBlock anchor consecutive spike state may exist only for "
                "the current objective"
            )
        if value > current_failure_streak:
            raise ValueError(
                f"DBlock {family} anchor consecutive spike count exceeds "
                "current failure streak"
            )

    scalar_counter_keys = (
        "fullstack_anchor_attempts", "fullstack_anchor_runs",
        "fullstack_anchor_skipped_empty_mask",
        "fullstack_sat_anchor_attempts", "fullstack_sat_anchor_runs",
        "fullstack_sat_anchor_skipped_empty_mask",
        "fullstack_sat_anchor_skipped_overlap",
        "fullstack_sat_anchor_skipped_short",
        "fullstack_nat_anchor_attempts", "fullstack_nat_anchor_runs",
        "fullstack_nat_anchor_skipped_empty_mask",
        "fullstack_nat_anchor_skipped_overlap",
        "fullstack_nat_anchor_skipped_short",
        "optimizer_overflow_skips",
    )
    scalar_counters = {
        key: _dblock_require_exact_int(
            snapshot.get(key), f"DBlock {key}", minimum=0,
            maximum=attempt_step,
        )
        for key in scalar_counter_keys
    }
    if scalar_counters["fullstack_anchor_runs"] > scalar_counters["fullstack_anchor_attempts"]:
        raise ValueError("DBlock AR anchor runs exceed attempts")
    if scalar_counters["fullstack_sat_anchor_runs"] > scalar_counters["fullstack_sat_anchor_attempts"]:
        raise ValueError("DBlock SAT anchor runs exceed attempts")
    if scalar_counters["fullstack_nat_anchor_runs"] > scalar_counters["fullstack_nat_anchor_attempts"]:
        raise ValueError("DBlock NAT anchor runs exceed attempts")
    anchor_run_bindings = {
        "ar": ("fullstack_anchor_attempts", "fullstack_anchor_runs"),
        "sat": (
            "fullstack_sat_anchor_attempts", "fullstack_sat_anchor_runs",
        ),
        "nat": (
            "fullstack_nat_anchor_attempts", "fullstack_nat_anchor_runs",
        ),
    }
    for family, (_attempt_key, run_key) in anchor_run_bindings.items():
        if scalar_counters[run_key] != committed_steps[family]:
            raise ValueError(
                f"DBlock {family} anchor runs must equal committed {family} "
                "objective steps"
            )
    pinned_zero_skip_keys = (
        "fullstack_anchor_skipped_empty_mask",
        "fullstack_sat_anchor_skipped_empty_mask",
        "fullstack_sat_anchor_skipped_overlap",
        "fullstack_sat_anchor_skipped_short",
        "fullstack_nat_anchor_skipped_empty_mask",
        "fullstack_nat_anchor_skipped_overlap",
        "fullstack_nat_anchor_skipped_short",
    )
    if any(scalar_counters[key] != 0 for key in pinned_zero_skip_keys):
        raise ValueError(
            "strict staggered full-stack anchors may not carry skip counters"
        )
    fullstack_target_caps = {
        "fullstack_ar": ("fullstack_anchor_runs", 128),
        "fullstack_sat": ("fullstack_sat_anchor_runs", 126),
        "fullstack_nat": ("fullstack_nat_anchor_runs", 64),
    }
    for target_key, (run_key, cap) in fullstack_target_caps.items():
        expected_targets = scalar_counters[run_key] * cap
        if supervised[target_key] != expected_targets:
            raise ValueError(
                f"DBlock {target_key} targets {supervised[target_key]} "
                f"!= {expected_targets} from committed anchors"
            )
    for family, attempts_key in (
        ("ar", "fullstack_anchor_attempts"),
        ("sat", "fullstack_sat_anchor_attempts"),
        ("nat", "fullstack_nat_anchor_attempts"),
    ):
        if anchor_skips[family] > scalar_counters[attempts_key]:
            raise ValueError(f"DBlock {family} anchor spike skips exceed attempts")

    no_crop_consecutive = _dblock_require_exact_int(
        snapshot.get("fullstack_nat_anchor_no_valid_crop_consecutive"),
        "DBlock fullstack_nat_anchor_no_valid_crop_consecutive",
        minimum=0, maximum=attempt_step,
    )
    no_crop_total = _dblock_require_exact_int(
        snapshot.get("fullstack_nat_anchor_no_valid_crop_total"),
        "DBlock fullstack_nat_anchor_no_valid_crop_total",
        minimum=0, maximum=attempt_step,
    )
    if no_crop_consecutive > no_crop_total:
        raise ValueError("DBlock consecutive NAT no-crop count exceeds total")
    if no_crop_total > scalar_counters["fullstack_nat_anchor_attempts"]:
        raise ValueError("DBlock NAT no-crop total exceeds anchor attempts")
    if no_crop_consecutive > current_failure_streak:
        raise ValueError(
            "DBlock consecutive NAT no-crop count exceeds current failure streak"
        )
    if current_objective != "nat" and no_crop_consecutive != 0:
        raise ValueError(
            "DBlock consecutive NAT no-crop state may exist only on a NAT step"
        )
    accounted_anchor_attempts = {
        "ar": (
            scalar_counters["fullstack_anchor_runs"] + anchor_skips["ar"]
        ),
        "sat": (
            scalar_counters["fullstack_sat_anchor_runs"]
            + anchor_skips["sat"]
        ),
        "nat": (
            scalar_counters["fullstack_nat_anchor_runs"]
            + anchor_skips["nat"] + no_crop_total
        ),
    }
    overflow_anchor_attempts = 0
    for family, (attempt_key, _run_key) in anchor_run_bindings.items():
        extra = scalar_counters[attempt_key] - accounted_anchor_attempts[family]
        if extra < 0:
            raise ValueError(
                f"DBlock {family} anchor attempts are below runs/rejections"
            )
        overflow_anchor_attempts += extra
    if overflow_anchor_attempts != scalar_counters["optimizer_overflow_skips"]:
        raise ValueError(
            "DBlock anchor attempt surplus does not match optimizer overflow skips"
        )

    anchor_ema = snapshot.get("fullstack_anchor_spike_ema_by_family")
    if not isinstance(anchor_ema, dict) or not set(anchor_ema).issubset(objective_keys):
        raise ValueError("DBlock anchor spike EMA map has unknown families")
    normalized_anchor_ema = {
        family: _dblock_require_finite_number(
            value, f"DBlock fullstack_anchor_spike_ema_by_family.{family}",
            strictly_positive=True,
        )
        for family, value in anchor_ema.items()
    }
    expected_anchor_families = {
        family for family, run_key in (
            ("ar", "fullstack_anchor_runs"),
            ("sat", "fullstack_sat_anchor_runs"),
            ("nat", "fullstack_nat_anchor_runs"),
        )
        if scalar_counters[run_key] > 0
    }
    if set(normalized_anchor_ema) != expected_anchor_families:
        raise ValueError(
            "DBlock anchor EMA families do not exactly match committed anchor runs"
        )
    for family, run_key in (
        ("ar", "fullstack_anchor_runs"),
        ("sat", "fullstack_sat_anchor_runs"),
        ("nat", "fullstack_nat_anchor_runs"),
    ):
        if scalar_counters[run_key] > 0 and family not in normalized_anchor_ema:
            raise ValueError(f"DBlock missing committed {family} anchor EMA")

    # Keep these local names intentionally referenced: they make the strict
    # validation coverage auditable and prevent future accidental removal.
    _ = (failures, last_seen, local_consecutive, supervised_by_block)
    _dblock_json_copy(snapshot)
    return snapshot


def _dblock_restore_resume_state(state, payload, checkpoint_step, args):
    if payload is None:
        if int(checkpoint_step) != int(globals().get("_AGILLM43_REPAIR_BASE_STEP", 0)):
            raise ValueError("child repair checkpoint is missing DBlock resume state")
        return state
    snapshot = _dblock_validate_resume_payload(
        payload, checkpoint_step, args=args, expected_assign=state.get("assign"))
    for key in _DBLOCK_RESUME_KEYS:
        if key in snapshot:
            state[key] = copy.deepcopy(snapshot[key])
    state["last_update_trained"] = False
    print(
        f"[dblock-resume] restored committed_step={int(state.get('step', 0))} "
        f"attempt_step={int(state.get('attempt_step', 0))} "
        f"next_block={int(state.get('step', 0)) % max(1, int(state.get('B', 1)))}",
        flush=True,
    )
    return state


def _dblock_init(core, args):
    L = len(core.blocks)
    auto_search = getattr(args, "auto_dblock_search", False)
    
    if auto_search:
        candidates = _dblock_get_candidates(L)
        print(f"[dblock] Auto Search enabled with {len(candidates)} candidates.")
        B, asg, name = candidates[0]
        state = {
            "auto_search": True,
            "candidates": candidates,
            "candidate_idx": 0,
            "search_step": 0,
            "search_interval": 20,
            "scores": [],
        }
    else:
        requested_span = max(0, int(getattr(args, "dblock_layers_per_update", 0) or 0))
        if requested_span > 0:
            requested_span = min(requested_span, L)
            asg = [list(range(start, min(L, start + requested_span)))
                   for start in range(0, L, requested_span)]
            B = len(asg)
            setattr(args, "dblock_blocks", int(B))
            print(
                f"[dblock] exact granularity request: layers_per_update={requested_span} "
                f"-> blocks={B}",
                flush=True,
            )
        else:
            B = int(getattr(args, "dblock_blocks", 4))
            sp = max(1, L // B)
            asg = [list(range(i * sp, (i + 1) * sp)) for i in range(B)]
            asg[-1] = list(range((B - 1) * sp, L))
        state = {"auto_search": False}

    sigma_cfg = _dblock_sigma_config(args)
    requested_sigma_max = float(getattr(args, "dblock_sigma_max", 80.0) or 80.0)
    if abs(float(sigma_cfg[1]) - requested_sigma_max) > 1e-12:
        print(
            f"[dblock-sigma-cap] requested_max={requested_sigma_max:.6g} "
            f"effective_max={float(sigma_cfg[1]):.6g} blocks={B} "
            f"repair_mode={bool(getattr(args, 'repair_mode', False))}",
            flush=True,
        )
    bsig = _block_sigmas(B, *sigma_cfg)
    schedule = getattr(args, "dblock_schedule", "loss_balanced")
    print(f"[dblock] DiffusionBlocks mode: {L} layers -> {B} blocks {asg}")
    print(f"[dblock] schedule={schedule} sigma boundaries: {[round(x, 3) for x in bsig]}")
    train_span = int(getattr(args, "dblock_train_layers_per_update", 0) or 0)
    train_sublayer_span = int(getattr(args, "dblock_train_sublayers_per_update", 0) or 0)
    if train_sublayer_span not in (0, 1):
        raise RuntimeError("--dblock_train_sublayers_per_update must be 0 or 1")
    if train_sublayer_span == 1:
        if train_span != 1:
            raise RuntimeError(
                "safe one-sublayer training currently requires --dblock_train_layers_per_update 1"
            )
        if _dblock_sublayer_base_mode(args) not in {"off", "full"}:
            raise RuntimeError(
                "safe one-sublayer training requires --dblock_sublayer_mode off/full"
            )
        print(
            "[dblock-train-granularity] train_sublayers_per_update=1 "
            f"policy={str(getattr(args, 'dblock_train_sublayer_policy', 'cyclic'))} "
            "full_forward=True targets_per_model_sweep=56 selective_checkpoint_recompute_freeze=v27.12",
            flush=True,
        )
    if train_span > 0:
        min_forward_span = min(len(group) for group in asg) if asg else 0
        if train_span > min_forward_span:
            raise ValueError(
                f"local-gradient span {train_span} exceeds smallest forward context {min_forward_span}; "
                "forward topology is checkpoint semantics and requires an explicit migration"
            )
        if getattr(core, "hc", None) is not None and train_span < min_forward_span:
            raise RuntimeError("selective local-layer gradients are not yet defined for Hyper-Connections")
        print(
            f"[dblock-train-contract] forward_blocks={B} "
            f"forward_spans={[len(group) for group in asg]} "
            f"train_layers_per_update={train_span} "
            f"policy={str(getattr(args, 'dblock_train_layer_policy', 'cyclic'))} "
            "forward_topology_unchanged=True", flush=True,
        )
    
    state.update({
        "B": B,
        "assign": asg,
        "bsig": bsig,
        "step": 0,
        "attempt_step": 0,
        "counts": [0 for _ in range(B)],
        "attempt_counts": [0 for _ in range(B)],
        "failure_streak": [0 for _ in range(B)],
        "loss_ema": [None for _ in range(B)],
        "loss_best": [None for _ in range(B)],
        "loss_ema_by_objective": {},
        "spike_ema_by_objective": {},
        "spike_block_ema_by_objective": {},
        "fullstack_anchor_spike_ema_by_family": {},
        "fullstack_anchor_spike_skips_by_family": {"ar": 0, "sat": 0, "nat": 0},
        "fullstack_anchor_spike_consecutive_by_family": {"ar": 0, "sat": 0, "nat": 0},
        "local_spike_consecutive_by_objective_block": {
            "ar": [0 for _ in range(B)],
            "sat": [0 for _ in range(B)],
            "nat": [0 for _ in range(B)],
        },
        "fullstack_nat_anchor_no_valid_crop_consecutive": 0,
        "fullstack_nat_anchor_no_valid_crop_total": 0,
        "last_seen": [-1 for _ in range(B)],
        "supervised_targets": {
            "ar": 0, "sat": 0, "nat": 0,
            "fullstack_ar": 0, "fullstack_sat": 0, "fullstack_nat": 0,
        },
        "supervised_targets_by_block": {
            "ar": [0 for _ in range(B)],
            "sat": [0 for _ in range(B)],
            "nat": [0 for _ in range(B)],
        },
        "committed_objective_steps": {"ar": 0, "sat": 0, "nat": 0},
        "committed_objective_steps_by_block": {
            "ar": [0 for _ in range(B)],
            "sat": [0 for _ in range(B)],
            "nat": [0 for _ in range(B)],
        },
        "fullstack_anchor_attempts": 0,
        "fullstack_anchor_runs": 0,
        "fullstack_anchor_skipped_empty_mask": 0,
        "fullstack_sat_anchor_attempts": 0,
        "fullstack_sat_anchor_runs": 0,
        "fullstack_sat_anchor_skipped_empty_mask": 0,
        "fullstack_sat_anchor_skipped_overlap": 0,
        "fullstack_sat_anchor_skipped_short": 0,
        "fullstack_nat_anchor_attempts": 0,
        "fullstack_nat_anchor_runs": 0,
        "fullstack_nat_anchor_skipped_empty_mask": 0,
        "fullstack_nat_anchor_skipped_overlap": 0,
        "fullstack_nat_anchor_skipped_short": 0,
        "optimizer_overflow_skips": 0,
        "sat_variable_gate_committed": {
            "updates": 0, "blocks": 0, "stride2_labels": 0,
            "predicted_stride2": 0, "false_accepts": 0,
            "correct": 0, "loss_times_blocks": 0.0,
            "mean_ce": 0.0, "confusion": [[0, 0], [0, 0]],
        },
    })
    if bool(getattr(args, "dblock_looped", False)):
        loop_layers = int(getattr(args, "dblock_loop_layers", 0) or 0)
        if loop_layers <= 0:
            loop_layers = max(1, L // max(1, B))
        loop_layers = max(1, min(loop_layers, L))
        loop_start = max(0, min(int(getattr(args, "dblock_loop_start", 0) or 0), L - loop_layers))
        loop_group = list(range(loop_start, loop_start + loop_layers))
        if not hasattr(core, "dblock_loop_embed"):
            d = int(getattr(core.emb, "embedding_dim", 0))
            core.dblock_loop_embed = nn.Embedding(B, d).to(core.emb.weight.device)
            nn.init.normal_(core.dblock_loop_embed.weight, mean=0.0, std=0.02)
        state.update({
            "looped": True,
            "loop_group": loop_group,
            "loop_layers": loop_layers,
            "loop_start": loop_start,
        })
        print(
            f"[dblock-looped] enabled: shared_layers={loop_group} bands={B} "
            f"unrolled_depth={loop_layers * B} one-band-per-step no_bptt=True",
            flush=True,
        )
    _dblock_router_boot(state, args, ctx_dim=int(getattr(core.emb, "embedding_dim", 0)) or None)
    if bool(getattr(args, "repair_mode", False)):
        _dblock_restore_resume_state(
            state,
            getattr(args, "_repair_dblock_resume_state", None),
            int(getattr(args, "_repair_resume_checkpoint_step", 0) or 0),
            args,
        )
    elif hasattr(args, "_continuation_resume_checkpoint_step"):
        _continuation_restore_dblock_state(
            state,
            getattr(args, "_continuation_dblock_resume_state", None),
            int(getattr(args, "_continuation_resume_checkpoint_step", 0) or 0),
            getattr(args, "_continuation_training_profile", ""),
            args=args,
        )
        _dblock_router_restore_checkpoint(
            state,
            args,
            getattr(args, "_continuation_dblock_router_state", None),
            int(getattr(args, "_continuation_resume_checkpoint_step", 0) or 0),
            getattr(args, "_continuation_training_profile", ""),
        )
    _dblock_target_route_boot(
        state,
        args,
        getattr(args, "_continuation_dblock_target_route_state", None),
        int(getattr(args, "_continuation_resume_checkpoint_step", 0) or 0),
    )
    return state


def _choose_block(state, args):
    if (not bool(getattr(args, "repair_mode", False))
            and not state.get("auto_search", False)
            and int(getattr(args, "dblock_layers_per_update", 0) or 0) <= 0
            and state.get("step", 0) % 100 == 0):
        try:
            cfg = get_hot_config()
            # Topology is never mutable in-process. A block-count/assignment
            # change requires a versioned checkpoint migration.
            if False and "dblock_blocks" in cfg:
                new_B = int(cfg["dblock_blocks"])
                if new_B != state.get("B"):
                    L = sum(len(x) for x in state["assign"]) if "assign" in state else 28
                    new_sp = max(1, L // new_B)
                    new_asg = [list(range(i * new_sp, (i + 1) * new_sp)) for i in range(new_B)]
                    new_asg[-1] = list(range((new_B - 1) * new_sp, L))
                    
                    print(f"[dblock] Dynamically adjusting block configuration from hot_config: B={state['B']} -> {new_B}, assign={new_asg}", flush=True)
                    state["B"] = new_B
                    state["assign"] = new_asg
                    state["bsig"] = _block_sigmas(new_B, *_dblock_sigma_config(args))
                    state["counts"] = [0] * new_B
                    state["attempt_counts"] = [0] * new_B
                    state["failure_streak"] = [0] * new_B
                    state["loss_ema"] = [None] * new_B
                    state["loss_best"] = [None] * new_B
                    state["loss_ema_by_objective"] = {}
                    state["last_seen"] = [-1] * new_B
        except Exception as e:
            print(f"[dblock] Error reloading hot_config in _choose_block: {e}", flush=True)

    if state.get("auto_search", False) and state["candidate_idx"] < len(state["candidates"]):
        state["search_step"] += 1
        if "search_start_time" not in state:
            state["search_start_time"] = time.perf_counter()
            state["search_tokens"] = 0
            
        if state["search_step"] >= state["search_interval"]:
            valid_emas = [e for e in state["loss_ema"] if e is not None]
            avg_loss = sum(valid_emas) / max(1, len(valid_emas)) if valid_emas else float('inf')
            
            elapsed = time.perf_counter() - state["search_start_time"]
            tokens = state.get("search_tokens", 0)
            tokps = tokens / max(1e-9, elapsed)
            
            cand = state["candidates"][state["candidate_idx"]]
            cand_name = cand[2] if len(cand) > 2 else f"Candidate-{state['candidate_idx']}"
            
            state["scores"].append({
                "idx": state["candidate_idx"],
                "B": state["B"],
                "assign": state["assign"],
                "name": cand_name,
                "loss": avg_loss,
                "tokps": tokps
            })
            print(f"[dblock] Candidate {state['candidate_idx']} ({cand_name}) complete: loss={avg_loss:.4f} speed={tokps:.1f} tok/s", flush=True)
            
            state["candidate_idx"] += 1
            state["search_step"] = 0
            if "search_start_time" in state:
                del state["search_start_time"]
            state["search_tokens"] = 0
            
            if state["candidate_idx"] < len(state["candidates"]):
                B, asg, cand_name = state["candidates"][state["candidate_idx"]]
                state["B"] = B
                state["assign"] = asg
                state["bsig"] = _block_sigmas(B, *_dblock_sigma_config(args))
                state["counts"] = [0] * B
                state["attempt_counts"] = [0] * B
                state["failure_streak"] = [0] * B
                state["loss_ema"] = [None] * B
                state["loss_best"] = [None] * B
                state["loss_ema_by_objective"] = {}
                state["last_seen"] = [-1] * B
                print(f"[dblock] Switched to candidate {state['candidate_idx']} ({cand_name}): {B} blocks {asg}", flush=True)
            else:
                # Select the candidate with highest speed/loss utility
                best_cand = None
                best_utility = -1.0
                for score_entry in state["scores"]:
                    loss = score_entry["loss"]
                    tokps = score_entry["tokps"]
                    utility = tokps / max(1e-3, loss)
                    score_entry["utility"] = utility
                    if utility > best_utility:
                        best_utility = utility
                        best_cand = score_entry
                
                B = best_cand["B"]
                asg = best_cand["assign"]
                state["B"] = B
                state["assign"] = asg
                state["bsig"] = _block_sigmas(B, *_dblock_sigma_config(args))
                state["counts"] = [0] * B
                state["attempt_counts"] = [0] * B
                state["failure_streak"] = [0] * B
                state["loss_ema"] = [None] * B
                state["loss_best"] = [None] * B
                state["loss_ema_by_objective"] = {}
                state["last_seen"] = [-1] * B
                state["auto_search"] = False
                print(f"[dblock] Search complete. Locked in best candidate {best_cand['name']} (Utility={best_utility:.2f}, Loss={best_cand['loss']:.4f}, Speed={best_cand['tokps']:.1f} tok/s): {B} blocks {asg}", flush=True)
    B = state["B"]
    schedule = str(getattr(args, "dblock_schedule", "loss_balanced") or "loss_balanced").lower()
    step = int(state.get("step", 0))
    counts = state.setdefault("counts", [0 for _ in range(B)])
    attempts = state.setdefault("attempt_counts", [0 for _ in range(B)])
    failures = state.setdefault("failure_streak", [0 for _ in range(B)])
    emas = state.setdefault("loss_ema", [None for _ in range(B)])
    bests = state.setdefault("loss_best", [None for _ in range(B)])
    last_seen = state.setdefault("last_seen", [-1 for _ in range(B)])
    for arr, fill in ((counts, 0), (attempts, 0), (failures, 0), (emas, None), (bests, None), (last_seen, -1)):
        if len(arr) != B:
            arr[:] = [fill for _ in range(B)]
    state["router_last"] = None
    state["fleet_router_last"] = None
    if schedule == "random":
        return random.randrange(B)
    if schedule == "roundrobin":
        return step % B

    def least_trained():
        # Allocate compute by attempted updates, not successful commits. A band
        # that fails is retried once in the next fair rotation instead of being
        # selected forever because its successful count cannot rise. Successful
        # counts remain separate evidence of whether the band is actually learning.
        return min(range(B), key=lambda i: (attempts[i], counts[i], last_seen[i], i))

    if schedule == "balanced":
        return least_trained()

    explore = max(0.0, min(1.0, float(getattr(args, "dblock_explore", 0.05))))
    warmup = int(getattr(args, "dblock_warmup_steps", max(8, B * 2)))

    if step < warmup or any(a == 0 for a in attempts):
        return least_trained()

    max_stale = int(getattr(args, "dblock_max_stale_steps", 64) or 0)
    stale = [step - last_seen[i] if last_seen[i] >= 0 else step + 1 for i in range(B)]
    if max_stale > 0 and max(stale) >= max_stale:
        return max(range(B), key=lambda i: (stale[i], -attempts[i], -i))

    max_count = max(attempts) if attempts else 0
    min_count = min(attempts) if attempts else 0
    max_skew = float(getattr(args, "dblock_max_count_skew", 1.35) or 0.0)
    if max_skew > 1.0 and min_count > 0 and (max_count / max(1, min_count)) > max_skew:
        return least_trained()

    if explore > 0.0 and random.random() < explore:
        return least_trained()

    stale_bonus = float(getattr(args, "dblock_stale_bonus", 0.35) or 0.0)
    undertrain_bonus = float(getattr(args, "dblock_undertrain_bonus", 0.25) or 0.0)
    stale_denom = float(max(1, max_stale if max_stale > 0 else max(stale) if stale else 1))
    count_denom = float(max(1, max_count))

    def score(i):
        # Raw CE is not comparable across sigma bands. Score only regression
        # relative to each band's own best EMA, then add explicit coverage terms.
        if emas[i] is None or bests[i] is None or float(bests[i]) <= 0.0:
            loss_score = 0.0
        else:
            loss_score = max(0.0, float(emas[i]) / max(1e-6, float(bests[i])) - 1.0)
        stale_score = stale_bonus * min(1.0, max(0.0, stale[i] / stale_denom))
        undertrain_score = undertrain_bonus * max(0.0, (max_count - attempts[i]) / count_denom)
        return (loss_score + stale_score + undertrain_score, -attempts[i], stale[i], -i)

    base_scores = [float(score(i)[0]) for i in range(B)]
    route_scores = _dblock_fleet_router_scores(state, args, base_scores) or base_scores
    if route_scores is base_scores:
        heuristic_choice = max(range(B), key=score)
    else:
        heuristic_choice = max(range(B), key=lambda i: (route_scores[i], -attempts[i], stale[i], -i))
    learned_choice = _dblock_router_choose(
        state, args, route_scores, heuristic_choice=heuristic_choice
    )
    return heuristic_choice if learned_choice is None else learned_choice


def _sample_sigma(ids, lo, hi, args, state):
    cur_step = int(state.get("step", 0))
    curriculum = int(getattr(args, "dblock_sigma_curriculum_steps", 0))
    if curriculum > 0:
        frac = min(1.0, max(0.05, (cur_step + 1) / float(curriculum)))
        hi = lo * ((hi / max(lo, 1e-8)) ** frac)
    mode = str(getattr(args, "dblock_sigma_sampling", "lognormal") or "lognormal").lower()
    if mode in {"lognormal", "truncated_lognormal", "edm"}:
        _, _, pm, ps = _dblock_sigma_config(args)
        qa = _cdf((math.log(max(lo, 1e-6)) - pm) / ps)
        qb = _cdf((math.log(max(hi, lo * 1.0001)) - pm) / ps)
        qa = min(max(qa, 1e-7), 1.0 - 1e-7)
        qb = min(max(qb, qa + 1e-7), 1.0 - 1e-7)
        n = int(ids.size(0))
        if bool(getattr(args, "dblock_sigma_stratified", True)) and n > 1:
            # Beyond the DBT paper: randomized quantile strata reduce Monte Carlo
            # variance of the conditional p_noise integral for each block.
            u = (torch.arange(n, device=ids.device, dtype=torch.float32) + torch.rand((), device=ids.device)) / float(n)
            u = u.index_select(0, torch.randperm(n, device=ids.device))
        else:
            u = torch.rand(n, device=ids.device, dtype=torch.float32)
        q = qa + (qb - qa) * u
        q = q.clamp(1e-7, 1.0 - 1e-7)
        z = torch.erfinv(2.0 * q - 1.0) * math.sqrt(2.0)
        return torch.exp(torch.tensor(pm, device=ids.device, dtype=torch.float32) + float(ps) * z)
    sig_np = np.exp(
        np.random.uniform(
            math.log(max(lo, 1e-4)),
            math.log(max(hi, lo + 1e-4)),
            ids.size(0),
        ).astype("float32")
    )
    return torch.from_numpy(sig_np).to(ids.device)


def _maybe_log(
    state,
    args,
    bi,
    layers,
    ar_val,
    sat_val,
    nat_val,
    total_val,
    peak_alloc,
    peak_reserved,
    objective=None,
    raw_avg=None,
    raw_total=None,
    edm_weight=None,
):
    log_every = int(getattr(args, "dblock_log_every", 50))
    step = int(state.get("step", 0))
    if log_every <= 0 or step % log_every != 0:
        return
    counts_list = state.get("counts", [])
    last_seen = state.get("last_seen", [-1 for _ in counts_list])
    counts = ",".join(str(x) for x in counts_list)
    emas = ",".join("nan" if x is None else f"{x:.2f}" for x in state.get("loss_ema", []))
    stale = ",".join(str(max(0, step - int(last_seen[i]))) for i in range(min(len(counts_list), len(last_seen))))
    mem = ""
    if peak_alloc is not None:
        mem = f" peak_alloc={peak_alloc:.2f}GB peak_reserved={peak_reserved:.2f}GB"
    display = float(raw_avg) if raw_avg is not None and math.isfinite(float(raw_avg)) else float(total_val)
    raw_part = ""
    if raw_total is not None:
        raw_part += f" raw_sum={float(raw_total):.3f}"
    if edm_weight is not None:
        raw_part += f" edm_w={float(edm_weight):.3f}"
    supervised = state.get("supervised_targets", {})
    if supervised:
        raw_part += (
            f" sup=[ar:{int(supervised.get('ar', 0))},sat:{int(supervised.get('sat', 0))},"
            f"nat:{int(supervised.get('nat', 0))},fsar:{int(supervised.get('fullstack_ar', 0))}]"
        )
    route = state.get("router_last")
    if isinstance(route, dict):
        pred = ",".join(f"{float(x):.2f}" for x in route.get("pred", []))
        hist = route.get("history")
        hist_part = "" if hist is None else f" hist={int(hist)}"
        raw_part += (
            f" router={route.get('mode', 'none')} blend={float(route.get('blend', 0.0)):.2f}{hist_part} "
            f"policy={route.get('policy_choice')} shadow={route.get('shadow_choice')} "
            f"agree={route.get('agreement')} pred=[{pred}]"
        )
    rloss = state.get("router_train_loss")
    if rloss is not None:
        samples = int(state.get("router_shadow_samples", 0))
        mae = state.get("router_shadow_mae_ema")
        base_mae = state.get("router_shadow_baseline_mae_ema")
        total_choices = max(1, int(state.get("router_shadow_choice_total", 0)))
        agreement = int(state.get("router_shadow_choice_agreement", 0)) / total_choices
        raw_part += (
            f" router_fit={float(rloss):.3f} router_n={samples} "
            f"router_mae={float(mae) if mae is not None else float('nan'):.3f} "
            f"router_zero_mae={float(base_mae) if base_mae is not None else float('nan'):.3f} "
            f"router_agree={agreement:.3f} router_ready={bool(state.get('router_shadow_ready', False))}"
        )
    fleet = state.get("fleet_router_last")
    if isinstance(fleet, dict):
        fbias = fleet.get("bias", [])
        top = []
        try:
            top = sorted(range(len(fbias)), key=lambda j: abs(float(fbias[j])), reverse=True)[:3]
        except Exception:
            top = []
        top_part = ",".join(f"{j}:{float(fbias[j]):+.2f}" for j in top)
        raw_part += f" fleet={fleet.get('lane', '')} role={fleet.get('role', '')} strength={float(fleet.get('strength', 0.0)):.2f}"
        if top_part:
            raw_part += f" fleet_bias=[{top_part}]"
    print(
        f"[dblock] step={step} block={bi} obj={objective or 'mixed'} layers={layers} "
        f"loss={display:.3f} weighted={total_val:.3f} ar={ar_val:.3f} sat={sat_val:.3f} nat={nat_val:.3f}"
        f"{raw_part} counts=[{counts}] ema=[{emas}] stale=[{stale}]{mem}",
        flush=True,
    )


def _update_stats(state, bi, loss_value, args=None, objective="mixed", trained=True):
    """Record one attempted band update using raw predictive CE.

    Sigma bands have different irreducible losses, so weighted EDM loss is never
    used for cross-band scheduling. `counts` means successful optimizer commits;
    failed/non-finite/AMP-skipped attempts advance age and failure credit only.
    """
    B = int(state["B"])
    idx = int(bi)
    counts = state.setdefault("counts", [0 for _ in range(B)])
    attempts = state.setdefault("attempt_counts", [0 for _ in range(B)])
    failures = state.setdefault("failure_streak", [0 for _ in range(B)])
    emas = state.setdefault("loss_ema", [None for _ in range(B)])
    bests = state.setdefault("loss_best", [None for _ in range(B)])
    last_seen = state.setdefault("last_seen", [-1 for _ in range(B)])
    for arr, fill in ((counts, 0), (attempts, 0), (failures, 0), (emas, None), (bests, None), (last_seen, -1)):
        if len(arr) != B:
            arr[:] = [fill for _ in range(B)]

    step = int(state.get("step", 0))
    attempt_step = int(state.get("attempt_step", 0))
    attempts[idx] += 1
    last_seen[idx] = step
    try:
        value = float(loss_value)
        finite = math.isfinite(value)
    except Exception:
        value = float("nan")
        finite = False
    committed = bool(trained and finite)
    objective = str(objective or "mixed").lower()

    if committed:
        prior_best = bests[idx]
        relative = value / max(
            1e-6, float(prior_best) if prior_best is not None else value
        )
        counts[idx] += 1
        failures[idx] = 0
        beta = 0.96
        prev = emas[idx]
        emas[idx] = value if prev is None else beta * float(prev) + (1.0 - beta) * value
        bests[idx] = value if bests[idx] is None else min(float(bests[idx]), float(emas[idx]))
        by_obj = state.setdefault("loss_ema_by_objective", {})
        obj_arr = by_obj.setdefault(objective, [None for _ in range(B)])
        if len(obj_arr) != B:
            obj_arr[:] = [None for _ in range(B)]
        prev_obj = obj_arr[idx]
        obj_arr[idx] = value if prev_obj is None else beta * float(prev_obj) + (1.0 - beta) * value
        if args is not None:
            _dblock_router_update(state, args, idx, relative)
    else:
        failures[idx] = min(B * 4, int(failures[idx]) + 1)

    state["last_objective"] = objective
    state["last_update_trained"] = committed
    state["last_raw_ce"] = value
    state["attempt_step"] = attempt_step + 1
    if committed:
        state["step"] = step + 1


def _activation_offload_enabled(args):
    return bool(getattr(args, "dblock_activation_offload", False)) and torch.cuda.is_available()


def _activation_offload_hooks(args):
    min_bytes = int(float(getattr(args, "dblock_activation_offload_min_mb", 1.0) or 1.0) * 1024 * 1024)

    def pack(t):
        if not torch.is_tensor(t) or not t.is_cuda or not t.is_floating_point() or t.numel() * t.element_size() < min_bytes:
            return t
        return ("cpu_offload", t.device, t.detach().to("cpu", non_blocking=True))

    def unpack(x):
        if isinstance(x, tuple) and len(x) == 3 and x[0] == "cpu_offload":
            _, dev, cpu_t = x
            return cpu_t.to(dev, non_blocking=True)
        return x

    return torch.autograd.graph.saved_tensors_hooks(pack, unpack)


def _dblock_sublayer_base_mode(args):
    mode = str(getattr(args, "dblock_sublayer_mode", "off") or "off").strip().lower().replace("-", "_")
    if mode in {"none", "disabled"}:
        return "off"
    return mode


def _dblock_sublayer_mode_for_layer(args, state, block_idx, layer_pos):
    mode = _dblock_sublayer_base_mode(args)
    if mode == "split_alt":
        step = int((state or {}).get("step", 0))
        return "attn_only" if ((step + int(block_idx) + int(layer_pos)) % 2 == 0) else "ffn_only"
    if mode == "cycle":
        step = int((state or {}).get("step", 0))
        return ("full", "ffn_only", "attn_only")[(step + int(block_idx) + int(layer_pos)) % 3]
    return mode


def _run_block_forward(block, x, mask, sublayer_mode="off"):
    mode = str(sublayer_mode or "off").strip().lower().replace("-", "_")
    if mode in {"off", "full"}:
        return block(x, mask)
    if mode == "attn_only":
        n = x.size(1)
        return x + block.mha(block.ln1(x), mask, rel_bias_tokens=n)
    if mode == "ffn_only":
        return x + block.ff(block.ln2(x))
    raise ValueError(f"unknown DBlock sublayer mode: {sublayer_mode}")


def _run_block(block, x, mask, use_checkpoint, args=None, sublayer_mode="off", train_sublayer="full"):
    train_sublayer = str(train_sublayer or "full").lower()
    if use_checkpoint:
        if train_sublayer != "full":
            # The outer local-span forward freezes the sibling sublayer for the
            # original forward. Non-reentrant checkpointing later recomputes the
            # block during backward, after the outer scope has restored normal
            # requires_grad flags. Re-freeze the sibling inside *every* checkpoint
            # invocation so recomputation cannot resurrect its parameter grads.
            def _selected_sublayer_recompute(y, block=block, mode=sublayer_mode, selected=train_sublayer):
                snapshots = _dblock_freeze_unselected_sublayer(block, selected)
                try:
                    return _run_block_forward(block, y, mask, mode)
                finally:
                    for param, original in snapshots:
                        param.requires_grad_(original)
            return _ck.checkpoint(_selected_sublayer_recompute, x, use_reentrant=False)
        return _ck.checkpoint(lambda y, block=block, mode=sublayer_mode: _run_block_forward(block, y, mask, mode), x, use_reentrant=False)
    if args is not None and _activation_offload_enabled(args):
        with _activation_offload_hooks(args):
            return _run_block_forward(block, x, mask, sublayer_mode)
    return _run_block_forward(block, x, mask, sublayer_mode)


def _dblock_checkpoint_this_layer(args, base_enabled, layer_pos, layer_count=None):
    if not base_enabled:
        return False
    pos = int(layer_pos)
    count = int(layer_count or 0)
    skip_tail = max(0, int(getattr(args, "dblock_checkpoint_skip_tail", 0) or 0))
    if skip_tail > 0 and count > 0 and pos >= max(0, count - skip_tail):
        return False
    stride = int(getattr(args, "dblock_checkpoint_stride", 1) or 1)
    if stride <= 0:
        return False
    if stride == 1:
        return True
    return (pos % stride) == 0


def _dblock_loop_condition(core, h, block_idx, args):
    emb = getattr(core, "dblock_loop_embed", None)
    if emb is None:
        return h
    idx = torch.tensor([int(block_idx)], device=h.device, dtype=torch.long)
    cond = emb(idx).to(dtype=h.dtype).view(1, 1, -1)
    return h + float(getattr(args, "dblock_loop_cond_scale", 1.0) or 0.0) * cond


def _maybe_register_looped_infer(core, sd, args):
    """Looped checkpoints carry 'dblock_loop_embed.weight' in their core state.
    Recreate the matching embedding on the inference core (so the strict core load
    accepts it) and flip args into looped mode so the EDM block-chain decodes
    through the single shared looped group with loop-index conditioning."""
    core_sd = sd.get("core") if isinstance(sd, dict) else None
    if not isinstance(core_sd, dict):
        return
    w = core_sd.get("dblock_loop_embed.weight")
    if w is None:
        return
    if str(sd.get("repair_schema") or "") == _AGILLM_REPAIR_SCHEMA:
        raise RuntimeError(
            "repair checkpoint loop embedding contradicts non-looped execution contract")
    bands = int(w.shape[0])
    d = int(getattr(core.emb, "embedding_dim", 0)) or int(w.shape[1])
    if not hasattr(core, "dblock_loop_embed"):
        core.dblock_loop_embed = nn.Embedding(bands, d).to(core.emb.weight.device)
    try:
        setattr(args, "dblock_looped", True)
        setattr(args, "dblock_blocks", bands)
    except Exception:
        pass
    print("[dblock-looped] inference: shared looped group, bands=%d" % bands, flush=True)


def _sample_token_loss_inputs(hidden, targets, max_tokens, loss_mask=None):
    max_tokens = int(max_tokens or 0)
    flat_targets = targets.reshape(-1)
    total = int(flat_targets.numel())
    flat_hidden = hidden.reshape(total, hidden.size(-1))
    if loss_mask is not None:
        mask = loss_mask.reshape(-1).to(device=targets.device, dtype=torch.bool)
        if int(mask.numel()) != total:
            raise ValueError(f"loss_mask size {int(mask.numel())} does not match targets {total}")
        keep = torch.nonzero(mask, as_tuple=False).flatten()
        flat_hidden = flat_hidden.index_select(0, keep)
        flat_targets = flat_targets.index_select(0, keep)
        total = int(flat_targets.numel())
    if total <= 0:
        raise ValueError("no target tokens selected for loss")
    if max_tokens <= 0 or total <= max_tokens:
        return flat_hidden.contiguous(), flat_targets.contiguous(), total, total
    # With-replacement sampling avoids building a full randperm each step; the sampled
    # mean remains an unbiased estimator of the selected token CE mean.
    idx = torch.randint(total, (max_tokens,), device=flat_targets.device)
    return flat_hidden.index_select(0, idx).contiguous(), flat_targets.index_select(0, idx).contiguous(), int(max_tokens), total


def _sample_sat_pair_loss_inputs(hidden, targets, max_tokens, loss_mask=None, block=2):
    """Sample complete SAT output blocks instead of unrelated flat tokens.

    Fixed SAT emits ``block`` adjacent targets from one visible block.  Sampling
    individual flattened tokens breaks that unit and adds avoidable variance,
    especially around document boundaries.  This keeps every selected SAT pair
    intact while retaining the same with-replacement, unbiased CE estimator and
    the same maximum token budget.
    """
    block = int(block or 0)
    if block <= 0:
        raise ValueError("SAT sampling block must be positive")
    if hidden.ndim != 3 or targets.ndim != 2:
        raise ValueError(
            f"SAT pair sampler expects hidden[B,T,D] and targets[B,T], got "
            f"{tuple(hidden.shape)} and {tuple(targets.shape)}"
        )
    if hidden.shape[:2] != targets.shape:
        raise ValueError(
            f"SAT pair sampler shape mismatch: hidden={tuple(hidden.shape)} "
            f"targets={tuple(targets.shape)}"
        )
    batch, seq, dim = hidden.shape
    usable = (int(seq) // block) * block
    if usable <= 0:
        raise ValueError("no complete SAT output block available for loss")
    pair_hidden = hidden[:, :usable].reshape(batch, usable // block, block, dim)
    pair_targets = targets[:, :usable].reshape(batch, usable // block, block)
    pair_valid = torch.ones(
        (batch, usable // block), device=targets.device, dtype=torch.bool
    )
    if loss_mask is not None:
        if loss_mask.shape != targets.shape:
            raise ValueError(
                f"SAT loss_mask shape {tuple(loss_mask.shape)} does not match "
                f"targets {tuple(targets.shape)}"
            )
        pair_valid &= loss_mask[:, :usable].to(
            device=targets.device, dtype=torch.bool
        ).reshape(batch, usable // block, block).all(dim=-1)
    flat_valid = torch.nonzero(pair_valid.reshape(-1), as_tuple=False).flatten()
    available_pairs = int(flat_valid.numel())
    if available_pairs <= 0:
        raise ValueError("no complete valid SAT output block selected for loss")
    max_tokens = int(max_tokens or 0)
    max_pairs = 0 if max_tokens <= 0 else max(1, max_tokens // block)
    if max_pairs <= 0 or available_pairs <= max_pairs:
        selected = flat_valid
    else:
        draw = torch.randint(
            available_pairs, (max_pairs,), device=flat_valid.device
        )
        selected = flat_valid.index_select(0, draw)
    flat_hidden = pair_hidden.reshape(-1, block, dim).index_select(0, selected)
    flat_targets = pair_targets.reshape(-1, block).index_select(0, selected)
    used_tokens = int(flat_targets.numel())
    available_tokens = int(available_pairs * block)
    return (
        flat_hidden.reshape(-1, dim).contiguous(),
        flat_targets.reshape(-1).contiguous(),
        used_tokens,
        available_tokens,
    )


def _choose_objectives(state, args, ar_weight, sat_weight, nat_weight, do_sat_periodic, do_nat_periodic):
    mode = str(getattr(args, "dblock_objective_mode", "periodic") or "periodic").lower()
    if mode == "committed_9_1_1":
        # A deterministic, versioned 9:1:1 AR/SAT/NAT schedule. Its 11-step
        # period is coprime with the 14-block round-robin, so every block sees
        # every family over 154 committed updates without RNG clustering.
        phase = (int(state.get("step", 0)) + 1) % 11
        picked = ("ar",) * 9 + ("sat", "nat")
        picked = picked[phase]
        enabled = {
            "ar": ar_weight > 0.0,
            "sat": sat_weight > 0.0 and do_sat_periodic,
            "nat": nat_weight > 0.0 and do_nat_periodic,
        }
        if not enabled[picked]:
            raise RuntimeError(
                f"committed 9:1:1 objective schedule selected disabled family {picked!r}"
            )
        return picked == "ar", picked == "sat", picked == "nat", picked
    if mode == "committed_cycle":
        # One-based phase matches the full-stack anchor scheduler. Since the
        # block round-robin has period 14 and this cycle has period 3, every
        # block receives AR, SAT and NAT exactly once per 42 committed updates.
        phase = (int(state.get("step", 0)) + 1) % 3
        picked = ("ar", "sat", "nat")[phase]
        enabled = {
            "ar": ar_weight > 0.0,
            "sat": sat_weight > 0.0 and do_sat_periodic,
            "nat": nat_weight > 0.0 and do_nat_periodic,
        }
        if not enabled[picked]:
            raise RuntimeError(f"committed objective cycle selected disabled family {picked!r}")
        return picked == "ar", picked == "sat", picked == "nat", picked
    if mode != "stochastic":
        return ar_weight > 0.0, sat_weight > 0.0 and do_sat_periodic, nat_weight > 0.0 and do_nat_periodic, "periodic"
    choices = []
    probs = []
    if ar_weight > 0.0:
        choices.append("ar")
        probs.append(max(0.0, _dblock_hot_float(args, "dblock_ar_prob", 0.80, min_value=0.0)))
    if sat_weight > 0.0 and not getattr(args, "ar_only", False):
        choices.append("sat")
        probs.append(max(0.0, _dblock_hot_float(args, "dblock_sat_prob", 0.10, min_value=0.0)))
    if nat_weight > 0.0 and not getattr(args, "ar_only", False):
        choices.append("nat")
        probs.append(max(0.0, _dblock_hot_float(args, "dblock_nat_prob", 0.10, min_value=0.0)))
    if not choices:
        return False, False, False, "none"
    total = sum(probs)
    if total <= 0.0:
        probs = [1.0 / len(choices) for _ in choices]
    else:
        probs = [p / total for p in probs]
    picked = random.choices(choices, weights=probs, k=1)[0]
    return picked == "ar", picked == "sat", picked == "nat", picked




def _dblock_clear_moe_aux_stash(model):
    """Clear detached MoE router inputs, including checkpoint recompute leftovers."""
    for module in model.modules():
        if hasattr(module, "last_router_input"):
            module.last_router_input = None


def _dblock_record_supervised(state, objective, used, block_idx=None):
    """Track actual CE target positions instead of only gross streamed tokens."""
    used = max(0, int(used or 0))
    obj = str(objective)
    totals = state.setdefault("supervised_targets", {})
    totals[obj] = int(totals.get(obj, 0)) + used
    if block_idx is None:
        return
    block_count = max(1, int(state.get("B", 1)))
    by_block = state.setdefault("supervised_targets_by_block", {})
    arr = list(by_block.get(obj, []))
    if len(arr) != block_count:
        arr = (arr + [0] * block_count)[:block_count]
    idx = int(block_idx)
    if 0 <= idx < block_count:
        arr[idx] = int(arr[idx]) + used
    by_block[obj] = arr


def _dblock_commit_supervised(
    state, block_idx, local_targets, anchor_info=None,
    sat_anchor_info=None, nat_anchor_info=None,
):
    """Commit target counters only after an optimizer update actually succeeds."""
    committed_steps = state.setdefault("committed_objective_steps", {})
    block_count = max(1, int(state.get("B", 1)))
    by_block_steps = state.setdefault("committed_objective_steps_by_block", {})
    for objective, used in dict(local_targets or {}).items():
        used = max(0, int(used or 0))
        if used <= 0:
            continue
        _dblock_record_supervised(state, objective, used, block_idx)
        committed_steps[objective] = int(committed_steps.get(objective, 0)) + 1
        arr = list(by_block_steps.get(objective, []))
        if len(arr) != block_count:
            arr = (arr + [0] * block_count)[:block_count]
        idx = int(block_idx)
        if 0 <= idx < block_count:
            arr[idx] = int(arr[idx]) + 1
        by_block_steps[objective] = arr
    anchor_specs = (
        (anchor_info or {}, "fullstack_ar", "fullstack_anchor_runs"),
        (sat_anchor_info or {}, "fullstack_sat", "fullstack_sat_anchor_runs"),
        (nat_anchor_info or {}, "fullstack_nat", "fullstack_nat_anchor_runs"),
    )
    for info, objective, run_counter in anchor_specs:
        if not (info.get("ran") and info.get("finite", False)):
            continue
        used = max(0, int(info.get("tokens", 0) or 0))
        if used > 0:
            _dblock_record_supervised(state, objective, used, block_idx=None)
            state[run_counter] = int(state.get(run_counter, 0)) + 1
        family = objective.removeprefix("fullstack_")
        ema_next = info.get("anchor_ema_next")
        if ema_next is not None and math.isfinite(float(ema_next)) and not info.get("spike", False):
            state.setdefault("fullstack_anchor_spike_ema_by_family", {})[family] = float(ema_next)
        if objective == "fullstack_sat":
            gate_info = info.get("sat_variable_gate") or {}
            if gate_info.get("applied", False):
                aggregate = state.setdefault("sat_variable_gate_committed", {
                    "updates": 0, "blocks": 0, "stride2_labels": 0,
                    "predicted_stride2": 0, "false_accepts": 0,
                    "correct": 0, "loss_times_blocks": 0.0,
                    "confusion": [[0, 0], [0, 0]],
                })
                blocks = int(gate_info.get("blocks", 0) or 0)
                aggregate["updates"] = int(aggregate.get("updates", 0)) + 1
                aggregate["blocks"] = int(aggregate.get("blocks", 0)) + blocks
                for key in ("stride2_labels", "predicted_stride2", "false_accepts", "correct"):
                    aggregate[key] = int(aggregate.get(key, 0)) + int(gate_info.get(key, 0) or 0)
                aggregate["loss_times_blocks"] = (
                    float(aggregate.get("loss_times_blocks", 0.0))
                    + float(gate_info.get("loss", 0.0) or 0.0) * blocks
                )
                confusion = gate_info.get("confusion") or [[0, 0], [0, 0]]
                for true_class in range(2):
                    for predicted_class in range(2):
                        aggregate["confusion"][true_class][predicted_class] += int(
                            confusion[true_class][predicted_class]
                        )
                aggregate["mean_ce"] = (
                    float(aggregate["loss_times_blocks"])
                    / max(1, int(aggregate["blocks"]))
                )
                aggregate["last"] = _dblock_json_copy(gate_info)
        if info.get("softcap_applied", False):
            counts = state.setdefault(
                "fullstack_anchor_softcap_commits_by_family",
                {"ar": 0, "sat": 0, "nat": 0},
            )
            counts[family] = int(counts.get(family, 0)) + 1
            removed = max(
                0.0,
                float(info.get("uncapped_weighted", 0.0) or 0.0)
                - float(info.get("weighted", 0.0) or 0.0),
            )
            totals = state.setdefault(
                "fullstack_anchor_softcap_removed_weighted_ce_by_family",
                {"ar": 0.0, "sat": 0.0, "nat": 0.0},
            )
            totals[family] = float(totals.get(family, 0.0)) + removed



def _dblock_fullstack_anchor_int(args, attr, default=0):
    cli = max(0, int(getattr(args, attr, default) or 0))
    if bool(getattr(args, "repair_mode", False)):
        return cli
    try:
        return _hot_int_from_config(get_hot_config(), [attr, attr.removeprefix("dblock_")], cli)
    except Exception:
        return cli


def _dblock_fullstack_anchor_signed_int(args, attr, default=0):
    """Integer which may use -1 as a sentinel; strict repair freezes the CLI contract."""
    cli = int(getattr(args, attr, default) if getattr(args, attr, default) is not None else default)
    if bool(getattr(args, "repair_mode", False)):
        return cli
    try:
        return int(_hot_int_from_config(get_hot_config(), [attr, attr.removeprefix("dblock_")], cli))
    except Exception:
        return cli


def _dblock_fullstack_anchor_due(step, every, offset=0):
    """Use one-based optimizer-step phases: offset=4 means steps 4,36,..."""
    every = max(0, int(every or 0))
    if every <= 0:
        return False
    return ((int(step) + 1) % every) == (int(offset) % every)


def _dblock_fullstack_aux_weight(args, attr):
    """Keep rare SAT/NAT composition anchors inside the reviewed 0.05-0.10 band."""
    requested = _dblock_hot_float(
        args, attr, 0.0,
        names=[attr, attr.removeprefix("dblock_")],
        min_value=0.0,
    )
    if requested <= 0.0:
        return 0.0
    # v27.16.6: hot-configurable ceiling (default 0.10 = the reviewed band; hard cap 3.0).
    ceiling = _dblock_hot_float(
        args, "dblock_fullstack_aux_weight_max", 0.10,
        names=["dblock_fullstack_aux_weight_max", "fullstack_aux_weight_max"],
        min_value=0.10, max_value=3.0,
    )
    return min(float(ceiling), max(0.05, float(requested)))


def _dblock_anchor_spike_probe(state, args, family, raw_ce):
    family = str(family).strip().lower()
    raw_ce = float(raw_ce)
    multiplier = float(getattr(args, "dblock_fullstack_anchor_spike_skip", 3.0) or 0.0)
    absolute_max = float(getattr(args, "dblock_fullstack_anchor_max_ce", 50.0) or 0.0)
    if not math.isfinite(raw_ce):
        return {"spike": False, "baseline": None, "ema_next": None,
                "multiplier": multiplier, "absolute_max": absolute_max,
                "reason": "nonfinite_handled_separately"}
    ema_map = state.get("fullstack_anchor_spike_ema_by_family", {})
    baseline = ema_map.get(family) if isinstance(ema_map, dict) else None
    if baseline is not None:
        baseline = float(baseline)
        if not math.isfinite(baseline) or baseline < 0.0:
            raise RuntimeError(f"invalid persisted {family} anchor spike EMA={baseline!r}")
    absolute_spike = absolute_max > 0.0 and raw_ce > absolute_max
    relative_spike = (
        baseline is not None and baseline > 1e-3
        and multiplier > 0.0 and raw_ce > multiplier * baseline
    )
    advisory_spike = bool(absolute_spike or relative_spike)
    # Full-stack anchors directly train the serving graph and can dominate the
    # much smaller local DBlock objective. Reject an outlier before backward;
    # the caller clears the local gradients and retries the same committed
    # objective/block on a fresh batch. This makes the CLI fuse contractual
    # instead of telemetry-only.
    spike = advisory_spike
    reason = (
        "absolute_max" if absolute_spike
        else "relative_ema" if relative_spike
        else "accepted"
    )
    # Cap the sample used for the EMA so one hard batch cannot poison the
    # diagnostic baseline for thousands of later updates.
    ema_sample = raw_ce if baseline is None else min(
        raw_ce, max(float(baseline) * 4.0, float(baseline) + 1.0)
    )
    ema_next = (
        ema_sample if baseline is None
        else 0.95 * float(baseline) + 0.05 * ema_sample
    )
    return {
        "spike": spike, "baseline": baseline, "ema_next": ema_next,
        "multiplier": multiplier, "absolute_max": absolute_max, "reason": reason,
        "advisory_spike": advisory_spike,
        "absolute_spike": bool(absolute_spike),
        "relative_spike": bool(relative_spike),
        "quality_gate_mode": "hard_reject",
    }



def _dblock_anchor_softcap_probe(state, args, family, raw_ce):
    """Continuously limit pathological composition-anchor gradients.

    This is deliberately not a sample, checkpoint, validation, or quality gate.
    The local DBlock objective and the hard example both remain in the optimizer
    step. Only the auxiliary anchor scalar is rescaled when its CE lies far
    outside the family's committed EMA. The detached multiplier changes no
    model parameters, optimizer tensors, or checkpoint layout.
    """
    family = str(family).strip().lower()
    if family not in {"ar", "sat", "nat"}:
        raise ValueError(f"unknown full-stack anchor family {family!r}")
    raw_ce = _dblock_require_finite_number(
        raw_ce, f"{family} full-stack anchor raw CE", minimum=0.0
    )
    sat_specific = bool(
        family == "sat" and not bool(getattr(args, "repair_mode", False))
    )
    if sat_specific:
        mult_name = "dblock_sat_anchor_softcap_mult"
        min_name = "dblock_sat_anchor_softcap_min_ce"
        max_name = "dblock_sat_anchor_softcap_max_ce"
        mult_default, min_default, max_default = 2.0, 12.0, 20.0
    else:
        mult_name = "dblock_anchor_softcap_mult"
        min_name = "dblock_anchor_softcap_min_ce"
        max_name = "dblock_anchor_softcap_max_ce"
        mult_default, min_default, max_default = 4.0, 25.0, 50.0
    multiplier = _dblock_require_finite_number(
        getattr(args, mult_name, mult_default),
        f"--{mult_name}", minimum=0.0,
    )
    minimum_ce = _dblock_require_finite_number(
        getattr(args, min_name, min_default),
        f"--{min_name}", minimum=0.0,
    )
    maximum_ce = _dblock_require_finite_number(
        getattr(args, max_name, max_default),
        f"--{max_name}", minimum=0.0,
    )
    if maximum_ce > 0.0 and minimum_ce > maximum_ce:
        raise ValueError(
            "--dblock_anchor_softcap_min_ce cannot exceed "
            "--dblock_anchor_softcap_max_ce"
        )
    ema_map = state.get("fullstack_anchor_spike_ema_by_family", {})
    baseline = ema_map.get(family) if isinstance(ema_map, dict) else None
    if baseline is not None:
        baseline = _dblock_require_finite_number(
            baseline, f"persisted {family} anchor EMA", minimum=0.0
        )

    enabled = multiplier > 0.0 or minimum_ce > 0.0 or maximum_ce > 0.0
    cap_ce = None
    if enabled:
        if baseline is not None and baseline > 1e-3 and multiplier > 0.0:
            cap_ce = max(float(minimum_ce), float(multiplier) * float(baseline))
        elif maximum_ce > 0.0:
            cap_ce = float(maximum_ce)
        else:
            cap_ce = float(minimum_ce)
        if maximum_ce > 0.0:
            cap_ce = min(float(cap_ce), float(maximum_ce))
        if minimum_ce > 0.0:
            cap_ce = max(float(cap_ce), float(minimum_ce))

    gradient_scale = 1.0
    if cap_ce is not None and cap_ce > 0.0 and raw_ce > cap_ce:
        gradient_scale = float(cap_ce) / max(float(raw_ce), 1e-12)
    gradient_scale = min(1.0, max(0.0, float(gradient_scale)))
    effective_ce = float(raw_ce) * gradient_scale
    ema_sample = effective_ce
    ema_next = (
        ema_sample if baseline is None
        else 0.95 * float(baseline) + 0.05 * ema_sample
    )
    return {
        "mode": "continuous_gradient_scale_no_rejection",
        "enabled": bool(enabled),
        "family": family,
        "policy_scope": (
            "fixed_sat_robust_v1" if sat_specific else "shared_anchor_v1"
        ),
        "baseline": baseline,
        "multiplier": float(multiplier),
        "minimum_ce": float(minimum_ce),
        "maximum_ce": float(maximum_ce),
        "cap_ce": cap_ce,
        "raw_ce": float(raw_ce),
        "effective_ce": float(effective_ce),
        "gradient_scale": float(gradient_scale),
        "softcapped": bool(gradient_scale < 1.0 - 1e-12),
        "ema_next": float(ema_next),
    }



def _dblock_anchor_spike_retry_limit(args):
    raw = getattr(args, "dblock_fullstack_anchor_spike_retry_limit", 3)
    if isinstance(raw, bool):
        raise ValueError("full-stack anchor spike retry limit must be an integer")
    limit = int(raw)
    if limit <= 0:
        raise ValueError("full-stack anchor spike retry limit must be positive")
    return limit


def _dblock_local_spike_retry_limit(args):
    raw = getattr(args, "dblock_local_spike_retry_limit", 3)
    if isinstance(raw, bool):
        raise ValueError("local loss spike retry limit must be an integer")
    limit = int(raw)
    if limit <= 0:
        raise ValueError("local loss spike retry limit must be positive")
    return limit


def _dblock_record_anchor_spike_rejection(state, args, family):
    family = str(family).strip().lower()
    if family not in {"ar", "sat", "nat"}:
        raise ValueError(f"unknown full-stack anchor family {family!r}")
    skips = state.setdefault(
        "fullstack_anchor_spike_skips_by_family",
        {"ar": 0, "sat": 0, "nat": 0},
    )
    consecutive = state.setdefault(
        "fullstack_anchor_spike_consecutive_by_family",
        {"ar": 0, "sat": 0, "nat": 0},
    )
    skips[family] = int(skips.get(family, 0)) + 1
    consecutive[family] = int(consecutive.get(family, 0)) + 1
    limit = _dblock_anchor_spike_retry_limit(args)
    return {
        "family": family,
        "consecutive": int(consecutive[family]),
        "total": int(skips[family]),
        "limit": int(limit),
        "limit_reached": bool(consecutive[family] >= limit),
    }


def _dblock_record_local_spike_rejection(state, args, objective, block_idx):
    objective = str(objective or "mixed").strip().lower()
    B = max(1, int(state.get("B", 1)))
    block_idx = int(block_idx)
    if not (0 <= block_idx < B):
        raise ValueError(f"local spike block {block_idx} outside B={B}")
    by_objective = state.setdefault(
        "local_spike_consecutive_by_objective_block",
        {
            "ar": [0 for _ in range(B)],
            "sat": [0 for _ in range(B)],
            "nat": [0 for _ in range(B)],
        },
    )
    counters = by_objective.setdefault(
        objective, [0 for _ in range(B)]
    )
    if len(counters) != B:
        raise ValueError(
            f"local spike counters for {objective} have length "
            f"{len(counters)} != B={B}"
        )
    counters[block_idx] = int(counters[block_idx]) + 1
    limit = _dblock_local_spike_retry_limit(args)
    return {
        "objective": objective,
        "block": int(block_idx),
        "consecutive": int(counters[block_idx]),
        "limit": int(limit),
        "limit_reached": bool(counters[block_idx] >= limit),
    }



def _dblock_observe_anchor_nonspike(state, family):
    family = str(family).strip().lower()
    counters = state.setdefault(
        "fullstack_anchor_spike_consecutive_by_family",
        {"ar": 0, "sat": 0, "nat": 0},
    )
    counters[family] = 0


def _dblock_observe_local_nonspike(state, objective, block_idx):
    objective = str(objective or "mixed").strip().lower()
    B = max(1, int(state.get("B", 1)))
    counters = state.setdefault(
        "local_spike_consecutive_by_objective_block",
        {
            "ar": [0 for _ in range(B)],
            "sat": [0 for _ in range(B)],
            "nat": [0 for _ in range(B)],
        },
    ).setdefault(objective, [0 for _ in range(B)])
    if len(counters) != B:
        raise ValueError(
            f"local spike counters for {objective} have invalid length"
        )
    counters[int(block_idx)] = 0


def _dblock_local_spike_probe(state, args, objective, block_idx, raw_avg):
    """Enforce finite-CE fuses while staging EMA state until commit."""
    objective = str(objective or "mixed").strip().lower()
    raw_avg = float(raw_avg)
    B = max(1, int(state.get("B", 1)))
    block_idx = int(block_idx)
    multiplier = max(
        0.0, float(getattr(args, "loss_spike_skip", 0.0) or 0.0)
    )
    global_map = state.get("spike_ema_by_objective", {})
    block_map = state.get("spike_block_ema_by_objective", {})
    if not isinstance(global_map, dict) or not isinstance(block_map, dict):
        raise ValueError("local spike EMA state must be mappings")
    global_ema = global_map.get(objective)
    existing = block_map.get(objective)
    if existing is None:
        existing = [None for _ in range(B)]
    if not isinstance(existing, list) or len(existing) != B:
        raise ValueError(
            f"local spike block EMA for {objective} has invalid length"
        )
    block_ema = existing[block_idx]
    baselines = [
        float(value) for value in (global_ema, block_ema)
        if value is not None
        and math.isfinite(float(value))
        and float(value) > 1e-3
    ]
    baseline = max(baselines) if baselines else None
    aux_policy = _dblock_local_aux_policy_probe(args, objective, raw_avg)
    relative_spike = bool(
        multiplier > 0.0
        and baseline is not None
        and raw_avg > multiplier * baseline
    )
    absolute_spike = bool(aux_policy["would_hard_reject"])
    advisory_spike = bool(absolute_spike or relative_spike)
    spike = advisory_spike
    ema_baselines = [
        float(value) for value in (global_ema, block_ema)
        if value is not None and math.isfinite(float(value))
        and float(value) > 1e-3
    ]
    ema_cap_base = max(ema_baselines) if ema_baselines else None
    ema_sample = raw_avg if ema_cap_base is None else min(
        raw_avg, max(float(ema_cap_base) * 4.0, float(ema_cap_base) + 1.0)
    )
    pending = {
        "objective": objective,
        "block": int(block_idx),
        "global_next": (
            ema_sample if global_ema is None
            else 0.98 * float(global_ema) + 0.02 * ema_sample
        ),
        "block_next": (
            ema_sample if block_ema is None
            else 0.96 * float(block_ema) + 0.04 * ema_sample
        ),
    }
    return {
        "spike": spike,
        "advisory_spike": advisory_spike,
        "baseline": baseline,
        "multiplier": float(multiplier),
        "pending": pending,
        "reason": (
            "absolute_max" if absolute_spike
            else "relative_ema" if relative_spike
            else "accepted"
        ),
        "absolute_spike": absolute_spike,
        "relative_spike": relative_spike,
        "aux_warning": bool(aux_policy["warning"]),
        "aux_policy": aux_policy,
        "quality_gate_mode": "hard_reject",
    }


def _dblock_local_aux_policy_probe(args, objective, raw_ce):
    """Read-only SAT/NAT local-CE telemetry; AR is unchanged."""
    objective = str(objective or "mixed").strip().lower()
    raw_ce = _dblock_require_finite_number(
        raw_ce, "local auxiliary raw CE", minimum=0.0
    )
    warn_ce = _dblock_require_finite_number(
        getattr(args, "dblock_local_aux_warn_ce", 0.0),
        "--dblock_local_aux_warn_ce", minimum=0.0,
    )
    max_ce = _dblock_require_finite_number(
        getattr(args, "dblock_local_aux_max_ce", 0.0),
        "--dblock_local_aux_max_ce", minimum=0.0,
    )
    enabled = warn_ce > 0.0 or max_ce > 0.0
    if warn_ce > 0.0 and max_ce > 0.0 and max_ce <= warn_ce:
        raise ValueError(
            "--dblock_local_aux_max_ce must be greater than "
            "--dblock_local_aux_warn_ce"
        )
    applies = objective in {"sat", "nat"}
    would_hard_reject = bool(
        applies and max_ce > 0.0 and raw_ce > max_ce
    )
    return {
        "objective": objective,
        "raw_ce": float(raw_ce),
        "applies": bool(applies),
        "warning_ce": float(warn_ce),
        "maximum_ce": float(max_ce),
        "enabled": bool(enabled),
        # Strict edges are contractual: 25.0 is green, 50.0 is yellow.
        "warning": bool(applies and warn_ce > 0.0 and raw_ce > warn_ce),
        "hard_reject": would_hard_reject,
        "would_hard_reject": would_hard_reject,
        "quality_gate_mode": "hard_reject",
    }


def _dblock_local_aux_warning_receipt(
    state, objective, block_idx, spike_probe, local_diagnostics,
    input_hashes, target_hashes, *, committed, outcome,
):
    """Build non-semantic warning telemetry from already-computed diagnostics."""
    policy = spike_probe.get("aux_policy", {})
    if not bool(policy.get("warning", False)):
        return None
    return {
        "schema": "agillm43.dblock.local_aux_warning.v1",
        "step": int(state.get("step", 0)),
        "attempt_step": int(state.get("attempt_step", 0)),
        "objective": str(objective),
        "block": int(block_idx),
        "raw_ce": float(policy["raw_ce"]),
        "warning_ce": float(policy["warning_ce"]),
        "maximum_ce": float(policy["maximum_ce"]),
        "hard_reject": bool(policy["hard_reject"]),
        "spike": bool(spike_probe.get("spike", False)),
        "spike_reason": str(spike_probe.get("reason", "accepted")),
        "relative_baseline": (
            None if spike_probe.get("baseline") is None
            else float(spike_probe["baseline"])
        ),
        "relative_multiplier": float(spike_probe.get("multiplier", 0.0)),
        "relative_spike": bool(spike_probe.get("relative_spike", False)),
        "absolute_spike": bool(spike_probe.get("absolute_spike", False)),
        "committed": bool(committed),
        "outcome": str(outcome),
        "batch_sha256": str(local_diagnostics["batch"]["sha256"]),
        "input_sha256_by_objective": dict(input_hashes),
        "target_sha256_by_objective": dict(target_hashes),
    }


def _dblock_emit_local_aux_warning(receipt):
    """Emit warning telemetry only; never mutate training or resume state."""
    if receipt is None:
        return
    print(
        "[dblock-local-aux-warning] " + json.dumps(
            receipt, sort_keys=True, separators=(",", ":"), allow_nan=False
        ),
        flush=True,
    )


def _dblock_commit_local_spike_state(state, pending):
    """Commit local EMA and retry reset only with a successful optimizer update."""
    if not isinstance(pending, dict):
        return
    objective = str(pending["objective"])
    block_idx = int(pending["block"])
    B = max(1, int(state.get("B", 1)))
    global_next = pending.get("global_next")
    block_next = pending.get("block_next")
    if global_next is not None:
        state.setdefault("spike_ema_by_objective", {})[objective] = float(
            global_next
        )
    if block_next is not None:
        block_map = state.setdefault("spike_block_ema_by_objective", {})
        counters = block_map.setdefault(
            objective, [None for _ in range(B)]
        )
        if len(counters) != B:
            raise ValueError(
                f"local spike block EMA for {objective} has invalid length"
            )
        counters[block_idx] = float(block_next)


def _dblock_clear_rejected_attempt(core, opt):
    """Discard every gradient/auxiliary trace from a rejected attempt."""
    opt.zero_grad(set_to_none=True)
    _dblock_clear_moe_aux_stash(core)
    if torch.cuda.is_available():
        torch.cuda.empty_cache()


def _dblock_fullstack_ar_due(args, state):
    every = _dblock_fullstack_anchor_int(args, "dblock_fullstack_ar_every", 0)
    offset = _dblock_fullstack_anchor_signed_int(args, "dblock_fullstack_ar_offset", 0)
    requested_targets = _dblock_fullstack_anchor_int(args, "dblock_fullstack_ar_tokens", 0)
    weight = _dblock_hot_float(
        args, "dblock_fullstack_ar_weight", 0.0,
        names=["dblock_fullstack_ar_weight", "fullstack_ar_weight"],
        min_value=0.0,
    )
    return (
        every > 0 and requested_targets > 0 and weight > 0.0
        and _dblock_fullstack_anchor_due(int(state.get("step", 0)), every, offset)
    )


def _agillm43_v25_sat_anchor_contract(args):
    """Single source of truth for SAT cadence, weight and gate supervision."""
    if bool(getattr(args, "repair_mode", False)):
        return (
            _dblock_fullstack_anchor_int(
                args, "dblock_fullstack_sat_every", 0),
            _dblock_fullstack_anchor_signed_int(
                args, "dblock_fullstack_sat_offset", 4),
            _dblock_fullstack_anchor_int(
                args, "dblock_fullstack_sat_tokens", 0),
            _dblock_fullstack_aux_weight(
                args, "dblock_fullstack_sat_weight"),
            0.0,
            0,
        )
    return 3, 1, 128, 0.10, float(EMIT_LAMBDA), 64


def _dblock_fullstack_sat_due(args, state):
    every, offset, requested_tokens, weight, _gate_weight, _gate_blocks = (
        _agillm43_v25_sat_anchor_contract(args)
    )
    return (
        every > 0 and requested_tokens > 0 and weight > 0.0
        and _dblock_fullstack_anchor_due(int(state.get("step", 0)), every, offset)
    )



@_agillm_contextmanager
def _dblock_deterministic_anchor_context(core, reference_tensor):
    """Serving-aligned eval modes and forked RNG across forward and backward."""
    prior_modes = [(module, bool(module.training)) for module in core.modules()]
    devices = []
    if torch.is_tensor(reference_tensor) and reference_tensor.is_cuda:
        device_index = reference_tensor.device.index
        if device_index is None:
            device_index = torch.cuda.current_device()
        devices = [int(device_index)]
    try:
        with torch.random.fork_rng(devices=devices, enabled=True):
            core.eval()
            yield
    finally:
        try:
            _dblock_clear_moe_aux_stash(core)
        finally:
            for module, training in prior_modes:
                module.training = bool(training)



def _dblock_retain_small_activations(args, hidden):
    """Default-off memory-for-compute option, capped at two 2048-token rows."""
    try:
        rows = int(_dblock_fullstack_anchor_int(args, "dblock_retain_activations_rows", 0))
    except (TypeError, ValueError, OverflowError):
        return False
    if rows not in (1, 2) or hidden.ndim != 3:
        return False
    return (0 < int(hidden.shape[0]) <= rows
            and 0 < int(hidden.shape[1]) <= 2048
            and int(hidden.shape[0]) * int(hidden.shape[1]) <= 4096)


def _dblock_fullstack_hidden(core, input_ids, attention_mask, args):
    """Run the exact full serving stack with every transformer layer checkpointed."""
    M = _agillm41_sys.modules[__name__]
    with M.amp(args.amp):
        h = core.emb(input_ids)
        _retain_activations = _dblock_retain_small_activations(args, h)
        if getattr(core, "hc", None) is not None:
            for _db, _grp in enumerate(core.hc_groups):
                h = _hc_span_forward(core, _db, _grp, h, attention_mask, True, args)
                if getattr(core, "anchor", None) is not None and int(getattr(core, "anchor_position", -1)) in _grp:
                    anchor_module = core.anchor
                    h = _ck.checkpoint(lambda y, module=anchor_module: module(y)[0], h, use_reentrant=False)
        else:
            for li, block in enumerate(core.blocks):
                if _retain_activations:
                    h = _run_block_forward(block, h, attention_mask, "off")
                else:
                    h = _run_block(block, h, attention_mask, True, args, "off")
                if getattr(core, "anchor", None) is not None and li == int(getattr(core, "anchor_position", -1)):
                    anchor_module = core.anchor
                    h = _ck.checkpoint(lambda y, module=anchor_module: module(y)[0], h, use_reentrant=False)
        h = core.ln(h)
    return h


def _dblock_fullstack_ar_anchor(
    core, ar_h, scaler, args, ids, state, loss_mask=None,
    batch_diagnostics=None,
):
    """Periodic short full-stack causal-AR loss on the exact serving graph.

    Legacy local EDM DBlock remains the majority objective. This auxiliary only
    teaches the independently trained blocks to compose when all layers are run
    in order. It uses B=1, a cropped sequence, checkpointed layers, and fused CE
    so no [B,T,V] logits tensor is materialized.
    """
    every = _dblock_fullstack_anchor_int(args, "dblock_fullstack_ar_every", 0)
    offset = _dblock_fullstack_anchor_signed_int(args, "dblock_fullstack_ar_offset", 0)
    requested_targets = _dblock_fullstack_anchor_int(args, "dblock_fullstack_ar_tokens", 0)
    # v27.16: the 256-target repair cap is a hot-configurable ceiling
    # (dblock_fullstack_anchor_cap) and the crop may span several batch rows
    # (dblock_fullstack_ar_rows) so the composition anchor can carry a real
    # end-to-end token budget instead of one 256-token crop.
    anchor_cap = max(1, _dblock_fullstack_anchor_int(args, "dblock_fullstack_anchor_cap", 256))
    anchor_rows = max(1, _dblock_fullstack_anchor_int(args, "dblock_fullstack_ar_rows", 1))
    max_targets = min(anchor_cap, requested_targets)
    if requested_targets > anchor_cap and not bool(state.get("fullstack_anchor_cap_warned", False)):
        state["fullstack_anchor_cap_warned"] = True
        print(
            f"[dblock-anchor] requested {requested_targets} targets; anchor cap is {anchor_cap}",
            flush=True,
        )
    weight = _dblock_hot_float(
        args,
        "dblock_fullstack_ar_weight",
        0.0,
        names=["dblock_fullstack_ar_weight", "fullstack_ar_weight"],
        min_value=0.0,
    )
    step = int(state.get("step", 0))
    due = (
        every > 0 and max_targets > 0 and weight > 0.0
        and _dblock_fullstack_anchor_due(step, every, offset)
    )
    # The owner may tune AR cadence, but cannot indirectly suppress the
    # mandatory v25 SAT anchor by moving AR onto SAT's immutable phase.
    # v27.16.3: with dblock_fullstack_ar_every == 1 the anchors run back to
    # back in the same step (SAT keeps its mandatory phase and still runs), so
    # the precedence skip only applies in round-robin mode; it was silently
    # dropping the AR composition anchor on every third step.
    if (due and not bool(getattr(args, "repair_mode", False))
            and every != 1
            and _dblock_fullstack_sat_due(args, state)):
        return {
            "ran": False, "due": True, "finite": True,
            "reason": "mandatory_fullstack_sat_precedence", "tokens": 0,
            "raw": 0.0, "weighted": 0.0,
        }
    if not due or ids.size(1) < 2:
        return {"ran": False, "finite": True, "raw": 0.0, "weighted": 0.0, "tokens": 0}

    anchor_rows = min(anchor_rows, max(1, int(ids.size(0))))
    per_row_targets = min(max(1, int(max_targets) // anchor_rows), int(ids.size(1)) - 1)
    seq_len = per_row_targets + 1
    target_count = min(int(max_targets), per_row_targets * anchor_rows)
    row = step % max(1, int(ids.size(0)))
    max_start = max(0, int(ids.size(1)) - seq_len)
    # Deterministic but changing crop, so restart receipts are reproducible.
    start = 0 if max_start == 0 else ((step * 104729 + row * 1543) % (max_start + 1))
    if anchor_rows == 1:
        anchor_ids = ids[row:row + 1, start:start + seq_len]
        anchor_loss_mask = None if loss_mask is None else loss_mask[row:row + 1, start + 1:start + seq_len]
    else:
        _rows_sel = [(row + k * 7919) % int(ids.size(0)) for k in range(anchor_rows)]
        _starts = [0 if max_start == 0 else ((step * 104729 + r * 1543 + k * 65537) % (max_start + 1))
                   for k, r in enumerate(_rows_sel)]
        anchor_ids = torch.stack([ids[r, s:s + seq_len] for r, s in zip(_rows_sel, _starts)], dim=0)
        anchor_loss_mask = None if loss_mask is None else torch.stack(
            [loss_mask[r, s + 1:s + seq_len] for r, s in zip(_rows_sel, _starts)], dim=0)
    if anchor_loss_mask is not None:
        if not bool(anchor_loss_mask.any()):
            state["fullstack_anchor_skipped_empty_mask"] = int(
                state.get("fullstack_anchor_skipped_empty_mask", 0)
            ) + 1
            print(
                f"[dblock-anchor] step={step} skipped: crop has no supervised mask positions",
                flush=True,
            )
            return {"ran": False, "due": True, "finite": True, "raw": 0.0, "weighted": 0.0, "tokens": 0}

    if batch_diagnostics is None:
        batch_diagnostics = _dblock_token_boundary_diagnostics(ids, loss_mask)
    crop_diagnostics = _dblock_token_boundary_diagnostics(anchor_ids)

    with _dblock_deterministic_anchor_context(core, anchor_ids):
        _dblock_clear_moe_aux_stash(core)
        causal = _agillm41_sys.modules[__name__].causal_mask(
            seq_len,
            structured=_agillm41_sys.modules[__name__].use_structured_masks(args),
        )
        with _agillm41_sys.modules[__name__].amp(args.amp):
            h = core.emb(anchor_ids)
            _retain_activations = _dblock_retain_small_activations(args, h)
            if getattr(core, "hc", None) is not None:
                for _db, _grp in enumerate(core.hc_groups):
                    h = _hc_span_forward(core, _db, _grp, h, causal, True, args)
                    if getattr(core, "anchor", None) is not None and int(getattr(core, "anchor_position", -1)) in _grp:
                        h = _ck.checkpoint(lambda y: core.anchor(y)[0], h, use_reentrant=False)
            else:
                for li, block in enumerate(core.blocks):
                    # Always checkpoint this auxiliary: production core.grad_checkpoint is
                    # false because local DBlock normally runs only two layers.
                    if _retain_activations:
                        h = _run_block_forward(block, h, causal, "off")
                    else:
                        h = _run_block(block, h, causal, True, args, "off")
                    if getattr(core, "anchor", None) is not None and li == int(getattr(core, "anchor_position", -1)):
                        h = _ck.checkpoint(lambda y: core.anchor(y)[0], h, use_reentrant=False)
            h = core.ln(h)

        popup_runtime = getattr(args, "_detachable_50m_runtime", None)
        teacher_every = max(1, int(getattr(
            args, "detachable_50m_teacher_every", 1) or 1))
        teacher_capture_index = int(
            state.get("fullstack_anchor_attempts", 0)) + 1
        if (popup_runtime is not None
                and teacher_capture_index % teacher_every == 0):
            popup_mapping = popup_runtime.peek_mapping(args)
            popup_mode = str(popup_mapping.get("popup_mode", "ar") or "ar")
            kd_schedule = ((popup_runtime.manifest.get("schedule") or {}).get(
                "logit_distillation") or {})
            teacher_logits = None
            teacher_logit_positions = 0
            # The mature hidden is already available from the exact serving graph.
            # For causal AR student updates, capture the mature output distribution
            # before the parent optimiser mutates its tied vocabulary table.  The
            # bounded transient is at most 64 x 129,280 bf16 values (~16 MiB), is
            # stop-gradient, and is consumed immediately after the accepted parent
            # commit.  SAT/NAT retain token CE only because their attention contract
            # differs from this causal teacher packet.
            if bool(kd_schedule.get("enabled", True)):
                teacher_logit_positions = min(
                    max(1, int(kd_schedule.get("max_tokens", 64) or 64)),
                    max(1, int(h.size(1)) - 1),
                )
                with torch.no_grad():
                    # This helper receives only the mature causal AR head.  In the
                    # production tied-head configuration AR/SAT/NAT projections share
                    # the same bias-free embedding weight, so use ar_h unconditionally.
                    # Referencing sat_h/nat_h here caused a production NameError when a
                    # detachable NAT mapping coincided with an AR full-stack anchor.
                    proj_w = ar_h.proj.weight.detach()
                    proj_b = None if ar_h.proj.bias is None else ar_h.proj.bias.detach()
                    teacher_logits = F.linear(
                        h[:1, :teacher_logit_positions].detach(),
                        proj_w,
                        proj_b,
                    ).detach()
                if teacher_logits.requires_grad or teacher_logits.grad_fn is not None:
                    raise RuntimeError("detachable-50m teacher logits are not stop-gradient")
            # This is the already-computed mature serving representation plus, for
            # AR only, its exact pre-commit vocabulary logits.  Both are transient.
            state["_det50_teacher_packet"] = {
                "schema": "agillm5.detachable-50m.teacher-packet.v2",
                "direction": "mature_1p1b_to_detachable_50m",
                "teacher_stop_gradient": True,
                "teacher_representation": "mature_fullstack_ar_final_hidden",
                "dblock_step_before": int(step),
                "expected_dblock_commit_step": int(step) + 1,
                "teacher_capture_index": int(teacher_capture_index),
                "popup_layer": int(popup_mapping["layer"]),
                "popup_sublayer": str(popup_mapping["sublayer"]),
                "anchor_ids": anchor_ids[:1].detach().clone(),
                "anchor_loss_mask": (
                    None if anchor_loss_mask is None
                    else anchor_loss_mask[:1].detach().clone()),
                "teacher_hidden": h[:1].detach(),
                "teacher_hidden_shape": [int(v) for v in h[:1].shape],
                "teacher_logits": teacher_logits,
                "teacher_logits_shape": (
                    None if teacher_logits is None
                    else [int(v) for v in teacher_logits.shape]),
                "teacher_logit_positions": int(teacher_logit_positions),
                "teacher_logits_dtype": (
                    None if teacher_logits is None else str(teacher_logits.dtype)),
                "teacher_logits_pre_parent_commit": True,
                "teacher_vocab_size": int(ar_h.proj.weight.size(0)),
                "anchor_ids_sha256": _dblock_tensor_sha256(anchor_ids[:1]),
            }

        hidden, targets, used, available = _sample_token_loss_inputs(
            h[:, :-1], anchor_ids[:, 1:], target_count, anchor_loss_mask
        )
        target_diagnostics = _dblock_token_boundary_diagnostics(targets)
        raw = fused_ce(hidden, ar_h.proj.weight, targets)
        raw_value = float(raw.detach())
        raw_is_finite = math.isfinite(raw_value)
        softcap_probe = _dblock_anchor_softcap_probe(
            state, args, "ar", raw_value
        ) if raw_is_finite else {
            "gradient_scale": 1.0, "softcapped": False, "cap_ce": None,
            "effective_ce": float("nan"), "ema_next": None,
        }
        uncapped_weighted_value = float(weight) * raw_value if raw_is_finite else float("nan")
        weighted = float(weight) * raw * float(softcap_probe["gradient_scale"])
        # The selected local AR/SAT/NAT objective already contributes router auxiliary
        # loss in this optimizer step. Keep the composition anchor pure CE to avoid
        # counting MoE load-balance/z-loss twice. Clear forward stashes before backward;
        # checkpoint recomputation will create fresh detached stashes, cleared below.
        _dblock_clear_moe_aux_stash(core)
        total = weighted
        weighted_value = float(weighted.detach())
        finite = math.isfinite(weighted_value)
        spike_probe = _dblock_anchor_spike_probe(state, args, "ar", raw_value) if finite else {
            "spike": False, "baseline": None, "ema_next": None,
            "multiplier": 0.0, "absolute_max": 0.0, "reason": "nonfinite",
        }
        spike = bool(spike_probe.get("spike", False))
        if finite and not spike:
            _dblock_observe_anchor_nonspike(state, "ar")
            scaler.scale(total).backward()
        # non-reentrant checkpoint recomputation can restash every router input.
        _dblock_clear_moe_aux_stash(core)
    state["fullstack_anchor_attempts"] = int(state.get("fullstack_anchor_attempts", 0)) + 1
    # Successful-target counters are committed by the caller only after the
    # optimizer update survives finite/spike/AMP-overflow gates.
    state["fullstack_anchor_last"] = {
        "deterministic_eval": True,
        "step": step,
        "raw_ce": raw_value,
        "weighted": weighted_value,
        "uncapped_weighted": uncapped_weighted_value,
        "softcap_applied": bool(softcap_probe.get("softcapped", False)),
        "softcap_ce": softcap_probe.get("cap_ce"),
        "softcap_gradient_scale": float(softcap_probe.get("gradient_scale", 1.0)),
        "tokens": int(used),
        "available": int(available),
        "row": int(row),
        "start": int(start),
        "spike": spike, "spike_reason": spike_probe.get("reason"),
        "spike_baseline": spike_probe.get("baseline"),
        "diagnostics": {
            "batch": batch_diagnostics,
            "crop": crop_diagnostics,
            "selected_targets": target_diagnostics,
        },
    }
    if _dblock_audit_due(state, args):
        print(
            f"[dblock-anchor] step={step} raw_ce={raw_value:.4f} weight={weight:.4f} "
            f"weighted={weighted_value:.4f} targets={int(used)}/{int(available)} "
            f"crop=row{row}:{start}+{seq_len} rows={anchor_rows} finite={finite} spike={spike} "
            f"baseline={spike_probe.get('baseline')} softcap={softcap_probe.get('softcapped')} "
            f"cap_ce={softcap_probe.get('cap_ce')} grad_scale={softcap_probe.get('gradient_scale', 1.0):.6f} "
            f"batch_sha256={batch_diagnostics['sha256']} "
            f"crop_sha256={crop_diagnostics['sha256']} "
            f"target_sha256={target_diagnostics['sha256']} "
            f"eos={crop_diagnostics['eos_pad_count']} "
            f"mask={crop_diagnostics['nat_mask_count']}",
            flush=True,
        )
    del causal, anchor_ids, h, hidden, targets, raw, weighted, total
    return {
        "ran": True,
        "finite": finite,
        "raw": raw_value,
        "weighted": weighted_value,
        "tokens": int(used),
        "spike": spike, "spike_reason": spike_probe.get("reason"),
        "spike_baseline": spike_probe.get("baseline"),
        "anchor_ema_next": softcap_probe.get("ema_next"),
        "uncapped_weighted": uncapped_weighted_value,
        "softcap_applied": bool(softcap_probe.get("softcapped", False)),
        "softcap_ce": softcap_probe.get("cap_ce"),
        "softcap_gradient_scale": float(softcap_probe.get("gradient_scale", 1.0)),
        "diagnostics": {
            "batch": batch_diagnostics,
            "crop": crop_diagnostics,
            "selected_targets": target_diagnostics,
        },
    }


def _dblock_fullstack_sat_anchor(
    core, sat_h, scaler, args, ids, state, loss_mask=None,
    batch_diagnostics=None, ar_h=None,
):
    if ar_h is None:
        ar_h = _AGILLM43_V3_AR_HEAD_REF[0]
    """Mandatory fixed-SAT token CE plus bounded variable-gate supervision.

    The stride-1/stride-2 gate is trained only from full-stack serving features.
    Its teacher and features are detached, so this auxiliary changes the
    already-checkpointed gate only; core and SAT projection gradients retain
    the fixed shift-two contract.
    """
    M = _agillm41_sys.modules[__name__]
    every, offset, requested_tokens, weight, gate_weight, gate_blocks = (
        _agillm43_v25_sat_anchor_contract(args)
    )
    repair_mode = bool(getattr(args, "repair_mode", False))
    if not repair_mode:
        # v25 invariant: SAT-variable is pretraining, not an optional surface.
        if sat_h is None or getattr(sat_h, "gate", None) is None:
            raise RuntimeError("intelligence-v25 requires the SAT-variable gate")
    step = int(state.get("step", 0))
    due = (
        sat_h is not None and every > 0 and requested_tokens > 0 and weight > 0.0
        and _dblock_fullstack_anchor_due(step, every, offset)
    )
    if not due:
        return {"ran": False, "due": False, "finite": True, "raw": 0.0, "weighted": 0.0, "tokens": 0}
    seq_len = min(256, max(128, int(requested_tokens)))
    if int(ids.size(1)) < seq_len:
        state["fullstack_sat_anchor_skipped_short"] = int(
            state.get("fullstack_sat_anchor_skipped_short", 0)
        ) + 1
        return {"ran": False, "due": True, "finite": True, "reason": "short_sequence", "tokens": 0}

    row = (step + 1) % max(1, int(ids.size(0)))
    max_start = max(0, int(ids.size(1)) - seq_len)
    start = 0 if max_start == 0 else ((step * 130363 + row * 1741 + 17) % (max_start + 1))
    # v27.16.6: optional extra crops on other batch rows (hot int dblock_fullstack_sat_rows, default 1).
    _sat_rows = max(1, min(int(ids.size(0)), _dblock_fullstack_anchor_int(args, "dblock_fullstack_sat_rows", 1)))
    _rows_sel = [(row + k * 7919) % int(ids.size(0)) for k in range(_sat_rows)]
    _starts = [start] + [
        (0 if max_start == 0 else ((start + k * 997) % (max_start + 1))) for k in range(1, _sat_rows)
    ]
    anchor_ids = torch.stack([ids[r, s:s + seq_len] for r, s in zip(_rows_sel, _starts)], dim=0)
    shift = int(M.SAT_BLOCK)
    if shift != 2:
        raise RuntimeError(f"full-stack SAT anchor requires fixed shift2, got SAT_BLOCK={shift}")
    anchor_loss_mask = None
    if loss_mask is not None:
        anchor_loss_mask = torch.stack(
            [loss_mask[r, s + shift:s + seq_len] for r, s in zip(_rows_sel, _starts)], dim=0
        )
        if not bool(anchor_loss_mask.any()):
            state["fullstack_sat_anchor_skipped_empty_mask"] = int(
                state.get("fullstack_sat_anchor_skipped_empty_mask", 0)
            ) + 1
            return {"ran": False, "due": True, "finite": True, "reason": "empty_loss_mask", "tokens": 0}

    if batch_diagnostics is None:
        batch_diagnostics = _dblock_token_boundary_diagnostics(ids, loss_mask)
    crop_diagnostics = _dblock_token_boundary_diagnostics(anchor_ids)

    with _dblock_deterministic_anchor_context(core, anchor_ids):
        # v3: one extra no-grad causal pass over the first crop gives the AR-side
        # gate labels (AR top-1 correct / draft2 == AR argmax).  It runs BEFORE
        # the stash clear so its MoE aux entries never reach the SAT backward.
        _v3_ar_hidden = None
        if ar_h is not None and getattr(sat_h, "gate_conf", None) is not None:
            with torch.no_grad():
                _v3_causal_mask = M.causal_mask(seq_len, structured=M.use_structured_masks(args))
                _v3_ar_hidden = _dblock_fullstack_hidden(core, anchor_ids[:1], _v3_causal_mask, args)
                if isinstance(_v3_ar_hidden, (tuple, list)):
                    _v3_ar_hidden = _v3_ar_hidden[0]
                _v3_ar_hidden = _v3_ar_hidden.detach()
        _dblock_clear_moe_aux_stash(core)
        fixed_sat_mask = M.sat_mask(
            seq_len, block=2, structured=M.use_structured_masks(args)
        )
        h = _dblock_fullstack_hidden(core, anchor_ids, fixed_sat_mask, args)
        hidden, targets, used, available = _sample_token_loss_inputs(
            h[:, :-shift], anchor_ids[:, shift:], _sat_rows * (seq_len - shift), anchor_loss_mask
        )
        target_diagnostics = _dblock_token_boundary_diagnostics(targets)
        raw = fused_ce(hidden, sat_h.proj.weight, targets)
        gate_class_weights, gate_class_balance_source = (
            _sat_variable_gate_history_class_weights(state)
        )
        # The SAT-variable gate keeps its single-crop supervision contract (first crop only).
        gate_loss, gate_info = _sat_variable_gate_anchor_loss(
            sat_h, h[:1, :-shift], anchor_ids[:1, shift:],
            max_blocks=gate_blocks,
            loss_mask=None if anchor_loss_mask is None else anchor_loss_mask[:1],
            token_ids=anchor_ids[:1],
            boundary_token_ids=_nat_boundary_ids(),
            class_weights=gate_class_weights,
            ar_h=ar_h, ar_hidden=_v3_ar_hidden,
        )
        gate_info["class_balance_source"] = gate_class_balance_source
        raw_value = float(raw.detach())
        gate_loss_value = (
            0.0 if gate_loss is None else float(gate_loss.detach())
        )
        raw_is_finite = (
            math.isfinite(raw_value) and math.isfinite(gate_loss_value)
        )
        softcap_probe = _dblock_anchor_softcap_probe(
            state, args, "sat", raw_value
        ) if raw_is_finite else {
            "gradient_scale": 1.0, "softcapped": False, "cap_ce": None,
            "effective_ce": float("nan"), "ema_next": None,
        }
        uncapped_weighted_value = (
            float(weight) * raw_value + float(gate_weight) * gate_loss_value
            if raw_is_finite else float("nan")
        )
        weighted = float(weight) * raw * float(softcap_probe["gradient_scale"])
        if gate_loss is not None:
            weighted = weighted + float(gate_weight) * gate_loss
        # The selected local DBlock objective already owns router aux.
        _dblock_clear_moe_aux_stash(core)
        weighted_value = float(weighted.detach())
        finite = math.isfinite(weighted_value)
        spike_probe = _dblock_anchor_spike_probe(state, args, "sat", raw_value) if finite else {
            "spike": False, "baseline": None, "ema_next": None,
            "multiplier": 0.0, "absolute_max": 0.0, "reason": "nonfinite",
        }
        spike = bool(spike_probe.get("spike", False))
        if finite and not spike:
            _dblock_observe_anchor_nonspike(state, "sat")
            scaler.scale(weighted).backward()
        _dblock_clear_moe_aux_stash(core)
    gate_state = dict(gate_info)
    gate_state.update({
        "loss": gate_loss_value,
        "weight": float(gate_weight),
        "required": not repair_mode,
        "applied": bool(gate_loss is not None and finite and not spike),
    })
    state["fullstack_sat_anchor_attempts"] = int(state.get("fullstack_sat_anchor_attempts", 0)) + 1
    state["fullstack_sat_anchor_last"] = {
        "deterministic_eval": True,
        "step": step, "raw_ce": raw_value, "weighted": weighted_value,
        "uncapped_weighted": uncapped_weighted_value,
        "softcap_applied": bool(softcap_probe.get("softcapped", False)),
        "softcap_ce": softcap_probe.get("cap_ce"),
        "softcap_gradient_scale": float(softcap_probe.get("gradient_scale", 1.0)),
        "tokens": int(used), "available": int(available), "row": int(row),
        "start": int(start), "seq_len": int(seq_len), "shift": int(shift),
        "spike": spike, "spike_reason": spike_probe.get("reason"),
        "spike_baseline": spike_probe.get("baseline"),
        "sat_variable_gate": gate_state,
        "diagnostics": {
            "batch": batch_diagnostics,
            "crop": crop_diagnostics,
            "selected_targets": target_diagnostics,
        },
    }
    if _dblock_audit_due(state, args):
        print(
            f"[dblock-sat-anchor] step={step} raw_ce={raw_value:.4f} weight={weight:.4f} "
            f"weighted={weighted_value:.4f} targets={int(used)}/{int(available)} "
            f"gate_ce={gate_loss_value:.4f} gate_weight={gate_weight:.4f} "
            f"gate_labels2={gate_info['stride2_labels']}/{gate_info['blocks']} "
            f"gate_pred2={gate_info['predicted_stride2']} false_accepts={gate_info['false_accepts']} "
            f"gate_class_w={gate_info.get('class_weights_stride1_stride2')} "
            f"gate_balance={gate_info.get('class_balance_source')} "
            f"gate_tau={gate_info.get('threshold')} gate_prec={gate_info.get('accept_precision')} "
            f"gate_pdraft_mean={gate_info.get('p_draft_mean')} gate_aux={gate_info.get('aux_compact')} "
            f"crop=row{row}:{start}+{seq_len} rows={_sat_rows} shift={shift} finite={finite} "
            f"spike={spike} baseline={spike_probe.get('baseline')} softcap={softcap_probe.get('softcapped')} "
            f"cap_ce={softcap_probe.get('cap_ce')} grad_scale={softcap_probe.get('gradient_scale', 1.0):.6f} "
            f"batch_sha256={batch_diagnostics['sha256']} "
            f"crop_sha256={crop_diagnostics['sha256']} "
            f"target_sha256={target_diagnostics['sha256']} "
            f"eos={crop_diagnostics['eos_pad_count']} "
            f"mask={crop_diagnostics['nat_mask_count']}",
            flush=True,
        )
    del fixed_sat_mask, anchor_ids, h, hidden, targets, raw, weighted, gate_loss
    return {
        "ran": True, "due": True, "finite": finite, "raw": raw_value,
        "weighted": weighted_value, "tokens": int(used), "row": int(row),
        "start": int(start), "seq_len": int(seq_len), "shift": int(shift),
        "spike": spike, "spike_reason": spike_probe.get("reason"),
        "spike_baseline": spike_probe.get("baseline"),
        "anchor_ema_next": softcap_probe.get("ema_next"),
        "uncapped_weighted": uncapped_weighted_value,
        "softcap_applied": bool(softcap_probe.get("softcapped", False)),
        "softcap_ce": softcap_probe.get("cap_ce"),
        "softcap_gradient_scale": float(softcap_probe.get("gradient_scale", 1.0)),
        "sat_variable_gate": gate_state,
        "diagnostics": {
            "batch": batch_diagnostics,
            "crop": crop_diagnostics,
            "selected_targets": target_diagnostics,
        },
    }


def _dblock_fullstack_satvar_anchor(core, sat_h, scaler, args, ids, state, loss_mask=None):
    """v28: variable-block SAT anchor through the whole serving stack.

    A random block partition (sizes 1..SATVAR_KMAX from the hot distribution) is applied to a
    few crops; every slot predicts its distance-conditioned target and the detached regret
    head regresses the observed per-slot CE.  Finite-checked like the other anchors; no spike
    machinery (its CE is bounded by construction) and no effect on the fixed SAT contract.
    """
    M = _agillm41_sys.modules[__name__]
    every = _dblock_fullstack_anchor_int(args, "dblock_fullstack_satvar_every", 3)
    offset = _dblock_fullstack_anchor_int(args, "dblock_fullstack_satvar_offset", 0)
    tokens = _dblock_fullstack_anchor_int(args, "dblock_fullstack_satvar_tokens", 256)
    rows = max(1, _dblock_fullstack_anchor_int(args, "dblock_fullstack_satvar_rows", 2))
    weight = _dblock_hot_float(args, "dblock_fullstack_satvar_weight", 0.10, min_value=0.0, max_value=3.0)
    regret_w = _dblock_hot_float(args, "dblock_satvar_regret_weight", 0.05, min_value=0.0, max_value=1.0)
    step = int(state.get("step", 0))
    enabled = _satvar_enabled(args) and not M.use_structured_masks(args)
    due = (
        enabled and sat_h is not None and every > 0 and tokens > 0 and weight > 0.0
        and _dblock_fullstack_anchor_due(step, every, offset)
    )
    if not due:
        return {"ran": False, "due": False, "finite": True, "raw": 0.0, "weighted": 0.0, "tokens": 0}
    seq_len = min(512, max(64, int(tokens)))
    if int(ids.size(1)) < seq_len:
        return {"ran": False, "due": True, "finite": True, "reason": "short_sequence", "tokens": 0}
    rows = min(rows, int(ids.size(0)))
    row0 = (step + 3) % int(ids.size(0))
    max_start = max(0, int(ids.size(1)) - seq_len)
    start0 = 0 if max_start == 0 else ((step * 97879 + row0 * 1093 + 29) % (max_start + 1))
    rows_sel = [(row0 + k * 7919) % int(ids.size(0)) for k in range(rows)]
    starts = [start0] + [(0 if max_start == 0 else ((start0 + k * 1009) % (max_start + 1))) for k in range(1, rows)]
    anchor_ids = torch.stack([ids[r, s:s + seq_len] for r, s in zip(rows_sel, starts)], dim=0)
    anchor_lm = None
    if loss_mask is not None:
        anchor_lm = torch.stack([loss_mask[r, s:s + seq_len] for r, s in zip(rows_sel, starts)], dim=0)
        if not bool(anchor_lm.any()):
            return {"ran": False, "due": True, "finite": True, "reason": "empty_loss_mask", "tokens": 0}
    sizes = satvar_sample_sizes(seq_len, _satvar_block_probs(args))
    with _dblock_deterministic_anchor_context(core, anchor_ids):
        _dblock_clear_moe_aux_stash(core)
        mask = satvar_partition_mask(sizes, seq_len, device=anchor_ids.device)
        h = _dblock_fullstack_hidden(core, anchor_ids, mask, args)
        W = sat_h.proj.weight
        hidden, targets, used, available, d_idx, _e, _r = _satvar_gather(
            sat_h, h, anchor_ids, anchor_lm, sizes, rows * seq_len)
        raw = fused_ce(hidden, W, targets)
        regret_loss, regret_info = (None, {"blocks": 0})
        if regret_w > 0.0:
            regret_loss, regret_info = _satvar_regret_loss(
                sat_h, h.detach(), anchor_ids, anchor_lm, sizes, W.detach(), max_blocks=128)
        raw_value = float(raw.detach())
        regret_value = 0.0 if regret_loss is None else float(regret_loss.detach())
        finite = math.isfinite(raw_value) and math.isfinite(regret_value)
        weighted = float(weight) * raw
        if regret_loss is not None and finite:
            weighted = weighted + float(regret_w) * regret_loss
        weighted_value = float(weighted.detach())
        finite = finite and math.isfinite(weighted_value)
        if finite:
            scaler.scale(weighted).backward()
            if regret_loss is not None:
                with torch.no_grad():
                    sat_h.satvar_regret_updates += 1
        _dblock_clear_moe_aux_stash(core)
    with torch.no_grad():
        d_hist = {str(d + 1): int((d_idx == d).sum()) for d in range(SATVAR_KMAX) if int((d_idx == d).sum()) > 0}
    info = {
        "ran": True, "due": True, "finite": finite, "raw": raw_value, "weighted": weighted_value,
        "regret_loss": regret_value, "tokens": int(used), "available": int(available),
        "rows": int(rows), "seq_len": int(seq_len), "sizes": _satvar_size_hist(sizes),
        "d_hist": d_hist, "regret": regret_info, "weight": float(weight), "regret_weight": float(regret_w),
        "regret_updates": int(sat_h.satvar_regret_updates.item()), "schema": SATVAR_SCHEMA,
    }
    state["fullstack_satvar_anchor_attempts"] = int(state.get("fullstack_satvar_anchor_attempts", 0)) + 1
    state["fullstack_satvar_anchor_last"] = dict(info, step=step)
    if _dblock_audit_due(state, args):
        print("[dblock-satvar-anchor] " + json.dumps(dict(info, step=step), sort_keys=True, separators=(",", ":"), default=str), flush=True)
    del mask, anchor_ids, h, hidden, targets, raw, weighted, regret_loss
    return info


def _nat_boundary_ids(mask_id=None):
    """Return the pinned EOS/PAD and active NAT-mask IDs used as hard boundaries."""
    eos_pad = globals().get("EOS", None)
    if eos_pad is None:
        eos_pad = globals().get("_AGILLM43_REPAIR_EOS_PAD_ID", 1)
    active_mask = mask_id
    if active_mask is None:
        active_mask = globals().get(
            "NAT_MASK_ID", globals().get("_AGILLM43_REPAIR_NAT_MASK_ID", 2)
        )
    return int(eos_pad), int(active_mask)


def _nat_valid_intervals(row_ids, loss_mask_row=None, *, eos_pad_id=None, nat_mask_id=None):
    """Half-open packed-document runs; only EOS/PAD terminates context.

    loss_mask=False is prompt/unsupervised context, not a document boundary.
    The active NAT mask ID is validated separately and is never a clean target.
    """
    if row_ids.ndim != 1:
        raise ValueError("NAT document interval helper requires a one-dimensional token row")
    eos_default, _ = _nat_boundary_ids(nat_mask_id)
    eos_pad_id = eos_default if eos_pad_id is None else int(eos_pad_id)
    if loss_mask_row is not None and (
        loss_mask_row.ndim != 1
        or int(loss_mask_row.numel()) != int(row_ids.numel())
    ):
        raise ValueError("NAT loss-mask row shape differs from token row")
    content = row_ids.ne(eos_pad_id)
    edge = torch.zeros((1,), device=row_ids.device, dtype=torch.bool)
    padded = torch.cat((edge, content, edge))
    changes = torch.nonzero(padded[1:] != padded[:-1], as_tuple=False).flatten().tolist()
    return [
        (int(changes[i]), int(changes[i + 1]))
        for i in range(0, len(changes), 2)
    ]


def _dblock_audit_due(state=None, args=None):
    """Run heavyweight receipts only at the configured audit cadence."""
    if state is None:
        state = globals().get("_DBS")
    if not isinstance(state, dict):
        return True
    force = bool(state.get("diagnostic_force_full", False))
    if args is not None:
        force = force or bool(getattr(args, "repair_mode", False)) or bool(
            getattr(args, "repair_fail_fast", False)
        )
        every = max(1, int(getattr(args, "dblock_log_every", 25) or 25))
    else:
        every = max(1, int(state.get("diagnostic_every", 25) or 25))
    return bool(force or (int(state.get("step", 0)) % every == 0))


def _dblock_tensor_sha256(tensor):
    """Stable diagnostic digest; tensors are never serialized into run metadata."""
    if not _dblock_audit_due():
        return None
    cpu = tensor.detach().to(device="cpu", dtype=torch.int64).contiguous()
    prefix = json.dumps(
        {"shape": [int(x) for x in cpu.shape], "dtype": "int64"},
        sort_keys=True, separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(prefix + b"\n" + cpu.numpy().tobytes(order="C")).hexdigest()


def _dblock_token_boundary_diagnostics(tensor, loss_mask=None):
    """Minimal token receipt; no RNG, selectors, loss, or control-flow inputs."""
    if not torch.is_tensor(tensor) or tensor.ndim not in {1, 2}:
        raise ValueError("token diagnostics require a rank-1 or rank-2 tensor")
    if not _dblock_audit_due():
        eos_pad_id, nat_mask_id = _nat_boundary_ids()
        return {
            "sampled": False,
            "sha256": None,
            "shape": [int(value) for value in tensor.shape],
            "tokens": int(tensor.numel()),
            "eos_pad_id": int(eos_pad_id),
            "nat_mask_id": int(nat_mask_id),
            "eos_pad_count": None,
            "nat_mask_count": None,
            "eos_pad_count_by_row": None,
            "nat_mask_count_by_row": None,
            "loss_mask_sha256": None,
            "loss_mask_true": None,
            "loss_mask_false": None,
        }
    ids = tensor.detach().to(device="cpu", dtype=torch.int64).contiguous()
    rows = ids.unsqueeze(0) if ids.ndim == 1 else ids
    eos_pad_id, nat_mask_id = _nat_boundary_ids()
    eos_by_row = rows.eq(eos_pad_id).sum(dim=1)
    nat_mask_by_row = rows.eq(nat_mask_id).sum(dim=1)
    receipt = {
        "sampled": True,
        "sha256": _dblock_tensor_sha256(ids),
        "shape": [int(value) for value in ids.shape],
        "tokens": int(ids.numel()),
        "eos_pad_id": int(eos_pad_id),
        "nat_mask_id": int(nat_mask_id),
        "eos_pad_count": int(eos_by_row.sum().item()),
        "nat_mask_count": int(nat_mask_by_row.sum().item()),
        "eos_pad_count_by_row": [int(value) for value in eos_by_row.tolist()],
        "nat_mask_count_by_row": [
            int(value) for value in nat_mask_by_row.tolist()
        ],
    }
    if loss_mask is not None:
        if tuple(loss_mask.shape) != tuple(tensor.shape):
            raise ValueError("diagnostic loss mask shape differs from token IDs")
        mask = loss_mask.detach().to(device="cpu", dtype=torch.bool).contiguous()
        receipt.update({
            "loss_mask_sha256": _dblock_tensor_sha256(mask.to(torch.int64)),
            "loss_mask_true": int(mask.sum().item()),
            "loss_mask_false": int((~mask).sum().item()),
        })
    else:
        receipt.update({
            "loss_mask_sha256": None,
            "loss_mask_true": None,
            "loss_mask_false": None,
        })
    return receipt


def _dblock_token_ids_csv_sha256(tensor):
    if not _dblock_audit_due():
        return None
    values = tensor.detach().to(device="cpu", dtype=torch.int64).reshape(-1).tolist()
    return hashlib.sha256(
        ",".join(str(int(value)) for value in values).encode("ascii")
    ).hexdigest()


def _dblock_select_nat_anchor_crop(ids, loss_mask, seq_len, mask_id, step, rows=1):
    """Preserve a valid v10 crop; otherwise search EOS-delimited documents.
    v27.16.6: rows > 1 adds up to rows-1 further valid crops ("extra_crops"), spread through the
    candidate list from the primary crop and preferring other batch rows."""
    if ids.ndim != 2:
        raise ValueError("full-stack NAT anchor requires rank-2 token IDs")
    if loss_mask is not None and tuple(loss_mask.shape) != tuple(ids.shape):
        raise ValueError("full-stack NAT anchor loss mask shape differs from token IDs")
    eos_pad_id, mask_id = _nat_boundary_ids(mask_id)
    seq_len = int(seq_len)
    visible = seq_len // 2
    candidates = []
    eligible_rows = set()
    interval_count = 0
    content_positions = 0
    ids_cpu = ids.detach().to(device="cpu", dtype=torch.int64).contiguous()
    loss_mask_cpu = (
        None if loss_mask is None
        else loss_mask.detach().to(device="cpu", dtype=torch.bool).contiguous()
    )
    for row in range(int(ids_cpu.size(0))):
        row_ids_cpu = ids_cpu[row]
        row_loss_cpu = None if loss_mask_cpu is None else loss_mask_cpu[row]
        intervals = _nat_valid_intervals(
            row_ids_cpu, row_loss_cpu,
            eos_pad_id=eos_pad_id, nat_mask_id=mask_id,
        )
        mask_prefix = [0]
        mask_prefix.extend(
            torch.cumsum(row_ids_cpu.eq(mask_id).to(torch.int64), 0).tolist()
        )
        loss_prefix = None
        if row_loss_cpu is not None:
            loss_prefix = [0]
            loss_prefix.extend(
                torch.cumsum(row_loss_cpu.to(torch.int64), 0).tolist()
            )
        interval_count += len(intervals)
        for interval_start, interval_end in intervals:
            content_positions += int(interval_end - interval_start)
            if interval_end - interval_start < seq_len:
                continue
            for crop_start in range(
                int(interval_start), int(interval_end - seq_len + 1)
            ):
                if (
                    mask_prefix[crop_start + seq_len]
                    - mask_prefix[crop_start]
                ) > 0:
                    continue
                if loss_prefix is not None and (
                    loss_prefix[crop_start + seq_len]
                    - loss_prefix[crop_start + visible]
                ) <= 0:
                    continue
                candidates.append((
                    int(row), int(crop_start),
                    int(interval_start), int(interval_end),
                ))
                eligible_rows.add(int(row))
    total_windows = len(candidates)
    diagnostics = {
        "batch_sha256": _dblock_tensor_sha256(ids_cpu),
        "batch_shape": [int(ids_cpu.size(0)), int(ids_cpu.size(1))],
        "batch_eos_pad_count": int(ids_cpu.eq(eos_pad_id).sum().item()),
        "batch_nat_mask_count": int(ids_cpu.eq(mask_id).sum().item()),
        "batch_invalid_loss_count": (
            int((~loss_mask_cpu).sum().item())
            if loss_mask_cpu is not None else 0
        ),
        "loss_mask_sha256": (
            _dblock_tensor_sha256(loss_mask_cpu.to(dtype=torch.int64))
            if loss_mask_cpu is not None else None
        ),
        "eos_pad_id": int(eos_pad_id),
        "nat_mask_id": int(mask_id),
        "content_positions": int(content_positions),
        "valid_interval_count": int(interval_count),
        "eligible_row_count": int(len(eligible_rows)),
        "valid_window_count": int(total_windows),
        "required_crop_tokens": int(seq_len),
        "loss_mask_semantics": "target_filter_not_document_boundary",
    }

    original_row = (int(step) + 1) % max(1, int(ids.size(0)))
    max_start = max(0, int(ids.size(1)) - seq_len)
    original_start = (
        0 if max_start == 0
        else (
            int(step) * 15485863 + original_row * 2053 + 29
        ) % (max_start + 1)
    )
    original_valid = False
    original_reason = "sequence_too_short"
    if int(ids_cpu.size(1)) >= seq_len:
        original_crop = ids_cpu[
            original_row:original_row + 1,
            original_start:original_start + seq_len,
        ]
        original_valid = bool(
            int(original_crop.numel()) == seq_len
            and not bool(original_crop.eq(eos_pad_id).any())
            and not bool(original_crop.eq(mask_id).any())
        )
        if original_valid and loss_mask_cpu is not None:
            original_valid = bool(
                loss_mask_cpu[
                    original_row:original_row + 1,
                    original_start + visible:original_start + seq_len,
                ].any()
            )
            original_reason = (
                "valid" if original_valid else "no_supervised_targets"
            )
        elif original_valid:
            original_reason = "valid"
        else:
            original_reason = "special_token_boundary"
    diagnostics.update({
        "v10_original_row": int(original_row),
        "v10_original_start": int(original_start),
        "v10_original_valid": bool(original_valid),
        "v10_original_reason": str(original_reason),
    })
    if total_windows <= 0:
        return None, diagnostics

    chosen_tuple = None
    selection_source = ""
    if original_valid:
        for candidate in candidates:
            if candidate[0] == original_row and candidate[1] == original_start:
                chosen_tuple = candidate
                selection_source = "v10_original"
                break
        if chosen_tuple is None:
            raise RuntimeError(
                "valid v10 NAT anchor crop was absent from candidates"
            )
    else:
        index = (int(step) * 15485863 + 29) % total_windows
        chosen_tuple = candidates[index]
        selection_source = "document_fallback"
    row, start, interval_start, interval_end = chosen_tuple
    chosen = {
        "row": int(row),
        "start": int(start),
        "interval_start": int(interval_start),
        "interval_end": int(interval_end),
        "selection_source": str(selection_source),
    }
    extra_crops = []
    rows = max(1, int(rows or 1))
    if rows > 1 and total_windows > 1:
        chosen_index = candidates.index(chosen_tuple)
        stride = max(1, total_windows // rows)
        order = [(chosen_index + k * stride) % total_windows for k in range(1, rows)]
        order.extend((chosen_index + k) % total_windows for k in range(1, total_windows))
        taken = {(int(row), int(start))}
        taken_rows = {int(row)}
        deferred = []
        for index in order:
            cand = candidates[index]
            key = (int(cand[0]), int(cand[1]))
            if key in taken:
                continue
            if int(cand[0]) in taken_rows:
                deferred.append(cand)
                continue
            taken.add(key); taken_rows.add(int(cand[0]))
            extra_crops.append({"row": int(cand[0]), "start": int(cand[1])})
            if len(extra_crops) >= rows - 1:
                break
        for cand in deferred:
            if len(extra_crops) >= rows - 1:
                break
            key = (int(cand[0]), int(cand[1]))
            if key in taken:
                continue
            taken.add(key)
            extra_crops.append({"row": int(cand[0]), "start": int(cand[1])})
    chosen["extra_crops"] = extra_crops
    chosen["rows"] = 1 + len(extra_crops)
    crop_cpu = ids_cpu[row:row + 1, start:start + seq_len]
    target_ids_cpu = crop_cpu[:, visible:]
    target_loss_cpu = (
        None if loss_mask_cpu is None
        else loss_mask_cpu[row:row + 1, start + visible:start + seq_len]
    )
    diagnostics.update({
        **chosen,
        "selected_interval_tokens": int(interval_end - interval_start),
        "crop_sha256": _dblock_tensor_sha256(crop_cpu),
        "crop_token_ids_csv_sha256": _dblock_token_ids_csv_sha256(crop_cpu),
        "crop_eos_pad_count": int(crop_cpu.eq(eos_pad_id).sum().item()),
        "crop_nat_mask_count": int(crop_cpu.eq(mask_id).sum().item()),
        "target_stats": {
            "count": int(target_ids_cpu.numel()),
            "supervised_count": (
                int(target_loss_cpu.sum().item())
                if target_loss_cpu is not None else int(target_ids_cpu.numel())
            ),
            "unique": int(torch.unique(target_ids_cpu).numel()),
            "min_id": int(target_ids_cpu.min().item()),
            "max_id": int(target_ids_cpu.max().item()),
            "eos_pad_count": int(target_ids_cpu.eq(eos_pad_id).sum().item()),
            "nat_mask_count": int(target_ids_cpu.eq(mask_id).sum().item()),
            "sha256": _dblock_tensor_sha256(target_ids_cpu),
            "token_ids_csv_sha256": _dblock_token_ids_csv_sha256(target_ids_cpu),
        },
    })
    return chosen, diagnostics


def _dblock_nat_no_valid_crop_limit(args):
    raw = getattr(args, "dblock_fullstack_nat_no_valid_crop_limit", 8)
    if isinstance(raw, bool):
        raise ValueError("NAT no-valid-crop limit must be an integer")
    limit = int(raw)
    if limit <= 0:
        raise ValueError("NAT no-valid-crop limit must be positive")
    return limit


def _dblock_record_nat_no_valid_crop(state, args):
    consecutive = int(
        state.get("fullstack_nat_anchor_no_valid_crop_consecutive", 0)
    ) + 1
    total = int(state.get("fullstack_nat_anchor_no_valid_crop_total", 0)) + 1
    state["fullstack_nat_anchor_no_valid_crop_consecutive"] = consecutive
    state["fullstack_nat_anchor_no_valid_crop_total"] = total
    return consecutive, total, _dblock_nat_no_valid_crop_limit(args)


def _dblock_fullstack_nat_anchor(core, nat_h, scaler, args, ids, state, loss_mask=None):
    """Rare B=1,T=128 single-document clean-prefix/masked-suffix NAT CE anchor."""
    M = _agillm41_sys.modules[__name__]
    every = _dblock_fullstack_anchor_int(args, "dblock_fullstack_nat_every", 0)
    offset = _dblock_fullstack_anchor_signed_int(args, "dblock_fullstack_nat_offset", 20)
    requested_tokens = _dblock_fullstack_anchor_int(args, "dblock_fullstack_nat_tokens", 0)
    weight = _dblock_fullstack_aux_weight(args, "dblock_fullstack_nat_weight")
    step = int(state.get("step", 0))
    due = (
        nat_h is not None and every > 0 and requested_tokens > 0 and weight > 0.0
        and _dblock_fullstack_anchor_due(step, every, offset)
    )
    if not due:
        return {"ran": False, "due": False, "finite": True, "raw": 0.0, "weighted": 0.0, "tokens": 0}
    # v27.16.2: the overlap guard exists for the AR/SAT/NAT every=3 round-robin.
    # With dblock_fullstack_ar_every == 1 the AR anchor is due on every step,
    # so the guard starved this anchor completely (0 NAT anchors since hot rev6);
    # in that regime the anchors run back to back and the guard is skipped.
    _ar_every = _dblock_fullstack_anchor_int(args, "dblock_fullstack_ar_every", 0)
    if _ar_every != 1 and (
        _dblock_fullstack_ar_due(args, state) or _dblock_fullstack_sat_due(args, state)
    ):
        state["fullstack_nat_anchor_skipped_overlap"] = int(
            state.get("fullstack_nat_anchor_skipped_overlap", 0)
        ) + 1
        return {"ran": False, "due": True, "finite": True, "reason": "fullstack_anchor_overlap", "tokens": 0}

    if requested_tokens != 128:
        raise ValueError(
            f"initial full-stack NAT recovery anchor requires exactly 128 sequence tokens, got {requested_tokens}"
        )
    seq_len, visible = requested_tokens, requested_tokens // 2
    mask_id = _dblock_fullstack_anchor_signed_int(args, "dblock_fullstack_nat_mask_id", -1)
    mask_source = "runtime_nat_mask_id" if mask_id < 0 else "explicit"
    try:
        mask_id = int(M._resolve_nat_mask_id(mask_id, require_active=True))
    except Exception as exc:
        raise RuntimeError(
            "full-stack NAT anchor requires the active runtime NAT_MASK_ID contract"
        ) from exc
    vocab_size = int(getattr(core.emb, "num_embeddings", 0) or 0)
    if vocab_size > 0 and mask_id >= vocab_size:
        raise ValueError(f"full-stack NAT anchor mask id {mask_id} outside vocab size {vocab_size}")

    _nat_rows = max(1, _dblock_fullstack_anchor_int(args, "dblock_fullstack_nat_rows", 1))
    selection, diagnostics = _dblock_select_nat_anchor_crop(
        ids, loss_mask, seq_len, mask_id, step, rows=_nat_rows
    )
    state["fullstack_nat_anchor_attempts"] = int(
        state.get("fullstack_nat_anchor_attempts", 0)
    ) + 1
    if selection is None:
        if int(ids.size(1)) < seq_len:
            state["fullstack_nat_anchor_skipped_short"] = int(
                state.get("fullstack_nat_anchor_skipped_short", 0)
            ) + 1
        consecutive, total, limit = _dblock_record_nat_no_valid_crop(state, args)
        info = {
            "ran": False, "due": True, "finite": True, "raw": 0.0,
            "weighted": 0.0, "tokens": 0,
            "reason": "no_valid_doc_crop_telemetry",
            "retry_no_valid_doc_crop": False,
            "no_valid_crop_consecutive": int(consecutive),
            "no_valid_crop_total": int(total),
            "no_valid_crop_limit": int(limit),
            "limit_reached": bool(consecutive >= limit),
            "diagnostics": diagnostics,
        }
        state["fullstack_nat_anchor_last"] = _dblock_json_copy({
            "step": step, **info,
        })
        print(
            f"[dblock-nat-anchor] step={step} no valid single-document "
            f"{seq_len}-token crop; telemetry={consecutive}/{limit} "
            f"batch_sha256={diagnostics['batch_sha256']}",
            flush=True,
        )
        return info

    state["fullstack_nat_anchor_no_valid_crop_consecutive"] = 0
    row, start = int(selection["row"]), int(selection["start"])
    # v27.16.6: primary crop first, then the extra crops (all valid single-document windows).
    _crops = [(row, start)] + [
        (int(e["row"]), int(e["start"])) for e in (selection.get("extra_crops") or [])
    ]
    clean_ids = torch.stack([ids[r, s:s + seq_len] for r, s in _crops], dim=0)
    nat_input = clean_ids.clone()
    nat_input[:, visible:] = int(mask_id)
    anchor_loss_mask = None
    if loss_mask is not None:
        anchor_loss_mask = torch.stack(
            [loss_mask[r, s + visible:s + seq_len] for r, s in _crops], dim=0
        )
        if not bool(anchor_loss_mask.any()):
            raise RuntimeError("selected NAT document crop has no supervised target position")

    with _dblock_deterministic_anchor_context(core, nat_input):
        _dblock_clear_moe_aux_stash(core)
        h = _dblock_fullstack_hidden(core, nat_input, None, args)
        hidden, targets, used, available = _sample_token_loss_inputs(
            h[:, visible:], clean_ids[:, visible:], len(_crops) * (seq_len - visible), anchor_loss_mask
        )
        raw = fused_ce(hidden, nat_h.proj.weight, targets)
        raw_value = float(raw.detach())
        raw_is_finite = math.isfinite(raw_value)
        softcap_probe = _dblock_anchor_softcap_probe(
            state, args, "nat", raw_value
        ) if raw_is_finite else {
            "gradient_scale": 1.0, "softcapped": False, "cap_ce": None,
            "effective_ce": float("nan"), "ema_next": None,
        }
        uncapped_weighted_value = float(weight) * raw_value if raw_is_finite else float("nan")
        weighted = float(weight) * raw * float(softcap_probe["gradient_scale"])
        _dblock_clear_moe_aux_stash(core)
        weighted_value = float(weighted.detach())
        finite = math.isfinite(weighted_value)
        spike_probe = _dblock_anchor_spike_probe(state, args, "nat", raw_value) if finite else {
            "spike": False, "baseline": None, "ema_next": None,
            "multiplier": 0.0, "absolute_max": 0.0, "reason": "nonfinite",
        }
        spike = bool(spike_probe.get("spike", False))
        if finite and not spike:
            _dblock_observe_anchor_nonspike(state, "nat")
            scaler.scale(weighted).backward()
        _dblock_clear_moe_aux_stash(core)
    diagnostics["sampled_target_count"] = int(used)
    diagnostics["rows"] = int(len(_crops))
    state["fullstack_nat_anchor_last"] = {
        "deterministic_eval": True, "rows": int(len(_crops)),
        "step": step, "raw_ce": raw_value, "weighted": weighted_value,
        "uncapped_weighted": uncapped_weighted_value,
        "softcap_applied": bool(softcap_probe.get("softcapped", False)),
        "softcap_ce": softcap_probe.get("cap_ce"),
        "softcap_gradient_scale": float(softcap_probe.get("gradient_scale", 1.0)),
        "tokens": int(used), "available": int(available), "row": int(row),
        "start": int(start), "seq_len": int(seq_len), "visible": int(visible),
        "masked": int(seq_len - visible), "mask_id": int(mask_id),
        "mask_source": str(mask_source),
        "spike": spike, "spike_reason": spike_probe.get("reason"),
        "spike_baseline": spike_probe.get("baseline"),
        "diagnostics": diagnostics,
    }
    if _dblock_audit_due(state, args):
        print(
            f"[dblock-nat-anchor] step={step} raw_ce={raw_value:.4f} weight={weight:.4f} "
            f"weighted={weighted_value:.4f} targets={int(used)}/{int(available)} "
            f"crop=row{row}:{start}+{seq_len} rows={len(_crops)} visible={visible} mask_id={mask_id} "
            f"crop_sha256={diagnostics['crop_sha256']} finite={finite} "
            f"spike={spike} baseline={spike_probe.get('baseline')} softcap={softcap_probe.get('softcapped')} "
            f"cap_ce={softcap_probe.get('cap_ce')} grad_scale={softcap_probe.get('gradient_scale', 1.0):.6f}",
            flush=True,
        )
    del clean_ids, nat_input, h, hidden, targets, raw, weighted
    return {
        "ran": True, "due": True, "finite": finite, "raw": raw_value,
        "weighted": weighted_value, "tokens": int(used), "row": int(row),
        "start": int(start), "seq_len": int(seq_len), "visible": int(visible),
        "masked": int(seq_len - visible), "mask_id": int(mask_id),
        "mask_source": str(mask_source),
        "spike": spike, "spike_reason": spike_probe.get("reason"),
        "spike_baseline": spike_probe.get("baseline"),
        "anchor_ema_next": softcap_probe.get("ema_next"),
        "uncapped_weighted": uncapped_weighted_value,
        "softcap_applied": bool(softcap_probe.get("softcapped", False)),
        "softcap_ce": softcap_probe.get("cap_ce"),
        "softcap_gradient_scale": float(softcap_probe.get("gradient_scale", 1.0)),
        "diagnostics": diagnostics,
    }

def _dblock_scalar_values(*tensors):
    """Read scalar telemetry tensors with one CUDA synchronization."""
    if not tensors:
        return ()
    packed = torch.stack([
        tensor.detach().to(dtype=torch.float32).reshape(())
        for tensor in tensors
    ])
    return tuple(float(value) for value in packed.cpu().tolist())


def _dblock_scaler_step_committed(scale_before, scale_after):
    """GradScaler lowers its scale exactly when scaler.step skipped the optimizer."""
    return not (
        scale_before is not None and scale_after is not None and scale_after < scale_before
    )


def _dblock_local_embedding(core, ids):
    """Embedding values for a local band, detached from shared vocabulary state."""
    return core.emb(ids).detach()


def _dblock_local_final_norm(core, hidden):
    """LayerNorm with frozen affine values while preserving dL/d(hidden)."""
    norm = core.ln
    if not isinstance(norm, nn.LayerNorm):
        raise RuntimeError("strict local DBlock isolation requires nn.LayerNorm final norm")
    weight = norm.weight.detach() if norm.weight is not None else None
    bias = norm.bias.detach() if norm.bias is not None else None
    return F.layer_norm(hidden, norm.normalized_shape, weight, bias, norm.eps)


def _dblock_local_head_weight(head):
    """Tied vocab matrix as a constant; CE gradients still flow into the band."""
    proj = getattr(head, "proj", None)
    weight = getattr(proj, "weight", None)
    if weight is None:
        raise RuntimeError("strict local DBlock isolation requires a linear tied projection")
    return weight.detach()




def _dblock_select_train_layers(state, args, block_idx, forward_layers):
    """Choose which forward-context layers receive *local* gradients.

    Forward topology and train granularity are intentionally separate contracts.
    The forward span remains checkpoint-compatible; a smaller train span merely
    freezes the other context layers for that local pass.  Selection is derived
    from the already-checkpointed per-block commit counter, so restart/resume is
    deterministic without adding another mutable sidecar.
    """
    forward_layers = [int(x) for x in forward_layers]
    if not forward_layers:
        raise ValueError("DBlock forward context may not be empty")
    requested = int(getattr(args, "dblock_train_layers_per_update", 0) or 0)
    if requested <= 0 or requested == len(forward_layers):
        return list(forward_layers)
    if requested < 1 or requested > len(forward_layers):
        raise ValueError(
            f"--dblock_train_layers_per_update={requested} cannot fit forward "
            f"context {forward_layers}; change forward topology only via an explicit migration"
        )
    policy = str(getattr(args, "dblock_train_layer_policy", "cyclic") or "cyclic").lower()
    if policy != "cyclic":
        raise ValueError(f"unsupported DBlock train-layer policy {policy!r}")
    counts = list(state.get("counts", []))
    committed_for_block = int(counts[int(block_idx)]) if int(block_idx) < len(counts) else 0
    start = committed_for_block % len(forward_layers)
    return [forward_layers[(start + j) % len(forward_layers)] for j in range(requested)]


def _dblock_clear_moe_stash_for_layers(core, layer_ids):
    # A frozen context layer must not regain a local gradient through the
    # post-forward MoE auxiliary-loss recomputation.
    for li in layer_ids:
        for module in core.blocks[int(li)].modules():
            if hasattr(module, "last_router_input"):
                module.last_router_input = None


def _dblock_select_train_sublayers(state, args, block_idx, forward_layers, train_layers):
    """Choose principal sublayer gradients without changing the forward function.

    With the safe one-sublayer primitive, each two-layer DBlock visits:
    layer0-attn, layer1-attn, layer0-ffn, layer1-ffn, then repeats. The
    checkpointed per-block commit counter is the only schedule state, so a
    rejected attempt retries the same target and resume is deterministic.
    """
    forward_layers = [int(x) for x in forward_layers]
    train_layers = [int(x) for x in train_layers]
    requested = int(getattr(args, "dblock_train_sublayers_per_update", 0) or 0)
    policy = str(getattr(args, "dblock_train_sublayer_policy", "cyclic") or "cyclic").lower()
    if requested <= 0:
        return {int(li): "full" for li in train_layers}
    if requested != 1:
        raise ValueError("--dblock_train_sublayers_per_update currently supports only 0 or 1")
    if policy != "cyclic":
        raise ValueError(f"unsupported DBlock train-sublayer policy {policy!r}")
    if len(train_layers) != 1:
        raise RuntimeError(
            "safe one-sublayer local gradients require exactly one selected physical layer; "
            "extend this primitive explicitly before enabling variable multi-layer local gradients"
        )
    forward_mode = _dblock_sublayer_base_mode(args)
    if forward_mode not in {"off", "full"}:
        raise RuntimeError(
            "safe train-sublayer gradients require --dblock_sublayer_mode off/full so both "
            "attention and FFN remain in the forward path"
        )
    counts = list((state or {}).get("counts", []))
    committed_for_block = int(counts[int(block_idx)]) if int(block_idx) < len(counts) else 0
    if not forward_layers:
        raise ValueError("DBlock forward context may not be empty")
    expected_layer = int(forward_layers[committed_for_block % len(forward_layers)])
    selected_layer = int(train_layers[0])
    if selected_layer != expected_layer:
        raise RuntimeError(
            "train-layer and train-sublayer cyclic schedules diverged: "
            f"block={int(block_idx)} count={committed_for_block} "
            f"expected_layer={expected_layer} selected_layer={selected_layer}"
        )
    sublayer_phase = (committed_for_block // len(forward_layers)) % 2
    return {selected_layer: ("attn" if sublayer_phase == 0 else "ffn")}


def _dblock_sublayer_modules(block, sublayer):
    mode = str(sublayer or "full").lower()
    if mode == "attn":
        return (block.ln1, block.mha)
    if mode == "ffn":
        return (block.ln2, block.ff)
    if mode == "full":
        return (block,)
    raise ValueError(f"unknown train sublayer {sublayer!r}")


def _dblock_freeze_unselected_sublayer(block, train_sublayer):
    mode = str(train_sublayer or "full").lower()
    if mode == "full":
        return []
    if mode == "attn":
        freeze_modules = (block.ln2, block.ff)
    elif mode == "ffn":
        freeze_modules = (block.ln1, block.mha)
    else:
        raise ValueError(f"unknown train sublayer {train_sublayer!r}")
    snapshots = []
    seen = set()
    for module in freeze_modules:
        for param in module.parameters():
            if id(param) in seen:
                continue
            seen.add(id(param))
            snapshots.append((param, bool(param.requires_grad)))
            param.requires_grad_(False)
    return snapshots


def _dblock_selected_train_params(core, train_layers, train_sublayers=None):
    train_sublayers = dict(train_sublayers or {})
    params = []
    seen = set()
    for li in train_layers:
        li = int(li)
        mode = str(train_sublayers.get(li, "full") or "full").lower()
        for module in _dblock_sublayer_modules(core.blocks[li], mode):
            for param in module.parameters():
                if param.requires_grad and id(param) not in seen:
                    seen.add(id(param))
                    params.append(param)
    return params


def _dblock_train_sublayer_receipt(core, train_layers, train_sublayers):
    rows = []
    total = 0
    for li in train_layers:
        li = int(li)
        mode = str((train_sublayers or {}).get(li, "full") or "full").lower()
        seen = set()
        count = 0
        for module in _dblock_sublayer_modules(core.blocks[li], mode):
            for param in module.parameters():
                if id(param) in seen:
                    continue
                seen.add(id(param))
                count += int(param.numel())
        rows.append({"layer": li, "sublayer": mode, "params": int(count)})
        total += int(count)
    return rows, int(total)


def _dblock_local_span_forward(core, bi, forward_layers, train_layers, h, mask,
                               use_layer_checkpoint, args, state,
                               train_sublayers=None):
    """Run the checkpoint-compatible full forward while limiting local gradients.

    Both attention and FFN remain in the forward function. Frozen parameters
    still propagate dL/d(input). For a selected principal sublayer, checkpoint
    recomputation on that physical layer is disabled so restoring requires_grad
    before backward cannot recreate gradients for the frozen sibling sublayer.
    """
    forward_layers = [int(x) for x in forward_layers]
    train_layers = [int(x) for x in train_layers]
    train_sublayers = dict(train_sublayers or {int(li): "full" for li in train_layers})
    if not set(train_layers).issubset(set(forward_layers)) or not train_layers:
        raise ValueError(
            f"local train layers {train_layers} must be a non-empty subset of forward layers {forward_layers}"
        )
    selective = set(train_layers) != set(forward_layers)
    selective_sublayer = any(
        str(train_sublayers.get(int(li), "full")).lower() != "full" for li in train_layers
    )
    if (selective or selective_sublayer) and getattr(core, "hc", None) is not None:
        raise RuntimeError(
            "selective local layer/sublayer gradients are not yet defined for Hyper-Connections; "
            "use full forward-span training or a versioned HC migration"
        )
    frozen_layers = [li for li in forward_layers if li not in set(train_layers)]
    snapshots = []
    frozen_ffn_layers = []
    for li in frozen_layers:
        for param in core.blocks[li].parameters():
            snapshots.append((param, bool(param.requires_grad)))
            param.requires_grad_(False)
    for li in train_layers:
        sublayer = str(train_sublayers.get(int(li), "full") or "full").lower()
        snapshots.extend(_dblock_freeze_unselected_sublayer(core.blocks[int(li)], sublayer))
        if sublayer == "attn":
            frozen_ffn_layers.append(int(li))
    try:
        out = h
        for lpos, li in enumerate(forward_layers):
            forward_mode = _dblock_sublayer_mode_for_layer(args, state, bi, lpos)
            train_mode = str(train_sublayers.get(int(li), "full") or "full").lower()
            checkpoint_this = (
                int(li) in set(train_layers)
                and _dblock_checkpoint_this_layer(
                    args, use_layer_checkpoint, lpos, len(forward_layers)
                )
            )
            out = _run_block(
                core.blocks[int(li)], out, mask, checkpoint_this, args, forward_mode,
                train_sublayer=(train_mode if int(li) in set(train_layers) else "full"),
            )
        return out
    finally:
        _dblock_clear_moe_stash_for_layers(core, list(frozen_layers) + list(frozen_ffn_layers))
        for param, original in snapshots:
            param.requires_grad_(original)


def _dblock_ar_protected_aux_grad(
    core, ar_h, scaler, args, ids, layers, bi, sig, cs, co, ci, edm_weight,
    use_layer_checkpoint, state, loss_mask=None, train_layers=None,
    train_sublayers=None,
):
    """Project SAT/NAT shared-block gradients away from AR conflict and norm-cap them.

    GradScaler applies the same scale to both gradients, so dot products, projection,
    and the norm ratio are invariant in the scaled-gradient domain. Head-specific
    SAT/NAT gradients are untouched; only shared selected-block gradients are guarded.
    """
    ratio = max(0.0, float(getattr(args, "dblock_aux_grad_ratio", 0.5) or 0.0))
    train_layers = list(layers if train_layers is None else train_layers)
    params = _dblock_selected_train_params(
        core, train_layers, train_sublayers=train_sublayers
    )

    aux_grads = {}
    for param in params:
        if param.grad is not None:
            aux_grads[id(param)] = param.grad.detach().clone()
        param.grad = None
    if not aux_grads:
        return {
            "ran": False, "reason": "no_shared_aux_gradients", "objective_block": int(bi),
            "ar_tokens": 0,
        }

    # cudaMallocAsync keeps dead blocks reusable without a device-wide cache
    # synchronization. OOM recovery still performs an explicit reclaim.

    M = _agillm41_sys.modules[__name__]
    T = int(ids.size(1))
    causal = M.causal_mask(T, structured=M.use_structured_masks(args))
    _cc_mode = _dblock_clean_context_mode(args)
    ids_ref, lm_ref = ids, loss_mask
    with M.amp(args.amp):
        if _cc_mode in ("deep", "e2e"):
            # v27.16.3: the AR reference direction must be the objective the AR
            # steps actually train (deep clean context below the block, frozen
            # checkpointed stack above it in e2e mode) on the same local rows;
            # the legacy whole-batch noised-embedding reference was the
            # non-composing objective and the memory peak of every SAT/NAT step.
            _rows = _dblock_local_rows(args, ids)
            ids_ref = ids[:_rows]
            lm_ref = loss_mask[:_rows] if loss_mask is not None else None
            emb = _dblock_deep_context_input(core, ids_ref, min(int(x) for x in layers), causal, args)
            zt = _dblock_clean_context_noise(args, sig[:_rows], emb)
            h = (
                _dblock_loop_condition(core, zt, bi, args)
                if bool(getattr(args, "dblock_looped", False))
                else zt
            )
            h = _dblock_local_span_forward(
                core, bi, layers, train_layers, h, causal,
                use_layer_checkpoint, args, state,
                train_sublayers=train_sublayers,
            )
            if _cc_mode == "e2e":
                h = _dblock_frozen_suffix_forward(core, max(int(x) for x in layers), h, causal, args)
            denoised = _dblock_local_final_norm(core, h)
        else:
            emb = _dblock_local_embedding(core, ids)
            zt = emb + sig[:, None, None] * torch.randn_like(emb)
            h = (
                _dblock_loop_condition(core, ci * zt, bi, args)
                if bool(getattr(args, "dblock_looped", False))
                else ci * zt
            )
            h = _dblock_local_span_forward(
                core, bi, layers, train_layers, h, causal,
                use_layer_checkpoint, args, state,
                train_sublayers=train_sublayers,
            )
            denoised = _dblock_local_final_norm(core, cs * zt + co * h)

    ar_loss_mask = lm_ref[:, 1:] if lm_ref is not None else None
    ar_hidden, ar_targets, ar_used, ar_total = _sample_token_loss_inputs(
        denoised[:, :-1], ids_ref[:, 1:], _dblock_loss_token_cap(args, "ar"),
        ar_loss_mask,
    )
    ar_raw = fused_ce(
        ar_hidden, _dblock_local_head_weight(ar_h), ar_targets
    )
    ar_weight = _dblock_hot_float(
        args, "dblock_ar_weight", 1.0, min_value=0.0
    )
    ar_ref = ar_weight * edm_weight * ar_raw
    _dblock_clear_moe_aux_stash(core)
    scaler.scale(ar_ref).backward()
    _dblock_clear_moe_aux_stash(core)

    device = ids.device
    dot = torch.zeros((), device=device, dtype=torch.float32)
    ar_sq = torch.zeros((), device=device, dtype=torch.float32)
    aux_sq = torch.zeros((), device=device, dtype=torch.float32)
    paired = 0
    dropped_unreferenced = 0
    for param in params:
        aux = aux_grads.get(id(param))
        ar = param.grad
        if aux is not None:
            aux_sq = aux_sq + aux.float().square().sum()
        if ar is not None:
            ar_sq = ar_sq + ar.detach().float().square().sum()
        if aux is not None and ar is not None:
            dot = dot + (aux.float() * ar.detach().float()).sum()
            paired += 1

    dot_value, ar_sq_value, aux_sq_value, ar_raw_value, ar_ref_value = _dblock_scalar_values(
        dot, ar_sq, aux_sq, ar_raw, ar_ref
    )
    finite = all(math.isfinite(v) for v in (dot_value, ar_sq_value, aux_sq_value))
    if (not finite) or ar_sq_value <= 0.0:
        for param in params:
            if id(param) in aux_grads:
                param.grad = None
        result = {
            "ran": False,
            "reason": "invalid_ar_reference_gradient",
            "finite": bool(finite),
            "dot": dot_value if math.isfinite(dot_value) else None,
            "ar_norm": math.sqrt(ar_sq_value) if ar_sq_value > 0.0 and math.isfinite(ar_sq_value) else None,
            "aux_norm": math.sqrt(aux_sq_value) if aux_sq_value >= 0.0 and math.isfinite(aux_sq_value) else None,
            "objective_block": int(bi),
            "ar_tokens": int(ar_used),
        }
        print("[aux-grad-guard] " + json.dumps(
            result, sort_keys=True, separators=(",", ":"), allow_nan=False
        ), flush=True)
        del causal, emb, zt, h, denoised, ar_hidden, ar_targets, ar_raw, ar_ref
        return result

    conflict = dot_value < 0.0
    projection_coeff = (dot_value / ar_sq_value) if conflict else 0.0
    projected_sq = (
        max(0.0, aux_sq_value - (dot_value * dot_value) / ar_sq_value)
        if conflict else max(0.0, aux_sq_value)
    )
    ar_norm = math.sqrt(ar_sq_value)
    projected_aux_norm = math.sqrt(projected_sq)
    cap_scale = (
        min(1.0, (ratio * ar_norm) / max(projected_aux_norm, 1e-12))
        if ratio > 0.0 else 0.0
    )

    for param in params:
        aux = aux_grads.get(id(param))
        ar = param.grad
        if ar is None:
            if aux is not None:
                dropped_unreferenced += 1
            param.grad = None
            continue
        if aux is None:
            continue
        # g = g_ar + scale * (g_aux - coeff*g_ar)
        ar.mul_(1.0 - cap_scale * projection_coeff).add_(
            aux, alpha=cap_scale
        )

    result = {
        "ran": True,
        "method": "same_step_ar_reference_pcgrad",
        "objective_block": int(bi),
        "conflict_projected": bool(conflict),
        "dot_before": dot_value,
        "ar_norm": ar_norm,
        "aux_norm_before": math.sqrt(max(0.0, aux_sq_value)),
        "aux_norm_after_projection": projected_aux_norm,
        "aux_cap_scale": cap_scale,
        "max_aux_to_ar_ratio": ratio,
        "paired_tensors": int(paired),
        "dropped_unreferenced_tensors": int(dropped_unreferenced),
        "ar_raw_ce": ar_raw_value,
        "ar_weighted": ar_ref_value,
        "ar_tokens": int(ar_used),
        "ar_available_tokens": int(ar_total),
    }
    if _dblock_audit_due(state, args):
        print("[aux-grad-guard] " + json.dumps(
            result, sort_keys=True, separators=(",", ":"), allow_nan=False
        ), flush=True)
    aux_grads.clear()
    del causal, emb, zt, h, denoised, ar_hidden, ar_targets, ar_raw, ar_ref
    # Dead guard storage remains reusable by cudaMallocAsync; avoid synchronizing
    # the ordinary SAT/NAT path. The OOM handler remains the hard fallback.
    return result



# ===== BEGIN AGILLM43 WEIGHT-TRAJECTORY ACCELERATOR V1 2026-08-26 =====
_WEIGHT_ACCEL_SCHEMA = "agillm43.weight-trajectory.v1"
_WEIGHT_ACCEL_STATE_SCHEMA = "agillm43.weight-trajectory-state.v1"
_WEIGHT_ACCEL_MODES = {"off", "capture", "shadow", "apply"}


def _weight_accel_mode(args) -> str:
    mode = str(getattr(args, "weight_accel_mode", "off") or "off").strip().lower()
    if mode not in _WEIGHT_ACCEL_MODES:
        raise ValueError(
            f"unknown --weight_accel_mode {mode!r}; choose one of "
            + ", ".join(sorted(_WEIGHT_ACCEL_MODES))
        )
    return mode


def _weight_accel_finite_float(value, default=0.0) -> float:
    try:
        out = float(value)
    except Exception:
        return float(default)
    return out if math.isfinite(out) else float(default)


def _weight_accel_atomic_torch_save(payload, path: pathlib.Path) -> None:
    path = pathlib.Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + f".{os.getpid()}.tmp")
    torch.save(payload, tmp)
    with open(tmp, "rb") as fh:
        os.fsync(fh.fileno())
    os.replace(tmp, path)


def _weight_accel_append_jsonl(path: pathlib.Path, payload: dict) -> None:
    path = pathlib.Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    line = json.dumps(
        payload, sort_keys=True, separators=(",", ":"), allow_nan=False
    ) + "\n"
    with open(path, "a", encoding="utf-8", buffering=1) as fh:
        fh.write(line)
        fh.flush()


class _WeightTrajectoryPredictor(nn.Module):
    """Tiny CPU transformer that predicts a linear combination of recent updates.

    It never generates a billion raw scalars. It learns coefficients over recent
    real block deltas, which preserves the proposed learned weight-space mapping
    while keeping the first implementation feasible on one RTX 3090.
    """

    def __init__(
        self,
        history: int,
        sketch_dim: int,
        hidden: int,
        heads: int,
        layers: int,
        max_blocks: int,
        max_scale: float = 2.0,
    ):
        super().__init__()
        history = int(history)
        sketch_dim = int(sketch_dim)
        hidden = int(hidden)
        heads = int(heads)
        layers = int(layers)
        if history < 2:
            raise ValueError("weight accelerator history must be >= 2")
        if sketch_dim < 8:
            raise ValueError("weight accelerator sketch_dim must be >= 8")
        if hidden < 16 or heads < 1 or hidden % heads:
            raise ValueError("weight accelerator hidden must be >=16 and divisible by heads")
        if layers < 1:
            raise ValueError("weight accelerator transformer layers must be >= 1")
        self.history = history
        self.sketch_dim = sketch_dim
        self.max_scale = max(1.0, float(max_scale))
        self.input_proj = nn.Linear(sketch_dim + 6, hidden)
        self.block_embed = nn.Embedding(max(1, int(max_blocks)), hidden)
        self.position = nn.Parameter(torch.zeros(1, history, hidden))
        enc_layer = nn.TransformerEncoderLayer(
            d_model=hidden,
            nhead=heads,
            dim_feedforward=hidden * 4,
            dropout=0.0,
            activation="gelu",
            batch_first=True,
            norm_first=True,
        )
        self.encoder = nn.TransformerEncoder(enc_layer, num_layers=layers)
        self.norm = nn.LayerNorm(hidden)
        self.head = nn.Linear(hidden, history + 1)
        nn.init.normal_(self.position, mean=0.0, std=0.01)
        nn.init.zeros_(self.head.weight)
        nn.init.constant_(self.head.bias, -2.0)
        with torch.no_grad():
            self.head.bias[history - 1] = 2.0  # begin as repeat-the-latest
            self.head.bias[history] = 0.0      # scale begins at 1

    def forward(
        self,
        sketches: torch.Tensor,
        contexts: torch.Tensor,
        block_ids: torch.Tensor,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        if sketches.ndim != 3 or sketches.shape[1:] != (
            self.history,
            self.sketch_dim,
        ):
            raise ValueError(
                f"bad sketch shape {tuple(sketches.shape)}; expected "
                f"[batch,{self.history},{self.sketch_dim}]"
            )
        if contexts.shape != (sketches.shape[0], self.history, 6):
            raise ValueError(f"bad context shape {tuple(contexts.shape)}")
        rms = sketches.square().mean(dim=-1, keepdim=True).sqrt().clamp_min(1.0e-12)
        normalized = sketches / rms
        x = torch.cat([normalized, contexts], dim=-1)
        x = self.input_proj(x)
        x = x + self.position + self.block_embed(block_ids).unsqueeze(1)
        x = self.encoder(x)
        pooled = self.norm(x[:, -1])
        raw = self.head(pooled)
        mixture = torch.softmax(raw[:, : self.history], dim=-1)
        log_scale = torch.tanh(raw[:, self.history]) * math.log(self.max_scale)
        coeffs = mixture * torch.exp(log_scale).unsqueeze(-1)
        prediction = torch.einsum("bh,bhd->bd", coeffs, sketches)
        return prediction, coeffs


class _WeightTrajectoryRuntime:
    def __init__(self, core: nn.Module, args, state: dict):
        self.mode = _weight_accel_mode(args)
        self.history_len = max(2, int(getattr(args, "weight_accel_history", 4) or 4))
        self.sketch_dim = max(
            8, int(getattr(args, "weight_accel_sketch_dim", 128) or 128)
        )
        self.block_count = max(1, int(state.get("B", 1) or 1))
        hidden = max(16, int(getattr(args, "weight_accel_hidden", 64) or 64))
        heads = max(1, int(getattr(args, "weight_accel_heads", 4) or 4))
        layers = max(1, int(getattr(args, "weight_accel_layers", 2) or 2))
        if hidden % heads:
            raise ValueError("--weight_accel_hidden must be divisible by --weight_accel_heads")
        self.model = _WeightTrajectoryPredictor(
            history=self.history_len,
            sketch_dim=self.sketch_dim,
            hidden=hidden,
            heads=heads,
            layers=layers,
            max_blocks=self.block_count,
            max_scale=float(getattr(args, "weight_accel_max_scale", 2.0) or 2.0),
        ).to(device="cpu", dtype=torch.float32)
        self.optimizer = torch.optim.AdamW(
            self.model.parameters(),
            lr=float(getattr(args, "weight_accel_lr", 3.0e-4) or 3.0e-4),
            weight_decay=1.0e-4,
        )
        self.histories: dict[int, list[dict]] = {
            i: [] for i in range(self.block_count)
        }
        self.full_histories: dict[int, list[dict[str, torch.Tensor]]] = {
            i: [] for i in range(self.block_count)
        }
        self.metrics: dict[int, dict] = {
            i: {
                "samples": 0,
                "cos_ema": None,
                "baseline_cos_ema": None,
                "rel_error_ema": None,
                "baseline_rel_error_ema": None,
                "win_ema": None,
            }
            for i in range(self.block_count)
        }
        self.samples = 0
        self.trained_samples = 0
        self.accepted_jumps = 0
        self.rejected_jumps = 0
        self.pending: dict | None = None
        self.candidate: dict | None = None
        self._plans: dict[tuple[int, tuple[int, ...]], list] = {}
        self.architecture_sha256 = self._architecture_digest(core)
        configured_dir = str(getattr(args, "weight_accel_dir", "") or "").strip()
        base_dir = pathlib.Path(configured_dir) if configured_dir else (
            pathlib.Path(getattr(args, "save_dir", ".")) / "weight_trajectory_accel"
        )
        self.directory = base_dir.expanduser().resolve()
        self.directory.mkdir(parents=True, exist_ok=True)
        self.state_path = self.directory / "predictor_state.pt"
        self.trajectory_path = self.directory / "trajectory.jsonl"
        self.events_path = self.directory / "events.jsonl"
        self._load_state()
        self._event(
            "weight_accel_boot",
            mode=self.mode,
            architecture_sha256=self.architecture_sha256,
            history=self.history_len,
            sketch_dim=self.sketch_dim,
            blocks=self.block_count,
            restored_samples=self.samples,
            directory=str(self.directory),
        )
        print(
            "[weight-accel] "
            + json.dumps(
                {
                    "schema": _WEIGHT_ACCEL_SCHEMA,
                    "mode": self.mode,
                    "architecture_sha256": self.architecture_sha256,
                    "history": self.history_len,
                    "sketch_dim": self.sketch_dim,
                    "blocks": self.block_count,
                    "restored_samples": self.samples,
                    "directory": str(self.directory),
                    "mutation_enabled": self.mode == "apply",
                },
                sort_keys=True,
                separators=(",", ":"),
                allow_nan=False,
            ),
            flush=True,
        )

    def _architecture_digest(self, core: nn.Module) -> str:
        h = hashlib.sha256()
        for name, param in core.named_parameters():
            if name.startswith("blocks."):
                h.update(name.encode("utf-8"))
                h.update(str(tuple(param.shape)).encode("ascii"))
                h.update(str(param.dtype).encode("ascii"))
        return h.hexdigest()

    def _event(self, event: str, **payload) -> None:
        record = {
            "schema": _WEIGHT_ACCEL_SCHEMA,
            "event": str(event),
            "time_unix": float(time.time()),
            **payload,
        }
        try:
            _weight_accel_append_jsonl(self.events_path, record)
        except Exception as exc:
            print(f"[weight-accel] event log warning: {exc}", flush=True)

    def _block_items(
        self, core: nn.Module, layers: list[int] | tuple[int, ...]
    ) -> list[tuple[str, torch.nn.Parameter]]:
        prefixes = tuple(f"blocks.{int(layer)}." for layer in layers)
        items = [
            (name, param)
            for name, param in core.named_parameters()
            if prefixes and name.startswith(prefixes) and param.is_floating_point()
        ]
        if not items:
            raise RuntimeError(
                f"weight accelerator found no floating parameters for layers={list(layers)}"
            )
        return items

    def _plan_for(
        self,
        core: nn.Module,
        block_id: int,
        layers: list[int] | tuple[int, ...],
    ) -> list:
        key = (int(block_id), tuple(int(x) for x in layers))
        cached = self._plans.get(key)
        if cached is not None:
            return cached
        items = self._block_items(core, layers)
        counts = [int(param.numel()) for _, param in items]
        total = sum(counts)
        if total <= 0:
            raise RuntimeError("weight accelerator block has zero parameters")
        used_dim = min(self.sketch_dim, total)
        if used_dim == 1:
            global_positions = [0]
        else:
            global_positions = (
                torch.linspace(0, total - 1, used_dim, dtype=torch.float64)
                .round()
                .to(torch.long)
                .tolist()
            )
        grouped: dict[int, tuple[list[int], list[int]]] = {}
        item_index = 0
        start = 0
        end = counts[0]
        for out_pos, global_pos in enumerate(global_positions):
            while global_pos >= end and item_index + 1 < len(items):
                start = end
                item_index += 1
                end += counts[item_index]
            locals_and_out = grouped.setdefault(item_index, ([], []))
            locals_and_out[0].append(int(global_pos - start))
            locals_and_out[1].append(int(out_pos))
        plan = []
        for idx, (local_positions, output_positions) in grouped.items():
            name, param = items[idx]
            plan.append(
                (
                    name,
                    param,
                    torch.tensor(
                        local_positions, dtype=torch.long, device=param.device
                    ),
                    torch.tensor(
                        output_positions, dtype=torch.long, device=param.device
                    ),
                )
            )
        self._plans[key] = plan
        return plan

    def _sample(
        self,
        core: nn.Module,
        block_id: int,
        layers: list[int] | tuple[int, ...],
    ) -> torch.Tensor:
        plan = self._plan_for(core, block_id, layers)
        if not plan:
            raise RuntimeError("weight accelerator sampling plan is empty")
        sample_device = plan[0][1].device
        out = torch.zeros(
            self.sketch_dim, dtype=torch.float32, device=sample_device
        )
        for _, param, local_index, output_index in plan:
            if param.device != sample_device:
                raise RuntimeError(
                    "weight accelerator block parameters span multiple devices"
                )
            values = (
                param.detach()
                .reshape(-1)
                .index_select(0, local_index)
                .to(dtype=torch.float32)
            )
            out.index_copy_(0, output_index, values)
        # One bounded device-to-host transfer per observed optimizer update.
        return out.to(device="cpu")

    def _full_snapshot(
        self, core: nn.Module, layers: list[int] | tuple[int, ...]
    ) -> dict[str, torch.Tensor]:
        return {
            name: param.detach().to(device="cpu").clone()
            for name, param in self._block_items(core, layers)
        }

    def _full_delta(
        self,
        core: nn.Module,
        layers: list[int] | tuple[int, ...],
        before: dict[str, torch.Tensor],
    ) -> dict[str, torch.Tensor]:
        result = {}
        for name, param in self._block_items(core, layers):
            prior = before.get(name)
            if prior is None:
                raise RuntimeError(f"weight accelerator full snapshot missing {name}")
            after = param.detach().to(device="cpu", dtype=torch.float32)
            result[name] = (after - prior.to(dtype=torch.float32)).to(torch.float16)
        return result

    def _context(
        self,
        *,
        block_id: int,
        step: int,
        objective: str,
        loss: float,
        lr: float,
        delta_norm: float,
    ) -> torch.Tensor:
        objective_id = {
            "ar": 0.0,
            "sat": 1.0,
            "nat": 2.0,
            "mixed": 3.0,
        }.get(str(objective or "mixed").lower(), 3.0)
        safe_lr = max(1.0e-12, abs(_weight_accel_finite_float(lr, 0.0)))
        values = [
            math.tanh(math.log1p(abs(_weight_accel_finite_float(loss, 0.0))) / 5.0),
            math.tanh((math.log10(safe_lr) + 6.0) / 4.0),
            objective_id / 3.0,
            float(block_id) / float(max(1, self.block_count - 1)),
            math.tanh(math.log1p(max(0, int(step))) / 15.0),
            math.tanh(math.log1p(max(0.0, delta_norm)) / 5.0),
        ]
        return torch.tensor(values, dtype=torch.float32)

    def before(
        self,
        core: nn.Module,
        opt,
        args,
        state: dict,
        block_id: int,
        layers: list[int] | tuple[int, ...],
        objective: str,
    ) -> None:
        every = max(1, int(getattr(args, "weight_accel_every", 1) or 1))
        attempt_step = int(state.get("attempt_step", 0) or 0)
        if attempt_step % every:
            self.pending = None
            return
        lr_values = [
            _weight_accel_finite_float(group.get("lr", 0.0), 0.0)
            for group in getattr(opt, "param_groups", [])
        ]
        lr = sum(lr_values) / max(1, len(lr_values))
        capture_full = self.mode == "apply"
        self.pending = {
            "attempt_step": attempt_step,
            "committed_step_before": int(state.get("step", 0) or 0),
            "block_id": int(block_id),
            "layers": [int(x) for x in layers],
            "objective": str(objective or "mixed"),
            "lr": float(lr),
            "before_sketch": self._sample(core, block_id, layers),
            "before_full": self._full_snapshot(core, layers) if capture_full else None,
        }

    @staticmethod
    def _ema(previous, value, beta=0.95):
        value = float(value)
        if previous is None:
            return value
        return beta * float(previous) + (1.0 - beta) * value

    def _history_tensors(self, block_id: int) -> tuple[torch.Tensor, torch.Tensor]:
        history = self.histories[int(block_id)][-self.history_len :]
        if len(history) != self.history_len:
            raise RuntimeError("weight accelerator history is not warm")
        sketches = torch.stack([rec["sketch"] for rec in history]).unsqueeze(0)
        contexts = torch.stack([rec["context"] for rec in history]).unsqueeze(0)
        return sketches.to(torch.float32), contexts.to(torch.float32)

    def _predict(self, block_id: int, *, grad: bool) -> tuple[torch.Tensor, torch.Tensor]:
        sketches, contexts = self._history_tensors(block_id)
        block_ids = torch.tensor([int(block_id)], dtype=torch.long)
        if grad:
            prediction, coeffs = self.model(sketches, contexts, block_ids)
        else:
            self.model.eval()
            with torch.no_grad():
                prediction, coeffs = self.model(sketches, contexts, block_ids)
        return prediction[0], coeffs[0]

    def after(
        self,
        core: nn.Module,
        opt,
        args,
        state: dict,
        block_id: int,
        layers: list[int] | tuple[int, ...],
        objective: str,
        loss: float,
        committed: bool,
    ) -> None:
        pending = self.pending
        self.pending = None
        if not committed or not isinstance(pending, dict):
            return
        if int(pending.get("block_id", -1)) != int(block_id):
            raise RuntimeError("weight accelerator pending block changed within one step")
        after_sketch = self._sample(core, block_id, layers)
        actual = after_sketch - pending["before_sketch"]
        if not bool(torch.isfinite(actual).all()):
            raise RuntimeError("weight accelerator observed a non-finite parameter delta")
        actual_norm = float(torch.linalg.vector_norm(actual).item())
        if actual_norm <= 0.0:
            self._event(
                "zero_delta_skipped",
                block_id=int(block_id),
                step=int(state.get("step", 0) or 0),
            )
            return

        prior = self.histories[int(block_id)]
        shadow = None
        if (
            self.mode in {"shadow", "apply"}
            and len(prior) >= self.history_len
        ):
            target = actual.to(torch.float32)
            # Score the predictor before fitting on this target. This preserves
            # honest one-step-ahead shadow metrics instead of grading homework
            # after showing the model the answer.
            prediction, coeffs = self._predict(block_id, grad=False)
            baseline = prior[-1]["sketch"].to(torch.float32)
            target_norm = torch.linalg.vector_norm(target).clamp_min(1.0e-12)
            prediction_norm = torch.linalg.vector_norm(prediction).clamp_min(1.0e-12)
            baseline_norm = torch.linalg.vector_norm(baseline).clamp_min(1.0e-12)
            cosine = _weight_accel_finite_float(
                (
                    torch.dot(prediction, target)
                    / (prediction_norm * target_norm)
                ).item(),
                -1.0,
            )
            baseline_cosine = _weight_accel_finite_float(
                (
                    torch.dot(baseline, target)
                    / (baseline_norm * target_norm)
                ).item(),
                -1.0,
            )
            rel_error = _weight_accel_finite_float(
                (
                    torch.linalg.vector_norm(prediction - target)
                    / target_norm
                ).item(),
                1.0e9,
            )
            baseline_rel_error = _weight_accel_finite_float(
                (
                    torch.linalg.vector_norm(baseline - target)
                    / target_norm
                ).item(),
                1.0e9,
            )
            win = 1.0 if rel_error < baseline_rel_error else 0.0

            train_every = max(
                1, int(getattr(args, "weight_accel_train_every", 4) or 4)
            )
            do_train = (self.samples % train_every) == 0
            fit_value = None
            if do_train:
                self.model.train()
                train_prediction, train_coeffs = self._predict(
                    block_id, grad=True
                )
                denom = target.square().mean().sqrt().clamp_min(1.0e-12)
                fit_loss = ((train_prediction - target) / denom).square().mean()
                coefficient_penalty = 1.0e-3 * train_coeffs.square().mean()
                objective_loss = fit_loss + coefficient_penalty
                if not bool(torch.isfinite(objective_loss).item()):
                    raise RuntimeError(
                        "weight accelerator predictor objective became non-finite"
                    )
                self.optimizer.zero_grad(set_to_none=True)
                objective_loss.backward()
                nn.utils.clip_grad_norm_(self.model.parameters(), 1.0)
                self.optimizer.step()
                self.trained_samples += 1
                fit_value = float(fit_loss.detach().item())

            metrics = self.metrics[int(block_id)]
            metrics["samples"] = int(metrics.get("samples", 0) or 0) + 1
            metrics["cos_ema"] = self._ema(metrics.get("cos_ema"), cosine)
            metrics["baseline_cos_ema"] = self._ema(
                metrics.get("baseline_cos_ema"), baseline_cosine
            )
            metrics["rel_error_ema"] = self._ema(
                metrics.get("rel_error_ema"), rel_error
            )
            metrics["baseline_rel_error_ema"] = self._ema(
                metrics.get("baseline_rel_error_ema"), baseline_rel_error
            )
            metrics["win_ema"] = self._ema(metrics.get("win_ema"), win)
            shadow = {
                "fit_loss": fit_value,
                "cosine": cosine,
                "baseline_cosine": baseline_cosine,
                "relative_error": rel_error,
                "baseline_relative_error": baseline_rel_error,
                "win": bool(win),
                "coefficients": [float(x) for x in coeffs.tolist()],
            }

        committed_step = int(state.get("step", 0) or 0)
        context = self._context(
            block_id=int(block_id),
            step=committed_step,
            objective=objective,
            loss=loss,
            lr=float(pending.get("lr", 0.0)),
            delta_norm=actual_norm,
        )
        record = {
            "sketch": actual.detach().to(device="cpu", dtype=torch.float32),
            "context": context,
            "step": committed_step,
            "block_id": int(block_id),
            "layers": [int(x) for x in layers],
            "objective": str(objective or "mixed"),
            "loss": _weight_accel_finite_float(loss, 0.0),
            "lr": _weight_accel_finite_float(pending.get("lr", 0.0), 0.0),
            "delta_norm": actual_norm,
        }
        prior.append(record)
        del prior[: max(0, len(prior) - self.history_len)]

        if self.mode == "apply":
            before_full = pending.get("before_full")
            if not isinstance(before_full, dict):
                raise RuntimeError("apply mode requires a full pre-update snapshot")
            full_delta = self._full_delta(core, layers, before_full)
            full_history = self.full_histories[int(block_id)]
            full_history.append(full_delta)
            del full_history[: max(0, len(full_history) - self.history_len)]

        self.samples += 1
        record_every = max(
            1, int(getattr(args, "weight_accel_record_every", 14) or 14)
        )
        if self.samples % record_every == 0:
            payload = {
                "schema": _WEIGHT_ACCEL_SCHEMA,
                "event": "trajectory_sample",
                "time_unix": float(time.time()),
                "architecture_sha256": self.architecture_sha256,
                "sample": int(self.samples),
                "trained_samples": int(self.trained_samples),
                "step": committed_step,
                "block_id": int(block_id),
                "layers": [int(x) for x in layers],
                "objective": str(objective or "mixed"),
                "loss": _weight_accel_finite_float(loss, 0.0),
                "lr": _weight_accel_finite_float(pending.get("lr", 0.0), 0.0),
                "delta_norm": actual_norm,
                "sketch": [float(x) for x in actual.tolist()],
                "shadow": shadow,
            }
            _weight_accel_append_jsonl(self.trajectory_path, payload)

        state_every = max(
            1, int(getattr(args, "weight_accel_state_every", 256) or 256)
        )
        if self.samples % state_every == 0:
            self.save_state()

        if (
            self.mode == "apply"
            and len(self.histories[int(block_id)]) == self.history_len
            and len(self.full_histories[int(block_id)]) == self.history_len
        ):
            prediction, coeffs = self._predict(block_id, grad=False)
            self.candidate = {
                "block_id": int(block_id),
                "layers": [int(x) for x in layers],
                "created_step": committed_step,
                "created_sample": int(self.samples),
                "prediction_sketch": prediction.detach().to("cpu"),
                "coefficients": coeffs.detach().to("cpu"),
            }

    def _state_payload(self) -> dict:
        small_histories = {}
        for block_id, records in self.histories.items():
            small_histories[int(block_id)] = [
                {
                    **{k: copy.deepcopy(v) for k, v in rec.items() if k not in {"sketch", "context"}},
                    "sketch": rec["sketch"].detach().to("cpu", dtype=torch.float32),
                    "context": rec["context"].detach().to("cpu", dtype=torch.float32),
                }
                for rec in records[-self.history_len :]
            ]
        return {
            "schema": _WEIGHT_ACCEL_STATE_SCHEMA,
            "architecture_sha256": self.architecture_sha256,
            "history_len": self.history_len,
            "sketch_dim": self.sketch_dim,
            "block_count": self.block_count,
            "samples": int(self.samples),
            "trained_samples": int(self.trained_samples),
            "accepted_jumps": int(self.accepted_jumps),
            "rejected_jumps": int(self.rejected_jumps),
            "model": self.model.state_dict(),
            "optimizer": self.optimizer.state_dict(),
            "histories": small_histories,
            "metrics": copy.deepcopy(self.metrics),
        }

    def save_state(self) -> None:
        _weight_accel_atomic_torch_save(self._state_payload(), self.state_path)
        self._event(
            "predictor_state_saved",
            samples=int(self.samples),
            trained_samples=int(self.trained_samples),
            path=str(self.state_path),
        )

    def _load_state(self) -> None:
        if not self.state_path.exists():
            return
        try:
            try:
                payload = torch.load(
                    self.state_path, map_location="cpu", weights_only=False
                )
            except TypeError:
                payload = torch.load(self.state_path, map_location="cpu")
            if not isinstance(payload, dict):
                raise ValueError("predictor state is not a mapping")
            if payload.get("schema") != _WEIGHT_ACCEL_STATE_SCHEMA:
                raise ValueError("predictor state schema mismatch")
            if payload.get("architecture_sha256") != self.architecture_sha256:
                raise ValueError("predictor architecture digest mismatch")
            if int(payload.get("history_len", -1)) != self.history_len:
                raise ValueError("predictor history length mismatch")
            if int(payload.get("sketch_dim", -1)) != self.sketch_dim:
                raise ValueError("predictor sketch dimension mismatch")
            if int(payload.get("block_count", -1)) != self.block_count:
                raise ValueError("predictor block count mismatch")
            self.model.load_state_dict(payload["model"], strict=True)
            try:
                self.optimizer.load_state_dict(payload["optimizer"])
            except Exception as exc:
                print(
                    f"[weight-accel] optimizer state reset after load warning: {exc}",
                    flush=True,
                )
            histories = payload.get("histories", {})
            for block_id in range(self.block_count):
                loaded = histories.get(block_id, histories.get(str(block_id), []))
                checked = []
                for rec in list(loaded or [])[-self.history_len :]:
                    sketch = rec.get("sketch")
                    context = rec.get("context")
                    if (
                        torch.is_tensor(sketch)
                        and tuple(sketch.shape) == (self.sketch_dim,)
                        and torch.is_tensor(context)
                        and tuple(context.shape) == (6,)
                    ):
                        copied = dict(rec)
                        copied["sketch"] = sketch.to("cpu", dtype=torch.float32)
                        copied["context"] = context.to("cpu", dtype=torch.float32)
                        checked.append(copied)
                self.histories[block_id] = checked
            loaded_metrics = payload.get("metrics")
            if isinstance(loaded_metrics, dict):
                for block_id in range(self.block_count):
                    metric = loaded_metrics.get(
                        block_id, loaded_metrics.get(str(block_id))
                    )
                    if isinstance(metric, dict):
                        self.metrics[block_id].update(copy.deepcopy(metric))
            self.samples = max(0, int(payload.get("samples", 0) or 0))
            self.trained_samples = max(
                0, int(payload.get("trained_samples", 0) or 0)
            )
            self.accepted_jumps = max(
                0, int(payload.get("accepted_jumps", 0) or 0)
            )
            self.rejected_jumps = max(
                0, int(payload.get("rejected_jumps", 0) or 0)
            )
        except Exception as exc:
            quarantined = self.state_path.with_name(
                self.state_path.name
                + f".rejected-{time.strftime('%Y%m%dT%H%M%SZ', time.gmtime())}"
            )
            try:
                os.replace(self.state_path, quarantined)
            except Exception:
                quarantined = self.state_path
            print(
                f"[weight-accel] rejected incompatible predictor state "
                f"{quarantined}: {exc}",
                flush=True,
            )

    def summary(self) -> dict:
        warm_blocks = sum(
            1
            for records in self.histories.values()
            if len(records) >= self.history_len
        )
        metric_samples = sum(
            int(metric.get("samples", 0) or 0) for metric in self.metrics.values()
        )
        weighted_cos = 0.0
        weighted_rel = 0.0
        weighted_win = 0.0
        if metric_samples:
            for metric in self.metrics.values():
                n = int(metric.get("samples", 0) or 0)
                weighted_cos += n * _weight_accel_finite_float(
                    metric.get("cos_ema"), 0.0
                )
                weighted_rel += n * _weight_accel_finite_float(
                    metric.get("rel_error_ema"), 0.0
                )
                weighted_win += n * _weight_accel_finite_float(
                    metric.get("win_ema"), 0.0
                )
            weighted_cos /= metric_samples
            weighted_rel /= metric_samples
            weighted_win /= metric_samples
        return {
            "schema": _WEIGHT_ACCEL_SCHEMA,
            "mode": self.mode,
            "architecture_sha256": self.architecture_sha256,
            "history": int(self.history_len),
            "sketch_dim": int(self.sketch_dim),
            "samples": int(self.samples),
            "trained_samples": int(self.trained_samples),
            "metric_samples": int(metric_samples),
            "warm_blocks": int(warm_blocks),
            "blocks": int(self.block_count),
            "shadow_cos_ema": float(weighted_cos),
            "shadow_rel_error_ema": float(weighted_rel),
            "shadow_win_ema": float(weighted_win),
            "accepted_jumps": int(self.accepted_jumps),
            "rejected_jumps": int(self.rejected_jumps),
            "mutation_enabled": self.mode == "apply",
            "directory": str(self.directory),
        }


def _weight_accel_runtime(core: nn.Module, args, state: dict):
    mode = _weight_accel_mode(args)
    if mode == "off":
        return None
    runtime = getattr(args, "_weight_accel_runtime", None)
    if runtime is None:
        runtime = _WeightTrajectoryRuntime(core, args, state)
        args._weight_accel_runtime = runtime
    return runtime


def _weight_accel_handle_error(args, where: str, exc: Exception) -> None:
    mode = _weight_accel_mode(args)
    print(f"[weight-accel] {where} disabled after error: {exc}", flush=True)
    runtime = getattr(args, "_weight_accel_runtime", None)
    if runtime is not None:
        try:
            runtime._event("weight_accel_error", where=str(where), error=repr(exc))
            runtime.mode = "off"
        except Exception:
            pass
    if mode == "apply" and bool(getattr(args, "weight_accel_fail_closed", True)):
        raise RuntimeError(f"weight accelerator {where} failed closed") from exc
    setattr(args, "weight_accel_mode", "off")


def _weight_accel_before_update(
    core: nn.Module,
    opt,
    args,
    state: dict,
    block_id: int,
    layers,
    objective: str,
) -> None:
    if _weight_accel_mode(args) == "off":
        return
    try:
        runtime = _weight_accel_runtime(core, args, state)
        runtime.before(core, opt, args, state, block_id, layers, objective)
    except Exception as exc:
        _weight_accel_handle_error(args, "before_update", exc)


def _weight_accel_after_update(
    core: nn.Module,
    opt,
    args,
    state: dict,
    block_id: int,
    layers,
    objective: str,
    loss: float,
    committed: bool,
) -> None:
    if _weight_accel_mode(args) == "off":
        return
    try:
        runtime = _weight_accel_runtime(core, args, state)
        runtime.after(
            core,
            opt,
            args,
            state,
            block_id,
            layers,
            objective,
            loss,
            committed,
        )
    except Exception as exc:
        _weight_accel_handle_error(args, "after_update", exc)


def _weight_accel_combine_full_history(
    runtime: _WeightTrajectoryRuntime, block_id: int, coeffs: torch.Tensor
) -> dict[str, torch.Tensor]:
    history = runtime.full_histories[int(block_id)][-runtime.history_len :]
    if len(history) != runtime.history_len:
        raise RuntimeError("weight accelerator full history is not warm")
    coeffs = coeffs.detach().to("cpu", dtype=torch.float32)
    if tuple(coeffs.shape) != (runtime.history_len,):
        raise RuntimeError("weight accelerator coefficient shape mismatch")
    names = set(history[0])
    if any(set(item) != names for item in history):
        raise RuntimeError("weight accelerator full-history parameter keys drifted")
    combined = {}
    for name in sorted(names):
        value = torch.zeros_like(history[0][name], dtype=torch.float32, device="cpu")
        for coefficient, update in zip(coeffs, history):
            value.add_(update[name].to(dtype=torch.float32), alpha=float(coefficient))
        combined[name] = value
    return combined


def _weight_accel_damp_optimizer_state(opt, param_map: dict, names, damp: float) -> None:
    damp = float(damp)
    if damp >= 1.0:
        return
    damp = max(0.0, damp)
    for name in names:
        param = param_map.get(name)
        if param is None:
            continue
        state = getattr(opt, "state", {}).get(param)
        if not isinstance(state, dict):
            continue
        for value in state.values():
            if torch.is_tensor(value) and value.is_floating_point():
                value.mul_(damp)


def _weight_accel_maybe_apply(
    core: nn.Module,
    ar_h,
    sat_h,
    nat_h,
    opt,
    args,
    state: dict,
    val_batches,
    step: int,
) -> None:
    if _weight_accel_mode(args) != "apply":
        return
    runtime = getattr(args, "_weight_accel_runtime", None)
    if runtime is None or not isinstance(runtime.candidate, dict):
        return
    apply_every = max(
        1, int(getattr(args, "weight_accel_apply_every", 1400) or 1400)
    )
    if int(step) % apply_every:
        return
    min_samples = max(
        runtime.history_len,
        int(getattr(args, "weight_accel_min_samples", 128) or 128),
    )
    if runtime.trained_samples < min_samples:
        return
    candidate = runtime.candidate
    block_id = int(candidate["block_id"])
    metric = runtime.metrics.get(block_id, {})
    min_block_samples = max(
        runtime.history_len,
        int(getattr(args, "weight_accel_min_block_samples", 32) or 32),
    )
    if int(metric.get("samples", 0) or 0) < min_block_samples:
        return
    cos_ema = _weight_accel_finite_float(metric.get("cos_ema"), -1.0)
    rel_ema = _weight_accel_finite_float(metric.get("rel_error_ema"), 1.0e9)
    win_ema = _weight_accel_finite_float(metric.get("win_ema"), 0.0)
    min_cos = float(getattr(args, "weight_accel_min_cos", 0.20) or 0.20)
    max_rel = float(
        getattr(args, "weight_accel_max_rel_error", 1.20) or 1.20
    )
    min_win = min(
        1.0,
        max(
            0.0,
            float(getattr(args, "weight_accel_min_win_rate", 0.55) or 0.55),
        ),
    )
    if cos_ema < min_cos or rel_ema > max_rel or win_ema < min_win:
        return
    if not val_batches:
        runtime._event(
            "speculative_jump_skipped",
            step=int(step),
            block_id=block_id,
            reason="no_frozen_validation_batches",
        )
        runtime.candidate = None
        return

    param_map = dict(core.named_parameters())
    backups: dict[str, torch.Tensor] = {}
    applied = False
    try:
        gate_batches = max(
            1, int(getattr(args, "weight_accel_gate_batches", 1) or 1)
        )
        frozen = list(val_batches[:gate_batches])
        baseline_ce = _run_validation(
            core, ar_h, frozen, args, int(step), sat_h=sat_h, nat_h=nat_h
        )
        if baseline_ce is None or not math.isfinite(float(baseline_ce)):
            raise RuntimeError("baseline validation did not produce finite CE")
        combined = _weight_accel_combine_full_history(
            runtime, block_id, candidate["coefficients"]
        )
        apply_scale = max(
            0.0, float(getattr(args, "weight_accel_apply_scale", 1.0) or 1.0)
        )
        max_ratio = max(
            0.0,
            float(
                getattr(args, "weight_accel_max_update_ratio", 0.002) or 0.002
            ),
        )
        with torch.no_grad():
            for name, delta in combined.items():
                target = param_map.get(name)
                if target is None:
                    raise KeyError(f"candidate targets unknown parameter {name}")
                backups[name] = target.detach().to("cpu").clone()
                proposed = delta.to(dtype=torch.float32)
                if max_ratio > 0.0:
                    weight_norm = float(
                        torch.linalg.vector_norm(
                            backups[name].to(dtype=torch.float32)
                        ).item()
                    )
                    update_norm = float(torch.linalg.vector_norm(proposed).item())
                    ceiling = max_ratio * max(weight_norm, 1.0e-12)
                    if update_norm > ceiling > 0.0:
                        proposed.mul_(ceiling / update_norm)
                target.add_(
                    proposed.to(device=target.device, dtype=target.dtype),
                    alpha=apply_scale,
                )
        applied = True
        candidate_ce = _run_validation(
            core, ar_h, frozen, args, int(step), sat_h=sat_h, nat_h=nat_h
        )
        min_improve = max(
            0.0, float(getattr(args, "weight_accel_min_improve", 0.0) or 0.0)
        )
        accepted = (
            candidate_ce is not None
            and math.isfinite(float(candidate_ce))
            and float(candidate_ce) <= float(baseline_ce) - min_improve
        )
        if not accepted:
            with torch.no_grad():
                for name, original in backups.items():
                    target = param_map[name]
                    target.copy_(
                        original.to(device=target.device, dtype=target.dtype)
                    )
            applied = False
            runtime.rejected_jumps += 1
            runtime._event(
                "speculative_jump_rejected",
                step=int(step),
                block_id=block_id,
                baseline_ce=float(baseline_ce),
                candidate_ce=(
                    None if candidate_ce is None else float(candidate_ce)
                ),
                cos_ema=float(cos_ema),
                rel_error_ema=float(rel_ema),
            )
            print(
                f"[weight-accel] rejected block={block_id} step={step} "
                f"baseline_ce={float(baseline_ce):.6f} "
                f"candidate_ce={float(candidate_ce) if candidate_ce is not None else float('nan'):.6f}",
                flush=True,
            )
        else:
            runtime.accepted_jumps += 1
            _weight_accel_damp_optimizer_state(
                opt,
                param_map,
                backups.keys(),
                float(
                    getattr(
                        args, "weight_accel_optimizer_state_damp", 1.0
                    )
                    or 1.0
                ),
            )
            runtime._event(
                "speculative_jump_accepted",
                step=int(step),
                block_id=block_id,
                baseline_ce=float(baseline_ce),
                candidate_ce=float(candidate_ce),
                improvement=float(baseline_ce) - float(candidate_ce),
                cos_ema=float(cos_ema),
                rel_error_ema=float(rel_ema),
                coefficients=[
                    float(x) for x in candidate["coefficients"].tolist()
                ],
            )
            print(
                f"[weight-accel] accepted block={block_id} step={step} "
                f"baseline_ce={float(baseline_ce):.6f} "
                f"candidate_ce={float(candidate_ce):.6f}",
                flush=True,
            )
        runtime.candidate = None
        runtime.save_state()
    except Exception as exc:
        if applied and backups:
            try:
                with torch.no_grad():
                    for name, original in backups.items():
                        target = param_map[name]
                        target.copy_(
                            original.to(device=target.device, dtype=target.dtype)
                        )
            except Exception as rollback_exc:
                raise RuntimeError(
                    f"weight accelerator rollback failed after {exc!r}: "
                    f"{rollback_exc!r}"
                ) from rollback_exc
        runtime.candidate = None
        _weight_accel_handle_error(args, "speculative_apply", exc)


def _weight_accel_checkpoint_metadata(args):
    runtime = getattr(args, "_weight_accel_runtime", None)
    if runtime is None:
        mode = _weight_accel_mode(args)
        if mode == "off":
            return None
        return {
            "schema": _WEIGHT_ACCEL_SCHEMA,
            "mode": mode,
            "initialized": False,
            "mutation_enabled": mode == "apply",
        }
    try:
        runtime.save_state()
    except Exception as exc:
        print(f"[weight-accel] checkpoint sidecar save warning: {exc}", flush=True)
    return runtime.summary()
# ===== END AGILLM43 WEIGHT-TRAJECTORY ACCELERATOR V1 =====

def _dblock_target_route_anchor_audit(family, info=None, *, completed=True):
    """Normalize full-stack anchor activity for per-attempt route receipts."""
    family = str(family)
    if not completed:
        return {
            "family": family,
            "call_started": True,
            "call_completed": False,
            "ran": False,
            "accepted": False,
            "finite": None,
            "spike": None,
            "reason": "call_aborted_before_receipt",
            "sequence_tokens": 0,
            "target_tokens": 0,
        }
    info = dict(info or {})
    ran = bool(info.get("ran", False))
    finite = bool(info.get("finite", False)) if ran else None
    spike = bool(info.get("spike", False)) if ran else False
    target_tokens = int(info.get("tokens", 0) or 0)
    sequence_tokens = (
        target_tokens + (1 if ran else 0)
        if family == "ar" else int(info.get("seq_len", 0) or 0)
    )
    return {
        "family": family,
        "call_started": True,
        "call_completed": True,
        "ran": ran,
        "accepted": bool(ran and finite and not spike),
        "finite": finite,
        "spike": spike,
        "reason": str(info.get("reason") or ""),
        "sequence_tokens": int(sequence_tokens),
        "target_tokens": int(target_tokens),
    }


def _dblock_emit_target_route_receipt(state, args):
    """Emit exactly one audit record at every normal DBlock attempt return."""
    if _dblock_target_route_policy(args) == "legacy":
        return None
    route = _dblock_target_route_validate_runtime_state(state, args)
    receipt = state.get("training_science_last_receipt")
    if not isinstance(receipt, dict) or not receipt.get("route_policy_id"):
        raise RuntimeError("xor-fold56-v1 attempt has no route receipt")
    if bool(receipt.get("_target_route_audit_emitted", False)):
        existing = receipt.get("target_route")
        if not isinstance(existing, dict):
            raise RuntimeError("xor-fold56-v1 receipt emission marker is corrupt")
        return _dblock_json_copy(existing)
    committed = bool(receipt.get("committed", False))
    event = {
        "schema": "agillm43.dblock.target-route.receipt.v1",
        "policy_id": _DBLOCK_TARGET_ROUTE_POLICY_ID,
        "policy_sha256": _DBLOCK_TARGET_ROUTE_POLICY_SHA256,
        "route_policy_id": _DBLOCK_TARGET_ROUTE_POLICY_ID,
        "route_policy_sha256": _DBLOCK_TARGET_ROUTE_POLICY_SHA256,
        "controller_source_sha256": str(route["controller_source_sha256"]),
        "attempt_step": int(receipt.get("attempt_step", 0)),
        "route_attempt_clock_after": int(route["route_attempt_clock"]),
        "dblock_attempt_step_after": int(state.get("attempt_step", 0) or 0),
        "route_clock_before": int(receipt.get("route_clock_before", 0)),
        "route_clock_after": int(route["route_commit_clock"]),
        "route_offset": int(route["route_offset"]),
        "target_id": int(receipt.get("target_id", -1)),
        "target_sha256": str(receipt.get("target_sha256") or ""),
        "block": int(receipt.get("block", -1)),
        "forward_layers": list(receipt.get("forward_layers", []) or []),
        "train_layers": list(receipt.get("train_layers", []) or []),
        "train_sublayers": list(receipt.get("train_sublayers", []) or []),
        "anchors": _dblock_json_copy(receipt.get("anchors", {}) or {}),
        "committed": committed,
        "outcome": str(
            receipt.get("route_outcome")
            or ("optimizer_committed" if committed else "rejected")
        ),
        "committed_step_before": int(receipt.get("committed_step_before", 0)),
        "committed_step_after": int(
            receipt.get("committed_step_after", state.get("step", 0))
        ),
        "pending_target_after": _dblock_json_copy(route["pending_target"]),
        "committed_target": (
            _dblock_json_copy(route["last_committed_target"])
            if committed else None
        ),
    }
    receipt["route_clock_after"] = int(event["route_clock_after"])
    receipt["route_pending_after"] = _dblock_json_copy(
        event["pending_target_after"]
    )
    receipt["target_route"] = _dblock_json_copy(event)
    receipt["_target_route_audit_emitted"] = True
    print(
        "[dblock-target-route-receipt] "
        + json.dumps(
            event, sort_keys=True, separators=(",", ":"), allow_nan=False
        ),
        flush=True,
    )
    return event



# ───────────── AGILLM43 v27.16: deep-context DBlock local objective (20260906) ─────────────
_DBLOCK_CLEAN_CONTEXT_MODES = ("off", "deep", "e2e")


def _dblock_clean_context_mode(args):
    raw = str(getattr(args, "dblock_clean_context", "off") or "off").strip().lower()
    if raw in {"", "0", "off", "false", "none", "no"}:
        return "off"
    if raw in {"deep", "stack"}:
        return "deep"
    if raw in {"e2e", "masked_e2e", "fullstack", "1", "on", "true"}:
        return "e2e"
    raise ValueError(f"unknown --dblock_clean_context {raw!r}; expected off|deep|e2e")


def _dblock_clean_context_noise(args, sig, like):
    """Band noise for the deep/e2e input: sigma scaled by --dblock_clean_context_noise_scale
    (1.0 = legacy band sigma; 0.0 = clean input)."""
    scale = float(getattr(args, "dblock_clean_context_noise_scale", 1.0) or 0.0)
    if scale <= 0.0:
        return like
    return like + (scale * sig)[:, None, None].to(like.dtype) * torch.randn_like(like)


def _dblock_frozen_suffix_forward(core, last_layer, h, mask, args):
    """e2e mode: run every layer above the selected DBlock with its parameters
    frozen (no parameter gradient) and per-layer activation checkpointing, so the
    exact top-of-stack loss can be backpropagated into the selected sublayer at
    O(1 layer) live activation memory.  Returns the final-norm input hidden."""
    last_layer = int(last_layer)
    upper = list(range(last_layer + 1, len(core.blocks)))
    if not upper:
        return h
    if getattr(core, "hc", None) is not None:
        raise RuntimeError("e2e DBlock suffix is not defined for Hyper-Connections")
    _retain_activations = _dblock_retain_small_activations(args, h)
    snapshots = []
    for li in upper:
        for param in core.blocks[li].parameters():
            snapshots.append((param, bool(param.requires_grad)))
            param.requires_grad_(False)
    def _frozen_recompute(y, block):
        # Non-reentrant checkpoint recomputes this block during backward, after
        # the outer scope has restored requires_grad.  Re-freeze inside every
        # invocation so the recomputed graph saves exactly what the original
        # forward saved (and never resurrects parameter grads for this block).
        inner = [(param, bool(param.requires_grad)) for param in block.parameters()]
        for param, _ in inner:
            param.requires_grad_(False)
        try:
            return _run_block_forward(block, y, mask, "off")
        finally:
            for param, original in inner:
                param.requires_grad_(original)
    try:
        for li in upper:
            block = core.blocks[li]
            if _retain_activations:
                h = _frozen_recompute(h, block)
            else:
                h = _ck.checkpoint(lambda y, block=block: _frozen_recompute(y, block), h, use_reentrant=False)
            if getattr(core, "anchor", None) is not None and li == int(getattr(core, "anchor_position", -1)):
                h = core.anchor(h)[0]
    finally:
        # Frozen upper routers must not add MoE auxiliary terms to the local loss.
        _dblock_clear_moe_stash_for_layers(core, upper)
        for param, original in snapshots:
            param.requires_grad_(original)
    return h


def _dblock_local_rows(args, ids):
    rows = int(_dblock_fullstack_anchor_int(args, "dblock_local_rows", 0) or 0)
    if rows <= 0 or rows >= int(ids.size(0)):
        return int(ids.size(0))
    return rows


def _dblock_deep_context_input(core, ids, first_layer, mask, args):
    """Residual-stream input of DBlock ``first_layer``: the frozen plain stack
    below it, run on the token embeddings with the objective's own attention
    mask.  No gradient ever flows into or out of it (shared vocab state stays
    detached exactly like _dblock_local_embedding)."""
    first_layer = int(first_layer)
    with torch.no_grad():
        h = core.emb(ids)
        if first_layer > 0:
            if getattr(core, "hc", None) is not None:
                raise RuntimeError("deep DBlock context is not defined for Hyper-Connections")
            for li in range(first_layer):
                h = _run_block(core.blocks[li], h, mask, False, args, "off")
                if getattr(core, "anchor", None) is not None and li == int(getattr(core, "anchor_position", -1)):
                    h = core.anchor(h)[0]
            _dblock_clear_moe_stash_for_layers(core, list(range(first_layer)))
    return h.detach()


def _dblock_depth_anchor(core, ar_h, args, ids, state, loss_mask=None):
    """No-grad composition receipt: plain-stack next-token CE after each DBlock
    on the same deterministic crop the full-stack AR anchor uses."""
    every = int(getattr(args, "dblock_depth_anchor_every", 0) or 0)
    step = int(state.get("step", 0))
    if every <= 0 or step % every != 0 or ids.size(1) < 2:
        return None
    tokens = max(8, min(256, int(getattr(args, "dblock_depth_anchor_tokens", 256) or 256)))
    target_count = min(tokens, int(ids.size(1)) - 1)
    seq_len = target_count + 1
    row = step % max(1, int(ids.size(0)))
    max_start = max(0, int(ids.size(1)) - seq_len)
    start = 0 if max_start == 0 else ((step * 104729 + row * 1543) % (max_start + 1))
    crop = ids[row:row + 1, start:start + seq_len]
    keep = None
    if loss_mask is not None:
        keep = loss_mask[row:row + 1, start + 1:start + seq_len].reshape(-1).to(torch.bool)
        if not bool(keep.any()):
            return None
    M = _agillm41_sys.modules[__name__]
    groups = _dblock_block_layers(core, int(getattr(args, "dblock_blocks", 14) or 14))
    ends = {int(g[-1]): gi for gi, g in enumerate(groups)}
    out = {}
    with torch.no_grad(), _dblock_deterministic_anchor_context(core, crop):
        causal = M.causal_mask(seq_len, structured=M.use_structured_masks(args))
        W = _dblock_local_head_weight(ar_h)
        with M.amp(args.amp):
            h = core.emb(crop)
            for li, block in enumerate(core.blocks):
                h = _run_block(block, h, causal, False, args, "off")
                if getattr(core, "anchor", None) is not None and li == int(getattr(core, "anchor_position", -1)):
                    h = core.anchor(h)[0]
                if li in ends:
                    hid = core.ln(h)[:, :-1].reshape(-1, h.size(-1))
                    tgt = crop[:, 1:].reshape(-1)
                    if keep is not None:
                        hid, tgt = hid[keep], tgt[keep]
                    ce = fused_ce(hid, W, tgt)
                    out[f"d{ends[li] + 1}"] = round(float(ce.detach().float().item()), 4)
        _dblock_clear_moe_aux_stash(core)
    print(
        "[dblock-depth-anchor] " + json.dumps({
            "step": step, "crop": f"row{row}:{start}+{seq_len}", "targets": int(target_count),
            "ce_after_block": out,
        }, sort_keys=True),
        flush=True,
    )
    state["dblock_depth_anchor_last"] = {"step": step, "ce_after_block": out}
    return out


def _dblock_step(core, ar_h, sat_h, nat_h, opt, scaler, args, ids, state, loss_mask=None):
    M = _agillm41_sys.modules[__name__]
    # Teacher activations are single-attempt transients.  A rejected/aborted
    # mature update must never leak its packet into a later accepted commit.
    state.pop("_det50_teacher_packet", None)
    state["last_update_trained"] = False
    state["training_science_last_receipt"] = {
        "schema": "agillm43.dblock.science.receipt.v2",
        "committed": False,
        "attempt_step": int(state.get("attempt_step", 0) or 0),
        "dblock_attempt_step_before": int(state.get("attempt_step", 0) or 0),
        "committed_step_before": int(state.get("step", 0) or 0),
        "block": None,
        "layers": [],
        "local_objectives": [],
        "local_passes": 0,
        "anchors": {},
    }
    state["diagnostic_every"] = max(1, int(getattr(args, "dblock_log_every", 25) or 25))
    state["diagnostic_force_full"] = bool(
        getattr(args, "repair_mode", False) or getattr(args, "repair_fail_fast", False)
    )

    if state is not None and state.get("auto_search", False):
        state["search_tokens"] = state.get("search_tokens", 0) + ids.numel()

    prof = _profile_active(state, args)
    _step_t = _profile_tic(prof)
    if torch.cuda.is_available():
        torch.cuda.reset_peak_memory_stats()

    _setup_t = _profile_tic(prof)
    B = state["B"]
    asg = state["assign"]
    bs = state["bsig"]
    T = ids.size(1)
    use_layer_checkpoint = bool(getattr(args, "grad_checkpoint", False))
    if _dblock_router_enabled(args):
        with torch.no_grad():
            _rc_emb = core.emb(ids)
            _rc_ctx = _rc_emb.mean(dim=(0, 1)).detach().float()
            _rc_ctx = _rc_ctx / torch.sqrt(_rc_ctx.square().mean() + 1e-6)
            state["router_ctx"] = _rc_ctx.to("cpu")
            del _rc_ctx, _rc_emb
    route_target = _dblock_target_route_begin_attempt(state, args)
    if route_target is None:
        bi = _choose_block(state, args)
        bi = _dblock_router_shadow_observe(state, args, bi)
    else:
        bi = int(route_target["block"])
        # The existing learned router has a 14-block output head. It may observe
        # the deterministic teacher block, but it cannot control a 56-way joint
        # target and its return value is intentionally ignored here.
        _dblock_router_shadow_observe(state, args, bi)
    lo, hi = sorted([bs[bi], bs[bi + 1]])
    layers = [int(layer) for layer in asg[bi]]
    if state.get("looped", False):
        layers = [int(layer) for layer in (state.get("loop_group") or layers)]
    if route_target is None:
        train_layers = _dblock_select_train_layers(state, args, bi, layers)
        train_sublayers = _dblock_select_train_sublayers(
            state, args, bi, layers, train_layers
        )
    else:
        train_layers = [int(route_target["physical_layer"])]
        if train_layers[0] not in layers:
            raise RuntimeError(
                "xor-fold56-v1 physical layer is outside selected forward DBlock"
            )
        train_sublayers = {
            train_layers[0]: str(route_target["sublayer"])
        }
    train_sublayer_rows, train_sublayer_param_count = _dblock_train_sublayer_receipt(
        core, train_layers, train_sublayers
    )
    state["training_science_last_receipt"].update({
        "attempt_step": (
            int(state.get("attempt_step", 0) or 0)
            if route_target is None
            else int(route_target["last_attempt_step"])
        ),
        "block": int(bi),
        "layers": [int(layer) for layer in train_layers],
        "forward_layers": [int(layer) for layer in layers],
        "train_layers": [int(layer) for layer in train_layers],
        "train_sublayers": train_sublayer_rows,
        "selected_train_param_count": int(train_sublayer_param_count),
        "route_policy_id": (
            None if route_target is None else _DBLOCK_TARGET_ROUTE_POLICY_ID
        ),
        "route_policy_sha256": (
            None if route_target is None else _DBLOCK_TARGET_ROUTE_POLICY_SHA256
        ),
        "route_clock_before": (
            None if route_target is None
            else int(route_target["route_commit_clock"])
        ),
        "route_clock_after": (
            None if route_target is None
            else int(route_target["route_commit_clock"])
        ),
        "route_offset": (
            None if route_target is None else int(route_target["route_offset"])
        ),
        "target_id": (
            None if route_target is None else int(route_target["target_id"])
        ),
        "target_sha256": (
            None if route_target is None else str(route_target["target_sha256"])
        ),
    })
    sig = _sample_sigma(ids, lo, hi, args, state)
    cs, co, ci = _edm_pre(sig)
    w = _edm_w(sig, float(getattr(args, "dblock_edm_wmax", 5.0)))
    SATB = M.SAT_BLOCK
    ar_weight = _dblock_hot_float(args, "dblock_ar_weight", 1.0, min_value=0.0)
    sat_weight = _dblock_hot_float(args, "dblock_sat_weight", 1.0, min_value=0.0)
    nat_weight = (
        _dblock_hot_float(args, "dblock_nat_weight", 1.0, min_value=0.0)
        * _dblock_hot_float(args, "nat_loss_weight", 1.0, names=["nat_loss_weight", "dblock_nat_loss_weight"], min_value=0.0)
    )
    do_sat_periodic = (not getattr(args, "ar_only", False)) and (
        int(getattr(args, "sat_every", 1)) <= 1 or ((int(state.get("step", 0)) + 1) % int(getattr(args, "sat_every", 1)) == 0)
    )
    do_nat_periodic = (
        nat_h is not None
        and (not getattr(args, "ar_only", False))
        and int(getattr(args, "nat_every", 1)) > 0
        and (
            int(getattr(args, "nat_every", 1)) <= 1
            or ((int(state.get("step", 0)) + 1) % int(getattr(args, "nat_every", 1)) == 0)
        )
    )
    run_ar, run_sat, run_nat, objective = _choose_objectives(
        state, args, ar_weight, sat_weight, nat_weight, do_sat_periodic, do_nat_periodic
    )
    _weight_accel_before_update(
        core, opt, args, state, bi, train_layers, objective
    )
    _profile_toc(state, "setup", _setup_t)

    ar_val = 0.0
    sat_val = 0.0
    nat_val = 0.0
    ar_raw_val = 0.0
    sat_raw_val = 0.0
    nat_raw_val = 0.0
    pending_supervised = {"ar": 0, "sat": 0, "nat": 0}
    local_diagnostics = {
        "committed_step": int(state.get("step", 0)),
        "attempt_step_before": int(state.get("attempt_step", 0)),
        "objective": str(objective),
        "block": int(bi),
        "layers": [int(layer) for layer in train_layers],
        "forward_layers": [int(layer) for layer in layers],
        "train_layers": [int(layer) for layer in train_layers],
        "train_sublayers": train_sublayer_rows,
        "selected_train_param_count": int(train_sublayer_param_count),
        "target_route": (
            None if route_target is None else _dblock_json_copy(route_target)
        ),
        "batch": _dblock_token_boundary_diagnostics(ids, loss_mask),
        "objectives": {},
    }

    _cc_mode = _dblock_clean_context_mode(args)
    if run_ar and _cc_mode in ("deep", "e2e"):
        # v27.16 deep-context local AR: block input = frozen plain stack below the
        # block (+ optional band noise); plain block; e2e additionally runs the
        # frozen stack above it so the loss is the exact serving next-token CE.
        _rows = _dblock_local_rows(args, ids)
        ids_l = ids[:_rows]
        lm_l = loss_mask[:_rows] if loss_mask is not None else None
        sig_l = sig[:_rows]
        causal = M.causal_mask(T, structured=M.use_structured_masks(args))
        _t = _profile_tic(prof)
        with M.amp(args.amp):
            emb = _dblock_deep_context_input(core, ids_l, min(int(x) for x in layers), causal, args)
            zt = _dblock_clean_context_noise(args, sig_l, emb)
            h = _dblock_loop_condition(core, zt, bi, args) if state.get("looped", False) else zt
            h = _dblock_local_span_forward(
                core, bi, layers, train_layers, h, causal,
                bool(use_layer_checkpoint), args, state,
                train_sublayers=train_sublayers,
            )
            if _cc_mode == "e2e":
                h = _dblock_frozen_suffix_forward(core, max(int(x) for x in layers), h, causal, args)
            Dn = _dblock_local_final_norm(core, h)
        _profile_toc(state, "ar_forward", _t)
        _t = _profile_tic(prof)
        ar_loss_mask = lm_l[:, 1:] if lm_l is not None else None
        ar_hidden, ar_targets, ar_used, ar_total = _sample_token_loss_inputs(
            Dn[:, :-1], ids_l[:, 1:], _dblock_loss_token_cap(args, "ar"), ar_loss_mask
        )
        ar_raw = fused_ce(ar_hidden, _dblock_local_head_weight(ar_h), ar_targets)
        local_diagnostics["objectives"]["ar"] = {
            "input": {
                "sha256": local_diagnostics["batch"]["sha256"],
                "source": "%s_rows%d_below_layer%d" % (_cc_mode, int(_rows), min(int(x) for x in layers)),
            },
            "selected_targets": _dblock_token_boundary_diagnostics(ar_targets),
            "selected_target_count": int(ar_used),
            "available_target_count": int(ar_total),
        }
        ar = ar_weight * w * ar_raw
        ar_raw_val, ar_val = _dblock_scalar_values(ar_raw, ar)
        _profile_toc(state, "ar_ce", _t)
        _t = _profile_tic(prof)
        _aux = _collect_moe_aux(core, getattr(args,'moe_aux_coef',0.0), getattr(args,'moe_z_coef',0.0))
        if torch.is_tensor(_aux):
            ar = ar + _aux.to(ar.dtype)
        scaler.scale(ar).backward()
        pending_supervised["ar"] = int(ar_used)
        _profile_toc(state, "ar_backward", _t)
        del causal, emb, zt, h, Dn, ar_hidden, ar_targets, ar_raw, ar, ar_used, ar_total, ids_l, lm_l, sig_l
    elif run_ar:
        causal = M.causal_mask(T, structured=M.use_structured_masks(args))
        _t = _profile_tic(prof)
        with M.amp(args.amp):
            emb = _dblock_local_embedding(core, ids)
            zt = emb + sig[:, None, None] * torch.randn_like(emb)
            h = _dblock_loop_condition(core, ci * zt, bi, args) if state.get("looped", False) else ci * zt
            h = _dblock_local_span_forward(
                core, bi, layers, train_layers, h, causal,
                bool(use_layer_checkpoint), args, state,
                train_sublayers=train_sublayers,
            )
            Dn = _dblock_local_final_norm(core, cs * zt + co * h)
        _profile_toc(state, "ar_forward", _t)
        _t = _profile_tic(prof)
        ar_loss_mask = loss_mask[:, 1:] if loss_mask is not None else None
        ar_hidden, ar_targets, ar_used, ar_total = _sample_token_loss_inputs(
            Dn[:, :-1], ids[:, 1:], _dblock_loss_token_cap(args, "ar"), ar_loss_mask
        )
        ar_raw = fused_ce(ar_hidden, _dblock_local_head_weight(ar_h), ar_targets)
        local_diagnostics["objectives"]["ar"] = {
            "input": {
                "sha256": local_diagnostics["batch"]["sha256"],
                "source": "whole_batch",
            },
            "selected_targets": _dblock_token_boundary_diagnostics(ar_targets),
            "selected_target_count": int(ar_used),
            "available_target_count": int(ar_total),
        }
        ar = ar_weight * w * ar_raw
        ar_raw_val, ar_val = _dblock_scalar_values(ar_raw, ar)
        _profile_toc(state, "ar_ce", _t)
        _t = _profile_tic(prof)
        _aux = _collect_moe_aux(core, getattr(args,'moe_aux_coef',0.0), getattr(args,'moe_z_coef',0.0))
        if torch.is_tensor(_aux):
            ar = ar + _aux.to(ar.dtype)
        scaler.scale(ar).backward()
        pending_supervised["ar"] = int(ar_used)
        _profile_toc(state, "ar_backward", _t)
        del causal, emb, zt, h, Dn, ar_hidden, ar_targets, ar_raw, ar, ar_used, ar_total

    if run_sat:
        _satvar_on = _satvar_enabled(args) and not M.use_structured_masks(args)
        if _satvar_on:
            _satvar_sizes = satvar_sample_sizes(T, _satvar_block_probs(args))
            smask = satvar_partition_mask(_satvar_sizes, T, device=ids.device)
        else:
            _satvar_sizes = None
            smask = M.sat_mask(T, structured=M.use_structured_masks(args))
        _t = _profile_tic(prof)
        if _cc_mode in ("deep", "e2e"):
            _rows_s = _dblock_local_rows(args, ids)
            ids_s = ids[:_rows_s]
            lm_s = loss_mask[:_rows_s] if loss_mask is not None else None
            with M.amp(args.amp):
                emb2 = _dblock_deep_context_input(core, ids_s, min(int(x) for x in layers), smask, args)
                zt2 = _dblock_clean_context_noise(args, sig[:_rows_s], emb2)
                h2 = _dblock_loop_condition(core, zt2, bi, args) if state.get("looped", False) else zt2
                h2 = _dblock_local_span_forward(
                    core, bi, layers, train_layers, h2, smask,
                    bool(use_layer_checkpoint), args, state,
                    train_sublayers=train_sublayers,
                )
                if _cc_mode == "e2e":
                    h2 = _dblock_frozen_suffix_forward(core, max(int(x) for x in layers), h2, smask, args)
                Ds = _dblock_local_final_norm(core, h2)
        else:
            ids_s = ids
            lm_s = loss_mask
            with M.amp(args.amp):
                emb2 = _dblock_local_embedding(core, ids)
                zt2 = emb2 + sig[:, None, None] * torch.randn_like(emb2)
                h2 = _dblock_loop_condition(core, ci * zt2, bi, args) if state.get("looped", False) else ci * zt2
                h2 = _dblock_local_span_forward(
                    core, bi, layers, train_layers, h2, smask,
                    bool(use_layer_checkpoint), args, state,
                    train_sublayers=train_sublayers,
                )
                Ds = _dblock_local_final_norm(core, cs * zt2 + co * h2)
        _profile_toc(state, "sat_forward", _t)
        _t = _profile_tic(prof)
        # SAT decode uses the latest SAT_BLOCK hidden states to emit the next
        # SAT_BLOCK tokens. Train that contract densely across the context.
        if _satvar_on:
            # v28 variable-block SAT: slot j of every block predicts the token j+1 beyond the
            # block through proj(h + E_{j+1}); the detached regret head learns E[CE_d].
            sat_hidden, sat_targets, sat_used, sat_total, _sv_d, _sv_end, _sv_row = _satvar_gather(
                sat_h, Ds, ids_s, lm_s, _satvar_sizes, _dblock_loss_token_cap(args, "sat"))
            _sv_regret_w = _dblock_hot_float(args, "dblock_satvar_regret_weight", 0.05, min_value=0.0, max_value=1.0)
            _sv_regret_blocks = _dblock_fullstack_anchor_int(args, "dblock_satvar_regret_blocks", 256)
            with M.amp(args.amp):
                satf = fused_ce(sat_hidden, _dblock_local_head_weight(sat_h), sat_targets)
                satv = 0.0
                sat_raw = satf
                _sv_regret_loss, _sv_regret_info = (None, {"blocks": 0})
                if _sv_regret_w > 0.0 and _sv_regret_blocks > 0:
                    _sv_regret_loss, _sv_regret_info = _satvar_regret_loss(
                        sat_h, Ds.detach(), ids_s, lm_s, _satvar_sizes,
                        _dblock_local_head_weight(sat_h), max_blocks=_sv_regret_blocks)
                local_diagnostics["objectives"]["sat"] = {
                    "input": {
                        "sha256": local_diagnostics["batch"]["sha256"],
                        "source": "whole_batch",
                    },
                    "selected_targets": _dblock_token_boundary_diagnostics(sat_targets),
                    "selected_target_count": int(sat_used),
                    "available_target_count": int(sat_total),
                    "sampling": "variable_block_partition_with_replacement",
                    "schema": SATVAR_SCHEMA,
                    "block_size_hist": _satvar_size_hist(_satvar_sizes),
                    "mean_block_size": round(float(T) / max(1, len(_satvar_sizes)), 4),
                    "selected_d_hist": {str(d + 1): int((_sv_d == d).sum()) for d in range(SATVAR_KMAX) if int((_sv_d == d).sum()) > 0},
                    "regret": _dblock_json_copy(_sv_regret_info),
                    "regret_weight": float(_sv_regret_w),
                }
                sat = sat_weight * w * sat_raw
                if _sv_regret_loss is not None and torch.is_tensor(_sv_regret_loss) and bool(torch.isfinite(_sv_regret_loss)):
                    sat = sat + float(_sv_regret_w) * _sv_regret_loss
                    with torch.no_grad():
                        sat_h.satvar_regret_updates += 1
                sat_raw_val, sat_val = _dblock_scalar_values(sat_raw, sat)
                if _dblock_audit_due(state, args):
                    print("[dblock-satvar] " + json.dumps({
                        "step": int(state.get("step", 0)), "block": int(bi), "ce": round(float(sat_raw_val), 4),
                        "targets": int(sat_used), "available": int(sat_total),
                        "sizes": _satvar_size_hist(_satvar_sizes),
                        "d_hist": local_diagnostics["objectives"]["sat"]["selected_d_hist"],
                        "regret": _sv_regret_info, "regret_updates": int(sat_h.satvar_regret_updates.item()),
                    }, sort_keys=True, separators=(",", ":"), default=str), flush=True)
            del _sv_d, _sv_end, _sv_row, _sv_regret_loss
        else:
            sat_ctx = Ds[:, :-SATB]
            sat_tgt = ids_s[:, SATB:]
            if sat_ctx.size(1) == 0 or sat_ctx.size(1) != sat_tgt.size(1):
                sat_ctx = Ds[:, :-1]
                sat_tgt = ids_s[:, 1:]
            sat_loss_mask = None
            if lm_s is not None:
                sat_loss_mask = lm_s[:, SATB:] if sat_ctx.size(1) == lm_s[:, SATB:].size(1) else lm_s[:, 1:]
            sat_hidden, sat_targets, sat_used, sat_total = _sample_sat_pair_loss_inputs(
                sat_ctx, sat_tgt, _dblock_loss_token_cap(args, "sat"),
                sat_loss_mask, block=SATB,
            )
            # SAT-variable admission gate is NOT trained by ordinary pretraining.
            # The old all-ones target contradicted the verifier contract; a later
            # full-vocab pseudo-label attempt was also prohibitively expensive at
            # production B/T. Gate supervision stays in bounded ORPO verifier loss.
            with M.amp(args.amp):
                satf = fused_ce(sat_hidden, _dblock_local_head_weight(sat_h), sat_targets)
                satv = 0.0
                sat_raw = satf
                local_diagnostics["objectives"]["sat"] = {
                    "input": {
                        "sha256": local_diagnostics["batch"]["sha256"],
                        "source": "whole_batch",
                    },
                    "selected_targets": _dblock_token_boundary_diagnostics(sat_targets),
                    "selected_target_count": int(sat_used),
                    "available_target_count": int(sat_total),
                    "sampling": "complete_sat_blocks_with_replacement",
                    "sat_block_size": int(SATB),
                    "selected_block_count": int(sat_used // max(1, SATB)),
                    "available_block_count": int(sat_total // max(1, SATB)),
                }
                sat = sat_weight * w * sat_raw
                sat_raw_val, sat_val = _dblock_scalar_values(sat_raw, sat)
        _profile_toc(state, "sat_ce", _t)
        _t = _profile_tic(prof)
        _aux = _collect_moe_aux(core, getattr(args,'moe_aux_coef',0.0), getattr(args,'moe_z_coef',0.0))
        if torch.is_tensor(_aux):
            sat = sat + _aux.to(sat.dtype)
        scaler.scale(sat).backward()
        pending_supervised["sat"] = int(sat_used)
        _profile_toc(state, "sat_backward", _t)
        del smask, emb2, zt2, h2, Ds, sat_hidden, sat_targets, satf, satv, sat_raw, sat, sat_used, sat_total, ids_s, lm_s

    if run_nat:
        ratio = min(max(float(getattr(args, "nat_mask_ratio", 0.5)), 0.05), 0.95)
        nat_mode = str(getattr(args, "dblock_nat_embed_noise_mode", "off") or "off").strip().lower()
        nat_noise_scale = max(0.0, float(getattr(args, "dblock_nat_embed_noise_scale", 1.0) or 1.0))
        nat_ids = M._nat_ids_for_training(ids, int(getattr(args, "nat_max_tokens", 0)))
        if _cc_mode in ("deep", "e2e"):
            # v27.16.1: deep/e2e NAT runs the frozen stack on the local row
            # subset only (the full batch through the checkpointed suffix OOMs).
            nat_ids = nat_ids[:_dblock_local_rows(args, ids)]
        _t = _profile_tic(prof)
        with M.amp(args.amp):
            nat_in = nat_ids.clone()
            lm_nat = (
                loss_mask[:nat_ids.size(0), -nat_ids.size(1):] if loss_mask is not None else None
            )
            try:
                m = M._nat_corruption_mask(
                    nat_ids, ratio, args, loss_mask=lm_nat
                )
            except ValueError as exc:
                opt.zero_grad(set_to_none=True)
                _dblock_clear_moe_aux_stash(core)
                eos_pad_id, nat_mask_id = _nat_boundary_ids()
                reason = (
                    "nat_corruption_clean_mask_id"
                    if bool(nat_ids.eq(nat_mask_id).any())
                    else "nat_corruption_invalid_input"
                )
                diagnostics = {
                    "batch_sha256": _dblock_tensor_sha256(nat_ids),
                    "batch_shape": [
                        int(nat_ids.size(0)), int(nat_ids.size(1))
                    ],
                    "eos_pad_count": int(
                        nat_ids.eq(eos_pad_id).sum().item()
                    ),
                    "nat_mask_count": int(
                        nat_ids.eq(nat_mask_id).sum().item()
                    ),
                    "error": str(exc),
                }
                if bool(getattr(args, "repair_mode", False)) or bool(
                    getattr(args, "repair_fail_fast", False)
                ):
                    _repair_write_fail(
                        args, reason, block=int(bi),
                        objective=str(objective),
                        diagnostics=diagnostics,
                    )
                raise RuntimeError(
                    f"NAT corruption rejected invalid clean input: {exc}"
                ) from exc
            corruption_mask_true = int(m.sum().item())
            if corruption_mask_true <= 0:
                opt.zero_grad(set_to_none=True)
                _dblock_clear_moe_aux_stash(core)
                diagnostics = {
                    "batch_sha256": _dblock_tensor_sha256(nat_ids),
                    "batch_shape": [int(nat_ids.size(0)), int(nat_ids.size(1))],
                    "eos_pad_count": int(nat_ids.eq(_nat_boundary_ids()[0]).sum().item()),
                    "nat_mask_count": int(nat_ids.eq(_nat_boundary_ids()[1]).sum().item()),
                    "invalid_loss_count": (
                        int((~lm_nat.to(dtype=torch.bool)).sum().item())
                        if lm_nat is not None else 0
                    ),
                }
                if bool(getattr(args, "repair_mode", False)) or bool(
                    getattr(args, "repair_fail_fast", False)
                ):
                    _repair_write_fail(
                        args, "nat_corruption_no_valid_targets",
                        block=int(bi), objective=str(objective),
                        diagnostics=diagnostics,
                    )
                    raise RuntimeError(
                        "repair fail-fast: NAT corruption has no eligible targets"
                    )
                raise RuntimeError("NAT corruption has no eligible targets")
            if nat_mode in {"visible", "mask_plus_noise"}:
                clean_hn = _dblock_local_embedding(core, nat_ids)
                if nat_mode == "mask_plus_noise":
                    nat_in[m] = M.NAT_MASK_ID
                    hn = _dblock_local_embedding(core, nat_in)
                else:
                    hn = clean_hn.clone()
                nat_noise = sig[:, None, None].to(clean_hn.dtype) * nat_noise_scale * torch.randn_like(clean_hn)
                hn = hn.clone()
                # mask_plus_noise must not leak the clean target embedding at masked
                # positions. The old code used clean_hn + noise, so training saw the
                # answer token while inference only has BLANK slots.
                noise_base = clean_hn if nat_mode == "visible" else hn
                hn[m] = (noise_base + nat_noise)[m]
            else:
                nat_in[m] = M.NAT_MASK_ID
                hn = _dblock_local_embedding(core, nat_in)
            if _cc_mode in ("deep", "e2e") and nat_mode not in {"visible", "mask_plus_noise"}:
                # v27.16: the corrupted sequence enters the block through the
                # frozen plain stack below it (bidirectional, as NAT serves).
                hn = _dblock_deep_context_input(core, nat_in, min(int(x) for x in layers), None, args)
            if state.get("looped", False):
                hn = _dblock_loop_condition(core, hn, bi, args)
            hn = _dblock_local_span_forward(
                core, bi, layers, train_layers, hn, None,
                bool(use_layer_checkpoint), args, state,
                train_sublayers=train_sublayers,
            )
            if _cc_mode == "e2e" and nat_mode not in {"visible", "mask_plus_noise"}:
                hn = _dblock_frozen_suffix_forward(core, max(int(x) for x in layers), hn, None, args)
            Dnat = _dblock_local_final_norm(core, hn)
        _profile_toc(state, "nat_forward", _t)
        _t = _profile_tic(prof)
        nat_hidden = Dnat[m]
        nat_targets = nat_ids[m]
        nat_hidden, nat_targets, nat_used, nat_total = _sample_token_loss_inputs(
            nat_hidden.unsqueeze(0), nat_targets.unsqueeze(0), _dblock_loss_token_cap(args, "nat")
        )
        nat_raw = fused_ce(nat_hidden, _dblock_local_head_weight(nat_h), nat_targets)
        local_diagnostics["objectives"]["nat"] = {
            "clean_input": {
                "sha256": local_diagnostics["batch"]["sha256"],
                "source": "whole_batch",
            },
            "corrupted_input": _dblock_token_boundary_diagnostics(nat_in, lm_nat),
            "corruption_mask_sha256": _dblock_tensor_sha256(m.to(torch.int64)),
            "corruption_mask_true": int(corruption_mask_true),
            "selected_targets": _dblock_token_boundary_diagnostics(nat_targets),
            "selected_target_count": int(nat_used),
            "available_target_count": int(nat_total),
        }
        nat = nat_weight * w * nat_raw
        nat_raw_val, nat_val = _dblock_scalar_values(nat_raw, nat)
        _profile_toc(state, "nat_ce", _t)
        _t = _profile_tic(prof)
        _aux = _collect_moe_aux(core, getattr(args,'moe_aux_coef',0.0), getattr(args,'moe_z_coef',0.0))
        if torch.is_tensor(_aux):
            nat = nat + _aux.to(nat.dtype)
        scaler.scale(nat).backward()
        pending_supervised["nat"] = int(nat_used)
        _profile_toc(state, "nat_backward", _t)
        del nat_ids, nat_in, m, hn, Dnat, nat_hidden, nat_targets, nat_raw, nat, nat_used, nat_total

    if _cc_mode in ("deep", "e2e"):
        try:
            _dblock_depth_anchor(core, ar_h, args, ids, state, loss_mask=loss_mask)
        except Exception as _depth_exc:  # receipt only; never fails a step
            print(f"[dblock-depth-anchor] skipped: {_depth_exc!r}", flush=True)
    total_val = ar_val + sat_val + nat_val
    raw_total_val = ar_raw_val + sat_raw_val + nat_raw_val
    raw_count = int(bool(run_ar)) + int(bool(run_sat)) + int(bool(run_nat))
    raw_avg_val = raw_total_val / max(1, raw_count)
    local_diagnostics.update({
        "raw_average_ce": (
            float(raw_avg_val) if math.isfinite(float(raw_avg_val)) else None
        ),
        "raw_ce_by_objective": {
            "ar": float(ar_raw_val) if math.isfinite(float(ar_raw_val)) else None,
            "sat": float(sat_raw_val) if math.isfinite(float(sat_raw_val)) else None,
            "nat": float(nat_raw_val) if math.isfinite(float(nat_raw_val)) else None,
        },
    })
    state["local_objective_last"] = _dblock_json_copy(local_diagnostics)
    _local_target_receipts = local_diagnostics["objectives"]
    _local_target_hashes = {
        name: receipt["selected_targets"]["sha256"]
        for name, receipt in _local_target_receipts.items()
    }
    _local_input_hashes = {
        name: (
            receipt.get("corrupted_input") or receipt.get("input")
        )["sha256"]
        for name, receipt in _local_target_receipts.items()
    }
    if _dblock_audit_due(state, args):
        print(
            "[dblock-local-diag] " + json.dumps({
                "step": int(state.get("step", 0)),
                "attempt_step": int(state.get("attempt_step", 0)),
                "objective": str(objective),
                "block": int(bi),
                "batch_sha256": local_diagnostics["batch"]["sha256"],
                "input_sha256_by_objective": _local_input_hashes,
                "target_sha256_by_objective": _local_target_hashes,
                "batch_eos_pad_count": local_diagnostics["batch"]["eos_pad_count"],
                "batch_nat_mask_count": local_diagnostics["batch"]["nat_mask_count"],
                "raw_average_ce": local_diagnostics["raw_average_ce"],
            }, sort_keys=True, separators=(",", ":"), allow_nan=False),
            flush=True,
        )
    if not math.isfinite(total_val) or not math.isfinite(raw_avg_val):
        opt.zero_grad(set_to_none=True)
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
        if bool(getattr(args, "repair_fail_fast", False)):
            _repair_write_fail(
                args, "nonfinite_local_loss", block=int(bi),
                total=float(total_val), raw_avg=float(raw_avg_val), objective=str(objective),
                diagnostics=local_diagnostics,
            )
            raise RuntimeError("repair fail-fast: non-finite local DBlock loss")
        print(f"[dblock] non-finite loss {total_val}; skipped optimizer step", flush=True)
        _profile_toc(state, "step_total", _step_t)
        _profile_step_done(state, args)
        _update_stats(state, bi, raw_avg_val, args, objective=objective, trained=False)
        state["training_science_last_receipt"]["route_outcome"] = "local_nonfinite"
        _dblock_emit_target_route_receipt(state, args)
        return raw_avg_val

    local_spike_probe = _dblock_local_spike_probe(
        state, args, objective, bi, raw_avg_val
    )
    pending_local_spike_state = local_spike_probe.get("pending")
    pending_local_aux_warning = _dblock_local_aux_warning_receipt(
        state, objective, bi, local_spike_probe, local_diagnostics,
        _local_input_hashes, _local_target_hashes,
        committed=False, outcome="observed",
    )
    _dblock_emit_local_aux_warning(pending_local_aux_warning)
    if not local_spike_probe.get("spike", False):
        _dblock_observe_local_nonspike(state, objective, bi)
    if local_spike_probe.get("spike", False):
        _dblock_clear_rejected_attempt(core, opt)
        rejection = _dblock_record_local_spike_rejection(
            state, args, objective, bi
        )
        if pending_local_aux_warning is not None:
            rejected_warning = dict(pending_local_aux_warning)
            rejected_warning.update({
                "committed": False,
                "outcome": "local_rejected",
            })
            _dblock_emit_local_aux_warning(rejected_warning)
        _local_baseline = local_spike_probe.get("baseline")
        _local_baseline_text = (
            "none" if _local_baseline is None else f"{float(_local_baseline):.2f}"
        )
        print(
            f"[dblock] loss spike obj={rejection['objective']} block={bi} "
            f"reason={local_spike_probe['reason']} raw_avg={raw_avg_val:.2f} "
            f"relative_limit={local_spike_probe['multiplier']:.2f}x "
            f"baseline={_local_baseline_text} "
            f"absolute_max={local_spike_probe['aux_policy']['maximum_ce']:.2f}; "
            f"rejected retry={rejection['consecutive']}/{rejection['limit']}",
            flush=True,
        )
        _profile_toc(state, "step_total", _step_t)
        _profile_step_done(state, args)
        _update_stats(
            state, bi, raw_avg_val, args,
            objective=objective, trained=False,
        )
        if rejection.get("limit_reached", False) and (
            bool(getattr(args, "repair_mode", False))
            or bool(getattr(args, "repair_fail_fast", False))
        ):
            _repair_write_fail(
                args, "local_loss_spike",
                block=int(bi), objective=str(objective),
                raw_avg=float(raw_avg_val),
                spike_probe=local_spike_probe,
                spike_retry=rejection,
                diagnostics=local_diagnostics,
            )
            raise RuntimeError(
                "repair fail-fast: local DBlock loss spike exhausted "
                f"{rejection['consecutive']}/{rejection['limit']} retries"
            )
        state["training_science_last_receipt"]["route_outcome"] = "local_loss_spike"
        _dblock_emit_target_route_receipt(state, args)
        return raw_avg_val

    aux_guard_info = {"ran": False, "reason": "local_ar_objective"}
    if objective in {"sat", "nat"}:
        aux_guard_info = _dblock_ar_protected_aux_grad(
            core, ar_h, scaler, args, ids, layers, bi, sig, cs, co, ci, w,
            use_layer_checkpoint, state, loss_mask=loss_mask, train_layers=train_layers,
            train_sublayers=train_sublayers,
        )
        pending_supervised["ar"] = int(pending_supervised.get("ar", 0)) + int(
            aux_guard_info.get("ar_tokens", 0) or 0
        )
        local_diagnostics["ar_protected_aux_guard"] = _dblock_json_copy(
            aux_guard_info
        )

    matryoshka_info = _matryoshka_dblock_aux(
        core, ar_h, scaler, args, ids, state, loss_mask=loss_mask)
    if matryoshka_info.get("ran"):
        local_diagnostics["matryoshka"] = _dblock_json_copy(matryoshka_info)

    state["training_science_last_receipt"]["anchors"]["ar"] = (
        _dblock_target_route_anchor_audit("ar", completed=False)
    )
    anchor_info = _dblock_fullstack_ar_anchor(
        core, ar_h, scaler, args, ids, state, loss_mask=loss_mask,
        batch_diagnostics=local_diagnostics["batch"],
    )
    state["training_science_last_receipt"]["anchors"]["ar"] = (
        _dblock_target_route_anchor_audit("ar", anchor_info)
    )
    if anchor_info.get("ran") and not anchor_info.get("finite", False):
        opt.zero_grad(set_to_none=True)
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
        msg = "[dblock-anchor] non-finite composition anchor"
        if bool(getattr(args, "repair_fail_fast", False)):
            _repair_write_fail(args, "nonfinite_fullstack_anchor", block=int(bi), anchor=anchor_info)
            print(msg + "; repair_fail_fast=on, aborting recovery run", flush=True)
            raise RuntimeError(msg)
        print(msg + "; skipped optimizer step", flush=True)
        _profile_toc(state, "step_total", _step_t)
        _profile_step_done(state, args)
        _update_stats(state, bi, raw_avg_val, args, objective=objective, trained=False)
        state["training_science_last_receipt"]["route_outcome"] = "ar_anchor_nonfinite"
        _dblock_emit_target_route_receipt(state, args)
        return raw_avg_val


    if anchor_info.get("spike", False):
        _dblock_clear_rejected_attempt(core, opt)
        rejection = _dblock_record_anchor_spike_rejection(
            state, args, "ar"
        )
        _profile_toc(state, "step_total", _step_t)
        _profile_step_done(state, args)
        _update_stats(
            state, bi, raw_avg_val, args,
            objective=objective, trained=False,
        )
        if rejection.get("limit_reached", False) and (
            bool(getattr(args, "repair_mode", False))
            or bool(getattr(args, "repair_fail_fast", False))
        ):
            _repair_write_fail(
                args, "fullstack_anchor_spike",
                block=int(bi), family="ar", anchor=anchor_info,
                spike_retry=rejection,
            )
            raise RuntimeError(
                "repair fail-fast: full-stack AR anchor spike "
                f"exhausted {rejection['consecutive']}/"
                f"{rejection['limit']} retries"
            )
        print(
            f"[dblock-ar-anchor] spike rejected; same committed state "
            f"will retry next batch "
            f"({rejection['consecutive']}/{rejection['limit']})",
            flush=True,
        )
        state["training_science_last_receipt"]["route_outcome"] = "ar_anchor_spike"
        _dblock_emit_target_route_receipt(state, args)
        return raw_avg_val

    state["training_science_last_receipt"]["anchors"]["sat"] = (
        _dblock_target_route_anchor_audit("sat", completed=False)
    )
    # v3: the AR head reaches the SAT anchor through a module-level ref because an
    # embedded overlay wraps _dblock_fullstack_sat_anchor with the legacy signature.
    _AGILLM43_V3_AR_HEAD_REF[0] = ar_h
    sat_anchor_info = _dblock_fullstack_sat_anchor(
        core, sat_h, scaler, args, ids, state, loss_mask=loss_mask,
        batch_diagnostics=local_diagnostics["batch"],
    )
    state["training_science_last_receipt"]["anchors"]["sat"] = (
        _dblock_target_route_anchor_audit("sat", sat_anchor_info)
    )
    if sat_anchor_info.get("ran") and not sat_anchor_info.get("finite", False):
        opt.zero_grad(set_to_none=True)
        _dblock_clear_moe_aux_stash(core)
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
        if bool(getattr(args, "repair_mode", False)) or bool(getattr(args, "repair_fail_fast", False)):
            _repair_write_fail(args, "nonfinite_fullstack_sat_anchor", block=int(bi), anchor=sat_anchor_info)
            raise RuntimeError("repair fail-fast: non-finite full-stack SAT anchor")
        print("[dblock-sat-anchor] non-finite; skipped optimizer step", flush=True)
        _profile_toc(state, "step_total", _step_t)
        _profile_step_done(state, args)
        _update_stats(state, bi, raw_avg_val, args, objective=objective, trained=False)
        state["training_science_last_receipt"]["route_outcome"] = "sat_anchor_nonfinite"
        _dblock_emit_target_route_receipt(state, args)
        return raw_avg_val


    if sat_anchor_info.get("spike", False):
        _dblock_clear_rejected_attempt(core, opt)
        rejection = _dblock_record_anchor_spike_rejection(
            state, args, "sat"
        )
        _profile_toc(state, "step_total", _step_t)
        _profile_step_done(state, args)
        _update_stats(
            state, bi, raw_avg_val, args,
            objective=objective, trained=False,
        )
        if rejection.get("limit_reached", False) and (
            bool(getattr(args, "repair_mode", False))
            or bool(getattr(args, "repair_fail_fast", False))
        ):
            _repair_write_fail(
                args, "fullstack_anchor_spike",
                block=int(bi), family="sat", anchor=sat_anchor_info,
                spike_retry=rejection,
            )
            raise RuntimeError(
                "repair fail-fast: full-stack SAT anchor spike "
                f"exhausted {rejection['consecutive']}/"
                f"{rejection['limit']} retries"
            )
        print(
            f"[dblock-sat-anchor] spike rejected; same committed state "
            f"will retry next batch "
            f"({rejection['consecutive']}/{rejection['limit']})",
            flush=True,
        )
        state["training_science_last_receipt"]["route_outcome"] = "sat_anchor_spike"
        _dblock_emit_target_route_receipt(state, args)
        return raw_avg_val

    satvar_anchor_info = _dblock_fullstack_satvar_anchor(
        core, sat_h, scaler, args, ids, state, loss_mask=loss_mask
    )
    if satvar_anchor_info.get("ran") and not satvar_anchor_info.get("finite", False):
        opt.zero_grad(set_to_none=True)
        _dblock_clear_moe_aux_stash(core)
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
        print("[dblock-satvar-anchor] non-finite; skipped optimizer step", flush=True)
        _profile_toc(state, "step_total", _step_t)
        _profile_step_done(state, args)
        _update_stats(state, bi, raw_avg_val, args, objective=objective, trained=False)
        state["training_science_last_receipt"]["route_outcome"] = "satvar_anchor_nonfinite"
        _dblock_emit_target_route_receipt(state, args)
        return raw_avg_val
    if satvar_anchor_info.get("ran"):
        local_diagnostics["satvar_anchor"] = _dblock_json_copy(satvar_anchor_info)

    state["training_science_last_receipt"]["anchors"]["nat"] = (
        _dblock_target_route_anchor_audit("nat", completed=False)
    )
    nat_anchor_info = _dblock_fullstack_nat_anchor(
        core, nat_h, scaler, args, ids, state, loss_mask=loss_mask
    )
    state["training_science_last_receipt"]["anchors"]["nat"] = (
        _dblock_target_route_anchor_audit("nat", nat_anchor_info)
    )
    if nat_anchor_info.get("reason") == "no_valid_doc_crop_telemetry":
        consecutive = int(
            nat_anchor_info.get("no_valid_crop_consecutive", 0)
        )
        limit = int(nat_anchor_info.get("no_valid_crop_limit", 0))
        print(
            f"[dblock-nat-anchor] no valid document crop telemetry; optional anchor "
            f"skipped and finite local/AR/SAT gradients continue "
            f"({consecutive}/{limit})",
            flush=True,
        )
    if nat_anchor_info.get("ran") and not nat_anchor_info.get("finite", False):
        opt.zero_grad(set_to_none=True)
        _dblock_clear_moe_aux_stash(core)
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
        if bool(getattr(args, "repair_mode", False)) or bool(getattr(args, "repair_fail_fast", False)):
            _repair_write_fail(args, "nonfinite_fullstack_nat_anchor", block=int(bi), anchor=nat_anchor_info)
            raise RuntimeError("repair fail-fast: non-finite full-stack NAT anchor")
        print("[dblock-nat-anchor] non-finite; skipped optimizer step", flush=True)
        _profile_toc(state, "step_total", _step_t)
        _profile_step_done(state, args)
        _update_stats(state, bi, raw_avg_val, args, objective=objective, trained=False)
        state["training_science_last_receipt"]["route_outcome"] = "nat_anchor_nonfinite"
        _dblock_emit_target_route_receipt(state, args)
        return raw_avg_val


    if nat_anchor_info.get("spike", False):
        _dblock_clear_rejected_attempt(core, opt)
        rejection = _dblock_record_anchor_spike_rejection(
            state, args, "nat"
        )
        _profile_toc(state, "step_total", _step_t)
        _profile_step_done(state, args)
        _update_stats(
            state, bi, raw_avg_val, args,
            objective=objective, trained=False,
        )
        if rejection.get("limit_reached", False) and (
            bool(getattr(args, "repair_mode", False))
            or bool(getattr(args, "repair_fail_fast", False))
        ):
            _repair_write_fail(
                args, "fullstack_anchor_spike",
                block=int(bi), family="nat", anchor=nat_anchor_info,
                spike_retry=rejection,
            )
            raise RuntimeError(
                "repair fail-fast: full-stack NAT anchor spike "
                f"exhausted {rejection['consecutive']}/"
                f"{rejection['limit']} retries"
            )
        print(
            f"[dblock-nat-anchor] spike rejected; same committed state "
            f"will retry next batch "
            f"({rejection['consecutive']}/{rejection['limit']})",
            flush=True,
        )
        state["training_science_last_receipt"]["route_outcome"] = "nat_anchor_spike"
        _dblock_emit_target_route_receipt(state, args)
        return raw_avg_val

    _t = _profile_tic(prof)
    _scale_before = float(scaler.get_scale()) if hasattr(scaler, "get_scale") else None
    scaler.unscale_(opt)
    _gate_parameters = list(sat_h.gate.parameters()) if getattr(sat_h, "gate", None) is not None else []
    if getattr(sat_h, "gate_conf", None) is not None:
        _gate_parameters = _gate_parameters + list(sat_h.gate_conf.parameters())
    _gate_parameter_ids = {id(param) for param in _gate_parameters}
    _main_parameters = [
        param for group in opt.param_groups for param in group["params"]
        if id(param) not in _gate_parameter_ids
    ]
    _main_grad_norm = nn.utils.clip_grad_norm_(_main_parameters, 1.0)
    _gate_grad_norm = (
        nn.utils.clip_grad_norm_(_gate_parameters, 0.25)
        if _gate_parameters else torch.tensor(0.0)
    )
    _grad_norm = _main_grad_norm
    _gate_group = next(
        (group for group in opt.param_groups
         if str(group.get("agillm43_role") or "") == "sat_variable_gate"),
        None,
    )
    _main_grad_finite = bool(
        torch.isfinite(torch.as_tensor(_main_grad_norm)).item()
    )
    _gate_grad_finite = bool(
        torch.isfinite(torch.as_tensor(_gate_grad_norm)).item()
    )
    if not (_main_grad_finite and _gate_grad_finite):
        opt.zero_grad(set_to_none=True)
        if bool(getattr(args, "repair_fail_fast", False)):
            _repair_write_fail(
                args, "nonfinite_gradient_norm", block=int(bi),
                main_grad_norm=str(_main_grad_norm), gate_grad_norm=str(_gate_grad_norm),
            )
            raise RuntimeError("repair fail-fast: non-finite gradient norm")
        _profile_toc(state, "step_total", _step_t)
        _profile_step_done(state, args)
        _update_stats(state, bi, raw_avg_val, args, objective=objective, trained=False)
        state["training_science_last_receipt"]["route_outcome"] = "gradient_nonfinite"
        _dblock_emit_target_route_receipt(state, args)
        return raw_avg_val
    state["sat_variable_gate_grad_last"] = {
        "main_preclip_norm": float(torch.as_tensor(_main_grad_norm).detach().cpu()),
        "gate_preclip_norm": float(torch.as_tensor(_gate_grad_norm).detach().cpu()),
        "main_clip": 1.0,
        "gate_clip": 0.25,
        "effective_lr": (
            None if _gate_group is None else float(_gate_group.get("lr", 0.0))
        ),
        "step": int(state.get("step", 0)),
    }
    if sat_anchor_info.get("ran", False):
        print(
            "[sat-variable-grad] "
            + json.dumps(
                state["sat_variable_gate_grad_last"],
                sort_keys=True, separators=(",", ":"), allow_nan=False,
            ),
            flush=True,
        )
    _dblock_target_route_validate_precommit(
        state, args, bi, train_layers, train_sublayers
    )
    scaler.step(opt)
    scaler.update()
    _scale_after = float(scaler.get_scale()) if hasattr(scaler, "get_scale") else None
    _optimizer_committed = _dblock_scaler_step_committed(_scale_before, _scale_after)
    if _optimizer_committed:
        _dblock_commit_supervised(
            state, bi, pending_supervised, anchor_info,
            sat_anchor_info=sat_anchor_info, nat_anchor_info=nat_anchor_info,
        )
        _dblock_commit_local_spike_state(
            state, pending_local_spike_state
        )
        if pending_local_aux_warning is not None:
            committed_warning = dict(pending_local_aux_warning)
            committed_warning.update({
                "committed": True,
                "outcome": "optimizer_committed",
            })
            _dblock_emit_local_aux_warning(committed_warning)
    else:
        state["optimizer_overflow_skips"] = int(state.get("optimizer_overflow_skips", 0)) + 1
        if pending_local_aux_warning is not None:
            overflow_warning = dict(pending_local_aux_warning)
            overflow_warning.update({
                "committed": False,
                "outcome": "amp_overflow",
            })
            _dblock_emit_local_aux_warning(overflow_warning)
        print(
            f"[dblock] AMP overflow skipped optimizer update scale={_scale_before}->{_scale_after}; target counters not committed",
            flush=True,
        )
    opt.zero_grad(set_to_none=True)
    _profile_toc(state, "opt_step", _t)

    peak_alloc = None
    peak_reserved = None
    if torch.cuda.is_available():
        peak_alloc = torch.cuda.max_memory_allocated() / (1024**3)
        peak_reserved = torch.cuda.max_memory_reserved() / (1024**3)
    _profile_toc(state, "step_total", _step_t)
    _profile_step_done(state, args)
    _update_stats(
        state, bi, raw_avg_val, args, objective=objective, trained=_optimizer_committed
    )
    if _optimizer_committed:
        _dblock_target_route_commit(state, args)
    _weight_accel_after_update(
        core, opt, args, state, bi, train_layers, objective, raw_avg_val,
        _optimizer_committed,
    )
    local_objectives = [
        str(name) for name, used in pending_supervised.items()
        if int(used or 0) > 0
    ]
    state["training_science_last_receipt"].update({
        "committed": bool(_optimizer_committed),
        "committed_step_after": int(state.get("step", 0) or 0),
        "route_clock_after": (
            None if route_target is None
            else int(state["target_route"]["route_commit_clock"])
        ),
        "route_pending_after": (
            None if route_target is None
            else _dblock_json_copy(state["target_route"]["pending_target"])
        ),
        "local_objectives": local_objectives,
        "local_passes": int(len(local_objectives)),
        "anchors": _dblock_json_copy(
            state["training_science_last_receipt"].get("anchors", {})
        ),
    })
    if not _optimizer_committed:
        state["training_science_last_receipt"]["route_outcome"] = "amp_overflow"
    _maybe_log(
        state,
        args,
        bi,
        train_layers,
        ar_val,
        sat_val,
        nat_val,
        total_val,
        peak_alloc,
        peak_reserved,
        objective=objective,
        raw_avg=raw_avg_val,
        raw_total=raw_total_val,
        edm_weight=w,
    )
    _dblock_emit_target_route_receipt(state, args)
    return raw_avg_val

# ===== END dblocks_train.py =====


