# Dedicated mutable dataset policy. This is intentionally separate from HOT_CONFIG_PATH:
# production launches may pin HOT_CONFIG_PATH by SHA256 for optimizer/objective safety, while
# dataset membership remains atomically changeable without restarting model or optimizer state.
DATASET_HOTLOAD_SCHEMA_V1 = "agillm.dataset_hotload.config.v1"
DATASET_HOTLOAD_SCHEMA_V2 = "agillm.dataset_hotload.config.v2"
DATASET_HOTLOAD_CONFIG_PATH = Path(
    os.environ.get("AGILLM_DATASET_HOTLOAD_CONFIG")
    or os.environ.get("AGILLM_DATASET_HOT_CONFIG")
    or "/workspace/agillm43_dataset_hotload.json"
)
try:
    DATASET_HOTLOAD_MAX_BYTES = max(
        4096, int(os.environ.get("AGILLM_DATASET_HOTLOAD_MAX_BYTES", "262144") or 262144)
    )
except Exception:
    DATASET_HOTLOAD_MAX_BYTES = 262144
_dataset_hotload_cache = {
    "stamp": None,
    "bad_stamp": None,
    "data": {},
    "sha256": "",
    "last_error": "",
}
_DATASET_HOTLOAD_ALLOWED_KEYS = {
    "schema", "enabled", "generation", "note", "reason", "updated_utc", "updated_by", "metadata",
    "datasets", "datasets_append", "extra_datasets",
    "datasets_remove", "remove_datasets",
    "dataset_min_fractions", "source_min_fractions",
}


def _dataset_hotload_stamp(path=None):
    target = Path(path) if path is not None else DATASET_HOTLOAD_CONFIG_PATH
    try:
        st = target.stat()
        return (int(st.st_dev), int(st.st_ino), int(st.st_mtime_ns), int(st.st_size))
    except Exception:
        return (0, 0, 0, 0)


def _dataset_hotload_split_specs(value, *, field, allow_weight=True):
    if value is None or value == "":
        return []
    values = value if isinstance(value, list) else [value]
    if not isinstance(values, list):
        raise TypeError(f"{field} must be a string or list of strings")
    ordered = []
    by_source = {}
    for item in values:
        if not isinstance(item, str):
            raise TypeError(f"{field} entries must be strings")
        for raw_spec in item.split(","):
            spec = raw_spec.strip()
            if not spec:
                continue
            if len(spec) > 1024 or any(ord(ch) < 32 or ord(ch) == 127 for ch in spec):
                raise ValueError(f"invalid control character or oversized entry in {field}")
            source = spec
            head, sep, tail = spec.rpartition("|")
            if sep:
                if not allow_weight:
                    raise ValueError(f"weights are not allowed in {field}: {spec!r}")
                try:
                    weight = float(tail)
                except Exception as exc:
                    raise ValueError(f"invalid dataset weight in {field}: {spec!r}") from exc
                if not math.isfinite(weight) or weight < 0.0 or weight > 100.0:
                    raise ValueError(f"dataset weight must be finite and in [0,100]: {spec!r}")
                source = head.strip()
                spec = f"{source}|{weight:.12g}"
            if not source or "," in source:
                raise ValueError(f"invalid empty/comma-containing dataset source in {field}: {spec!r}")
            if source not in by_source:
                ordered.append(source)
            by_source[source] = spec
            if len(ordered) > 256:
                raise ValueError(f"{field} exceeds 256 unique dataset sources")
    return [by_source[source] for source in ordered]


def _dataset_hotload_validate_payload(payload):
    if not isinstance(payload, dict):
        raise TypeError("dataset hotload config must be a JSON object")
    unknown = sorted(set(payload) - _DATASET_HOTLOAD_ALLOWED_KEYS)
    if unknown:
        raise ValueError(f"non-dataset keys are forbidden in mutable dataset config: {unknown}")
    out = dict(payload)
    schema = str(out.get("schema") or DATASET_HOTLOAD_SCHEMA_V2).strip()
    if schema not in {DATASET_HOTLOAD_SCHEMA_V1, DATASET_HOTLOAD_SCHEMA_V2}:
        raise ValueError(f"unsupported dataset hotload schema: {schema!r}")
    out["schema"] = schema
    enabled = out.get("enabled", True)
    if not isinstance(enabled, bool):
        raise TypeError("dataset hotload enabled must be boolean")
    out["enabled"] = enabled
    try:
        generation = int(out.get("generation", 0) or 0)
    except Exception as exc:
        raise TypeError("dataset hotload generation must be an integer") from exc
    if generation < 0:
        raise ValueError("dataset hotload generation must be non-negative")
    out["generation"] = generation
    for key in ("note", "reason", "updated_utc", "updated_by"):
        if key not in out:
            continue
        value = str(out.get(key) or "").strip()
        if len(value) > 4096 or any(ord(ch) == 0 for ch in value):
            raise ValueError(f"invalid or oversized {key}")
        out[key] = value
    if "metadata" in out and not isinstance(out.get("metadata"), dict):
        raise TypeError("dataset hotload metadata must be an object")
    for key in ("datasets", "datasets_append", "extra_datasets"):
        if key in out:
            out[key] = _dataset_hotload_split_specs(out.get(key), field=key, allow_weight=True)
    for key in ("datasets_remove", "remove_datasets"):
        if key in out:
            out[key] = _dataset_hotload_split_specs(out.get(key), field=key, allow_weight=False)
    for key in ("dataset_min_fractions", "source_min_fractions"):
        if key not in out:
            continue
        floors = out.get(key)
        if not isinstance(floors, dict):
            raise TypeError(f"{key} must be an object mapping source patterns to fractions")
        normalized = {}
        for raw_pattern, raw_fraction in floors.items():
            pattern = str(raw_pattern or "").strip()
            if not pattern or len(pattern) > 1024 or any(ord(ch) < 32 for ch in pattern):
                raise ValueError(f"invalid source pattern in {key}")
            try:
                fraction = float(raw_fraction)
            except Exception as exc:
                raise TypeError(f"invalid fraction for {pattern!r} in {key}") from exc
            if not math.isfinite(fraction) or fraction < 0.0 or fraction > 0.80:
                raise ValueError(f"fraction for {pattern!r} must be finite and in [0,0.80]")
            normalized[pattern] = fraction
        out[key] = normalized
    return out


def _dataset_hotload_read_path(path):
    target = Path(path)
    before = _dataset_hotload_stamp(target)
    if before == (0, 0, 0, 0):
        raise FileNotFoundError(target)
    if before[3] > DATASET_HOTLOAD_MAX_BYTES:
        raise ValueError(
            f"dataset hotload config is {before[3]} bytes; limit is {DATASET_HOTLOAD_MAX_BYTES}"
        )
    raw = target.read_bytes()
    after = _dataset_hotload_stamp(target)
    if before != after:
        raise RuntimeError("dataset hotload config changed during read; retrying on next poll")
    parsed = json.loads(raw.decode("utf-8"))
    normalized = _dataset_hotload_validate_payload(parsed)
    return normalized, after, hashlib.sha256(raw).hexdigest()


def get_dataset_hotload_config() -> dict:
    """Read the last-known-good dedicated dataset policy.

    Invalid or partial writes cannot poison a live token stream. The mutable file accepts
    dataset-only keys, while LR, model, objective and checkpoint controls remain protected by
    the separately SHA-pinned HOT_CONFIG_PATH contract.
    """
    stamp = _dataset_hotload_stamp()
    if stamp == _dataset_hotload_cache.get("stamp"):
        return dict(_dataset_hotload_cache.get("data") or {})
    if stamp == _dataset_hotload_cache.get("bad_stamp"):
        return dict(_dataset_hotload_cache.get("data") or {})
    if stamp == (0, 0, 0, 0):
        _dataset_hotload_cache.update({
            "stamp": stamp, "bad_stamp": None, "data": {}, "sha256": "", "last_error": ""
        })
        return {}
    try:
        parsed, stable_stamp, sha256 = _dataset_hotload_read_path(DATASET_HOTLOAD_CONFIG_PATH)
        if parsed.get("enabled", True) is False:
            parsed = {
                "schema": parsed.get("schema"),
                "enabled": False,
                "generation": parsed.get("generation", 0),
                "reason": parsed.get("reason", ""),
                "updated_utc": parsed.get("updated_utc", ""),
                "updated_by": parsed.get("updated_by", ""),
            }
        _dataset_hotload_cache.update({
            "stamp": stable_stamp,
            "bad_stamp": None,
            "data": parsed,
            "sha256": sha256,
            "last_error": "",
        })
        print(
            f"[dataset-hotload] loaded policy path={DATASET_HOTLOAD_CONFIG_PATH} "
            f"generation={parsed.get('generation', 0)} enabled={parsed.get('enabled', True)} "
            f"sha256={sha256[:12]}",
            flush=True,
        )
        return dict(parsed)
    except Exception as exc:
        err = f"{type(exc).__name__}: {exc}"
        if err != _dataset_hotload_cache.get("last_error"):
            print(
                f"[dataset-hotload] invalid update ignored; keeping last-known-good policy: {err}",
                flush=True,
            )
        _dataset_hotload_cache["last_error"] = err
        _dataset_hotload_cache["bad_stamp"] = stamp
        return dict(_dataset_hotload_cache.get("data") or {})


def get_dataset_policy_config() -> dict:
    """Combine immutable/general hot config with the dedicated mutable dataset policy."""
    base = dict(get_hot_config() or {})
    dedicated = get_dataset_hotload_config()
    if dedicated.get("enabled", True) is False:
        return base

    def _csv(value):
        if isinstance(value, list):
            return ",".join(str(item).strip() for item in value if str(item).strip())
        return str(value or "").strip()

    # Preserve both policies instead of last-writer-wins. De-duplication by source key
    # is performed by get_hot_datasets/_dataset_merge_csv after module initialization.
    for key in (
        "datasets", "datasets_append", "extra_datasets", "datasets_remove", "remove_datasets"
    ):
        extra = _csv(dedicated.get(key))
        if not extra:
            continue
        prior = _csv(base.get(key))
        base[key] = ",".join(item for item in (prior, extra) if item)

    for key in ("dataset_min_fractions", "source_min_fractions"):
        extra = dedicated.get(key)
        if not isinstance(extra, dict):
            continue
        prior = base.get(key) if isinstance(base.get(key), dict) else {}
        merged = dict(prior)
        merged.update(extra)
        base[key] = merged
    return base


AR_NAT_SAT_FORCE_TOKEN = "I_ACCEPT_DISABLING_AR_NAT_SAT_HEADS"
_AR_NAT_SAT_SAFE_FLOATS = {
    "dblock_sat_prob": 0.25,
    "dblock_nat_prob": 0.30,
    "dblock_sat_weight": 1.0,
    "dblock_nat_weight": 1.0,
    "nat_loss_weight": 1.0,
}
_AR_NAT_SAT_SAFE_LOSS_TOKENS = {
    "sat": 1024,
    "nat": 4096,
}
_ar_nat_sat_guard_seen = set()


def _ar_nat_sat_force_override_ok(cfg: dict) -> bool:
    if not isinstance(cfg, dict):
        return False
    try:
        until = float(cfg.get("force_ar_nat_sat_override_until_unix") or 0.0)
    except Exception:
        until = 0.0
    if cfg.get("force_ar_nat_sat_override") != AR_NAT_SAT_FORCE_TOKEN:
        return False
    if until <= time.time() or until - time.time() > 7200:
        return False
    return bool(str(cfg.get("force_ar_nat_sat_override_by") or "").strip()) and bool(str(cfg.get("force_ar_nat_sat_override_reason") or "").strip())


def _ar_nat_sat_guard_reason() -> str:
    return (
        "AR+SAT+NAT must all stay active: SAT/NAT are separate trained inference heads, "
        "zeroing them starves those heads and can rot the fast inference modes; "
        "a previous AR-only recovery experiment worsened validation CE. "
        f"To force a short diagnostic override, set force_ar_nat_sat_override={AR_NAT_SAT_FORCE_TOKEN!r}, "
        "force_ar_nat_sat_override_by, force_ar_nat_sat_override_reason, and "
        "force_ar_nat_sat_override_until_unix (<=2h)."
    )


def _ar_nat_sat_guard_float(cfg: dict, attr: str, value: float) -> float:
    if attr not in _AR_NAT_SAT_SAFE_FLOATS or value > 0.0 or _ar_nat_sat_force_override_ok(cfg):
        return value
    fallback = float(_AR_NAT_SAT_SAFE_FLOATS[attr])
    key = (attr, fallback)
    if key not in _ar_nat_sat_guard_seen:
        _ar_nat_sat_guard_seen.add(key)
        print(f"[hot_config][GUARD] Refusing {attr}={value}; using {fallback}. {_ar_nat_sat_guard_reason()}", flush=True)
    return fallback


def _ar_nat_sat_guard_loss_tokens(cfg: dict, objective: str, value: int) -> int:
    obj = str(objective or "").strip().lower()
    if obj not in _AR_NAT_SAT_SAFE_LOSS_TOKENS or value > 0 or _ar_nat_sat_force_override_ok(cfg):
        return value
    fallback = int(_AR_NAT_SAT_SAFE_LOSS_TOKENS[obj])
    key = (f"{obj}_loss_tokens", fallback)
    if key not in _ar_nat_sat_guard_seen:
        _ar_nat_sat_guard_seen.add(key)
        print(f"[hot_config][GUARD] Refusing dblock_{obj}_loss_tokens={value}; using {fallback}. {_ar_nat_sat_guard_reason()}", flush=True)
    return fallback

# AGILLM-OBJECTIVE-GUARD 20260704: owner directive (Scott) — AR+NAT+SAT ALWAYS.
# On 2026-07-03 agents hot-tuned the objective mix to AR-only (nat/sat prob 0)
# chasing a val-CE regression; the run diverged to ppl 4.7M and needed a
# rollback+restart. Zeroing a head also silently rots the NAT/SAT inference
# modes. Any dblock_*_prob below OBJECTIVE_PROB_FLOOR is clamped with a loud
# warning unless the 4-field force_ar_nat_sat_override contract (below) is
# satisfied — ONE override mechanism for both guard layers.
OBJECTIVE_PROB_FLOOR = 0.05
_objective_guard_warned = {}


def _guard_objective_mix(cfg: dict) -> dict:
    # Defers to the same force_ar_nat_sat_override contract as the >0 guard
    # helpers above (token + by + reason + expiry <=2h) — a single override
    # mechanism so agents never satisfy one guard and get blocked by another.
    if not isinstance(cfg, dict) or _ar_nat_sat_force_override_ok(cfg):
        return cfg
    for key in ("dblock_ar_prob", "dblock_sat_prob", "dblock_nat_prob"):
        val = cfg.get(key)
        if val is None:
            continue
        try:
            val = float(val)
        except (TypeError, ValueError):
            continue
        if val < OBJECTIVE_PROB_FLOOR:
            cfg = dict(cfg)
            cfg[key] = OBJECTIVE_PROB_FLOOR
            if _objective_guard_warned.get(key) != val:
                _objective_guard_warned[key] = val
                print(
                    f"[hot_config] *** OBJECTIVE GUARD *** {key}={val} BLOCKED, clamped to {OBJECTIVE_PROB_FLOOR}.\n"
                    f"[hot_config]   WHY (owner policy, Scott): AGILLM4.3 is one shared trunk with THREE decode heads;\n"
                    f"[hot_config]   AR, SAT and NAT are all product surfaces (AR=quality, SAT~13 tok/s, NAT 150+ tok/s serving).\n"
                    f"[hot_config]   Zeroing a head freezes its weights while the trunk keeps moving under the other\n"
                    f"[hot_config]   objectives -> that head rots and its inference mode degrades until retrained.\n"
                    f"[hot_config]   Evidence 2026-07-03: agents thrashed the mix to AR-only chasing a val-CE regression;\n"
                    f"[hot_config]   it fixed nothing (divergence was weight-level, val CE 11->15.4, ppl 4.7M, needed a\n"
                    f"[hot_config]   rollback+restart) and risked rotting NAT/SAT. The 270k-step stable history all ran\n"
                    f"[hot_config]   on the mixed objective. If you have a genuinely good reason (e.g. brief diagnostic),\n"
                    f"[hot_config]   use the force_ar_nat_sat_override contract (token + _by + _reason + _until_unix <=2h)\n"
                    f"[hot_config]   AND announce it on the SG training channel first.",
                    flush=True,
                )
    return cfg


def get_hot_config() -> dict:
    """Load hot_config.json with caching, return empty dict if missing"""
    expected_sha256 = str(
        os.environ.get("AGILLM_HOT_CONFIG_SHA256", "") or ""
    ).strip().lower()
    try:
        if expected_sha256:
            if re.fullmatch(r"[0-9a-f]{64}", expected_sha256) is None:
                raise RuntimeError("AGILLM_HOT_CONFIG_SHA256 must be lowercase sha256")
            raw = HOT_CONFIG_PATH.read_bytes()
            actual_sha256 = hashlib.sha256(raw).hexdigest()
            if actual_sha256 != expected_sha256:
                raise RuntimeError(
                    "immutable hot_config sha256 mismatch: "
                    f"{actual_sha256} != {expected_sha256}"
                )
            if _hot_config_cache.get("sha256") != actual_sha256:
                parsed = json.loads(raw.decode("utf-8"))
                _hot_config_cache["data"] = _guard_objective_mix(parsed)
                _hot_config_cache["sha256"] = actual_sha256
                _hot_config_cache["mtime"] = HOT_CONFIG_PATH.stat().st_mtime
            return _hot_config_cache["data"]
        if HOT_CONFIG_PATH.exists():
            mtime = HOT_CONFIG_PATH.stat().st_mtime
            if mtime > _hot_config_cache["mtime"]:
                with open(HOT_CONFIG_PATH) as f:
                    _hot_config_cache["data"] = _guard_objective_mix(json.load(f))
                _hot_config_cache["mtime"] = mtime
        return _hot_config_cache["data"]
    except Exception as e:
        if expected_sha256:
            raise RuntimeError(
                f"immutable hot_config contract failed for {HOT_CONFIG_PATH}: {e}"
            ) from e
        print(f"[hot_config] Error loading: {e}")
        return {}



def _hot_int_from_config(cfg: dict, names: list[str], default: int) -> int:
    """Read a non-negative int from hot_config, accepting top-level or dblock-nested keys."""
    if not isinstance(cfg, dict):
        return int(default)
    candidates = []
    for name in names:
        candidates.append(cfg.get(name))
    nested = cfg.get("dblock")
    if isinstance(nested, dict):
        for name in names:
            candidates.append(nested.get(name))
    for value in candidates:
        if value is None or value == "":
            continue
        try:
            return max(0, int(value))
        except Exception:
            continue
    return int(default)


def _hot_float_from_config(cfg: dict, names: list[str], default: float, min_value=None, max_value=None) -> float:
    """Read a float from hot_config, accepting top-level or dblock-nested keys."""
    if not isinstance(cfg, dict):
        return float(default)
    candidates = []
    for name in names:
        candidates.append(cfg.get(name))
    nested = cfg.get("dblock")
    if isinstance(nested, dict):
        for name in names:
            candidates.append(nested.get(name))
    for value in candidates:
        if value is None or value == "":
            continue
        try:
            out = float(value)
        except Exception:
            continue
        if min_value is not None:
            out = max(float(min_value), out)
        if max_value is not None:
            out = min(float(max_value), out)
        return out
    return float(default)


_hot_dblock_loss_tokens_seen = {}
_hot_dblock_float_seen = {}


def _dblock_hot_float(args, attr: str, default: float, names=None, min_value=None, max_value=None) -> float:
    raw_cli = getattr(args, attr, default)
    cli_default = float(default if raw_cli is None else raw_cli)
    if min_value is not None:
        cli_default = max(float(min_value), cli_default)
    if max_value is not None:
        cli_default = min(float(max_value), cli_default)
    if bool(getattr(args, "repair_mode", False)):
        return cli_default
    keys = list(names or [attr])
    if attr not in keys:
        keys.insert(0, attr)
    try:
        cfg = get_hot_config()
    except Exception:
        return cli_default
    value = _hot_float_from_config(cfg, keys, cli_default, min_value=min_value, max_value=max_value)
    value = _ar_nat_sat_guard_float(cfg, attr, value)
    key = (id(args), attr)
    if _hot_dblock_float_seen.get(key) != value:
        _hot_dblock_float_seen[key] = value
        if value != cli_default:
            print(f"[hot_config] {attr}={value} (cli_default={cli_default})", flush=True)
    return value

def _dblock_loss_token_cap(args, objective: str) -> int:
    """Hot-reload AR/SAT/NAT sampled CE token caps from hot_config.json.

    Supported hot_config keys:
      dblock_loss_tokens: shared default for AR/SAT/NAT
      dblock_ar_loss_tokens / dblock_sat_loss_tokens / dblock_nat_loss_tokens
      dblock: {loss_tokens, ar_loss_tokens, sat_loss_tokens, nat_loss_tokens}
    """
    obj = str(objective or "").strip().lower()
    attr = f"dblock_{obj}_loss_tokens"
    default = int(getattr(args, attr, 0) or 0)
    if bool(getattr(args, "repair_mode", False)):
        return max(0, default)
    try:
        cfg = get_hot_config()
    except Exception:
        return default
    value = _hot_int_from_config(
        cfg,
        [attr, f"{obj}_loss_tokens", "dblock_loss_tokens", "loss_tokens"],
        default,
    )
    value = _ar_nat_sat_guard_loss_tokens(cfg, obj, value)
    key = (id(args), attr)
    if _hot_dblock_loss_tokens_seen.get(key) != value:
        _hot_dblock_loss_tokens_seen[key] = value
        if value != default:
            print(f"[hot_config] {attr}={value} (cli_default={default})", flush=True)
    return value

def _dataset_config_to_csv(value) -> str:
    if isinstance(value, list):
        return ",".join(str(item).strip() for item in value if str(item).strip())
    return str(value or "").strip()


def _dataset_specs_csv(value: str) -> list[str]:
    return [part.strip() for part in str(value or "").split(",") if part.strip()]


def _dataset_spec_without_weight(spec: str) -> str:
    head, sep, tail = str(spec or "").strip().rpartition("|")
    if sep:
        try:
            float(tail)
            return head.strip()
        except Exception:
            pass
    return str(spec or "").strip()


def _dataset_merge_csv(*groups: str) -> str:
    """Merge dataset CSV groups; later duplicate specs update weight/config but never remove defaults."""
    ordered = []
    by_key = {}
    for group in groups:
        for spec in _dataset_specs_csv(group):
            key = _dataset_spec_without_weight(spec)
            if not key:
                continue
            if key not in by_key:
                ordered.append(key)
            by_key[key] = spec
    return ",".join(by_key[key] for key in ordered if key in by_key)


def _dataset_remove_csv(sources: str, removals: str) -> str:
    """Remove dataset specs by unweighted key or substring."""
    specs = _dataset_specs_csv(sources)
    remove_specs = _dataset_specs_csv(removals)
    if not specs or not remove_specs:
        return str(sources or "").strip()
    remove_keys = {_dataset_spec_without_weight(spec) for spec in remove_specs if spec}
    remove_needles = {key.lower() for key in remove_keys if key}
    kept = []
    for spec in specs:
        key = _dataset_spec_without_weight(spec)
        key_l = key.lower()
        if key in remove_keys or any(needle and needle in key_l for needle in remove_needles):
            continue
        kept.append(spec)
    return ",".join(kept)


def _looks_like_numeracy_source(spec: str) -> bool:
    base = _dataset_spec_without_weight(spec).lower()
    return "agillm_math_numeracy" in base or "math_numeracy_synth" in base


def _looks_numeracy_only_sources(sources: str) -> bool:
    specs = _dataset_specs_csv(sources)
    return bool(specs) and all(_looks_like_numeracy_source(spec) for spec in specs)


def _language_pretrain_fallback_sources() -> str:
    return str(
        os.environ.get("AGILLM_LANGUAGE_PRETRAIN_SOURCES")
        or globals().get("DEFAULT_LANGUAGE_PRETRAIN_SOURCES", "")
        or globals().get("DEFAULT_PRETRAIN_SOURCES", "")
    ).strip()


def _augment_numeracy_only_sources(default_sources: str) -> str:
    default_sources = str(default_sources or "").strip()
    disabled = str(os.environ.get("AGILLM_DISABLE_LANGUAGE_FALLBACK", "")).strip().lower() in {"1", "true", "yes", "on"}
    if disabled or not _looks_numeracy_only_sources(default_sources):
        return default_sources
    language_sources = _language_pretrain_fallback_sources()
    if not language_sources:
        return default_sources
    print(
        "[dataset-policy] numeracy-only pretrain source replaced with built-in language pretrain mix; "
        "numeracy_weight=0",
        flush=True,
    )
    return language_sources


def get_hot_datasets(default_sources: str) -> str:
    """Merge general + dedicated hot dataset policy into the safe default mix."""
    cfg = get_dataset_policy_config()
    sources = _augment_numeracy_only_sources(default_sources)
    hot_ds = _dataset_config_to_csv(cfg.get("datasets"))
    if hot_ds:
        sources = _dataset_merge_csv(sources, hot_ds)
        print(f"[hot_config] Merged datasets into default mix: {hot_ds}", flush=True)
    append_ds = _dataset_config_to_csv(cfg.get("datasets_append") or cfg.get("extra_datasets"))
    if append_ds:
        sources = _dataset_merge_csv(sources, append_ds)
        print(f"[hot_config] Appended datasets: {append_ds}", flush=True)
    remove_ds = _dataset_config_to_csv(cfg.get("datasets_remove") or cfg.get("remove_datasets"))
    if remove_ds:
        before = sources
        sources = _dataset_remove_csv(sources, remove_ds)
        if sources != before:
            print(f"[hot_config] Removed datasets from mix: {remove_ds}", flush=True)
    return sources


def _dataset_source_summary(sources: str) -> dict:
    specs = _dataset_specs_csv(sources)
    return {
        "count": len(specs),
        "specs": specs,
        "has_language_mix": any(("fineweb" in s.lower()) or ("wikipedia" in s.lower()) or ("c4" in s.lower()) or ("proof-pile" in s.lower()) or ("txt360" in s.lower()) for s in specs),
        "has_numeracy": any(_looks_like_numeracy_source(s) for s in specs),
    }


def _dataset_provenance(phase_name: str, requested_source: str, effective_source: str, args, *, use_hot_config: bool = True, val_requested: str = "", val_effective: str = "") -> dict:
    cfg = get_dataset_policy_config() if use_hot_config else {}
    hot_mtime = None
    try:
        hot_mtime = HOT_CONFIG_PATH.stat().st_mtime if HOT_CONFIG_PATH.exists() else None
    except Exception:
        hot_mtime = None
    summary = _dataset_source_summary(effective_source)
    source_bases = {
        _parse_dataset_ref(spec.split("|", 1)[0])[0]
        for spec in summary["specs"]
    }
    pinned_revisions = {
        base: _DATASET_REVISIONS[base]
        for base in sorted(source_bases)
        if base in _DATASET_REVISIONS
    }
    return {
        "schema": "agillm.dataset_provenance.v1",
        "phase": str(phase_name),
        "source_requested": str(requested_source or ""),
        "source_effective": str(effective_source or ""),
        "source_count": int(summary["count"]),
        "source_specs": list(summary["specs"]),
        "has_language_mix": bool(summary["has_language_mix"]),
        "has_numeracy": bool(summary["has_numeracy"]),
        "hot_config_path": str(HOT_CONFIG_PATH),
        "hot_config_mtime": hot_mtime,
        "hot_config_used": bool(use_hot_config),
        "hot_config_has_datasets": bool(cfg.get("datasets")),
        "hot_config_has_append": bool(cfg.get("datasets_append") or cfg.get("extra_datasets")),
        "hot_config_expected_sha256": str(
            os.environ.get("AGILLM_HOT_CONFIG_SHA256", "") or ""
        ).strip().lower(),
        "dataset_hotload_config_path": str(DATASET_HOTLOAD_CONFIG_PATH),
        "dataset_hotload_config_stamp": list(_dataset_hotload_stamp()),
        "dataset_hotload_config_used": bool(use_hot_config),
        "dataset_hotload_config_sha256": str(_dataset_hotload_cache.get("sha256") or "") if use_hot_config else "",
        "dataset_hotload_schema": str((get_dataset_hotload_config() if use_hot_config else {}).get("schema") or ""),
        "dataset_hotload_enabled": bool((get_dataset_hotload_config() if use_hot_config else {}).get("enabled", True)),
        "dataset_hotload_generation": int((get_dataset_hotload_config() if use_hot_config else {}).get("generation", 0) or 0),
        "dataset_revision_map_sha256": _DATASET_REVISIONS_SHA256,
        "dataset_revisions": pinned_revisions,
        "proof_pile_paths_sha256": _PROOF_PILE_ALL_TRAIN_PATHS_SHA256,
        "proof_pile_lfs_manifest_sha256": _PROOF_PILE_ALL_TRAIN_LFS_MANIFEST_SHA256,
        "dolma_url_manifest_raw_sha256": _DOLMA_V16_SAMPLE_RAW_SHA256,
        "dolma_url_list_sha256": _DOLMA_V16_SAMPLE_URLS_SHA256,
        "dolma_payload_integrity": "external_url_manifest_pinned_payload_hashes_unavailable",
        "val_source_requested": str(val_requested or ""),
        "val_source_effective": str(val_effective or ""),
        "dataset_field_text": str(getattr(args, "dataset_field_text", "text")),
        "chat": bool(getattr(args, "chat", False)),
    }


