# ═══════════════════ v28 variable-block SAT (owner directive 2026-09-12) ═══════════════════
# A SAT block of size n is n consecutive tokens that attend to each other and to every
# earlier block (block-causal).  Slot j of a block (0-based) predicts the token j+1 beyond
# the block's last visible token through the tied projection of (h + shift_emb[j]).
# n=1 is the AR objective, n=2 the historical fixed SAT objective; the variable objective
# samples n in 1..SATVAR_KMAX so the model learns every stride and a regret head learns
# how much each extra drafted token costs, which is what lets decode trade speed for
# intelligence per position instead of a hard-coded 1-or-2 gate.
SATVAR_KMAX = 8
SATVAR_REGRET_HIDDEN = 256
# Measured per-slot held-out CE on checkpoint 2874393 (fixed block-2 slots 6.33/6.86, larger
# untrained blocks 7.4-7.9).  Used only as the regret head's initial bias (pessimistic prior).
SATVAR_REGRET_PRIOR_CE = [6.3, 6.9, 7.6, 7.8, 7.9, 8.0, 8.0, 8.1]
SATVAR_SCHEMA = "agillm44.satvar.variable-block.v1"
SATVAR_DEFAULT_BLOCK_PROBS = "1:0.20,2:0.40,3:0.20,4:0.20"
_SATVAR_PARAM_PREFIXES = ("shift_emb", "stride_regret.", "satvar_regret_updates")


def _satvar_is_param_key(key) -> bool:
    key = str(key)
    return any(key == p or key.startswith(p) for p in _SATVAR_PARAM_PREFIXES)


def _satvar_enabled(args) -> bool:
    """Hot-switchable: hot_config dblock_satvar_enabled (0/1) overrides the CLI default."""
    cli = int(getattr(args, "dblock_satvar_enabled", 1) or 0)
    if bool(getattr(args, "repair_mode", False)):
        return bool(cli)
    try:
        cfg = get_hot_config()
    except Exception:
        return bool(cli)
    return bool(_hot_int_from_config(cfg, ["dblock_satvar_enabled", "satvar_enabled"], cli))


def _satvar_parse_block_probs(spec, kmax=None):
    """'1:0.2,2:0.4,3:0.2,4:0.2' -> normalized list indexed by size-1 (length kmax)."""
    kmax = int(SATVAR_KMAX if kmax is None else kmax)
    probs = [0.0] * kmax
    for item in str(spec or "").replace(";", ",").split(","):
        item = item.strip()
        if not item:
            continue
        size, _, weight = item.partition(":")
        size = int(size)
        weight = float(weight) if weight else 1.0
        if 1 <= size <= kmax and weight > 0.0 and math.isfinite(weight):
            probs[size - 1] += weight
    total = sum(probs)
    if total <= 0.0:
        probs = [0.0] * kmax
        probs[1 if kmax >= 2 else 0] = 1.0
        total = 1.0
    return [p / total for p in probs]


_satvar_block_probs_seen = {}


def _satvar_block_probs(args):
    spec = str(getattr(args, "dblock_satvar_block_probs", SATVAR_DEFAULT_BLOCK_PROBS) or SATVAR_DEFAULT_BLOCK_PROBS)
    if not bool(getattr(args, "repair_mode", False)):
        try:
            cfg = get_hot_config()
            for key in ("dblock_satvar_block_probs", "satvar_block_probs"):
                val = cfg.get(key) if isinstance(cfg, dict) else None
                if val is None and isinstance(cfg, dict) and isinstance(cfg.get("dblock"), dict):
                    val = cfg["dblock"].get(key)
                if val:
                    spec = str(val)
                    break
        except Exception:
            pass
    probs = _satvar_parse_block_probs(spec)
    key = id(args)
    if _satvar_block_probs_seen.get(key) != spec:
        _satvar_block_probs_seen[key] = spec
        print(f"[satvar] block size distribution {spec} -> {[round(p, 3) for p in probs]}", flush=True)
    return probs


def satvar_sample_sizes(T, probs, rng=None):
    """i.i.d. block sizes covering exactly T positions (last block truncated to fit)."""
    T = int(T)
    rng = rng or random
    sizes = []
    total = 0
    population = [i + 1 for i, p in enumerate(probs) if p > 0.0]
    weights = [p for p in probs if p > 0.0]
    while total < T:
        n = int(rng.choices(population, weights=weights, k=1)[0])
        n = min(n, T - total)
        sizes.append(n)
        total += n
    return sizes


def satvar_partition_arrays(sizes, T, device=None):
    """Per-position block id, slot index (0-based), block size, block-end position (vectorized)."""
    T = int(T)
    sizes_t = torch.as_tensor([int(s) for s in sizes], dtype=torch.long, device=device)
    if int(sizes_t.sum()) != T:
        raise ValueError(f"partition sizes sum {int(sizes_t.sum())} != T {T}")
    block_id = torch.repeat_interleave(torch.arange(sizes_t.numel(), device=sizes_t.device), sizes_t)
    bsize = torch.repeat_interleave(sizes_t, sizes_t)
    ends = torch.cumsum(sizes_t, 0) - 1
    starts = ends - sizes_t + 1
    bend = torch.repeat_interleave(ends, sizes_t)
    slot = torch.arange(T, device=sizes_t.device) - torch.repeat_interleave(starts, sizes_t)
    return block_id, slot, bsize, bend


def satvar_partition_mask(sizes, T, device=None, dtype=torch.float32):
    """Dense block-causal mask for an arbitrary partition: q attends k iff block(k) <= block(q)."""
    block_id, _, _, _ = satvar_partition_arrays(sizes, T, device=device or DEV)
    allow = block_id.view(1, -1) <= block_id.view(-1, 1)
    return torch.where(allow, torch.zeros((), device=allow.device, dtype=dtype),
                       torch.full((), float("-inf"), device=allow.device, dtype=dtype)).unsqueeze(0).unsqueeze(0)


def satvar_loss_index(sizes, T, loss_mask_row=None, device=None):
    """Positions that have a target (t + size < T): returns (pos, d_index, tgt_pos, block_end)."""
    block_id, slot, bsize, bend = satvar_partition_arrays(sizes, T, device=device)
    pos = torch.arange(T, device=block_id.device)
    tgt = pos + bsize
    keep = tgt < T
    if loss_mask_row is not None:
        lm = loss_mask_row.to(device=block_id.device, dtype=torch.bool)
        keep = keep & lm[tgt.clamp(max=T - 1)]
    keep = keep & (slot < SATVAR_KMAX)
    return pos[keep], slot[keep], tgt[keep], bend[keep]


@torch.no_grad()
def _satvar_token_ce_nograd(h, W, tgt, vchunk=8192):
    """Exact per-token CE (fp32 log-sum-exp, streamed over the vocab), no autograd.

    Autocast is disabled inside: under bf16/fp16 autocast the matmul would otherwise come back
    in the low-precision dtype and the fp32 index_put below would fail (v28.0 crashed on the
    first live SAT step with 'Index put requires the source and destination dtypes match').
    """
    hf = h.detach().float()
    Wf = W.detach()
    N = hf.size(0)
    V = Wf.size(0)
    m = torch.full((N,), -1e30, device=hf.device, dtype=torch.float32)
    s = torch.zeros(N, device=hf.device, dtype=torch.float32)
    zt = torch.zeros(N, device=hf.device, dtype=torch.float32)
    with torch.autocast(device_type=("cuda" if hf.is_cuda else "cpu"), enabled=False):
        for c in range(0, V, vchunk):
            lg = (hf @ Wf[c:c + vchunk].float().T).float()
            cm = lg.max(1).values
            nm = torch.maximum(m, cm)
            s = s * torch.exp(m - nm) + torch.exp(lg - nm[:, None]).sum(1)
            m = nm
            ic = (tgt >= c) & (tgt < c + vchunk)
            zt[ic] = lg[ic, tgt[ic] - c].to(zt.dtype)
    return (m + torch.log(s)) - zt


def _satvar_gather(sat_h, hidden, ids, loss_mask, sizes, max_tokens, rng=None):
    """Gather (hidden + E_d, target) pairs for a partition across all rows, sampled to max_tokens.

    Returns sat_hidden [N,d], sat_targets [N], used, available, d_index [N], end_pos [N], row [N].
    """
    B, T, D = hidden.shape
    block_id, slot, bsize, bend = satvar_partition_arrays(sizes, T, device=hidden.device)
    pos_t = torch.arange(T, device=hidden.device)
    tgt_t = pos_t + bsize
    keep_t = (tgt_t < T) & (slot < SATVAR_KMAX)
    if loss_mask is not None:
        lm = loss_mask.to(device=hidden.device, dtype=torch.bool)
        lm_at_tgt = lm.gather(1, tgt_t.clamp(max=T - 1).view(1, T).expand(B, T))
        keep_bt = keep_t.view(1, T) & lm_at_tgt
    else:
        keep_bt = keep_t.view(1, T).expand(B, T)
    idx = torch.nonzero(keep_bt, as_tuple=False)
    available = int(idx.size(0))
    if available <= 0:
        raise ValueError("no variable-block SAT targets available")
    max_tokens = int(max_tokens or 0)
    if 0 < max_tokens < available:
        idx = idx.index_select(0, torch.randint(available, (max_tokens,), device=idx.device))
    row = idx[:, 0]
    pos = idx[:, 1]
    d_idx = slot.index_select(0, pos)
    tgt = tgt_t.index_select(0, pos)
    bend_sel = bend.index_select(0, pos)
    flat = hidden.reshape(B * T, D)
    sel = sat_h.slot_hidden(flat.index_select(0, row * T + pos), d_idx)
    targets = ids.reshape(-1).index_select(0, row * T + tgt)
    return sel.contiguous(), targets.contiguous(), int(targets.numel()), available, d_idx, bend_sel, row


def _satvar_regret_loss(sat_h, hidden, ids, loss_mask, sizes, W, max_blocks=256):
    """Regress log E[CE_d] from the block's last hidden state (detached) for every observed slot.

    Per-slot CE is computed exactly without autograd; the regret head is the only module that
    receives gradient here, so the trunk/projection contracts are unchanged.  Returns
    (loss, info) where info carries per-d mean CE on the sampled blocks for telemetry.
    """
    B, T, D = hidden.shape
    dev = hidden.device
    sizes_t = torch.as_tensor([int(s) for s in sizes], dtype=torch.long, device=dev)
    ends = torch.cumsum(sizes_t, 0) - 1
    starts = ends - sizes_t + 1
    valid_block = (ends + sizes_t) < T                    # every slot of the block has a target
    cand = torch.nonzero(valid_block, as_tuple=False).flatten()
    if cand.numel() == 0:
        return None, {"blocks": 0}
    M_ = int(max(1, max_blocks))
    pick = cand.index_select(0, torch.randint(int(cand.numel()), (M_,), device=dev))
    rows = torch.randint(B, (M_,), device=dev)
    n_use = torch.clamp(sizes_t.index_select(0, pick), max=SATVAR_KMAX)   # slots per picked block
    blk = torch.repeat_interleave(torch.arange(M_, device=dev), n_use)
    offs = torch.cumsum(n_use, 0) - n_use
    d_idx = torch.arange(int(n_use.sum()), device=dev) - torch.repeat_interleave(offs, n_use)
    pos = starts.index_select(0, pick).index_select(0, blk) + d_idx
    tgt = pos + sizes_t.index_select(0, pick).index_select(0, blk)
    row = rows.index_select(0, blk)
    if loss_mask is not None:
        keep = loss_mask.reshape(-1).to(torch.bool).index_select(0, row * T + tgt)
        pos, d_idx, tgt, row, blk = (x[keep] for x in (pos, d_idx, tgt, row, blk))
        if pos.numel() == 0:
            return None, {"blocks": 0}
    flat = hidden.reshape(B * T, D)
    with torch.no_grad():
        hs = sat_h.slot_hidden(flat.index_select(0, row * T + pos), d_idx)
        ce = _satvar_token_ce_nograd(hs, W, ids.reshape(-1).index_select(0, row * T + tgt))
    # regret head input: the block's LAST slot hidden state (it has seen the whole block)
    end_pos = ends.index_select(0, pick)                      # [M_]
    h_last = flat.index_select(0, rows * T + end_pos)          # [M_, D]
    pred = sat_h.regret_log_ce(h_last)                         # [M_, KMAX]
    target_log = torch.log(ce.clamp_min(1e-3))
    pred_sel = pred[blk, d_idx]
    loss = F.smooth_l1_loss(pred_sel, target_log, beta=0.5)
    with torch.no_grad():
        info = {"blocks": int(M_), "slots": int(pos.numel()),
                "regret_mae_log": round(float((pred_sel - target_log).abs().mean()), 4),
                "ce_by_d": {}, "count_by_d": {}, "pred_ce_by_d": {}}
        for d in range(SATVAR_KMAX):
            m = d_idx == d
            cnt = int(m.sum())
            if cnt > 0:
                info["ce_by_d"][str(d + 1)] = round(float(ce[m].mean()), 4)
                info["count_by_d"][str(d + 1)] = cnt
                info["pred_ce_by_d"][str(d + 1)] = round(float(pred_sel[m].exp().mean()), 4)
    return loss, info


def _satvar_size_hist(sizes):
    hist = {}
    for n in sizes:
        hist[str(int(n))] = hist.get(str(int(n)), 0) + 1
    return hist


def _satvar_choose_stride(ce_hat, n_avail, lam, mu, kmax, remaining):
    """Deterministic speed/quality trade: maximize lam*(m-1) - sum_{d=2..m} max(0, CE_d - CE_1) - mu*[m>n_avail]."""
    best_m, best_u = 1, 0.0
    base = float(ce_hat[0])
    penalty = 0.0
    for m in range(2, int(min(kmax, remaining)) + 1):
        penalty += max(0.0, float(ce_hat[m - 1]) - base)
        u = float(lam) * (m - 1) - penalty - (float(mu) if m > int(n_avail) else 0.0)
        if u > best_u:
            best_m, best_u = m, u
    return best_m, best_u

def _sat_variable_gate_targets(sat_h, sat_ctx, sat_tgt, block=None):
    """SAT-variable 1-vs-2 labels: admit stride-2 iff the second SAT token matches gold.

    Class 0 = emit 1 token (second SAT draft disagrees with the gold partner).
    Class 1 = emit 2 tokens (second SAT draft agrees).  Labels are detached so
    the token head is not trained through the gate target.  This is the
    training-time counterpart of inference SAT-variable (AGILLM43_SAT_V15).
    """
    block = int(SAT_BLOCK if block is None else block)
    first = sat_ctx[:, ::block]
    second = sat_ctx[:, 1::block]
    gold2 = sat_tgt[:, 1::block]
    n = min(int(first.size(1)), int(second.size(1)), int(gold2.size(1)))
    if n <= 0:
        empty = gold2.new_zeros((sat_ctx.size(0), 0), dtype=torch.long)
        return first[:, :0], empty
    first = first[:, :n]
    second = second[:, :n]
    gold2 = gold2[:, :n]
    with torch.no_grad():
        pred2 = sat_h.proj(second).argmax(dim=-1)
        labels = (pred2 == gold2).to(dtype=torch.long)
    return second, labels

def _agillm43_sat_variable_threshold_from_env():
    """Serving admission threshold on the CALIBRATED P(second SAT draft is correct).

    v3 objective (2026-09-12): the gate is trained with plain BCE (a proper scoring
    rule) so its output is a probability, and the 1-vs-2 decision is the Bayes rule
    for the utility  U = passes_saved - error_cost * extra_top1_errors.  Accepting a
    block saves one forward pass and costs (q_ar - p_draft) expected top-1 errors.
    Measured frontier on the frozen held-out (ckpt 2874393, 6096 blocks):
      tau 0.20 -> +2.4% tokens/pass, -0.25 pt second-token top-1
      tau 0.15 -> +5.4% tokens/pass, -0.66 pt
      tau 0.10 -> +16%  tokens/pass, -2.1 pt
    Default 0.15.  Override with AGILLM43_SAT_VARIABLE_STRIDE2_THRESHOLD.
    """
    raw = os.environ.get("AGILLM43_SAT_VARIABLE_STRIDE2_THRESHOLD", "0.15")
    try:
        value = float(raw)
    except (TypeError, ValueError):
        value = 0.15
    if not math.isfinite(value) or not (0.0 < value < 1.0):
        value = 0.15
    return value


_AGILLM43_SAT_VARIABLE_STRIDE2_THRESHOLD = _agillm43_sat_variable_threshold_from_env()
# v3 SAT-variable gate: the admission classifier sees the draft heads' OWN
# confidence (log p_max, top-1/top-2 margin, entropy of both SAT drafts, plus
# draft agreement) through a small MLP, with the legacy linear probe on the
# second hidden state kept as an additive residual.  A hidden-state probe alone
# could not recover its head's confidence (held-out AUC 0.60 vs 0.68 for raw
# p_max), never exceeded p=0.70 against a 0.95 threshold, and so never routed
# stride-2.  Checkpoints record the schema so the legacy probe is zeroed exactly
# once on migration and the new MLP is seeded from a sha256-verified prefit.
_AGILLM43_SAT_VARIABLE_GATE_FEATURE_SCHEMA = "draft_confidence_v3"
_AGILLM43_SAT_VARIABLE_GATE_CONF_FEATURES = 7
_AGILLM43_SAT_VARIABLE_GATE_CONF_HIDDEN = 32
_AGILLM43_SAT_VARIABLE_GATE_CONF_OUTPUTS = 3  # p_draft (decision), q_ar, p_agree (telemetry)
_AGILLM43_SAT_VARIABLE_GATE_CONF_PREFIT_PATH = os.environ.get(
    "AGILLM43_SAT_VARIABLE_GATE_CONF_PREFIT", "")
_AGILLM43_SAT_VARIABLE_GATE_CONF_PREFIT_SHA256 = os.environ.get(
    "AGILLM43_SAT_VARIABLE_GATE_CONF_PREFIT_SHA256", "")


def _agillm43_sat_variable_predictions(logits):
    """Return serving-aligned binary decisions (1 means admit stride two)."""
    if not torch.is_tensor(logits) or logits.ndim < 1 or logits.size(-1) != 2:
        raise ValueError("SAT-variable gate logits must end in exactly two classes")
    probability_stride2 = logits.float().softmax(dim=-1)[..., 1]
    return probability_stride2.ge(
        _AGILLM43_SAT_VARIABLE_STRIDE2_THRESHOLD
    ).to(dtype=torch.long)


def _sat_variable_gate_anchor_loss(
        sat_h, sat_ctx, sat_tgt, max_blocks=64, loss_mask=None,
        token_ids=None, boundary_token_ids=None, class_weights=None,
        ar_h=None, ar_hidden=None):
    """Return bounded gate-only CE and exact admission telemetry.

    Class 1 means the second fixed-SAT draft exactly matches its gold token.
    Hidden features and the token-projection teacher are detached, so gradient
    reaches only sat_h.gate. Packed-document boundaries and unsupervised target
    pairs are excluded deterministically.
    """
    gate = getattr(sat_h, "gate", None)
    cap = max(0, int(max_blocks or 0))
    empty_info = {
        "enabled": bool(gate is not None and cap > 0),
        "blocks": 0,
        "available_blocks": 0,
        "stride2_labels": 0,
        "predicted_stride2": 0,
        "false_accepts": 0,
        "confusion": [[0, 0], [0, 0]],
        "boundary_excluded": 0,
        "correct": 0,
    }
    if gate is None or cap <= 0:
        return None, empty_info

    block = int(SAT_BLOCK)
    if block != 2:
        raise ValueError(
            f"SAT-variable anchor requires SAT_BLOCK=2, got {block}"
        )
    first = sat_ctx[:, ::block]
    second = sat_ctx[:, 1::block]
    gold1 = sat_tgt[:, ::block]
    gold2 = sat_tgt[:, 1::block]
    n = min(
        int(first.size(1)), int(second.size(1)),
        int(gold1.size(1)), int(gold2.size(1)),
    )
    if n <= 0:
        return None, empty_info

    first = first[:, :n].reshape(-1, first.size(-1))
    second = second[:, :n].reshape(-1, second.size(-1))
    gold2 = gold2[:, :n].reshape(-1)
    # v3: causal hidden at position 2k+2 (AR slot for token 2k+3) rides along
    # the same selection so AR-side labels align block-for-block.
    ar_rows = None
    if ar_h is not None and ar_hidden is not None:
        ar_rows = ar_hidden[:, 2::block][:, :n]
        if int(ar_rows.size(1)) == int(n):
            ar_rows = ar_rows.reshape(-1, ar_rows.size(-1))
        else:
            ar_rows = None
    eligible = torch.ones(
        sat_tgt.size(0), n, dtype=torch.bool, device=sat_tgt.device
    )
    boundary_excluded = 0
    if token_ids is not None:
        expected_shape = (
            int(sat_tgt.size(0)), int(sat_tgt.size(1)) + block
        )
        if tuple(token_ids.shape) != expected_shape:
            raise ValueError(
                f"SAT gate token_ids shape {tuple(token_ids.shape)} "
                f"does not match expected clean anchor shape {expected_shape}"
            )
        if boundary_token_ids is None:
            boundary_token_ids = _nat_boundary_ids()
        boundary_ids = sorted(
            {int(token_id) for token_id in boundary_token_ids}
        )
        windows = token_ids.unfold(1, 2 * block, block)[:, :n]
        crosses = torch.zeros_like(eligible)
        for token_id in boundary_ids:
            crosses |= windows.eq(token_id).any(dim=-1)
        boundary_excluded = int(crosses.sum().item())
        eligible &= ~crosses
    if loss_mask is not None:
        if tuple(loss_mask.shape) != tuple(sat_tgt.shape):
            raise ValueError(
                f"SAT gate loss_mask shape {tuple(loss_mask.shape)} "
                f"does not match targets {tuple(sat_tgt.shape)}"
            )
        valid1 = loss_mask[:, ::block][:, :n]
        valid2 = loss_mask[:, 1::block][:, :n]
        eligible &= (valid1 & valid2).to(dtype=torch.bool)

    eligible = eligible.reshape(-1)
    first = first[eligible]
    second = second[eligible]
    gold2 = gold2[eligible]
    if ar_rows is not None:
        ar_rows = ar_rows[eligible]
    available = int(gold2.numel())
    if available <= 0:
        empty_info["boundary_excluded"] = int(boundary_excluded)
        return None, empty_info

    used = min(available, cap)
    if used < available:
        select = torch.div(
            torch.arange(used, device=gold2.device) * available,
            used,
            rounding_mode="floor",
        )
        first = first.index_select(0, select)
        second = second.index_select(0, select)
        gold2 = gold2.index_select(0, select)
        if ar_rows is not None:
            ar_rows = ar_rows.index_select(0, select)

    with torch.no_grad():
        teacher_logits = sat_h.proj(second.detach())
        if boundary_token_ids is None:
            boundary_token_ids = _nat_boundary_ids()
        nat_mask_id = int(tuple(boundary_token_ids)[-1])
        if 0 <= nat_mask_id < int(teacher_logits.size(-1)):
            teacher_logits[..., nat_mask_id] = -torch.inf
        pred2 = teacher_logits.argmax(dim=-1)
        labels = pred2.eq(gold2).to(dtype=torch.long)
    # The label is correctness of the second SAT draft.  Gate on the exact
    # hidden state that produced that draft; using the first hidden state was a
    # semantic mismatch and collapsed the rare stride-2 class.
    # v3 objective: confidence features from BOTH drafts' logits (decode-time
    # available) through the small MLP, legacy probe as additive residual,
    # plain BCE (== 2-class CE on [0, z] with unit weights) => calibrated P.
    class_weights = None
    with torch.no_grad():
        first_logits = sat_h.proj(first.detach())
        if 0 <= nat_mask_id < int(first_logits.size(-1)):
            first_logits[..., nat_mask_id] = -torch.inf
    gate_logits, conf_logits = _sat_variable_gate_v3_logits(
        sat_h, second.detach(), first_logits, teacher_logits)
    aux_loss = None
    aux_info = {"ar_labels_available": False}
    if conf_logits is not None and ar_rows is not None and ar_h is not None:
        with torch.no_grad():
            ar_logits = ar_h(ar_rows.detach().unsqueeze(0))
            if isinstance(ar_logits, (tuple, list)):
                ar_logits = ar_logits[0]
            ar_logits = ar_logits.float()[0]
            if 0 <= nat_mask_id < int(ar_logits.size(-1)):
                ar_logits[..., nat_mask_id] = -torch.inf
            ar_pred = ar_logits.argmax(dim=-1)
            q_labels = ar_pred.eq(gold2).to(dtype=torch.float32)
            agree_labels = ar_pred.eq(pred2).to(dtype=torch.float32)
        aux_loss = 0.5 * (
            F.binary_cross_entropy_with_logits(conf_logits[:, 1].float(), q_labels)
            + F.binary_cross_entropy_with_logits(conf_logits[:, 2].float(), agree_labels)
        )
        aux_info = {
            "ar_labels_available": True,
            "ar_top1_labels": int(q_labels.sum().item()),
            "agree_labels": int(agree_labels.sum().item()),
            "aux_bce": float(aux_loss.detach()),
        }
    # The live admission labels are naturally imbalanced (stride-2 is the rare
    # "second SAT draft is trustworthy" class).  Plain CE collapsed to always
    # choosing stride-1 even after tens of thousands of positive labels.  Use a
    # stable, committed-history inverse-frequency weight so both learned choices
    # keep gradient without changing the verifier teacher or token projection.
    weight_tensor = None
    applied_class_weights = [1.0, 1.0]
    if class_weights is not None:
        if len(class_weights) != 2:
            raise ValueError("SAT-variable class_weights must have two entries")
        applied_class_weights = [float(class_weights[0]), float(class_weights[1])]
        if any((not math.isfinite(value) or value <= 0.0) for value in applied_class_weights):
            raise ValueError(f"invalid SAT-variable class weights {applied_class_weights!r}")
        weight_tensor = torch.tensor(
            applied_class_weights, dtype=torch.float32, device=gate_logits.device)
    loss = F.cross_entropy(gate_logits.float(), labels, weight=weight_tensor)
    if aux_loss is not None:
        loss = loss + aux_loss
    with torch.no_grad():
        probabilities_stride2 = gate_logits.detach().float().softmax(dim=-1)[:, 1]
        predictions = _agillm43_sat_variable_predictions(gate_logits.detach())
        margins = gate_logits.detach().float()[:, 1] - gate_logits.detach().float()[:, 0]
        stride2_labels = int(labels.sum().item())
        predicted_stride2 = int(predictions.sum().item())
        correct = int(predictions.eq(labels).sum().item())
        tn = int(((labels == 0) & (predictions == 0)).sum().item())
        fp = int(((labels == 0) & (predictions == 1)).sum().item())
        fn = int(((labels == 1) & (predictions == 0)).sum().item())
        tp = int(((labels == 1) & (predictions == 1)).sum().item())
    return loss, {
        "enabled": True,
        "blocks": int(used),
        "available_blocks": int(available),
        "stride2_labels": stride2_labels,
        "predicted_stride2": predicted_stride2,
        "false_accepts": fp,
        "confusion": [[tn, fp], [fn, tp]],
        "boundary_excluded": int(boundary_excluded),
        "correct": correct,
        "serving_stride2_threshold": _AGILLM43_SAT_VARIABLE_STRIDE2_THRESHOLD,
        "mean_probability_stride2": float(probabilities_stride2.mean().item()),
        "max_probability_stride2": float(probabilities_stride2.max().item()),
        "mean_logit_margin_stride2_minus_stride1": float(margins.mean().item()),
        "max_abs_logit": float(gate_logits.detach().float().abs().max().item()),
        "class_weights_stride1_stride2": applied_class_weights,
        "objective": "bce_calibrated_v3",
        "feature_schema": _AGILLM43_SAT_VARIABLE_GATE_FEATURE_SCHEMA,
        "threshold": _AGILLM43_SAT_VARIABLE_STRIDE2_THRESHOLD,
        "accept_precision": (float(tp) / float(tp + fp)) if (tp + fp) > 0 else None,
        "accepted_blocks": int(tp + fp),
        "utility_passes_saved_minus_errors": int(tp) - int(fp),
        "p_draft_mean": float(probabilities_stride2.mean().item()),
        "p_draft_max": float(probabilities_stride2.max().item()),
        "aux": aux_info,
        "aux_compact": json.dumps(aux_info, sort_keys=True, separators=(",", ":")),
    }


def _sat_variable_gate_history_class_weights(state, max_weight=16.0):
    """v3: no class re-weighting.

    Inverse-frequency weights destroy calibration (the 0.95 threshold then means
    p_true ~ 0.55 while the probe never exceeded p_true ~ 0.13).  The v3 gate is
    a calibrated BCE classifier on draft-confidence features; the rare positive
    class is handled by features that separate it, not by weights.
    """
    return [1.0, 1.0], "calibrated-bce-v3-no-reweighting"


class _SATGateConf(nn.Module):
    """Confidence-feature admission head for SAT-variable (v3).

    Input features per 2-token block (all available at decode time from the SAT
    logits already computed for the drafts):
      [logp2max, margin2, H2, logp1max, margin1, H1, same12]
    Outputs 3 logits: P(draft2 == gold), P(AR top-1 correct at that slot),
    P(draft2 == AR argmax).  Only the first drives routing; the others are
    telemetry for the speed/quality utility.  Initialisation is deterministic
    (private generator) so migration never consumes the trainer RNG.
    """

    def __init__(self, n_features=None, hidden=None, n_outputs=None):
        super().__init__()
        n_features = int(n_features or _AGILLM43_SAT_VARIABLE_GATE_CONF_FEATURES)
        hidden = int(hidden or _AGILLM43_SAT_VARIABLE_GATE_CONF_HIDDEN)
        n_outputs = int(n_outputs or _AGILLM43_SAT_VARIABLE_GATE_CONF_OUTPUTS)
        self.fc1 = nn.Linear(n_features, hidden)
        self.fc2 = nn.Linear(hidden, hidden)
        self.fc3 = nn.Linear(hidden, n_outputs)
        self.register_buffer("mu", torch.zeros(n_features))
        self.register_buffer("sd", torch.ones(n_features))
        gen = torch.Generator(device="cpu").manual_seed(20260912)
        with torch.no_grad():
            for lin in (self.fc1, self.fc2):
                bound = 1.0 / math.sqrt(float(lin.weight.size(1)))
                lin.weight.copy_(torch.empty(
                    lin.weight.shape, dtype=torch.float32).uniform_(-bound, bound, generator=gen))
                lin.bias.zero_()
            self.fc3.weight.zero_()
            # held-out census base rates: p_draft 0.11, q_ar 0.21, agree 0.27
            self.fc3.bias.copy_(torch.tensor([-2.06, -1.32, -1.0], dtype=torch.float32))

    def forward(self, feats):
        dtype = self.fc1.weight.dtype
        x = ((feats.float() - self.mu.float()) / self.sd.float()).to(dtype=dtype)
        x = F.silu(self.fc1(x))
        x = F.silu(self.fc2(x))
        return self.fc3(x)


_AGILLM43_SAT_GATE_NAT_MASK_ID_CACHE = [None]
_AGILLM43_V3_AR_HEAD_REF = [None]  # set by _dblock_step before the SAT anchor (v3 AR-side labels)


def _sat_variable_gate_confidence_features(logits_first, logits_second, nat_mask_id=None):
    """(N,V),(N,V) SAT draft logits -> (N,7) decode-time confidence features."""
    if nat_mask_id is None:
        if _AGILLM43_SAT_GATE_NAT_MASK_ID_CACHE[0] is None:
            _AGILLM43_SAT_GATE_NAT_MASK_ID_CACHE[0] = int(tuple(_nat_boundary_ids())[-1])
        nat_mask_id = _AGILLM43_SAT_GATE_NAT_MASK_ID_CACHE[0]
    l1 = logits_first.detach().float().clone()
    l2 = logits_second.detach().float().clone()
    if 0 <= int(nat_mask_id) < int(l1.size(-1)):
        l1[..., int(nat_mask_id)] = -torch.inf
        l2[..., int(nat_mask_id)] = -torch.inf
    lp1 = l1.log_softmax(dim=-1)
    lp2 = l2.log_softmax(dim=-1)
    top1 = lp1.topk(2, dim=-1)
    top2 = lp2.topk(2, dim=-1)
    ent1 = -(lp1.exp() * torch.nan_to_num(lp1, neginf=0.0)).sum(dim=-1)
    ent2 = -(lp2.exp() * torch.nan_to_num(lp2, neginf=0.0)).sum(dim=-1)
    same = (top1.indices[..., 0] == top2.indices[..., 0]).to(dtype=torch.float32)
    return torch.stack([
        top2.values[..., 0], top2.values[..., 0] - top2.values[..., 1], ent2,
        top1.values[..., 0], top1.values[..., 0] - top1.values[..., 1], ent1,
        same,
    ], dim=-1)


def _sat_variable_gate_v3_logits(sat_h, hidden_second, logits_first, logits_second):
    """Return (2-class gate logits [0, z], 3 conf logits) for v3; legacy when gate_conf is absent."""
    lin = sat_h.gate(hidden_second)
    gate_conf = getattr(sat_h, "gate_conf", None)
    if gate_conf is None:
        return lin, None
    feats = _sat_variable_gate_confidence_features(logits_first, logits_second)
    conf = gate_conf(feats)
    z = conf[..., 0].float() + (lin[..., 1] - lin[..., 0]).float()
    two = torch.stack([torch.zeros_like(z), z], dim=-1)
    return two, conf


def _agillm43_v3_zero_linear_gate(sat_h):
    """Zero the legacy probe (weight AND bias) so it starts as a null residual. RNG-free."""
    gate = getattr(sat_h, "gate", None)
    if gate is None or not hasattr(gate, "weight"):
        raise RuntimeError("v3 SAT-variable migration requires a linear sat_h.gate")
    before_w = _agillm43_exact_parameter_sha256(gate.weight)
    before_b = _agillm43_exact_parameter_sha256(gate.bias)
    with torch.no_grad():
        gate.weight.zero_()
        gate.bias.zero_()
    receipt = {
        "schema": "agillm43.sat-variable-gate.parameters.v3",
        "applied": True,
        "parameter_tensors": 2,
        "weight_shape": [int(d) for d in gate.weight.shape],
        "bias_shape": [int(d) for d in gate.bias.shape],
        "initialization": "zero_weight_zero_bias_residual",
        "class_0": "stride1",
        "class_1": "stride2",
        "serving_stride2_threshold": _AGILLM43_SAT_VARIABLE_STRIDE2_THRESHOLD,
        "rng_consumed": False,
        "reason": "legacy_hidden_probe_becomes_additive_residual_of_confidence_mlp",
        "before_weight_sha256": before_w,
        "before_bias_sha256": before_b,
        "after_weight_sha256": _agillm43_exact_parameter_sha256(gate.weight),
        "after_bias_sha256": _agillm43_exact_parameter_sha256(gate.bias),
    }
    print("[sat-variable-parameters-v3] " + json.dumps(receipt, sort_keys=True, separators=(",", ":")), flush=True)
    return receipt


def _agillm43_v3_load_gate_conf_prefit(sat_h, path=None, expected_sha256=None):
    """Seed gate_conf from a sha256-verified prefit. Fails closed (deterministic init stays)."""
    gate_conf = getattr(sat_h, "gate_conf", None)
    receipt = {"schema": "agillm43.sat-variable-gate-conf.prefit.v1", "applied": False,
               "path": str(path or _AGILLM43_SAT_VARIABLE_GATE_CONF_PREFIT_PATH or ""), "reason": ""}
    if gate_conf is None:
        receipt["reason"] = "no gate_conf module"
        return receipt
    path = receipt["path"]
    expected = str(expected_sha256 or _AGILLM43_SAT_VARIABLE_GATE_CONF_PREFIT_SHA256 or "")
    if not path:
        receipt["reason"] = "no prefit path configured"
        return receipt
    p = pathlib.Path(path)
    if not p.is_file():
        receipt["reason"] = "prefit file missing"
        return receipt
    digest = hashlib.sha256(p.read_bytes()).hexdigest()
    receipt["sha256"] = digest
    if not expected or digest != expected:
        receipt["reason"] = f"prefit sha256 mismatch expected={expected[:16]} actual={digest[:16]}"
        return receipt
    try:
        blob = torch.load(str(p), map_location="cpu", weights_only=True)
    except TypeError:
        blob = torch.load(str(p), map_location="cpu")
    sd = blob["state_dict"]
    mapping = {"0.weight": "fc1.weight", "0.bias": "fc1.bias", "2.weight": "fc2.weight",
               "2.bias": "fc2.bias", "4.weight": "fc3.weight", "4.bias": "fc3.bias"}
    with torch.no_grad():
        for src_key, dst in mapping.items():
            key = src_key if src_key in sd else dst
            mod_name, attr = dst.split(".")
            tensor = getattr(getattr(gate_conf, mod_name), attr)
            value = sd[key]
            if tuple(value.shape) != tuple(tensor.shape):
                receipt["reason"] = f"shape mismatch {key}"
                return receipt
            tensor.copy_(value.to(dtype=tensor.dtype, device=tensor.device))
        gate_conf.mu.copy_(torch.as_tensor(blob["mu"], dtype=gate_conf.mu.dtype, device=gate_conf.mu.device))
        gate_conf.sd.copy_(torch.as_tensor(blob["sd"], dtype=gate_conf.sd.dtype, device=gate_conf.sd.device))
    receipt["applied"] = True
    receipt["features"] = [str(f) for f in (blob.get("features") or [])]
    receipt["train_rows"] = int(blob.get("train_rows") or 0)
    receipt["source"] = str(blob.get("source") or "")
    return receipt

