def _repair_execution_contract_errors(args):
    """Return every seed-architecture/execution mismatch without mutating args."""
    errors = []
    if str(getattr(args, "preset", "") or "") != "agillm4_floor":
        errors.append("--preset agillm4_floor is required by the protected seed")
    reviewed_run_shape = {
        "block": 2048,
        "batch_size": 24,
        "data_seed": 1729310,
    }
    for name, expected in reviewed_run_shape.items():
        raw = getattr(args, name, None)
        if type(raw) is not int or raw != expected:
            errors.append(f"--{name} must equal reviewed recovery value {expected}")
    steps = getattr(args, "steps", None)
    if type(steps) is not int or steps != _AGILLM43_REPAIR_TARGET_COMMITS:
        errors.append(
            f"--steps must equal the immutable repair endpoint request "
            f"{_AGILLM43_REPAIR_TARGET_COMMITS}"
        )
    if getattr(args, "target_tokens", None) is not None:
        errors.append(
            "--target_tokens must be omitted; strict repair uses the immutable "
            "step/token endpoint"
        )
    rank = getattr(args, "rank", None)
    try:
        rank_ok = rank is None or int(rank) == 160
    except (TypeError, ValueError):
        rank_ok = False
    if not rank_ok:
        errors.append("--rank must be omitted or equal the protected seed rank 160")
    for name in ("x2", "fresh", "chilla_max_double", "agillm3_compat",
                 "ar_only", "no_nat_head"):
        if bool(getattr(args, name, False)):
            errors.append(f"--{name} is forbidden by the protected seed execution contract")
    if str(getattr(args, "attn_backend", "") or "").strip().lower() != "sdpa":
        errors.append("--attn_backend sdpa is required by the protected seed")
    for name, expected in _REPAIR_REVIEWED_EXECUTION_INTS.items():
        raw = getattr(args, name, None)
        try:
            actual = int(raw)
        except (TypeError, ValueError):
            actual = None
        if isinstance(raw, bool) or actual != expected:
            errors.append(f"--{name} must equal protected seed value {expected}")
    for name, expected in _REPAIR_REVIEWED_EXECUTION_FLOATS.items():
        raw = getattr(args, name, None)
        try:
            actual = float(raw)
        except (TypeError, ValueError):
            actual = None
        if (isinstance(raw, bool) or actual is None
                or not math.isfinite(actual) or abs(actual - expected) > 1e-12):
            errors.append(f"--{name} must equal protected seed value {expected}")
    for name, expected in _REPAIR_REVIEWED_EXECUTION_BOOLS.items():
        actual = bool(getattr(args, name, False))
        if actual is not expected:
            required = "enabled" if expected else "disabled"
            errors.append(f"--{name} must be {required} for the protected seed")
    return errors


def _repair_normalize_execution_value(name, value):
    bool_fields = {
        "sublinear_pooled_landmarks", "no_structured_masks", "anchor_memory",
        "dblock_looped", "dblock_sigma_stratified",
        "var", "block_stream", "moe_expert_stream",
    }
    int_fields = {
        "sublinear_window", "sublinear_stride", "sublinear_max_anchors",
        "sublinear_chunk", "sublinear_sinks", "sublinear_recent_anchors",
        "anchor_stride", "anchor_max", "anchor_position", "dblock_blocks",
        "dblock_loop_layers", "dblock_loop_start",
    }
    float_fields = {
        "alibi_scale", "dblock_loop_cond_scale", "dblock_sigma_min",
        "dblock_sigma_max", "dblock_sigma_pmean", "dblock_sigma_pstd",
    }
    if name in bool_fields:
        if not isinstance(value, bool):
            raise RuntimeError(f"repair execution field {name} must be boolean")
        return bool(value)
    if name in int_fields:
        if isinstance(value, bool):
            raise RuntimeError(f"repair execution field {name} must be an integer")
        try:
            return int(value)
        except (TypeError, ValueError) as exc:
            raise RuntimeError(
                f"repair execution field {name} must be an integer") from exc
    if name in float_fields:
        try:
            result = float(value)
        except (TypeError, ValueError) as exc:
            raise RuntimeError(f"repair execution field {name} must be finite") from exc
        if not math.isfinite(result):
            raise RuntimeError(f"repair execution field {name} must be finite")
        return result
    if name in {"attn_backend", "alibi_mode", "dblock_sigma_sampling"}:
        result = str(value or "").strip().lower()
        if not result:
            raise RuntimeError(f"repair execution field {name} must be non-empty")
        return result
    raise RuntimeError(f"unknown repair execution field {name}")


def _repair_apply_inference_contract(args, checkpoint):
    """Inherit repair execution metadata at inference; reject every explicit drift."""
    if not isinstance(checkpoint, dict):
        raise RuntimeError("inference checkpoint payload is not a mapping")
    repair_schema = str(checkpoint.get("repair_schema") or "").strip()
    repair_marker_fields = (
        "repair_contract", "repair_contract_sha256",
        "repair_lineage_schema", "repair_base_step",
        "repair_seed_sha256", "repair_checkpoint_step",
        "repair_target_commits", "repair_target_step",
        "repair_target_seen_tok",
        "repair_dataset_contract", "repair_heldout_contract",
        "repair_tokenizer_contract", "repair_resolved_architecture",
        "repair_resolved_architecture_sha256", "dblock_resume_state",
        "repair_validation_state",
    )
    partial_markers = []
    for marker_name in repair_marker_fields:
        marker_value = checkpoint.get(marker_name)
        present = marker_value is not None
        if isinstance(marker_value, str):
            present = bool(marker_value.strip())
        if present:
            partial_markers.append(marker_name)
    if repair_schema and repair_schema != _AGILLM_REPAIR_SCHEMA:
        raise RuntimeError(
            f"repair inference schema {repair_schema!r} is not current "
            f"{_AGILLM_REPAIR_SCHEMA!r}")
    if not repair_schema:
        if partial_markers:
            raise RuntimeError(
                "checkpoint has repair markers without a valid repair schema: "
                + ", ".join(partial_markers))
        for name, default in _REPAIR_INFERENCE_DEFAULTS.items():
            if getattr(args, name, None) is None:
                setattr(args, name, default)
        return {"repair": False, "inherited": False}

    contract = checkpoint.get("repair_contract")
    if (not isinstance(contract, dict)
            or str(contract.get("schema") or "") != _AGILLM_REPAIR_CONTRACT_SCHEMA):
        raise RuntimeError("repair inference requires the current embedded repair contract")
    stored_digest = str(checkpoint.get("repair_contract_sha256") or "")
    if (not re.fullmatch(r"[0-9a-f]{64}", stored_digest)
            or _repair_contract_sha256(contract) != stored_digest):
        raise RuntimeError("repair inference contract digest is missing or corrupt")
    fields = contract.get("fields")
    if not isinstance(fields, dict):
        raise RuntimeError("repair inference contract fields are missing")
    for name, expected in (
        ("steps", _AGILLM43_REPAIR_TARGET_COMMITS),
        ("repair_target_commits", _AGILLM43_REPAIR_TARGET_COMMITS),
        ("repair_target_step", _AGILLM43_REPAIR_TARGET_STEP),
        ("repair_target_seen_tok", _AGILLM43_REPAIR_TARGET_SEEN_TOK),
    ):
        if type(fields.get(name)) is not int or fields.get(name) != expected:
            raise RuntimeError(
                f"repair inference contract {name} is not the immutable endpoint"
            )
    if "target_tokens" not in fields or fields["target_tokens"] is not None:
        raise RuntimeError(
            "repair inference contract target_tokens must be explicitly null"
        )
    for name, expected in (
        ("repair_target_commits", _AGILLM43_REPAIR_TARGET_COMMITS),
        ("repair_target_step", _AGILLM43_REPAIR_TARGET_STEP),
        ("repair_target_seen_tok", _AGILLM43_REPAIR_TARGET_SEEN_TOK),
    ):
        if type(checkpoint.get(name)) is not int or checkpoint.get(name) != expected:
            raise RuntimeError(
                f"repair inference checkpoint {name} is not the immutable endpoint"
            )

    reviewed = {
        "attn_backend": "sdpa",
        **_REPAIR_REVIEWED_EXECUTION_INTS,
        "sublinear_pooled_landmarks": False,
        "no_structured_masks": False,
        "anchor_memory": False,
        "alibi_mode": "corrected",
        "alibi_scale": 0.0,
        "dblock_blocks": 14,
        "dblock_looped": False,
        "dblock_loop_layers": 0,
        "dblock_loop_start": 0,
        "dblock_loop_cond_scale": 1.0,
        "dblock_sigma_sampling": "lognormal",
        "dblock_sigma_stratified": True,
        "dblock_sigma_min": 0.002,
        "dblock_sigma_max": 80.0,
        "dblock_sigma_pmean": -1.2,
        "dblock_sigma_pstd": 1.2,
    }
    applied = {}
    for name in _REPAIR_INFERENCE_EXECUTION_FIELDS:
        if name not in fields:
            raise RuntimeError(f"repair inference contract is missing execution field {name}")
        stored = _repair_normalize_execution_value(name, fields[name])
        expected = _repair_normalize_execution_value(name, reviewed[name])
        if stored != expected:
            raise RuntimeError(
                f"repair inference stored execution field {name}={stored!r} "
                f"does not equal reviewed value {expected!r}")
        requested_raw = getattr(args, name, None)
        if requested_raw is not None:
            requested = _repair_normalize_execution_value(name, requested_raw)
            if requested != stored:
                raise RuntimeError(
                    f"repair inference execution drift for {name}: "
                    f"requested {requested!r}, checkpoint requires {stored!r}")
        setattr(args, name, stored)
        applied[name] = stored

    var_marker_present = hasattr(args, "_repair_var_explicit")
    var_explicit = (
        bool(getattr(args, "_repair_var_explicit", False))
        if var_marker_present else getattr(args, "var", None) is not None)
    requested_var = getattr(
        args, "_repair_requested_var", getattr(args, "var", None))
    if var_explicit:
        if type(requested_var) is not bool:
            raise RuntimeError("repair inference var must be boolean")
        if requested_var:
            raise RuntimeError(
                "repair inference forbids variable SAT; fixed stride-2 SAT is required")
    requested_block_stream = (
        bool(getattr(args, "_repair_requested_block_stream"))
        if hasattr(args, "_repair_requested_block_stream")
        else bool(getattr(args, "block_stream", False)))
    requested_moe_stream = (
        bool(getattr(args, "_repair_requested_moe_expert_stream"))
        if hasattr(args, "_repair_requested_moe_expert_stream")
        else bool(getattr(args, "moe_expert_stream", False)))
    if requested_block_stream:
        raise RuntimeError("repair inference forbids unreviewed runtime mode block_stream")
    if requested_moe_stream:
        raise RuntimeError("repair inference forbids unreviewed runtime mode moe_expert_stream")
    draft_mode = _repair_normalize_ar_draft(
        getattr(args, "ar_draft", "off"))
    if draft_mode == "sat_var":
        raise RuntimeError(
            "repair inference forbids variable-SAT AR drafting")
    if draft_mode not in {"off", "sat_fixed", "nat"}:
        raise RuntimeError(
            f"repair inference AR draft mode {draft_mode!r} is invalid")
    for name, value in (
            ("var", False), ("block_stream", False),
            ("moe_expert_stream", False)):
        setattr(args, name, value)
        applied[name] = value
    return {
        "repair": True,
        "inherited": True,
        "repair_schema": repair_schema,
        "repair_contract_sha256": stored_digest,
        "fields": applied,
    }


def _repair_normalize_ar_draft(value):
    mode = str(value or "off").strip().lower().replace("-", "_").replace(" ", "_")
    return {
        "sat": "sat_var",
        "satvar": "sat_var",
        "satvariable": "sat_var",
        "satfixed": "sat_fixed",
    }.get(mode, mode)


def _repair_validate_inference_request(repair_execution, key, value):
    """Validate a warm-server mutation before it reaches the reusable instance."""
    if not bool((repair_execution or {}).get("repair", False)):
        return value
    protected = (repair_execution or {}).get("fields") or {}
    if key in protected:
        requested = _repair_normalize_execution_value(key, value)
        if requested != protected[key]:
            raise RuntimeError(
                f"repair inference execution drift for {key}: requested "
                f"{requested!r}, checkpoint requires {protected[key]!r}")
    if key == "mode":
        mode = str(value or "").strip().lower()
        if mode not in {"ar", "sat", "nat"}:
            raise RuntimeError(f"repair inference mode {value!r} is invalid")
    if key == "ar_draft":
        draft = _repair_normalize_ar_draft(value)
        if draft == "sat_var":
            raise RuntimeError("repair inference forbids variable-SAT AR drafting")
        if draft not in {"off", "sat_fixed", "nat"}:
            raise RuntimeError(
                f"repair inference AR draft mode {value!r} is invalid")
    return value


def _repair_validate_inference_state_topology(checkpoint):
    """Bind repair serving to the reviewed full, tied, simple-head state layout."""
    if not isinstance(checkpoint, dict):
        raise RuntimeError("repair inference checkpoint is not a mapping")
    if bool(checkpoint.get("delta")):
        raise RuntimeError("repair inference requires a full checkpoint, not a delta")
    states = {}
    for name in ("core", "ar", "sat", "nat"):
        state = checkpoint.get(name)
        if not isinstance(state, dict) or not state:
            raise RuntimeError(f"repair full checkpoint is missing {name} state")
        states[name] = _strip_orig_mod_prefix(state)
    core = states["core"]
    if any(str(key).endswith("dblock_loop_embed.weight") for key in core):
        raise RuntimeError(
            "repair checkpoint loop embedding contradicts non-looped execution contract")
    sat_mlp = checkpoint.get("sat_head_mlp", False)
    if type(sat_mlp) is not bool:
        raise RuntimeError("repair checkpoint sat_head_mlp marker must be boolean")
    if sat_mlp or any(str(key).startswith("proj.2.") for key in states["sat"]):
        raise RuntimeError("repair checkpoint SAT MLP head is outside reviewed topology")
    expected_keys = {
        "ar": {"proj.weight"},
        "sat": {"proj.weight", "gate.weight", "gate.bias"},
        "nat": {"proj.weight"},
    }
    for name, expected in expected_keys.items():
        actual = set(states[name])
        if actual != expected:
            raise RuntimeError(
                f"repair checkpoint {name} head keys {sorted(actual)!r} "
                f"do not equal reviewed simple tied layout {sorted(expected)!r}")
    d = int(_REPAIR_PROTECTED_ARCHITECTURE["d"])
    vocab = int(_AGILLM43_REPAIR_VOCAB)
    expected_shapes = {
        ("core", "emb.weight"): (vocab, d),
        ("ar", "proj.weight"): (vocab, d),
        ("sat", "proj.weight"): (vocab, d),
        ("sat", "gate.weight"): (2, d),
        ("sat", "gate.bias"): (2,),
        ("nat", "proj.weight"): (vocab, d),
    }
    for (state_name, key), expected in expected_shapes.items():
        value = states[state_name].get(key)
        if not torch.is_tensor(value) or tuple(value.shape) != expected:
            shape = tuple(value.shape) if torch.is_tensor(value) else None
            raise RuntimeError(
                f"repair checkpoint {state_name}.{key} shape {shape!r} "
                f"does not equal reviewed shape {expected!r}")
    return {
        "schema": "agillm43.repair.inference-heads.v1",
        "full_checkpoint": True,
        "simple_tied_heads": True,
        "sat_head_mlp": False,
        "nat_head": True,
        "looped": False,
    }


def _repair_validate_tokenizer_payload(payload, *, context):
    if not isinstance(payload, dict):
        raise RuntimeError(f"{context} tokenizer payload is missing")
    payload_schema = payload.get("tokenizer_payload_schema")
    if type(payload_schema) is not int or payload_schema != 2:
        raise RuntimeError(f"{context} tokenizer payload schema is not 2")
    backend = payload.get("tokenizer_json")
    if not isinstance(backend, str) or not backend:
        raise RuntimeError(f"{context} tokenizer_json is missing")
    backend_sha = hashlib.sha256(backend.encode("utf-8")).hexdigest()
    if backend_sha != _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256:
        raise RuntimeError(f"{context} tokenizer backend checksum mismatch")
    if payload.get("tokenizer_id") != _AGILLM43_REPAIR_TOKENIZER_ID:
        raise RuntimeError(f"{context} tokenizer_id mismatch")
    special = payload.get("tokenizer_special")
    if not isinstance(special, dict):
        raise RuntimeError(f"{context} tokenizer special contract is missing")
    exact = {
        "vocab_size": _AGILLM43_REPAIR_VOCAB,
        "eos_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
        "pad_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
    }
    for name, expected in exact.items():
        value = special.get(name)
        if type(value) is not int or value != expected:
            raise RuntimeError(
                f"{context} tokenizer {name}={value!r} != {expected!r}")
    return backend


def _repair_validate_inference_tokenizer_checkpoint(checkpoint, checkpoint_path):
    """Validate env, receipt, embedded payload, and exact checkpoint sidecar."""
    import_receipt = _repair_import_tokenizer_receipt()
    receipt = checkpoint.get("repair_tokenizer_contract")
    if not isinstance(receipt, dict) or receipt.get("schema") != "agillm43.repair.tokenizer.v1":
        raise RuntimeError("repair inference tokenizer receipt is missing or incompatible")
    exact_receipt = {
        "tokenizer_id": _AGILLM43_REPAIR_TOKENIZER_ID,
        "seed_sidecar_sha256": _AGILLM43_REPAIR_TOKENIZER_SIDECAR_SHA256,
        "backend_sha256": _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256,
        "vocab_size": _AGILLM43_REPAIR_VOCAB,
        "eos_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
        "pad_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
        "nat_mask_token_id": _AGILLM43_REPAIR_NAT_MASK_ID,
    }
    for name, expected in exact_receipt.items():
        value = receipt.get(name)
        if type(expected) is int:
            valid = type(value) is int and value == expected
        else:
            valid = type(value) is str and value == expected
        if not valid:
            raise RuntimeError(
                f"repair inference tokenizer receipt {name}={value!r} != {expected!r}")
    contract = checkpoint.get("repair_contract")
    fields = contract.get("fields") if isinstance(contract, dict) else None
    if not isinstance(fields, dict):
        raise RuntimeError("repair inference tokenizer contract fields are missing")
    exact_contract = {
        "repair_tokenizer_sidecar_sha256": _AGILLM43_REPAIR_TOKENIZER_SIDECAR_SHA256,
        "repair_tokenizer_backend_sha256": _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256,
    }
    for name, expected in exact_contract.items():
        if fields.get(name) != expected:
            raise RuntimeError(
                f"repair inference contract {name} does not equal reviewed digest")
    embedded_backend = _repair_validate_tokenizer_payload(
        checkpoint, context="embedded checkpoint")
    path = pathlib.Path(checkpoint_path)
    sidecar_path = pathlib.Path(str(path) + ".tokenizer.json")
    if sidecar_path.is_symlink() or not sidecar_path.is_file():
        raise RuntimeError(
            f"repair inference exact tokenizer sidecar is missing or unsafe: {sidecar_path}")
    try:
        sidecar = json.loads(sidecar_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise RuntimeError(
            f"repair inference tokenizer sidecar cannot be parsed: {exc}") from exc
    sidecar_backend = _repair_validate_tokenizer_payload(
        sidecar, context="checkpoint sidecar")
    if sidecar.get("checkpoint_name") != path.name:
        raise RuntimeError("repair inference tokenizer sidecar checkpoint_name mismatch")
    declared_path = sidecar.get("checkpoint_path")
    if not isinstance(declared_path, str) or not declared_path:
        raise RuntimeError("repair inference tokenizer sidecar checkpoint_path is missing")
    if pathlib.Path(declared_path).expanduser().resolve() != path.expanduser().resolve():
        raise RuntimeError("repair inference tokenizer sidecar checkpoint_path mismatch")
    if embedded_backend != sidecar_backend:
        raise RuntimeError("repair inference embedded and sidecar tokenizers disagree")
    return {
        "schema": "agillm43.repair.inference-tokenizer.v1",
        "sidecar_path": str(sidecar_path.resolve()),
        "backend_sha256": _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256,
        "import_receipt": import_receipt,
    }


def _repair_strict_restore_inference_tokenizer(checkpoint, checkpoint_path):
    global _AGILLM_REPAIR_ACTIVE
    receipt = _repair_validate_inference_tokenizer_checkpoint(
        checkpoint, checkpoint_path)
    old_active = bool(_AGILLM_REPAIR_ACTIVE)
    try:
        _AGILLM_REPAIR_ACTIVE = True
        _restore_tokenizer_from_ckpt(checkpoint, checkpoint_path)
    finally:
        _AGILLM_REPAIR_ACTIVE = old_active
    return receipt


def _repair_validate_inference_tokenizer_runtime():
    try:
        backend = tok.backend_tokenizer.to_str()
        vocab = tok.get_vocab()
        runtime = {
            "backend_sha256": hashlib.sha256(backend.encode("utf-8")).hexdigest(),
            "vocab_size": max(vocab.values()) + 1,
            "vocab_entries": len(vocab),
            "pad_token_id": int(getattr(tok, "pad_token_id", -1)),
            "eos_token_id": int(getattr(tok, "eos_token_id", -1)),
            "nat_mask_token_id": int(vocab.get(NAT_MASK_RECOVERY_TOKEN, -1)),
            "active_nat_mask_token_id": int(NAT_MASK_ID),
            "global_vocab": int(VOCAB),
            "global_blank": int(BLANK),
            "global_eos": int(EOS) if EOS is not None else None,
        }
    except Exception as exc:
        raise RuntimeError(
            f"cannot inspect strict repair inference tokenizer runtime: {exc}") from exc
    expected = {
        "backend_sha256": _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256,
        "vocab_size": _AGILLM43_REPAIR_VOCAB,
        "vocab_entries": _AGILLM43_REPAIR_VOCAB,
        "pad_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
        "eos_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
        "nat_mask_token_id": _AGILLM43_REPAIR_NAT_MASK_ID,
        "active_nat_mask_token_id": _AGILLM43_REPAIR_NAT_MASK_ID,
        "global_vocab": _AGILLM43_REPAIR_VOCAB,
        "global_blank": _AGILLM43_REPAIR_EOS_PAD_ID,
        "global_eos": _AGILLM43_REPAIR_EOS_PAD_ID,
    }
    if runtime != expected:
        raise RuntimeError(
            f"repair inference tokenizer runtime mismatch: {runtime!r} != {expected!r}")
    return runtime


_AGILLM_REPAIR_ARCHITECTURE_SCHEMA = "agillm43.repair.architecture.v1"
_REPAIR_PROTECTED_ARCHITECTURE = {
    "d": 1280,
    "layers": 28,
    "heads": 20,
    "rank": 160,
    "tie_weights": True,
    "tie_kv": True,
    "moe_ffn": True,
    "moe_experts": 2,
    "moe_top_k": 1,
    "moe_mlp_mult": 4,
    "moe_shared_experts": 1,
    "moe_shared_mlp_mult": 2,
}
_REPAIR_ARCHITECTURE_CONTRACT_FIELDS = {
    "tie_weights": "tie_weights",
    "tie_kv": "tie_kv",
    "moe_ffn": "moe_ffn",
    "moe_experts": "moe_experts",
    "moe_top_k": "moe_top_k",
    "moe_mlp_mult": "moe_mlp_mult",
    "moe_shared_experts": "moe_shared_experts",
    "moe_shared_mlp_mult": "moe_shared_mlp_mult",
}


def _repair_normalize_architecture_fields(values, *, context):
    if not isinstance(values, dict):
        raise RuntimeError(f"{context} resolved architecture is not a mapping")
    normalized = {}
    for name, expected in _REPAIR_PROTECTED_ARCHITECTURE.items():
        if name not in values:
            raise RuntimeError(f"{context} resolved architecture is missing {name}")
        value = values[name]
        if isinstance(expected, bool):
            if type(value) is not bool:
                raise RuntimeError(
                    f"{context} resolved architecture {name} must be boolean")
        else:
            if type(value) is not int:
                raise RuntimeError(
                    f"{context} resolved architecture {name} must be an integer")
        if value != expected:
            raise RuntimeError(
                f"{context} resolved architecture {name}={value!r} "
                f"does not equal protected value {expected!r}")
        normalized[name] = value
    return normalized


def _repair_resolved_architecture_fields(cfg, tie_weights, *, context):
    if not isinstance(cfg, dict):
        raise RuntimeError(f"{context} checkpoint cfg is missing or not a mapping")
    values = {name: cfg.get(name) for name in _REPAIR_PROTECTED_ARCHITECTURE
              if name != "tie_weights"}
    values["tie_weights"] = tie_weights
    return _repair_normalize_architecture_fields(values, context=context)


def _repair_resolved_architecture_payload(fields):
    normalized = _repair_normalize_architecture_fields(
        fields, context="generated")
    return {
        "schema": _AGILLM_REPAIR_ARCHITECTURE_SCHEMA,
        "fields": _dblock_json_copy(normalized),
    }


def _repair_validate_architecture_contract(contract, contract_sha256,
                                           resolved_fields, *, context):
    if (not isinstance(contract, dict)
            or str(contract.get("schema") or "") != _AGILLM_REPAIR_CONTRACT_SCHEMA):
        raise RuntimeError(f"{context} repair contract schema is missing or incompatible")
    digest = str(contract_sha256 or "")
    if (not re.fullmatch(r"[0-9a-f]{64}", digest)
            or _repair_contract_sha256(contract) != digest):
        raise RuntimeError(f"{context} repair contract digest is missing or corrupt")
    fields = contract.get("fields")
    if not isinstance(fields, dict):
        raise RuntimeError(f"{context} repair contract fields are missing")
    endpoint_ints = {
        "steps": _AGILLM43_REPAIR_TARGET_COMMITS,
        "repair_target_commits": _AGILLM43_REPAIR_TARGET_COMMITS,
        "repair_target_step": _AGILLM43_REPAIR_TARGET_STEP,
        "repair_target_seen_tok": _AGILLM43_REPAIR_TARGET_SEEN_TOK,
    }
    for name, expected in endpoint_ints.items():
        value = fields.get(name)
        if type(value) is not int or value != expected:
            raise RuntimeError(
                f"{context} repair contract {name}={value!r} != {expected!r}"
            )
    if "target_tokens" not in fields or fields["target_tokens"] is not None:
        raise RuntimeError(
            f"{context} repair contract target_tokens must be explicitly null"
        )
    if type(fields.get("preset")) is not str or fields.get("preset") != "agillm4_floor":
        raise RuntimeError(f"{context} repair contract preset is not agillm4_floor")
    if "rank" not in fields:
        raise RuntimeError(f"{context} repair contract is missing rank")
    raw_rank = fields["rank"]
    if raw_rank is not None and (type(raw_rank) is not int or raw_rank != 160):
        raise RuntimeError(
            f"{context} repair contract rank must be omitted or exactly 160")
    if resolved_fields["rank"] != 160:
        raise RuntimeError(f"{context} resolved rank is not 160")
    for resolved_name, contract_name in _REPAIR_ARCHITECTURE_CONTRACT_FIELDS.items():
        if contract_name not in fields:
            raise RuntimeError(
                f"{context} repair contract is missing {contract_name}")
        expected = _REPAIR_PROTECTED_ARCHITECTURE[resolved_name]
        value = fields[contract_name]
        if isinstance(expected, bool):
            if type(value) is not bool:
                raise RuntimeError(
                    f"{context} repair contract {contract_name} must be boolean")
        else:
            if type(value) is not int:
                raise RuntimeError(
                    f"{context} repair contract {contract_name} must be an integer")
        if value != expected or value != resolved_fields[resolved_name]:
            raise RuntimeError(
                f"{context} repair contract {contract_name}={value!r} "
                f"disagrees with resolved topology {resolved_fields[resolved_name]!r}")
    return digest


def _repair_validate_resolved_architecture(
        cfg, tie_weights, *, contract, contract_sha256,
        receipt=None, receipt_sha256=None, require_receipt, context):
    resolved = _repair_resolved_architecture_fields(
        cfg, tie_weights, context=context)
    contract_digest = _repair_validate_architecture_contract(
        contract, contract_sha256, resolved, context=context)
    generated = _repair_resolved_architecture_payload(resolved)
    generated_sha = _repair_contract_sha256(generated)
    if require_receipt:
        if (not isinstance(receipt, dict)
                or str(receipt.get("schema") or "")
                != _AGILLM_REPAIR_ARCHITECTURE_SCHEMA):
            raise RuntimeError(
                f"{context} resolved architecture receipt is missing or incompatible")
        stored_sha = str(receipt_sha256 or "")
        if (not re.fullmatch(r"[0-9a-f]{64}", stored_sha)
                or _repair_contract_sha256(receipt) != stored_sha):
            raise RuntimeError(
                f"{context} resolved architecture receipt digest is missing or corrupt")
        stored_fields = _repair_normalize_architecture_fields(
            receipt.get("fields"), context=f"{context} receipt")
        if stored_fields != resolved or stored_sha != generated_sha:
            raise RuntimeError(
                f"{context} resolved architecture receipt disagrees with checkpoint cfg")
    return {
        "schema": _AGILLM_REPAIR_ARCHITECTURE_SCHEMA,
        "fields": resolved,
        "payload": generated,
        "sha256": generated_sha,
        "contract_sha256": contract_digest,
    }


def _repair_checkpoint_architecture_probe(path):
    p = _resolve_ckpt(pathlib.Path(path)) or pathlib.Path(path)
    if not p.is_file():
        raise RuntimeError(f"repair topology probe checkpoint is missing: {p}")
    ck = _agillm43_load_pt(
        p, map_location="cpu", weights_only=False,
        skip_keys={"core", "ar", "sat", "nat", "opt", "scaler", "weights",
                   *_DET50_STATE_KEYS},
    )
    try:
        if not isinstance(ck, dict):
            raise RuntimeError("repair topology probe payload is not a mapping")
        keys = (
            "cfg", "tie_weights", "step", "repair_schema",
            "repair_contract", "repair_contract_sha256",
            "repair_resolved_architecture",
            "repair_resolved_architecture_sha256",
        )
        return {name: _dblock_json_copy(ck.get(name)) for name in keys}
    finally:
        _agillm43_release_loaded_checkpoint(ck)


def _repair_checkpoint_metadata(args, checkpoint_step, seen_tok, dblock_state,
                                validation_state=None):
    if not bool(getattr(args, "repair_mode", False)):
        return {}
    checkpoint_step = _dblock_require_exact_int(
        checkpoint_step, "repair checkpoint step",
        minimum=_AGILLM43_REPAIR_BASE_STEP,
        maximum=_AGILLM43_REPAIR_TARGET_STEP,
    )
    if checkpoint_step < _AGILLM43_REPAIR_BASE_STEP:
        raise ValueError("repair checkpoint step precedes immutable recovery base")
    contract = _repair_contract_payload(args)
    base_seen_tok = _dblock_require_exact_int(
        getattr(args, "_repair_base_seen_tok", None),
        "repair checkpoint base seen tokens",
        minimum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
        maximum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
    )
    seen_tok = _dblock_require_exact_int(
        seen_tok, "repair checkpoint seen tokens", minimum=base_seen_tok
    )
    _repair_validate_token_clocks({
        "repair_base_seen_tok": base_seen_tok,
        "seen_tok": seen_tok,
        "lr_schedule_origin_tok": getattr(args, "_lr_schedule_origin_tok", None),
    }, checkpoint_step)
    validation_snapshot = _repair_validate_validation_state(
        validation_state, checkpoint_step, require_authoritative=True
    )
    dataset_contract = getattr(args, "_repair_dataset_contract", None)
    heldout_contract = getattr(args, "_repair_heldout_contract", None)
    tokenizer_contract = getattr(args, "_repair_tokenizer_contract", None)
    architecture = getattr(args, "_repair_resolved_architecture", None)
    architecture_sha = str(
        getattr(args, "_repair_resolved_architecture_sha256", "") or "")
    if not all(isinstance(item, dict) for item in (
            dataset_contract, heldout_contract, tokenizer_contract)):
        raise ValueError("repair checkpoint requires dataset/heldout/tokenizer receipts")
    if (not isinstance(architecture, dict)
            or architecture_sha != _repair_contract_sha256(architecture)):
        raise ValueError("repair checkpoint requires a valid resolved architecture receipt")
    return {
        "repair_lineage_schema": _AGILLM_REPAIR_LINEAGE_SCHEMA,
        "repair_base_step": _AGILLM43_REPAIR_BASE_STEP,
        "repair_seed_sha256": _AGILLM43_REPAIR_SEED_SHA256,
        "repair_base_seen_tok": base_seen_tok,
        "repair_target_commits": _AGILLM43_REPAIR_TARGET_COMMITS,
        "repair_target_step": _AGILLM43_REPAIR_TARGET_STEP,
        "repair_target_seen_tok": _AGILLM43_REPAIR_TARGET_SEEN_TOK,
        "repair_checkpoint_step": checkpoint_step,
        "repair_contract": contract,
        "repair_contract_sha256": _repair_contract_sha256(contract),
        "repair_dataset_contract": _dblock_json_copy(dataset_contract),
        "repair_heldout_contract": _dblock_json_copy(heldout_contract),
        "repair_tokenizer_contract": _dblock_json_copy(tokenizer_contract),
        "repair_resolved_architecture": _dblock_json_copy(architecture),
        "repair_resolved_architecture_sha256": architecture_sha,
        "dblock_resume_state": _dblock_resume_payload(dblock_state, checkpoint_step),
        "repair_validation_state": validation_snapshot,
    }


def _repair_preflight(args, *, stage="startup", loaded_step=None, val_batches=None,
                      loaded_meta=None):
    """Fail closed unless every recovery invariant is explicit and independently checkable."""
    if not bool(getattr(args, "repair_mode", False)):
        return {"enabled": False, "stage": str(stage)}

    errors = []
    errors.extend(_repair_execution_contract_errors(args))

    def _finite_arg(name, default=None):
        raw = getattr(args, name, default)
        try:
            value = float(raw)
        except (TypeError, ValueError):
            errors.append(f"--{name} must be finite, got {raw!r}")
            return None
        if not math.isfinite(value):
            errors.append(f"--{name} must be finite, got {raw!r}")
            return None
        return value

    stage_name = str(stage).strip().lower()
    resume_raw = str(getattr(args, "resume", "") or "").strip()
    expected_step_raw = getattr(args, "repair_expected_resume_step", None)
    if type(expected_step_raw) is not int:
        errors.append(
            "--repair_expected_resume_step must be an exact non-boolean integer"
        )
        expected_step = 0
    else:
        expected_step = expected_step_raw
    if bool(getattr(args, "fresh", False)):
        errors.append("--fresh is forbidden in repair mode")
    if not resume_raw:
        errors.append("repair mode requires an explicit --resume checkpoint")
    if getattr(args, "resume_delta", None):
        errors.append("--resume_delta is forbidden by the full-checkpoint repair preflight")
    if int(getattr(args, "delta_every_steps", 0) or 0) > 0 or float(
            getattr(args, "delta_every_sec", 0.0) or 0.0) > 0.0:
        errors.append("repair mode forbids weight-only delta checkpoints")
    if getattr(args, "warmstart_from", None):
        errors.append("--warmstart_from is forbidden; use the explicit full --resume checkpoint")
    if expected_step <= 0:
        errors.append("--repair_expected_resume_step must be explicitly positive")
    elif expected_step < _AGILLM43_REPAIR_BASE_STEP:
        errors.append(
            f"--repair_expected_resume_step {expected_step} precedes immutable recovery base "
            f"{_AGILLM43_REPAIR_BASE_STEP}"
        )
    elif expected_step > _AGILLM43_REPAIR_TARGET_STEP:
        errors.append(
            f"--repair_expected_resume_step {expected_step} exceeds immutable "
            f"repair endpoint {_AGILLM43_REPAIR_TARGET_STEP}"
        )
    seed_resume = expected_step == _AGILLM43_REPAIR_BASE_STEP
    if resume_raw:
        resume_path = pathlib.Path(resume_raw).expanduser()
        if not resume_path.is_file():
            errors.append(f"resume checkpoint is missing: {resume_path}")
        path_step = _repair_resume_step_from_path(resume_path)
        if path_step is None:
            errors.append(f"resume filename has no parseable step: {resume_path.name}")
        elif expected_step > 0 and path_step != expected_step:
            errors.append(f"resume filename step {path_step} != explicitly allowed step {expected_step}")
        if seed_resume and resume_path.is_file():
            try:
                seed_digest = _sha256_file(resume_path)
            except Exception as exc:
                errors.append(f"cannot hash immutable repair seed: {type(exc).__name__}: {exc}")
            else:
                if seed_digest != _AGILLM43_REPAIR_SEED_SHA256:
                    errors.append(
                        f"repair seed sha256 {seed_digest} != pinned "
                        f"{_AGILLM43_REPAIR_SEED_SHA256}"
                    )
        elif not seed_resume and resume_path.is_file():
            try:
                _repair_verify_manifest_sidecar(resume_path)
            except Exception as exc:
                errors.append(str(exc))
    else:
        resume_path = None
        path_step = None
    if loaded_step is not None and expected_step > 0 and int(loaded_step) != expected_step:
        errors.append(f"loaded checkpoint step {int(loaded_step)} != explicitly allowed step {expected_step}")

    reset_optimizer = bool(getattr(args, "reset_optimizer_on_resume", False))
    if seed_resume and not reset_optimizer:
        errors.append("immutable seed resume requires --reset_optimizer_on_resume")
    if expected_step > _AGILLM43_REPAIR_BASE_STEP and reset_optimizer:
        errors.append("child repair resume must preserve optimizer/scaler state")
    if str(getattr(args, "optimizer", "") or "").lower() != "adamw8bit":
        errors.append("--optimizer adamw8bit is required for the pinned 24GB repair path")
    weight_decay = _finite_arg("weight_decay")
    if weight_decay is not None and abs(weight_decay) > 1e-12:
        errors.append("--weight_decay must equal exactly 0.0 in strict repair")
    if not bool(getattr(args, "amp", False)):
        errors.append("--amp is required for the reviewed RTX3090 repair path")
    if bool(getattr(args, "compile", False)):
        errors.append("--compile is forbidden until exact eager repair promotion")
    lr_core = _finite_arg("lr_core")
    lr_head = _finite_arg("lr_head")
    if lr_core is not None and not (1e-6 <= lr_core <= 2e-4):
        errors.append("--lr_core must be in [1e-6, 2e-4]")
    if lr_head is not None and not (1e-6 <= lr_head <= 5e-4):
        errors.append("--lr_head must be in [1e-6, 5e-4]")
    if any(bool(getattr(args, key, False)) for key in (
            "freeze_core", "unfreeze_ln", "train_emb")):
        errors.append("strict repair requires the full core trainable without freeze overrides")
    if bool(getattr(args, "reinit_nat", False)):
        errors.append("--reinit_nat is forbidden: tied NAT projection aliases the shared embedding/head")
    if bool(getattr(args, "seed_nat_from_ar", False)):
        errors.append("--seed_nat_from_ar is forbidden after the versioned checkpoint load")
    if not bool(getattr(args, "lr_schedule_reset_on_resume", False)):
        errors.append("--lr_schedule_reset_on_resume is required")
    if str(getattr(args, "lr_decay", "none")) != "cosine":
        errors.append("--lr_decay cosine is required")
    horizon = float(getattr(args, "lr_decay_tokens", 0.0) or 0.0)
    warmup = float(getattr(args, "lr_warmup_tokens", 0.0) or 0.0)
    if not math.isfinite(horizon) or horizon <= 0:
        errors.append("--lr_decay_tokens must be a finite positive repair-local horizon")
    if not math.isfinite(warmup) or warmup <= 0:
        errors.append("--lr_warmup_tokens must be a finite positive repair-local warmup")
    if horizon > 0 and warmup >= horizon:
        errors.append("--lr_warmup_tokens must be smaller than --lr_decay_tokens")

    if str(getattr(args, "alibi_mode", "legacy")) != "corrected":
        errors.append("--alibi_mode corrected is required")
    alibi_scale = float(getattr(args, "alibi_scale", 1.0))
    if not math.isfinite(alibi_scale) or abs(alibi_scale) > 1e-12:
        errors.append("--alibi_scale must be exactly 0.0 for the initial repair contract")
    if not bool(getattr(args, "repair_fail_fast", False)):
        errors.append("--repair_fail_fast is required")
    if not bool(getattr(args, "dblock", False)):
        errors.append("--dblock is required for this DBlock-preserving repair")
    if not bool(getattr(args, "tie_weights", False)):
        errors.append("--tie_weights is required because the pinned recovery checkpoint uses tied biasless vocab projections")
    expected_arch = {
        "moe_experts": 2, "moe_top_k": 1, "moe_mlp_mult": 4,
        "moe_shared_experts": 1, "moe_shared_mlp_mult": 2,
    }
    if not bool(getattr(args, "tie_kv", False)) or not bool(getattr(args, "moe_ffn", False)):
        errors.append("strict repair requires the seed tie_kv+MoE architecture")
    for name, expected in expected_arch.items():
        if int(getattr(args, name, -1) or -1) != expected:
            errors.append(f"--{name} must equal seed value {expected}")
    moe_aux = _finite_arg("moe_aux_coef")
    moe_z = _finite_arg("moe_z_coef")
    if moe_aux is not None and abs(moe_aux - 0.01) > 1e-12:
        errors.append("--moe_aux_coef must equal 0.01 to revive/balance routed experts")
    if moe_z is not None and abs(moe_z - 0.001) > 1e-12:
        errors.append("--moe_z_coef must equal 0.001 for the reviewed router stabilizer")
    if str(getattr(args, "attn_backend", "") or "").lower() != "sdpa":
        errors.append("--attn_backend sdpa is required for the reviewed repair")
    if bool(getattr(args, "no_structured_masks", False)):
        errors.append("--no_structured_masks is forbidden in strict repair")
    if not bool(getattr(args, "grad_checkpoint", False)):
        errors.append("--grad_checkpoint is required")
    if bool(getattr(args, "auto_dblock_search", False)):
        errors.append("--auto_dblock_search is forbidden in deterministic repair")
    if bool(getattr(args, "dblock_looped", False)):
        errors.append("--dblock_looped is forbidden for the pinned 28-layer checkpoint")
    if str(getattr(args, "dblock_router", "heuristic") or "").lower() != "heuristic":
        errors.append("--dblock_router heuristic is required")
    router_blend = _finite_arg("dblock_router_blend")
    if router_blend is not None and abs(router_blend) > 1e-12:
        errors.append("--dblock_router_blend must equal reviewed value 0.0")
    reviewed_router_ints = {
        "dblock_router_ramp_steps": 64,
        "dblock_warmup_steps": 14,
        "dblock_log_every": 1,
    }
    for name, expected in reviewed_router_ints.items():
        raw = getattr(args, name, None)
        try:
            actual = int(raw)
        except (TypeError, ValueError):
            actual = None
        if isinstance(raw, bool) or actual != expected:
            errors.append(f"--{name} must equal reviewed value {expected}")
    if str(getattr(args, "dblock_sublayer_mode", "off") or "").lower() != "off":
        errors.append("--dblock_sublayer_mode off is required")
    if int(getattr(args, "dblock_checkpoint_stride", -1) or -1) != 1:
        errors.append("--dblock_checkpoint_stride must equal 1")
    if int(getattr(args, "dblock_checkpoint_skip_tail", -1) or 0) != 0:
        errors.append("--dblock_checkpoint_skip_tail must equal 0")
    if bool(getattr(args, "dblock_activation_offload", False)):
        errors.append("--dblock_activation_offload is forbidden in the reviewed path")
    if int(getattr(args, "dblock_blocks", 0) or 0) != 14:
        errors.append("--dblock_blocks must equal 14")
    if int(getattr(args, "async_update_every_steps", 0) or 0) != 0 or str(
            getattr(args, "async_update_dir", "") or "").strip():
        errors.append("asynchronous external weight updates are forbidden in strict repair")
    if bool(getattr(args, "auto_grow", False)):
        errors.append("--auto_grow is forbidden in strict repair")
    if bool(getattr(args, "oom_auto_backoff", True)):
        errors.append("--no-oom_auto_backoff is required so effective batch/block match the contract")
    if not _agillm43_is_sharded_codec(str(getattr(args, "ckpt_codec", "") or "")):
        errors.append("--ckpt_codec must be block-sharded so every tensor has a verified shard")
    if str(getattr(args, "dblock_schedule", "") or "").strip().lower() != "roundrobin":
        errors.append("--dblock_schedule roundrobin is required for deterministic committed-step band coverage")
    if str(getattr(args, "dblock_objective_mode", "") or "").strip().lower() != "committed_cycle":
        errors.append("--dblock_objective_mode committed_cycle is required for deterministic AR/SAT/NAT coverage")
    repair_probs = {
        name: _finite_arg(f"dblock_{name}_prob")
        for name in ("ar", "sat", "nat")
    }
    if all(value is not None for value in repair_probs.values()):
        if any(value <= 0.0 for value in repair_probs.values()):
            errors.append("committed-cycle AR/SAT/NAT availability probabilities must all be positive")
    repair_weights = {
        name: _finite_arg(f"dblock_{name}_weight")
        for name in ("ar", "sat", "nat")
    }
    nat_loss_weight = _finite_arg("nat_loss_weight")
    if any(value is not None and abs(value - 1.0) > 1e-12
           for value in repair_weights.values()):
        errors.append("local DBlock AR/SAT/NAT weights must each equal 1.0")
    if nat_loss_weight is not None and abs(nat_loss_weight - 1.0) > 1e-12:
        errors.append("--nat_loss_weight must equal 1.0")
    repair_caps = {
        "ar": int(getattr(args, "dblock_ar_loss_tokens", 0) or 0),
        "sat": int(getattr(args, "dblock_sat_loss_tokens", 0) or 0),
        "nat": int(getattr(args, "dblock_nat_loss_tokens", 0) or 0),
    }
    if repair_caps != {"ar": 4096, "sat": 2048, "nat": 2048}:
        errors.append("repair supervision caps must equal AR=4096, SAT=2048, NAT=2048")
    spike_skip = _finite_arg("loss_spike_skip")
    if spike_skip is not None and abs(spike_skip - 3.0) > 1e-12:
        errors.append("--loss_spike_skip must equal 3.0")
    if bool(getattr(args, "ar_only", False)) or bool(getattr(args, "no_nat_head", False)):
        errors.append("AR, fixed-SAT, and NAT heads must all remain enabled")
    if bool(getattr(args, "sft_completion_only", False)):
        errors.append("completion-only SFT is forbidden until base repair passes promotion gates")
    if int(getattr(args, "after_sft_steps", 0) or 0) > 0 or str(
            getattr(args, "after_sft_source", "") or "").strip():
        errors.append("post-pretraining SFT is forbidden during strict base repair")
    if int(getattr(args, "sat_every", 0) or 0) != 1 or int(getattr(args, "nat_every", 0) or 0) != 1:
        errors.append("--sat_every and --nat_every must both equal 1 for the committed objective cycle")
    if str(getattr(args, "dblock_nat_embed_noise_mode", "")).strip().lower() != "off":
        errors.append("--dblock_nat_embed_noise_mode off is required to match clean-mask serving")
    strict_exact = {
        "dblock_nat_embed_noise_scale": 1.0,
        "nat_mask_ratio": 0.5,
        "nat_span_mask_prob": 0.35,
        "nat_suffix_mask_prob": 0.20,
        "dblock_sigma_min": 0.002,
        "dblock_sigma_max": 80.0,
        "dblock_sigma_pmean": -1.2,
        "dblock_sigma_pstd": 1.2,
        "dblock_edm_wmax": 5.0,
    }
    for name, expected in strict_exact.items():
        value = _finite_arg(name)
        if value is not None and abs(value - expected) > 1e-12:
            errors.append(f"--{name} must equal reviewed value {expected}")
    if int(getattr(args, "nat_max_tokens", -1) or 0) != 0:
        errors.append("--nat_max_tokens must equal 0")
    if int(getattr(args, "nat_span_max_tokens", -1) or 0) != 0:
        errors.append("--nat_span_max_tokens must equal 0")
    if int(getattr(args, "dblock_sigma_curriculum_steps", -1) or -1) != 2000:
        errors.append("--dblock_sigma_curriculum_steps must equal 2000")
    if str(getattr(args, "dblock_sigma_sampling", "") or "").lower() != "lognormal":
        errors.append("--dblock_sigma_sampling lognormal is required")
    if not bool(getattr(args, "dblock_sigma_stratified", False)):
        errors.append("--dblock_sigma_stratified is required")
    if int(getattr(args, "dblock_fullstack_nat_mask_id", 0)) != -1:
        errors.append("--dblock_fullstack_nat_mask_id -1 must resolve the active ID2 contract")

    anchor_spike_skip = _finite_arg("dblock_fullstack_anchor_spike_skip")
    anchor_max_ce = _finite_arg("dblock_fullstack_anchor_max_ce")
    if anchor_spike_skip is not None and abs(anchor_spike_skip - 3.0) > 1e-12:
        errors.append("--dblock_fullstack_anchor_spike_skip must equal 3.0")
    if anchor_max_ce is not None and abs(anchor_max_ce - 50.0) > 1e-12:
        errors.append("--dblock_fullstack_anchor_max_ce must equal 50.0")
    errors.extend(_repair_nat_boundary_contract_errors(args))

    errors.extend(_repair_v14_anchor_contract_errors(args))
    # The success receipt may use the immutable profile because every launch
    # value above is exact-type/equality checked before a receipt can be emitted.
    anchor_contract = _dblock_json_copy(_REPAIR_V14_ANCHOR_PROFILE)

    nat_mask_id = None
    nat_mask_active = stage_name != "startup"
    migration_flag = bool(
        getattr(args, "migrate_nat_mask_embedding_from_legacy", False))
    if not nat_mask_active:
        # Startup validates the explicit ID2 plan before checkpoint metadata can
        # activate either the legacy seed or an already-versioned child.
        requested_mask_id = getattr(args, "nat_mask_token_id", None)
        if requested_mask_id is None:
            errors.append("--nat_mask_token_id 2 is required for repair")
        else:
            try:
                nat_mask_id = int(requested_mask_id)
            except (TypeError, ValueError):
                errors.append(f"invalid --nat_mask_token_id {requested_mask_id!r}")
            else:
                recovery_id = _nat_mask_recovery_token_id()
                if nat_mask_id != 2 or recovery_id != 2:
                    errors.append(
                        f"repair requires {NAT_MASK_RECOVERY_TOKEN}=id2; "
                        f"tokenizer reports {recovery_id!r}, requested {nat_mask_id}"
                    )
                if EOS is not None and nat_mask_id == int(EOS):
                    errors.append(
                        f"requested NAT mask id {nat_mask_id} collides with EOS={int(EOS)}"
                    )
    else:
        try:
            nat_mask_id = _repair_runtime_nat_mask_id(args, require=True)
        except Exception as exc:
            errors.append(str(exc))
    if seed_resume and not migration_flag:
        errors.append(
            "--migrate_nat_mask_embedding_from_legacy is required for the immutable seed")
    if expected_step > _AGILLM43_REPAIR_BASE_STEP and migration_flag:
        errors.append("child repair resume must not request legacy mask-row migration")

    if int(getattr(args, "val_tokens", 0) or 0) < 129:
        errors.append("--val_tokens must be at least 129")
    val_every = int(getattr(args, "val_every_sec", 0) or 0)
    if not (1 <= val_every <= 300):
        errors.append("--val_every_sec must be in [1, 300]")
    val_every_steps = int(getattr(args, "repair_val_every_steps", 0) or 0)
    if val_every_steps <= 0 or val_every_steps > 300:
        errors.append("--repair_val_every_steps must be in [1, 300] for committed-step smoke coverage")
    if int(getattr(args, "repair_val_contract_batches", 0) or 0) != 1:
        errors.append("--repair_val_contract_batches must equal 1")
    if int(getattr(args, "repair_val_contract_tokens", 0) or 0) != 128:
        errors.append("--repair_val_contract_tokens must equal 128")
    if int(getattr(args, "repair_val_sat_draft_cases", 0) or 0) != 1:
        errors.append("--repair_val_sat_draft_cases must equal 1")
    if int(getattr(args, "repair_val_sat_draft_context", 0) or 0) != 64:
        errors.append("--repair_val_sat_draft_context must equal 64")
    if int(getattr(args, "repair_val_nat_passes", 0) or 0) != 4:
        errors.append("--repair_val_nat_passes must equal 4 in strict repair")
    if int(getattr(args, "repair_val_nat_decode_cases", 0) or 0) != 1:
        errors.append("--repair_val_nat_decode_cases must equal 1")
    try:
        repair_suffixes = tuple(_repair_nat_suffixes(args))
    except Exception as exc:
        errors.append(str(exc))
        repair_suffixes = ()
    if repair_suffixes != (16, 32, 64):
        errors.append("--repair_val_nat_suffixes must equal 16,32,64")
    regression_ce = _finite_arg("repair_val_regression_ce")
    if regression_ce is not None and abs(regression_ce - 0.75) > 1e-12:
        errors.append("--repair_val_regression_ce must equal 0.75")
    if int(getattr(args, "repair_val_min_checks", 0) or 0) != 2:
        errors.append("--repair_val_min_checks must equal 2")
    if int(getattr(args, "repair_val_max_bad_checks", 0) or 0) != 1:
        errors.append("--repair_val_max_bad_checks must equal 1")
    val_receipt = None
    try:
        val_receipt = _repair_verify_val_file(args, require=True)
    except Exception as exc:
        errors.append(str(exc))
    if val_batches is not None and len(val_batches) <= 0:
        errors.append("frozen validation produced zero batches")

    dataset_receipt = None
    heldout_receipt = None
    tokenizer_receipt = None
    try:
        dataset_receipt = _repair_dataset_contract_receipt(args)
    except Exception as exc:
        errors.append(str(exc))
    try:
        heldout_receipt = _repair_heldout_contract_receipt(args, val_receipt)
    except Exception as exc:
        errors.append(str(exc))
    if resume_path is not None and resume_path.is_file():
        try:
            tokenizer_receipt = _repair_tokenizer_contract_receipt(
                args, resume_path,
                require_runtime=(stage_name != "startup"),
                seed_resume=seed_resume,
            )
        except Exception as exc:
            errors.append(str(exc))

    save_raw = str(getattr(args, "save_dir", "") or "").strip()
    root_raw = str(getattr(args, "repair_isolated_save_root", "") or "").strip()
    save_path = pathlib.Path(save_raw).expanduser() if save_raw else None
    root_path = pathlib.Path(root_raw).expanduser() if root_raw else None
    if save_path is None or not save_path.is_absolute():
        errors.append("--save_dir must be an absolute isolated path")
    if root_path is None or not root_path.is_absolute():
        errors.append("--repair_isolated_save_root must be an absolute path")
    if save_path is not None and root_path is not None and save_path.is_absolute() and root_path.is_absolute():
        save_resolved = save_path.resolve()
        root_resolved = root_path.resolve()
        try:
            relative = save_resolved.relative_to(root_resolved)
            if not relative.parts:
                errors.append("--save_dir must be a child of --repair_isolated_save_root, not the root itself")
        except ValueError:
            errors.append(f"--save_dir {save_resolved} is outside isolated root {root_resolved}")
        if resume_path is not None:
            resume_resolved = resume_path.resolve()
            if resume_resolved.parent == save_resolved or save_resolved in resume_resolved.parents:
                errors.append("--save_dir overlaps the immutable resume checkpoint location")
    else:
        save_resolved = save_path
        root_resolved = root_path

    try:
        contract_payload = _repair_contract_payload(args)
        contract_digest = _repair_contract_sha256(contract_payload)
    except Exception as exc:
        errors.append(f"repair contract is not finite/JSON-safe: {type(exc).__name__}: {exc}")
        contract_payload = {"schema": _AGILLM_REPAIR_CONTRACT_SCHEMA, "fields": {}}
        contract_digest = ""
    if stage_name != "startup" and expected_step == _AGILLM43_REPAIR_BASE_STEP:
        meta = loaded_meta if isinstance(loaded_meta, dict) else {}
        try:
            _dblock_require_exact_int(
                loaded_step, "loaded seed step",
                minimum=_AGILLM43_REPAIR_BASE_STEP,
                maximum=_AGILLM43_REPAIR_BASE_STEP,
            )
            _dblock_require_exact_int(
                meta.get("checkpoint_step"), "seed checkpoint step",
                minimum=_AGILLM43_REPAIR_BASE_STEP,
                maximum=_AGILLM43_REPAIR_BASE_STEP,
            )
            _dblock_require_exact_int(
                meta.get("checkpoint_seen_tok"), "seed checkpoint seen_tok",
                minimum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
                maximum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
            )
            _dblock_require_exact_int(
                getattr(args, "_repair_base_seen_tok", None),
                "seed immutable base seen_tok",
                minimum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
                maximum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
            )
            _dblock_require_exact_int(
                getattr(args, "_lr_schedule_origin_tok", None),
                "seed repair LR origin",
                minimum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
                maximum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
            )
        except Exception as exc:
            errors.append(f"seed checkpoint token clocks rejected: {exc}")
        try:
            _repair_validate_resolved_architecture(
                meta.get("cfg"), meta.get("tie_weights"),
                contract=contract_payload, contract_sha256=contract_digest,
                receipt=None, receipt_sha256=None, require_receipt=False,
                context="seed post-resume",
            )
        except Exception as exc:
            errors.append(f"seed checkpoint resolved architecture rejected: {exc}")
    if stage_name != "startup" and expected_step > _AGILLM43_REPAIR_BASE_STEP:
        meta = loaded_meta if isinstance(loaded_meta, dict) else {}
        if not meta:
            errors.append("child repair resume metadata was not supplied to preflight")
        if str(meta.get("repair_schema") or "") != _AGILLM_REPAIR_SCHEMA:
            errors.append("child checkpoint repair schema is missing or incompatible")
        if str(meta.get("repair_lineage_schema") or "") != _AGILLM_REPAIR_LINEAGE_SCHEMA:
            errors.append("child checkpoint repair lineage schema is missing or incompatible")
        try:
            _dblock_require_exact_int(
                loaded_step, "loaded child step",
                minimum=expected_step, maximum=expected_step,
            )
            _dblock_require_exact_int(
                meta.get("checkpoint_step"), "child checkpoint step",
                minimum=expected_step, maximum=expected_step,
            )
            _dblock_require_exact_int(
                meta.get("repair_base_step"), "child repair_base_step",
                minimum=_AGILLM43_REPAIR_BASE_STEP,
                maximum=_AGILLM43_REPAIR_BASE_STEP,
            )
            _dblock_require_exact_int(
                meta.get("repair_checkpoint_step"),
                "child repair_checkpoint_step",
                minimum=expected_step, maximum=expected_step,
            )
            _dblock_require_exact_int(
                meta.get("repair_target_commits"),
                "child repair_target_commits",
                minimum=_AGILLM43_REPAIR_TARGET_COMMITS,
                maximum=_AGILLM43_REPAIR_TARGET_COMMITS,
            )
            _dblock_require_exact_int(
                meta.get("repair_target_step"),
                "child repair_target_step",
                minimum=_AGILLM43_REPAIR_TARGET_STEP,
                maximum=_AGILLM43_REPAIR_TARGET_STEP,
            )
            _dblock_require_exact_int(
                meta.get("repair_target_seen_tok"),
                "child repair_target_seen_tok",
                minimum=_AGILLM43_REPAIR_TARGET_SEEN_TOK,
                maximum=_AGILLM43_REPAIR_TARGET_SEEN_TOK,
            )
        except Exception as exc:
            errors.append(f"child checkpoint integer clocks rejected: {exc}")
        if str(meta.get("repair_seed_sha256") or "") != _AGILLM43_REPAIR_SEED_SHA256:
            errors.append("child checkpoint immutable seed digest mismatch")
        stored_contract = meta.get("repair_contract")
        stored_digest = str(meta.get("repair_contract_sha256") or "")
        try:
            computed_stored_digest = _repair_contract_sha256(stored_contract)
        except Exception as exc:
            errors.append(f"child checkpoint repair contract is invalid: {exc}")
        else:
            if stored_digest != computed_stored_digest:
                errors.append("child checkpoint repair contract digest is corrupt")
            if stored_digest != contract_digest:
                errors.append("child checkpoint repair contract differs from launch")
        try:
            child_architecture = _repair_validate_resolved_architecture(
                meta.get("cfg"), meta.get("tie_weights"),
                contract=stored_contract, contract_sha256=stored_digest,
                receipt=meta.get("repair_resolved_architecture"),
                receipt_sha256=meta.get("repair_resolved_architecture_sha256"),
                require_receipt=True, context="child post-resume",
            )
            expected_arch_sha = str(
                getattr(args, "_repair_resolved_architecture_sha256", "") or "")
            if expected_arch_sha and child_architecture["sha256"] != expected_arch_sha:
                errors.append("child resolved architecture differs from pre-allocation topology")
        except Exception as exc:
            errors.append(f"child checkpoint resolved architecture rejected: {exc}")
        try:
            _repair_validate_token_clocks({
                "repair_base_seen_tok": meta.get("repair_base_seen_tok"),
                "seen_tok": meta.get("checkpoint_seen_tok"),
                "lr_schedule_origin_tok": meta.get("lr_schedule_origin_tok"),
            }, expected_step)
            _dblock_require_exact_int(
                getattr(args, "_repair_base_seen_tok", None),
                "runtime repair base seen_tok",
                minimum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
                maximum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
            )
            _dblock_require_exact_int(
                getattr(args, "_lr_schedule_origin_tok", None),
                "runtime repair LR origin",
                minimum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
                maximum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
            )
        except Exception as exc:
            errors.append(f"child checkpoint token clocks rejected: {exc}")
        if not bool(meta.get("optimizer_state_load_requested", False)):
            errors.append("child checkpoint optimizer/scaler load was not requested")
        if not bool(meta.get("optimizer_state_loaded", False)):
            errors.append("child checkpoint optimizer state did not load exactly")
        if not bool(meta.get("scaler_state_loaded", False)):
            errors.append("child checkpoint scaler state did not load exactly")
        try:
            _dblock_validate_resume_payload(
                meta.get("dblock_resume_state"), expected_step, args=args)
        except Exception as exc:
            errors.append(f"child checkpoint DBlock state rejected: {exc}")
        stored_dataset = meta.get("repair_dataset_contract")
        stored_heldout = meta.get("repair_heldout_contract")
        stored_tokenizer = meta.get("repair_tokenizer_contract")
        if (
            not isinstance(stored_dataset, dict)
            or stored_dataset != dataset_receipt
        ):
            errors.append(
                "child checkpoint dataset provenance receipt is missing "
                "or incompatible"
            )
        if not isinstance(stored_heldout, dict) or str(stored_heldout.get("token_ids_sha256") or "") != _AGILLM43_HELDOUT_TOKEN_IDS_SHA256 or str(stored_heldout.get("manifest_sha256") or "") != _AGILLM43_HELDOUT_MANIFEST_SHA256:
            errors.append("child checkpoint heldout-v2 provenance receipt is missing or incompatible")
        if not isinstance(stored_tokenizer, dict) or str(stored_tokenizer.get("seed_sidecar_sha256") or "") != _AGILLM43_REPAIR_TOKENIZER_SIDECAR_SHA256 or str(stored_tokenizer.get("backend_sha256") or "") != _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256:
            errors.append("child checkpoint tokenizer provenance receipt is missing or incompatible")
        try:
            _repair_validate_validation_state(
                meta.get("repair_validation_state"), expected_step,
                require_authoritative=True,
            )
        except Exception as exc:
            errors.append(f"child checkpoint validation state rejected: {exc}")

    if errors:
        try:
            _repair_write_fail(
                args,
                "repair_preflight_rejected",
                stage=str(stage),
                errors=list(errors),
                expected_resume_step=int(expected_step),
                loaded_step=None if loaded_step is None else int(loaded_step),
            )
        except Exception:
            pass
        raise RuntimeError("repair preflight rejected: " + "; ".join(errors))

    args._repair_dataset_contract = _dblock_json_copy(dataset_receipt)
    args._repair_heldout_contract = _dblock_json_copy(heldout_receipt)
    args._repair_tokenizer_contract = _dblock_json_copy(tokenizer_receipt)
    receipt = {
        "enabled": True,
        "stage": str(stage),
        "resume": str(pathlib.Path(resume_raw).resolve()),
        "resume_step": int(expected_step),
        "loaded_step": None if loaded_step is None else int(loaded_step),
        "seed_resume": bool(seed_resume),
        "repair_schema": _AGILLM_REPAIR_SCHEMA,
        "repair_contract_sha256": contract_digest,
        "repair_endpoint": _repair_endpoint_progress(
            expected_step,
            _repair_expected_seen_tok(expected_step),
        ),
        "save_dir": str(save_resolved),
        "isolated_root": str(root_resolved),
        "nat_mask_id": int(nat_mask_id),
        "nat_mask_active": bool(nat_mask_active),
        "fullstack_anchors": anchor_contract,
        "dataset_contract": dataset_receipt,
        "heldout_contract": heldout_receipt,
        "tokenizer_contract": tokenizer_receipt,
        "validation": {
            "path": val_receipt["path"],
            "sha256": val_receipt["sha256"],
            "tokens": int(val_receipt["tokens"]),
            "batches": None if val_batches is None else int(len(val_batches)),
        },
    }
    print("[repair-preflight] " + json.dumps(receipt, sort_keys=True), flush=True)
    return receipt


def _build_val_set(source, chat_cfg, args, block):
    """Load a checksum-pinned frozen set; legacy runs may still build-and-freeze once."""
    strict = bool(getattr(args, "repair_mode", False))
    path = _repair_val_path(args)
    expected = _repair_val_expected_sha256(args)
    try:
        receipt = _repair_verify_val_file(args, require=strict)
    except Exception as exc:
        if strict:
            raise
        if expected:
            print(
                f"[val] frozen telemetry file unavailable ({type(exc).__name__}: {exc}); "
                f"skipping heldout until restored",
                flush=True,
            )
            return []
        receipt = None
    if receipt is not None:
        frozen = receipt["frozen"]
        batches = [
            torch.tensor(frozen[i:i + block + 1], dtype=torch.long).unsqueeze(0)
            for i in range(0, len(frozen) - block, block + 1)
        ]
        if strict and not batches:
            raise RuntimeError(
                f"frozen validation file has {len(frozen)} tokens but block={block} needs at least {block + 1}"
            )
        print(
            f"[val] checksum-pinned FROZEN set loaded from {receipt['path']}: "
            f"sha256={receipt['sha256']} batches={len(batches)} block_tokens={block + 1}",
            flush=True,
        )
        return batches
    if strict:
        raise RuntimeError("repair validation must load an existing checksum-pinned frozen set")

    batches = _build_val_set_legacy(source, chat_cfg, args, block)
    if path is not None and batches and not path.exists():
        flat = []
        for batch in batches:
            flat.extend(int(x) for x in batch.reshape(-1).tolist())
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_name(path.name + f".tmp.{os.getpid()}")
        tmp.write_text(json.dumps(flat), encoding="utf-8")
        os.replace(tmp, path)
        print(f"[val] froze held-out set to {path}; sha256={_sha256_file(path)}", flush=True)
    return batches


def _repair_nat_suffixes(args):
    raw = str(getattr(args, "repair_val_nat_suffixes", "16,32,64") or "16,32,64")
    values = []
    for piece in raw.split(","):
        piece = piece.strip()
        if not piece:
            continue
        value = int(piece)
        if value <= 0 or value > 4096:
            raise ValueError(f"invalid NAT validation suffix length: {value}")
        if value not in values:
            values.append(value)
    if not values:
        raise ValueError("NAT validation suffix list is empty")
    return tuple(sorted(values))


def _repair_runtime_nat_mask_id(args, *, require=False):
    """Resolve the versioned runtime NAT mask; strict repair never falls back to legacy BLANK/EOS."""
    value = globals().get("NAT_MASK_ID", None)
    if value is None:
        if require or bool(getattr(args, "repair_mode", False)):
            raise RuntimeError("repair requires merged runtime NAT_MASK_ID metadata")
        value = BLANK
    try:
        value = int(value)
    except (TypeError, ValueError) as exc:
        raise RuntimeError(f"invalid runtime NAT_MASK_ID={value!r}") from exc
    if value < 0 or value >= int(VOCAB):
        raise RuntimeError(f"runtime NAT_MASK_ID={value} is outside vocab size {VOCAB}")
    if (require or bool(getattr(args, "repair_mode", False))) and EOS is not None and value == int(EOS):
        raise RuntimeError(
            f"runtime NAT_MASK_ID={value} collides with EOS={int(EOS)}; merge the versioned mask-token contract"
        )
    return value


def _run_validation(core, ar_h, val_batches, args, step, sat_h=None, nat_h=None):
    """Deterministic full-stack AR plus bounded fixed-SAT and clean-mask NAT contracts."""
    strict = bool(getattr(args, "repair_mode", False))
    setattr(args, "_repair_last_validation", None)
    if not val_batches:
        if strict:
            raise RuntimeError("repair validation failed closed: zero validation batches")
        return None
    if strict and (sat_h is None or nat_h is None):
        raise RuntimeError("repair validation requires both SAT and NAT heads")

    modules = [m for m in (core, ar_h, sat_h, nat_h) if m is not None]
    prior_modes = [bool(m.training) for m in modules]
    for module in modules:
        module.eval()

    result = None
    try:
        tot_ce, tot_tok = 0.0, 0
        max_contract_batches = max(1, int(getattr(args, "repair_val_contract_batches", 1) or 1))
        max_contract_tokens = max(66, min(4096, int(getattr(args, "repair_val_contract_tokens", 128) or 128)))
        contract_batches = []

        with torch.no_grad():
            for index, ids_cpu in enumerate(val_batches):
                ids = ids_cpu.to(DEV)
                if ids.size(1) < 2:
                    continue
                with amp(args.amp):
                    h = core(ids, causal_mask(ids.size(1), structured=use_structured_masks(args)))
                    ar_ce = fused_ce(h[:, :-1], ar_h.proj.weight, ids[:, 1:])
                ntok = int(ids.numel() - ids.size(0))
                tot_ce += float(ar_ce.detach()) * ntok
                tot_tok += ntok
                if index < max_contract_batches:
                    contract_batches.append(ids[:, :max_contract_tokens].detach())
                del h, ar_ce, ids

            if tot_tok <= 0:
                raise RuntimeError("validation contained zero AR target tokens")
            ce = tot_ce / tot_tok
            ppl = math.exp(min(20.0, ce))
            contracts = {}

            if sat_h is not None:
                sat_loss_sum = 0.0
                sat_tokens = 0
                sat_correct = 0
                slot_correct = [0, 0]
                slot_tokens = [0, 0]
                block_correct = 0
                block_total = 0
                for ids in contract_batches:
                    if ids.size(1) <= 2:
                        continue
                    with amp(args.amp):
                        h_sat = core(ids, sat_mask(ids.size(1), block=2, structured=use_structured_masks(args)))
                        sat_ctx = h_sat[:, :-2]
                        target = ids[:, 2:]
                        logits = sat_h.proj(sat_ctx).float()
                    flat_logits = logits.reshape(-1, logits.size(-1))
                    flat_target = target.reshape(-1)
                    sat_loss_sum += float(F.cross_entropy(flat_logits, flat_target, reduction="sum"))
                    pred = _decode_guard_logits(logits).argmax(-1)
                    correct = pred.eq(target)
                    sat_tokens += int(target.numel())
                    sat_correct += int(correct.sum())
                    positions = torch.arange(2, ids.size(1), device=ids.device)
                    for slot in (0, 1):
                        smask = positions.remainder(2).eq(slot)
                        slot_tokens[slot] += int(smask.sum()) * int(ids.size(0))
                        slot_correct[slot] += int(correct[:, smask].sum())
                    usable = (correct.size(1) // 2) * 2
                    if usable:
                        pairs = correct[:, :usable].reshape(correct.size(0), -1, 2)
                        block_correct += int(pairs.all(-1).sum())
                        block_total += int(pairs.numel() // 2)
                    del h_sat, sat_ctx, target, logits, flat_logits, flat_target, pred, correct
                if sat_tokens <= 0 or min(slot_tokens) <= 0 or block_total <= 0:
                    raise RuntimeError("fixed-SAT validation produced incomplete shift-2 metrics")
                contracts.update({
                    "sat_shift2_ce": sat_loss_sum / sat_tokens,
                    "sat_shift2_top1": sat_correct / sat_tokens,
                    "sat_shift2_slot0_top1": slot_correct[0] / slot_tokens[0],
                    "sat_shift2_slot1_top1": slot_correct[1] / slot_tokens[1],
                    "sat_shift2_block_exact": block_correct / block_total,
                    "sat_shift2_tokens": int(sat_tokens),
                    "sat_shift2_blocks": int(block_total),
                })

                draft_cases = min(
                    len(contract_batches),
                    max(1, int(getattr(args, "repair_val_sat_draft_cases", 1) or 1)),
                )
                draft_tokens = 0
                draft_correct = 0
                draft_blocks = 0
                for ids in contract_batches[:draft_cases]:
                    context_cap = max(2, int(getattr(args, "repair_val_sat_draft_context", 64) or 64))
                    context_len = min(int(ids.size(1)) - 2, context_cap)
                    context_len -= context_len % 2
                    if context_len < 2:
                        continue
                    prefix = ids[:, :context_len]
                    with amp(args.amp):
                        h_sat = core(prefix, sat_mask(prefix.size(1), block=2, structured=use_structured_masks(args)))
                        sat_draft = _decode_guard_logits(sat_h.proj(h_sat[:, -2:]).float()).argmax(-1)
                    ar_work = prefix.clone()
                    ar_tokens = []
                    for _ in range(2):
                        with amp(args.amp):
                            h_ar = core(
                                ar_work,
                                causal_mask(ar_work.size(1), structured=use_structured_masks(args)),
                            )
                            nxt = _decode_guard_logits(ar_h(h_ar[:, -1:]).float()).argmax(-1)
                        ar_tokens.append(nxt)
                        ar_work = torch.cat([ar_work, nxt], dim=1)
                    ar_greedy = torch.cat(ar_tokens, dim=1)
                    agree = sat_draft.eq(ar_greedy)
                    draft_tokens += int(agree.numel())
                    draft_correct += int(agree.sum())
                    draft_blocks += int(agree.all(-1).sum())
                    del prefix, h_sat, sat_draft, ar_work, ar_tokens, ar_greedy, agree
                if draft_tokens <= 0:
                    raise RuntimeError("SAT draft agreement produced zero comparison tokens")
                contracts.update({
                    "sat_draft_vs_sequential_ar_top1": draft_correct / draft_tokens,
                    "sat_draft_vs_sequential_ar_block_exact": draft_blocks / (draft_tokens // 2),
                    "sat_draft_vs_sequential_ar_tokens": int(draft_tokens),
                })

            if nat_h is not None:
                nat_mask_id = _repair_runtime_nat_mask_id(args, require=strict)
                suffixes = _repair_nat_suffixes(args)
                nat_stats = {
                    span: {"loss": 0.0, "tokens": 0, "correct": 0, "exact": 0, "examples": 0}
                    for span in suffixes
                }
                for ids in contract_batches:
                    for span in suffixes:
                        if ids.size(1) <= span:
                            continue
                        work = ids.clone()
                        work[:, -span:] = nat_mask_id
                        with amp(args.amp):
                            h_nat = core(work, None)
                            logits = nat_h(h_nat[:, -span:]).float()
                        target = ids[:, -span:]
                        pred = _decode_guard_logits(logits).argmax(-1)
                        stat = nat_stats[span]
                        stat["loss"] += float(
                            F.cross_entropy(
                                logits.reshape(-1, logits.size(-1)),
                                target.reshape(-1),
                                reduction="sum",
                            )
                        )
                        stat["tokens"] += int(target.numel())
                        stat["correct"] += int(pred.eq(target).sum())
                        stat["exact"] += int(pred.eq(target).all(-1).sum())
                        stat["examples"] += int(target.size(0))
                        del work, h_nat, logits, target, pred
                nat_clean_loss = 0.0
                nat_clean_tokens = 0
                for span, stat in nat_stats.items():
                    if stat["tokens"] <= 0 or stat["examples"] <= 0:
                        raise RuntimeError(f"NAT suffix-{span} validation produced zero targets")
                    contracts.update({
                        f"nat_suffix{span}_ce": stat["loss"] / stat["tokens"],
                        f"nat_suffix{span}_top1": stat["correct"] / stat["tokens"],
                        f"nat_suffix{span}_exact": stat["exact"] / stat["examples"],
                        f"nat_suffix{span}_tokens": int(stat["tokens"]),
                    })
                    nat_clean_loss += float(stat["loss"])
                    nat_clean_tokens += int(stat["tokens"])
                contracts["nat_clean_suffix_ce"] = nat_clean_loss / nat_clean_tokens
                contracts["nat_mask_id"] = int(nat_mask_id)

                neutral_passes = max(0, min(8, int(getattr(args, "repair_val_nat_passes", 4) or 0)))
                decode_cases = min(
                    len(contract_batches),
                    max(0, int(getattr(args, "repair_val_nat_decode_cases", 1) or 0)),
                )
                if neutral_passes > 0 and decode_cases > 0:
                    span = max(suffixes)
                    decode_tokens = 0
                    decode_correct = 0
                    decode_exact = 0
                    decode_examples = 0
                    actual_forwards = 0
                    for ids in contract_batches[:decode_cases]:
                        if ids.size(1) <= span:
                            continue
                        target = ids[:, -span:]
                        work = ids.clone()
                        work[:, -span:] = nat_mask_id
                        remaining = set(range(int(ids.size(1)) - span, int(ids.size(1))))
                        for pass_index in range(neutral_passes):
                            if not remaining:
                                break
                            with amp(args.amp):
                                h_nat = core(work, None)
                                logits = nat_h(h_nat).float()
                            actual_forwards += 1
                            if 0 <= nat_mask_id < logits.size(-1):
                                logits[..., nat_mask_id] = -1e9
                            confidence = logits.softmax(-1).amax(-1)
                            need = max(1, -(-len(remaining) // (neutral_passes - pass_index)))
                            ordered = sorted(
                                remaining,
                                key=lambda pos: (-float(confidence[0, pos]), int(pos)),
                            )[:need]
                            for pos in ordered:
                                work[:, pos] = _decode_guard_logits(logits[:, pos]).argmax(-1)
                                remaining.discard(pos)
                            del h_nat, logits, confidence
                        if remaining:
                            raise RuntimeError(
                                f"neutral NAT {neutral_passes}-pass validation left {len(remaining)} positions unfilled"
                            )
                        decoded = work[:, -span:]
                        eq = decoded.eq(target)
                        decode_tokens += int(eq.numel())
                        decode_correct += int(eq.sum())
                        decode_exact += int(eq.all(-1).sum())
                        decode_examples += int(eq.size(0))
                        del target, work, decoded, eq
                    if decode_tokens <= 0:
                        raise RuntimeError("neutral NAT iterative validation produced zero targets")
                    contracts.update({
                        "nat_neutral_passes": int(neutral_passes),
                        "nat_neutral_span": int(span),
                        "nat_neutral_top1": decode_correct / decode_tokens,
                        "nat_neutral_exact": decode_exact / decode_examples,
                        "nat_neutral_tokens": int(decode_tokens),
                        "nat_neutral_forwards": int(actual_forwards),
                    })

            required = (
                "sat_shift2_ce",
                "sat_shift2_top1",
                "sat_shift2_slot0_top1",
                "sat_shift2_slot1_top1",
                "sat_shift2_block_exact",
                "sat_draft_vs_sequential_ar_top1",
                "nat_suffix16_ce",
                "nat_suffix16_top1",
                "nat_suffix16_exact",
                "nat_suffix32_ce",
                "nat_suffix32_top1",
                "nat_suffix32_exact",
                "nat_suffix64_ce",
                "nat_suffix64_top1",
                "nat_suffix64_exact",
                "nat_clean_suffix_ce",
                "nat_neutral_passes",
                "nat_neutral_span",
                "nat_neutral_top1",
                "nat_neutral_exact",
                "nat_neutral_tokens",
                "nat_neutral_forwards",
            )
            if strict:
                missing = [key for key in required if key not in contracts]
                if missing:
                    raise RuntimeError("repair validation missing contract metrics: " + ", ".join(missing))
                if int(contracts.get("nat_neutral_passes", 0)) != 4:
                    raise RuntimeError("repair validation NAT neutral pass count drifted")
                if int(contracts.get("nat_neutral_span", 0)) != 64:
                    raise RuntimeError("repair validation NAT neutral span must equal 64")
                if int(contracts.get("nat_neutral_tokens", 0)) <= 0 or int(
                        contracts.get("nat_neutral_forwards", 0)) <= 0:
                    raise RuntimeError("repair validation NAT iterative gate produced no work")
            for key, value in contracts.items():
                if isinstance(value, float) and not math.isfinite(value):
                    raise RuntimeError(f"non-finite validation metric {key}={value}")

            ce_families = {
                "ar": float(ce),
                "sat": contracts.get("sat_shift2_ce"),
                "nat": contracts.get("nat_clean_suffix_ce"),
            }
            setattr(args, "_repair_last_validation", ce_families)
            science_validation = None
            try:
                science_validation = _training_science_on_validation(args, ce, step)
            except Exception as exc:
                print(f"[training-science] validation accounting warning: {exc}", flush=True)

            print(
                f"[val] step={step} tokens={tot_tok} ce={ce:.4f} ppl={ppl:.2f} "
                + json.dumps(contracts, sort_keys=True, separators=(",", ":")),
                flush=True,
            )
            metrics_path = pathlib.Path(getattr(args, "save_dir", "/workspace")) / "repair_metrics.jsonl"
            metrics_path.parent.mkdir(parents=True, exist_ok=True)
            record = {
                "schema": "agillm43.repair.metrics.v3",
                "kind": "fullstack_ar_validation",
                "run_id": str(os.environ.get("AGILLM_RUN_ID", "") or ""),
                "parent_pointer_sha256": str(
                    os.environ.get("AGILLM_PARENT_POINTER_SHA256", "") or ""
                ),
                "utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                "step": int(step),
                "tokens": int(tot_tok),
                "ce": float(ce),
                "ce_families": ce_families,
                "ppl": float(ppl),
                "contracts": contracts,
                "frozen_val_path": str(_repair_val_path(args) or ""),
                "frozen_val_sha256": _repair_val_expected_sha256(args),
                "training_science_validation": science_validation,
                "training_science": _training_science_snapshot(args),
            }
            with metrics_path.open("a", encoding="utf-8") as handle:
                handle.write(json.dumps(record, sort_keys=True) + "\n")
            result = float(ce)
    except Exception as exc:
        message = f"[val] eval error ({type(exc).__name__}: {exc})"
        if strict:
            raise RuntimeError("repair validation failed closed: " + message) from exc
        print(message + "; skipping this round", flush=True)
        result = None
    finally:
        for module, mode in zip(modules, prior_modes):
            module.train(mode)
        if DEV.type == "cuda" and bool(
                getattr(args, "empty_cache_after_validation", False)):
            try:
                reserved_before = torch.cuda.memory_reserved()
                torch.cuda.empty_cache()
                reserved_after = torch.cuda.memory_reserved()
                print(
                    "[vram] validation cache reclaimed "
                    f"reserved={reserved_before / (1024**3):.2f}GB"
                    f"->{reserved_after / (1024**3):.2f}GB",
                    flush=True,
                )
            except Exception as exc:
                print(f"[vram] validation cache reclaim warning: {exc}", flush=True)
    return result


def _repair_update_validation(args, state, ce, step):
    if ce is None:
        if bool(getattr(args, "repair_mode", False)):
            return f"validation unavailable at step {step}"
        return None

    raw_families = getattr(args, "_repair_last_validation", None)
    if isinstance(raw_families, dict):
        values = {
            "ar": raw_families.get("ar", ce),
            "sat": raw_families.get("sat"),
            "nat": raw_families.get("nat"),
        }
    else:
        values = {"ar": ce}
    if bool(getattr(args, "repair_mode", False)):
        missing = [name for name in ("ar", "sat", "nat") if values.get(name) is None]
        if missing:
            return "validation families unavailable at step {}: {}".format(step, ", ".join(missing))
    for name, value in values.items():
        if value is None:
            continue
        if not math.isfinite(float(value)):
            return f"non-finite {name} validation CE at step {step}: {value}"

    checks = int(state.get("checks", 0)) + 1
    state["checks"] = checks
    threshold = max(0.0, float(getattr(args, "repair_val_regression_ce", 0.75) or 0.75))
    min_checks = max(1, int(getattr(args, "repair_val_min_checks", 2) or 2))
    max_bad = max(1, int(getattr(args, "repair_val_max_bad_checks", 1) or 1))
    families = state.setdefault("families", {})
    regressions = []
    for name in ("ar", "sat", "nat"):
        value = values.get(name)
        if value is None:
            continue
        value = float(value)
        family = families.setdefault(
            name,
            {"baseline": None, "best": None, "last": None, "checks": 0, "bad_checks": 0},
        )
        family["checks"] = int(family.get("checks", 0)) + 1
        if family.get("baseline") is None:
            family["baseline"] = value
            family["best"] = value
            family["last"] = value
            family["bad_checks"] = 0
            print(
                f"[repair-gate] {name} validation baseline ce={value:.4f} step={step}",
                flush=True,
            )
            continue
        family["last"] = value
        family["best"] = min(float(family.get("best", value)), value)
        reference = min(float(family.get("baseline", value)), float(family["best"]))
        if value > reference + threshold:
            family["bad_checks"] = int(family.get("bad_checks", 0)) + 1
        else:
            family["bad_checks"] = 0
        if checks >= min_checks and int(family["bad_checks"]) >= max_bad:
            regressions.append(
                f"{name}:ce={value:.4f} reference={reference:.4f} "
                f"threshold={threshold:.4f} bad_checks={family['bad_checks']}"
            )

    ar_state = families.get("ar", {})
    for key in ("baseline", "best", "last", "bad_checks"):
        state[key] = ar_state.get(key)
    state["last_family_values"] = {
        name: float(value) for name, value in values.items() if value is not None
    }
    if regressions:
        return "validation regression: " + "; ".join(regressions)
    return None


def _load_module_state_compatible(module: nn.Module, state: dict, label: str = "module") -> int:
    """Load matching tensors only; skip obsolete untied vocab matrices for tied heads."""
    if not isinstance(state, dict):
        return 0
    state = _strip_orig_mod_prefix(state)
    tgt_sd = module.state_dict()
    tied = bool(getattr(module, "tie_weights", False))
    filt = {}
    skipped = []
    for k, v in state.items():
        if tied and k == "proj.weight":
            skipped.append(k)
            continue
        if k in tgt_sd and hasattr(v, "shape") and v.shape == tgt_sd[k].shape:
            filt[k] = v
        else:
            skipped.append(k)
    if filt:
        module.load_state_dict(filt, strict=False)
    if tied and skipped:
        print(f"[ckpt] {label}: tied head active; skipped old untied tensors: {', '.join(skipped[:4])}{'...' if len(skipped)>4 else ''}")
    return len(filt)


class _skip_param_init:
    """Suppress torch.nn.init.* tensor fills while constructing inference models.

    Every parameter is overwritten from the checkpoint immediately after
    construction, so constructor random init is pure startup cost. Params the
    checkpoint cannot supply are re-initialized afterwards.
    """
    _FILLS = (
        "uniform_", "normal_", "trunc_normal_", "constant_", "ones_", "zeros_",
        "eye_", "dirac_", "xavier_uniform_", "xavier_normal_",
        "kaiming_uniform_", "kaiming_normal_", "orthogonal_", "sparse_",
    )

    def __enter__(self):
        import torch.nn.init as _init
        self._saved = {}
        for name in self._FILLS:
            fn = getattr(_init, name, None)
            if fn is None:
                continue
            self._saved[name] = fn

            def _noop(tensor, *args, **kwargs):
                return tensor

            setattr(_init, name, _noop)
        return self

    def __exit__(self, *exc):
        import torch.nn.init as _init
        for name, fn in self._saved.items():
            setattr(_init, name, fn)
        return False


def _reinit_params_missing_from_state(core: nn.Module, sd_core: dict):
    if not isinstance(sd_core, dict):
        return
    present = set(_strip_orig_mod_prefix(sd_core).keys())
    missing_mods = {}
    for name, _ in core.named_parameters():
        if name in present:
            continue
        mod_name = name.rsplit(".", 1)[0] if "." in name else ""
        missing_mods.setdefault(mod_name, name)
    reinit = 0
    for mod_name, param_name in missing_mods.items():
        try:
            mod = core.get_submodule(mod_name) if mod_name else core
        except AttributeError:
            mod = None
        if mod is not None and hasattr(mod, "reset_parameters"):
            mod.reset_parameters()
            reinit += 1
        else:
            print(f"[infer] WARNING: param {param_name} absent from checkpoint and module has no reset_parameters; it may be uninitialized", flush=True)
    if reinit:
        print(f"[infer] reinitialized {reinit} module(s) for checkpoint-missing parameters", flush=True)

def load_delta(path: pathlib.Path, core, ar_h, sat_h, nat_h=None, *,
               nat_mask_token_id=None,
               migrate_nat_mask_embedding=False):
    """Load weight-only delta. Returns (step, seen_tok) or raises."""
    # Verify checksum if sidecar exists
    sha_path = path.with_suffix(".sha256")
    if sha_path.exists():
        expected = sha_path.read_text().split()[0]
        actual = _sha256_file(path)
        if expected != actual:
            raise ValueError(f"Checksum mismatch for {path.name}: expected {expected[:12]}... got {actual[:12]}...")
        print(f"  [delta] checksum OK for {path.name}")
    ck = _agillm43_load_pt(path, map_location="cpu", weights_only=False)
    if not ck.get("delta"):
        raise ValueError(f"{path.name} is not a delta checkpoint")
    core.load_state_dict(_prepare_core_state_dict_for_load(core, ck["weights"]["core"]))
    _load_module_state_compatible(ar_h, ck["weights"].get("ar", {}), "ar")
    _load_module_state_compatible(sat_h, ck["weights"].get("sat", {}), "sat")
    if nat_h is not None:
        nat_sd = ck["weights"].get("nat")
        if nat_sd is not None:
            _load_module_state_compatible(nat_h, nat_sd, "nat")
        else:
            print("[nat] Delta has no NAT head; keeping fresh NAT initialization")
    _restore_tokenizer_from_ckpt(ck, path)
    _contract, _migration = _configure_nat_mask_contract(
        ck,
        explicit_id=nat_mask_token_id,
        optimizer_reset=True,
        migration_requested=bool(migrate_nat_mask_embedding),
    )
    if _migration is not None:
        _migrate_nat_mask_embedding_row(core, *_migration)
    print(
        f"[nat-mask] schema={_contract['schema_version']} "
        f"id={_contract['token_id']} source={_contract['source']}",
        flush=True,
    )
    step = ck.get("step", 0)
    seen_tok = ck.get("seen_tok", 0)
    _agillm43_release_loaded_checkpoint(ck)
    return step, seen_tok

def _flush_delta():
    """Wait for any in-flight delta save to complete."""
    global _delta_thread
    if _delta_thread is not None and _delta_thread.is_alive():
        print("  [delta] flushing in-flight write...")
        _delta_thread.join(timeout=120)

_AGILLM43_ON_DEMAND_CKPT_NONCE = 0


def _repair_unique_on_demand_checkpoint_name(
    phase_name, step, origin_tag="", role_tag=""
):
    global _AGILLM43_ON_DEMAND_CKPT_NONCE
    _AGILLM43_ON_DEMAND_CKPT_NONCE += 1
    stamp = time.strftime("_%Y%m%dT%H%M%S", time.gmtime())
    return (
        f"{phase_name}_step{int(step):08d}{origin_tag}{stamp}"
        f"_{time.time_ns()}_{os.getpid()}_"
        f"{_AGILLM43_ON_DEMAND_CKPT_NONCE:06d}{role_tag}.pt"
    )


def _repair_service_on_demand_flush_request(
    flush_flag, terminate_after_flush, sentinel, args, step, action
):
    sentinel = pathlib.Path(sentinel)
    requested = bool(flush_flag[0]) or sentinel.exists()
    if not requested:
        return {
            "serviced": False,
            "terminate": bool(terminate_after_flush[0]),
            "result": None,
        }
    try:
        result = action()
    except Exception as exc:
        flush_flag[0] = True
        try:
            sentinel.parent.mkdir(parents=True, exist_ok=True)
            sentinel.touch(exist_ok=True)
        except Exception:
            pass
        _repair_write_fail(
            args, "on_demand_flush_failed",
            step=int(step),
            terminate_after_flush=bool(terminate_after_flush[0]),
            error_type=type(exc).__name__,
            message=str(exc)[:1200],
        )
        raise
    flush_flag[0] = False
    try:
        sentinel.unlink()
    except FileNotFoundError:
        pass
    return {
        "serviced": True,
        "terminate": bool(terminate_after_flush[0]),
        "result": result,
    }


def _repair_pointer_block_reason(meta, checkpoint_step):
    if not _AGILLM_REPAIR_ACTIVE:
        return None
    try:
        step = _dblock_require_exact_int(
            checkpoint_step, "pointer checkpoint_step",
            minimum=_AGILLM43_REPAIR_BASE_STEP,
            maximum=_AGILLM43_REPAIR_TARGET_STEP,
        )
        contract = meta.get("repair_contract")
        if not isinstance(contract, dict) or not isinstance(
                contract.get("fields"), dict):
            return "missing repair contract fields"
        required = _dblock_require_exact_int(
            contract["fields"].get("repair_val_min_checks"),
            "repair contract validation min_checks", minimum=2,
        )
        validation = _repair_validate_validation_state(
            meta.get("repair_validation_state"), step,
            require_authoritative=True,
        )
        checks = _dblock_require_exact_int(
            validation.get("checks"), "pointer validation checks", minimum=0,
        )
    except Exception as exc:
        return f"invalid repair validation state: {type(exc).__name__}: {exc}"
    if checks < required:
        return f"validation checks {checks} < required {required}"
    return None


def _write_quarantine_pointer(path, meta, latest_payload, reason):
    payload = {
        "schema": "agillm43.repair.quarantine.v1",
        "path": str(path),
        "step": int(meta.get("step", 0) or 0),
        "reason": str(reason),
        "training_latest_promoted": False,
        "latest_promoted": False,
        "repair_schema": str(meta.get("repair_schema") or _AGILLM_REPAIR_SCHEMA),
        "repair_validation_state": meta.get("repair_validation_state"),
        "candidate": latest_payload,
        "saved_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
    }
    out = path.parent / "quarantine_latest.json"
    raw = (json.dumps(payload, indent=2, sort_keys=True) + "\n").encode("utf-8")
    _atomic_write_bytes_fsync(out, raw)
    print(f"[repair-quarantine] checkpoint saved without pointer promotion: {reason}", flush=True)




_AGILLM43_POINTER_SCHEMA = "agillm43.pointer.commit.v2"
_AGILLM43_POINTER_DIGEST_CACHE = {}
_AGILLM43_POINTER_MANIFEST_CACHE = {}
_AGILLM43_POINTER_PACKAGE_CACHE = {}
_AGILLM43_PACKAGE_RECEIPT_SCHEMA = "agillm43.checkpoint.package.receipt.v1"
_AGILLM43_LINEAGE_CLAIM_SCHEMA = "agillm43.checkpoint.lineage.claim.v1"


def _repair_canonical_json_bytes(payload):
    return json.dumps(
        payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")


def _repair_pointer_record_sha256(payload):
    body = dict(payload)
    body.pop("record_sha256", None)
    return hashlib.sha256(_repair_canonical_json_bytes(body)).hexdigest()


def _repair_test_crash_boundary(name):
    """Subprocess-only crash injection used by atomic publication tests."""
    if os.environ.get("AGILLM43_TEST_POINTER_CRASH_AFTER", "") == str(name):
        os._exit(197)


def _repair_checkpoint_digest_cached(path, expected):
    path = Path(path)
    st = path.stat()
    key = (
        str(path.resolve()), int(st.st_dev), int(st.st_ino), int(st.st_size),
        int(st.st_mtime_ns), int(st.st_ctime_ns), str(expected),
    )
    cached = _AGILLM43_POINTER_DIGEST_CACHE.get(key)
    if cached == expected:
        return cached
    actual = _sha256_file(path)
    if actual != expected:
        raise RuntimeError(
            f"pointer checkpoint checksum mismatch for {path}: {actual} != {expected}")
    _AGILLM43_POINTER_DIGEST_CACHE.clear()
    _AGILLM43_POINTER_DIGEST_CACHE[key] = actual
    return actual


def _repair_package_stat_key(path, declaration):
    paths = [Path(path)] + [Path(item["path"]) for item in declaration["shards"]]
    key = []
    for item in paths:
        st = item.stat()
        key.append((
            str(item.resolve()), int(st.st_dev), int(st.st_ino), int(st.st_size),
            int(st.st_mtime_ns), int(st.st_ctime_ns),
        ))
    return tuple(key)


def _repair_lineage_claim_sha256(claim):
    body = dict(claim)
    body.pop("claim_sha256", None)
    return hashlib.sha256(_repair_canonical_json_bytes(body)).hexdigest()


def _repair_revalidate_package_paths(checkpoint_path, declaration):
    """Re-lstat unresolved package paths even when content digests are cached."""
    path = Path(checkpoint_path).expanduser().resolve()
    raw_dir = str(declaration.get("shard_dir_relative") or "")
    unresolved_dir = path.parent / raw_dir
    if unresolved_dir.is_symlink() or not unresolved_dir.is_dir():
        raise RuntimeError(
            f"checkpoint package shard directory became unsafe: {unresolved_dir}")
    resolved_dir = unresolved_dir.resolve()
    if str(resolved_dir) != str(declaration.get("shard_dir") or ""):
        raise RuntimeError("checkpoint package shard directory identity changed")
    shards = declaration.get("shards")
    if not isinstance(shards, list) or not shards:
        raise RuntimeError("checkpoint package cached declaration has no shards")
    for shard in shards:
        raw_name = str(shard.get("relative_path") or "")
        unresolved = unresolved_dir / raw_name
        if unresolved.is_symlink() or not unresolved.is_file():
            raise RuntimeError(f"checkpoint package shard became unsafe: {unresolved}")
        resolved = unresolved.resolve()
        if str(resolved) != str(shard.get("path") or ""):
            raise RuntimeError(f"checkpoint package shard identity changed: {raw_name}")
        if int(unresolved.stat().st_size) != int(shard.get("nbytes", -1)):
            raise RuntimeError(f"checkpoint package shard size changed: {raw_name}")
    return declaration


def _repair_reviewed_package_lineage(checkpoint_path, manifest):
    """Extract only reviewed lineage facts from the already-hashed top manifest."""
    path = Path(checkpoint_path).expanduser().resolve()
    step = _repair_resume_step_from_path(path)
    if (step is None or step < _AGILLM43_REPAIR_BASE_STEP
            or step > _AGILLM43_REPAIR_TARGET_STEP):
        raise RuntimeError("checkpoint manifest has no valid repair step")
    if step == _AGILLM43_REPAIR_BASE_STEP:
        claim = {
            "schema": _AGILLM43_LINEAGE_CLAIM_SCHEMA,
            "kind": "pinned_seed",
            "checkpoint_step": int(step),
            "repair_base_step": _AGILLM43_REPAIR_BASE_STEP,
            "repair_seed_sha256": _AGILLM43_REPAIR_SEED_SHA256,
        }
        claim["claim_sha256"] = _repair_lineage_claim_sha256(claim)
        return claim
    skeleton = manifest.get("skeleton") if isinstance(manifest, dict) else None
    if not isinstance(skeleton, dict):
        raise RuntimeError("child checkpoint manifest has no lineage-bearing skeleton")

    def _exact_int(container, key, *, minimum=None):
        value = container.get(key)
        if isinstance(value, bool) or not isinstance(value, int):
            raise RuntimeError(f"child checkpoint lineage {key} is not an integer")
        if minimum is not None and value < minimum:
            raise RuntimeError(f"child checkpoint lineage {key} is below {minimum}")
        return int(value)

    exact_strings = {
        "repair_schema": _AGILLM_REPAIR_SCHEMA,
        "repair_lineage_schema": _AGILLM_REPAIR_LINEAGE_SCHEMA,
        "repair_seed_sha256": _AGILLM43_REPAIR_SEED_SHA256,
    }
    for key, expected in exact_strings.items():
        if str(skeleton.get(key) or "") != expected:
            raise RuntimeError(
                f"child checkpoint embedded {key} mismatch: "
                f"{skeleton.get(key)!r} != {expected!r}")
    if _exact_int(skeleton, "step") != step:
        raise RuntimeError("child checkpoint embedded step disagrees with filename")
    if _exact_int(skeleton, "repair_checkpoint_step") != step:
        raise RuntimeError("child checkpoint embedded repair step disagrees with filename")
    if _exact_int(skeleton, "repair_base_step") != _AGILLM43_REPAIR_BASE_STEP:
        raise RuntimeError("child checkpoint embedded repair base mismatch")
    endpoint_fields = {
        "repair_target_commits": _AGILLM43_REPAIR_TARGET_COMMITS,
        "repair_target_step": _AGILLM43_REPAIR_TARGET_STEP,
        "repair_target_seen_tok": _AGILLM43_REPAIR_TARGET_SEEN_TOK,
    }
    for key, expected in endpoint_fields.items():
        if _exact_int(skeleton, key) != expected:
            raise RuntimeError(
                f"child checkpoint embedded {key} disagrees with immutable endpoint"
            )
    clock_receipt = _repair_validate_token_clocks(skeleton, step)
    base_seen = clock_receipt["repair_base_seen_tok"]
    seen_tok = clock_receipt["seen_tok"]

    contract = skeleton.get("repair_contract")
    if (not isinstance(contract, dict)
            or str(contract.get("schema") or "") != _AGILLM_REPAIR_CONTRACT_SCHEMA):
        raise RuntimeError("child checkpoint embedded repair contract is invalid")
    contract_sha = str(skeleton.get("repair_contract_sha256") or "")
    if (not re.fullmatch(r"[0-9a-f]{64}", contract_sha)
            or _repair_contract_sha256(contract) != contract_sha):
        raise RuntimeError("child checkpoint embedded repair contract digest mismatch")
    architecture = _repair_validate_resolved_architecture(
        skeleton.get("cfg"), skeleton.get("tie_weights"),
        contract=contract, contract_sha256=contract_sha,
        receipt=skeleton.get("repair_resolved_architecture"),
        receipt_sha256=skeleton.get("repair_resolved_architecture_sha256"),
        require_receipt=True, context="child checkpoint embedded",
    )

    dataset = skeleton.get("repair_dataset_contract")
    if (not isinstance(dataset, dict)
            or dataset.get("schema") != _AGILLM43_REPAIR_DATASET_SCHEMA
            or dataset.get("example_boundary_policy")
            != _AGILLM43_EXAMPLE_BOUNDARY_POLICY
            or dataset.get("cropped_examples_end_with_eos") is not True
            or dataset.get("crop_rng_compatible_with_v11") is not True
            or dataset.get("crop_output_length_preserved") is not True
            or _exact_int(dataset, "eos_token_id")
            != _AGILLM43_REPAIR_EOS_PAD_ID
            or dataset.get("source_sha256") != _AGILLM43_REPAIR_SOURCE_SHA256
            or tuple(dataset.get("source_specs") or ()) != _AGILLM43_REPAIR_SOURCE_SPECS
            or _exact_int(dataset, "source_count") != len(_AGILLM43_REPAIR_SOURCE_SPECS)
            or dataset.get("hot_config") is not False
            or dataset.get("router_state") is not False
            or dataset.get("agent_router") is not False
            or dataset.get("source_floors") is not False
            or _exact_int(dataset, "max_example_tokens") != 4096
            or _exact_int(dataset, "remote_shards_per_iter") != 4):
        raise RuntimeError("child checkpoint embedded dataset receipt is incompatible")

    heldout = skeleton.get("repair_heldout_contract")
    if (not isinstance(heldout, dict)
            or heldout.get("schema") != "agillm43.repair.heldout.v2"
            or heldout.get("token_ids_sha256") != _AGILLM43_HELDOUT_TOKEN_IDS_SHA256
            or heldout.get("manifest_sha256") != _AGILLM43_HELDOUT_MANIFEST_SHA256
            or heldout.get("checkpoint_tokenizer_sidecar_sha256")
            != _AGILLM43_REPAIR_TOKENIZER_SIDECAR_SHA256
            or _exact_int(heldout, "tokens", minimum=1) != 12404):
        raise RuntimeError("child checkpoint embedded heldout receipt is incompatible")

    tokenizer = skeleton.get("repair_tokenizer_contract")
    if (not isinstance(tokenizer, dict)
            or tokenizer.get("schema") != "agillm43.repair.tokenizer.v1"
            or tokenizer.get("tokenizer_id") != _AGILLM43_REPAIR_TOKENIZER_ID
            or tokenizer.get("seed_sidecar_sha256")
            != _AGILLM43_REPAIR_TOKENIZER_SIDECAR_SHA256
            or tokenizer.get("backend_sha256")
            != _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256
            or _exact_int(tokenizer, "vocab_size") != _AGILLM43_REPAIR_VOCAB
            or _exact_int(tokenizer, "eos_token_id") != _AGILLM43_REPAIR_EOS_PAD_ID
            or _exact_int(tokenizer, "pad_token_id") != _AGILLM43_REPAIR_EOS_PAD_ID
            or _exact_int(tokenizer, "nat_mask_token_id") != _AGILLM43_REPAIR_NAT_MASK_ID):
        raise RuntimeError("child checkpoint embedded tokenizer receipt is incompatible")
    embedded_backend = skeleton.get("tokenizer_json")
    if (not isinstance(embedded_backend, str)
            or hashlib.sha256(embedded_backend.encode("utf-8")).hexdigest()
            != _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256
            or skeleton.get("tokenizer_id") != _AGILLM43_REPAIR_TOKENIZER_ID):
        raise RuntimeError("child checkpoint embedded tokenizer payload is incompatible")
    embedded_special = skeleton.get("tokenizer_special")
    if (not isinstance(embedded_special, dict)
            or _exact_int(embedded_special, "vocab_size") != _AGILLM43_REPAIR_VOCAB
            or _exact_int(embedded_special, "eos_token_id")
            != _AGILLM43_REPAIR_EOS_PAD_ID
            or _exact_int(embedded_special, "pad_token_id")
            != _AGILLM43_REPAIR_EOS_PAD_ID):
        raise RuntimeError("child checkpoint embedded tokenizer special contract is incompatible")

    dblock = skeleton.get("dblock_resume_state")
    try:
        dblock_snapshot = _dblock_validate_resume_payload(dblock, step)
    except Exception as exc:
        raise RuntimeError(f"child checkpoint embedded DBlock state is invalid: {exc}") from exc
    try:
        validation = _repair_validate_validation_state(
            skeleton.get("repair_validation_state"), step,
            require_authoritative=True,
        )
    except Exception as exc:
        raise RuntimeError(
            f"child checkpoint embedded validation state is invalid: {exc}"
        ) from exc
    validation_reason = _repair_pointer_block_reason(skeleton, step)
    if validation_reason:
        raise RuntimeError(
            "child checkpoint embedded validation state cannot be promoted: "
            + validation_reason)
    validation_sha = hashlib.sha256(
        _repair_canonical_json_bytes(validation)).hexdigest()
    dblock_state_sha = hashlib.sha256(
        _repair_canonical_json_bytes(dblock_snapshot)).hexdigest()
    claim = {
        "schema": _AGILLM43_LINEAGE_CLAIM_SCHEMA,
        "kind": "repair_child",
        "checkpoint_step": int(step),
        "repair_schema": _AGILLM_REPAIR_SCHEMA,
        "repair_lineage_schema": _AGILLM_REPAIR_LINEAGE_SCHEMA,
        "repair_base_step": _AGILLM43_REPAIR_BASE_STEP,
        "repair_seed_sha256": _AGILLM43_REPAIR_SEED_SHA256,
        "repair_base_seen_tok": base_seen,
        "repair_target_commits": _AGILLM43_REPAIR_TARGET_COMMITS,
        "repair_target_step": _AGILLM43_REPAIR_TARGET_STEP,
        "repair_target_seen_tok": _AGILLM43_REPAIR_TARGET_SEEN_TOK,
        "seen_tok": seen_tok,
        "repair_contract_sha256": contract_sha,
        "repair_resolved_architecture_sha256": architecture["sha256"],
        "repair_dataset_sha256": dataset["source_sha256"],
        "repair_heldout_token_ids_sha256": heldout["token_ids_sha256"],
        "repair_heldout_manifest_sha256": heldout["manifest_sha256"],
        "repair_tokenizer_sidecar_sha256": tokenizer["seed_sidecar_sha256"],
        "repair_tokenizer_backend_sha256": tokenizer["backend_sha256"],
        "repair_validation_state_sha256": validation_sha,
        "dblock_resume_schema": dblock["schema"],
        "dblock_resume_sha256": dblock["sha256"],
        "dblock_committed_step": int(dblock["committed_step"]),
        "dblock_B": int(dblock["B"]),
        "dblock_state_sha256": dblock_state_sha,
        "dblock_counts": list(dblock_snapshot["counts"]),
        "dblock_attempt_step": int(dblock_snapshot["attempt_step"]),
        "dblock_attempt_counts": list(dblock_snapshot["attempt_counts"]),
        "dblock_committed_objective_steps": dict(
            dblock_snapshot.get("committed_objective_steps") or {}),
    }
    claim["claim_sha256"] = _repair_lineage_claim_sha256(claim)
    return claim


def _repair_load_package_declaration(checkpoint_path):
    """Read and strictly normalize the block-sharded manifest without loading shards."""
    path = Path(checkpoint_path).expanduser().resolve()
    st = path.stat()
    cache_key = (
        str(path), int(st.st_dev), int(st.st_ino), int(st.st_size),
        int(st.st_mtime_ns), int(st.st_ctime_ns),
    )
    cached = _AGILLM43_POINTER_MANIFEST_CACHE.get(cache_key)
    if cached is not None:
        return _repair_revalidate_package_paths(path, cached)
    try:
        manifest = torch.load(str(path), map_location="cpu", weights_only=False)
    except Exception as exc:
        raise RuntimeError(
            f"pointer checkpoint manifest cannot be decoded: {path}: "
            f"{type(exc).__name__}: {exc}") from exc
    if (not isinstance(manifest, dict)
            or manifest.get(_AGILLM43_SHARDED_CODEC_MAGIC) != _AGILLM43_SHARDED_CODEC_MAGIC
            or int(manifest.get("format_version", -1) or -1) != 1
            or str(manifest.get("codec") or "") != "block-sharded"):
        raise RuntimeError(
            f"repair pointer checkpoint is not a v1 block-sharded package: {path}")
    lineage = _repair_reviewed_package_lineage(path, manifest)
    raw_shard_dir = str(manifest.get("shard_dir") or "")
    shard_dir_rel = Path(raw_shard_dir)
    if (not raw_shard_dir or shard_dir_rel.is_absolute()
            or raw_shard_dir in {".", ".."}
            or ".." in shard_dir_rel.parts):
        raise RuntimeError(f"checkpoint package has unsafe shard_dir: {raw_shard_dir!r}")
    parent = path.parent.resolve()
    shard_dir_unresolved = parent / shard_dir_rel
    if shard_dir_unresolved.is_symlink():
        raise RuntimeError(f"checkpoint package shard directory is a symlink: {shard_dir_unresolved}")
    shard_dir = shard_dir_unresolved.resolve()
    try:
        within_parent = os.path.commonpath((str(parent), str(shard_dir))) == str(parent)
    except ValueError:
        within_parent = False
    if not within_parent or not shard_dir.is_dir():
        raise RuntimeError(f"checkpoint package shard directory is unavailable: {shard_dir}")
    entries = manifest.get("entries")
    if not isinstance(entries, list) or not entries:
        raise RuntimeError("checkpoint package has no declared shards")
    shards = []
    seen = set()
    for ordinal, entry in enumerate(entries):
        if not isinstance(entry, dict):
            raise RuntimeError(f"checkpoint package shard entry {ordinal} is not an object")
        raw_name = str(entry.get("shard") or "")
        rel = Path(raw_name)
        if (not raw_name or rel.is_absolute() or len(rel.parts) != 1
                or raw_name in {".", ".."} or rel.name != raw_name):
            raise RuntimeError(f"checkpoint package has unsafe shard name: {raw_name!r}")
        if raw_name in seen:
            raise RuntimeError(f"checkpoint package repeats shard name: {raw_name}")
        seen.add(raw_name)
        shard_unresolved = shard_dir / raw_name
        if shard_unresolved.is_symlink():
            raise RuntimeError(f"checkpoint package shard is a symlink: {shard_unresolved}")
        shard_path = shard_unresolved.resolve()
        try:
            within_shards = os.path.commonpath(
                (str(shard_dir), str(shard_path))) == str(shard_dir)
        except ValueError:
            within_shards = False
        if not within_shards or not shard_path.is_file():
            raise RuntimeError(f"checkpoint package shard is unavailable: {shard_path}")
        try:
            nbytes = int(entry.get("nbytes"))
        except Exception as exc:
            raise RuntimeError(
                f"checkpoint package shard has invalid size: {raw_name}") from exc
        digest = str(entry.get("sha256") or "").lower()
        if nbytes < 0 or not re.fullmatch(r"[0-9a-f]{64}", digest):
            raise RuntimeError(
                f"checkpoint package shard has invalid digest/size: {raw_name}")
        if int(shard_path.stat().st_size) != nbytes:
            raise RuntimeError(
                f"checkpoint package shard size mismatch for {raw_name}: "
                f"{shard_path.stat().st_size} != {nbytes}")
        shards.append({
            "ordinal": int(ordinal),
            "relative_path": raw_name,
            "path": str(shard_path),
            "nbytes": nbytes,
            "sha256": digest,
        })
    declaration = {
        "package_format": _AGILLM43_SHARDED_CODEC_MAGIC,
        "format_version": 1,
        "codec": "block-sharded",
        "shard_codec": str(manifest.get("shard_codec") or ""),
        "shard_dir": str(shard_dir),
        "shard_dir_relative": raw_shard_dir,
        "shards": shards,
        "lineage": lineage,
    }
    _AGILLM43_POINTER_MANIFEST_CACHE.clear()
    _AGILLM43_POINTER_MANIFEST_CACHE[cache_key] = declaration
    return _repair_revalidate_package_paths(path, declaration)


def _repair_checkpoint_source_binding(path):
    step = _repair_resume_step_from_path(path)
    if step == _AGILLM43_REPAIR_BASE_STEP:
        return _AGILLM43_REPAIR_SEED_SHA256, {
            "kind": "pinned_seed_sha256",
            "step": int(step),
            "sha256": _AGILLM43_REPAIR_SEED_SHA256,
        }
    if step is None or step <= _AGILLM43_REPAIR_BASE_STEP:
        raise RuntimeError("pointer checkpoint has no valid repair lineage step")
    sidecar_unresolved = _repair_manifest_sidecar(path)
    if sidecar_unresolved.is_symlink():
        raise RuntimeError(
            f"child repair checkpoint manifest checksum is a symlink: {sidecar_unresolved}")
    sidecar = sidecar_unresolved.resolve()
    if not sidecar.is_file():
        raise RuntimeError(f"child repair checkpoint manifest checksum is missing: {sidecar}")
    sidecar_raw = sidecar.read_bytes()
    try:
        parts = sidecar_raw.decode("utf-8").split()
    except Exception as exc:
        raise RuntimeError(f"child repair checkpoint manifest is not UTF-8: {sidecar}") from exc
    expected = parts[0].lower() if parts else ""
    if (len(parts) != 2 or not re.fullmatch(r"[0-9a-f]{64}", expected)
            or Path(parts[1]).name != path.name):
        raise RuntimeError(f"child repair checkpoint manifest binding is invalid: {sidecar}")
    return expected, {
        "kind": "adjacent_sha256",
        "path": str(sidecar),
        "sha256": hashlib.sha256(sidecar_raw).hexdigest(),
        "nbytes": len(sidecar_raw),
        "checkpoint_sha256": expected,
    }


def _repair_checkpoint_package_receipt(checkpoint_path):
    path = Path(checkpoint_path).expanduser().resolve()
    if not path.is_file():
        raise RuntimeError(f"pointer checkpoint is missing: {path}")
    expected, source_binding = _repair_checkpoint_source_binding(path)
    declaration = _repair_load_package_declaration(path)
    package_key = (
        _repair_package_stat_key(path, declaration), expected,
        _repair_canonical_json_bytes(source_binding),
    )
    cached = _AGILLM43_POINTER_PACKAGE_CACHE.get(package_key)
    if cached is not None:
        return cached
    _repair_checkpoint_digest_cached(path, expected)
    for shard in declaration["shards"]:
        _repair_checkpoint_digest_cached(shard["path"], shard["sha256"])
    receipt = {
        "schema": _AGILLM43_PACKAGE_RECEIPT_SCHEMA,
        "checkpoint": {
            "path": str(path),
            "name": path.name,
            "sha256": expected,
            "nbytes": int(path.stat().st_size),
        },
        "package_format": declaration["package_format"],
        "format_version": declaration["format_version"],
        "codec": declaration["codec"],
        "shard_codec": declaration["shard_codec"],
        "shard_dir": declaration["shard_dir"],
        "shard_dir_relative": declaration["shard_dir_relative"],
        "shards": [dict(item) for item in declaration["shards"]],
        "lineage": dict(declaration["lineage"]),
        "source_binding": source_binding,
    }
    receipt["receipt_sha256"] = hashlib.sha256(
        _repair_canonical_json_bytes(receipt)).hexdigest()
    _AGILLM43_POINTER_PACKAGE_CACHE.clear()
    _AGILLM43_POINTER_PACKAGE_CACHE[package_key] = receipt
    return receipt


def _repair_validate_package_receipt(receipt):
    if (not isinstance(receipt, dict)
            or receipt.get("schema") != _AGILLM43_PACKAGE_RECEIPT_SCHEMA):
        raise RuntimeError("checkpoint package receipt schema is invalid")
    claimed = str(receipt.get("receipt_sha256") or "")
    body = dict(receipt)
    body.pop("receipt_sha256", None)
    if claimed != hashlib.sha256(_repair_canonical_json_bytes(body)).hexdigest():
        raise RuntimeError("checkpoint package receipt checksum mismatch")
    checkpoint = receipt.get("checkpoint")
    if not isinstance(checkpoint, dict):
        raise RuntimeError("checkpoint package receipt has no checkpoint")
    path = Path(str(checkpoint.get("path") or "")).expanduser().resolve()
    if not path.is_file() or path.name != checkpoint.get("name"):
        raise RuntimeError(f"checkpoint package receipt path is unavailable: {path}")
    expected = str(checkpoint.get("sha256") or "")
    if (not re.fullmatch(r"[0-9a-f]{64}", expected)
            or int(path.stat().st_size) != int(checkpoint.get("nbytes", -1))):
        raise RuntimeError("checkpoint package receipt checkpoint identity is invalid")
    source = receipt.get("source_binding")
    if not isinstance(source, dict):
        raise RuntimeError("checkpoint package receipt has no source binding")
    step = _repair_resume_step_from_path(path)
    if source.get("kind") == "pinned_seed_sha256":
        if (step != _AGILLM43_REPAIR_BASE_STEP
                or expected != _AGILLM43_REPAIR_SEED_SHA256
                or source.get("sha256") != expected
                or int(source.get("step", -1)) != _AGILLM43_REPAIR_BASE_STEP):
            raise RuntimeError("checkpoint package receipt seed binding is invalid")
    elif source.get("kind") == "adjacent_sha256":
        canonical_unresolved = _repair_manifest_sidecar(path)
        source_unresolved = Path(str(source.get("path") or "")).expanduser()
        if canonical_unresolved.is_symlink() or source_unresolved.is_symlink():
            raise RuntimeError("checkpoint package receipt child sidecar is a symlink")
        sidecar = source_unresolved.resolve()
        if (sidecar != canonical_unresolved.resolve()
                or not sidecar.is_file()
                or source_unresolved.absolute() != canonical_unresolved.absolute()):
            raise RuntimeError("checkpoint package receipt child sidecar is unavailable")
        sidecar_raw = sidecar.read_bytes()
        if (len(sidecar_raw) != int(source.get("nbytes", -1))
                or hashlib.sha256(sidecar_raw).hexdigest() != source.get("sha256")):
            raise RuntimeError("checkpoint package receipt child sidecar checksum mismatch")
        parts = sidecar_raw.decode("utf-8").split()
        if (len(parts) != 2 or parts[0].lower() != expected
                or Path(parts[1]).name != path.name
                or source.get("checkpoint_sha256") != expected):
            raise RuntimeError("checkpoint package receipt child sidecar binding mismatch")
    else:
        raise RuntimeError("checkpoint package receipt source binding is invalid")
    declaration = _repair_load_package_declaration(path)
    declared_shards = declaration["shards"]
    receipt_shards = receipt.get("shards")
    if not isinstance(receipt_shards, list) or receipt_shards != declared_shards:
        raise RuntimeError("checkpoint package receipt does not exactly cover manifest shards")
    if receipt.get("lineage") != declaration.get("lineage"):
        raise RuntimeError("checkpoint package receipt lineage claim mismatch")
    for key in (
        "package_format", "format_version", "codec", "shard_codec",
        "shard_dir", "shard_dir_relative",
    ):
        if receipt.get(key) != declaration.get(key):
            raise RuntimeError(f"checkpoint package receipt {key} binding mismatch")
    package_key = (
        _repair_package_stat_key(path, declaration), expected,
        _repair_canonical_json_bytes(source),
    )
    cached = _AGILLM43_POINTER_PACKAGE_CACHE.get(package_key)
    if cached is not None and cached.get("receipt_sha256") == claimed:
        return checkpoint
    _repair_checkpoint_digest_cached(path, expected)
    for shard in declared_shards:
        _repair_checkpoint_digest_cached(shard["path"], shard["sha256"])
    _AGILLM43_POINTER_PACKAGE_CACHE.clear()
    _AGILLM43_POINTER_PACKAGE_CACHE[package_key] = dict(receipt)
    return checkpoint


def _repair_package_manifest_artifact(save_dir, receipt):
    raw = _repair_canonical_json_bytes(receipt) + b"\n"
    digest = hashlib.sha256(raw).hexdigest()
    save = Path(save_dir).expanduser().resolve()
    root = save / "pointer_artifacts"
    artifact_dir = root / "manifests"
    if root.is_symlink() or artifact_dir.is_symlink():
        raise RuntimeError("checkpoint manifest artifact directory is a symlink")
    root.mkdir(parents=True, exist_ok=True)
    _fsync_directory(save)
    artifact_dir.mkdir(parents=True, exist_ok=True)
    _fsync_directory(root)
    safe_name = re.sub(
        r"[^A-Za-z0-9_.-]+", "_", receipt["checkpoint"]["name"])
    artifact = artifact_dir / f"{safe_name}.{digest}.manifest.json"
    if artifact.exists():
        if _sha256_file(artifact) != digest or artifact.read_bytes() != raw:
            raise RuntimeError(f"immutable checkpoint manifest collision: {artifact}")
    else:
        _atomic_write_bytes_fsync(artifact, raw)
    _fsync_directory(artifact_dir)
    return {
        "path": str(artifact.resolve()),
        "sha256": digest,
        "nbytes": len(raw),
        "schema": _AGILLM43_PACKAGE_RECEIPT_SCHEMA,
        "receipt_sha256": receipt["receipt_sha256"],
    }


def _repair_checkpoint_reference(checkpoint_path, save_dir=None):
    receipt = _repair_checkpoint_package_receipt(checkpoint_path)
    checkpoint = dict(receipt["checkpoint"])
    checkpoint.update({
        "package_format": receipt["package_format"],
        "package_shards": len(receipt["shards"]),
        "package_receipt_sha256": receipt["receipt_sha256"],
        "lineage": dict(receipt["lineage"]),
    })
    if save_dir is not None:
        artifact = _repair_package_manifest_artifact(save_dir, receipt)
        checkpoint.update({
            "manifest_path": artifact["path"],
            "manifest_sha256": artifact["sha256"],
            "manifest_nbytes": artifact["nbytes"],
            "manifest_schema": artifact["schema"],
            "manifest_receipt_sha256": artifact["receipt_sha256"],
        })
    return checkpoint


def _repair_bind_pointer_lineage(payload, checkpoint):
    claim = checkpoint.get("lineage")
    if not isinstance(claim, dict):
        raise RuntimeError("pointer checkpoint has no embedded lineage claim")
    if claim.get("claim_sha256") != _repair_lineage_claim_sha256(claim):
        raise RuntimeError("pointer checkpoint lineage claim checksum mismatch")
    payload["checkpoint_lineage_sha256"] = claim["claim_sha256"]
    payload["repair_schema"] = _AGILLM_REPAIR_SCHEMA
    payload["repair_lineage_schema"] = _AGILLM_REPAIR_LINEAGE_SCHEMA
    payload["repair_base_step"] = _AGILLM43_REPAIR_BASE_STEP
    payload["repair_seed_sha256"] = _AGILLM43_REPAIR_SEED_SHA256
    payload["repair_checkpoint_step"] = int(claim["checkpoint_step"])
    if claim.get("kind") == "repair_child":
        for key in (
            "repair_base_seen_tok", "repair_target_commits",
            "repair_target_step", "repair_target_seen_tok",
            "repair_contract_sha256",
            "repair_dataset_sha256", "repair_heldout_token_ids_sha256",
            "repair_heldout_manifest_sha256", "repair_tokenizer_sidecar_sha256",
            "repair_tokenizer_backend_sha256", "repair_validation_state_sha256",
            "dblock_resume_schema", "dblock_resume_sha256",
            "dblock_committed_step", "dblock_state_sha256",
        ):
            payload[key] = claim[key]
    return payload


def _repair_validate_lineage_fields(payload, checkpoint):
    try:
        step = _dblock_require_exact_int(
            payload.get("step"), "pointer checkpoint step",
            minimum=_AGILLM43_REPAIR_BASE_STEP,
            maximum=_AGILLM43_REPAIR_TARGET_STEP,
        )
    except ValueError as exc:
        raise RuntimeError("pointer has no exact integer checkpoint step") from exc
    path_step = _repair_resume_step_from_path(checkpoint["path"])
    if path_step != step:
        raise RuntimeError(f"pointer step {step} != checkpoint filename step {path_step}")
    if (step < _AGILLM43_REPAIR_BASE_STEP
            or step > _AGILLM43_REPAIR_TARGET_STEP):
        raise RuntimeError("pointer checkpoint is outside immutable repair endpoint")
    claim = checkpoint.get("lineage")
    claim_valid = (
        isinstance(claim, dict)
        and claim.get("schema") == _AGILLM43_LINEAGE_CLAIM_SCHEMA
        and claim.get("claim_sha256") == _repair_lineage_claim_sha256(claim)
        and type(claim.get("checkpoint_step")) is int
        and claim.get("checkpoint_step") == step
        and type(claim.get("repair_base_step")) is int
        and claim.get("repair_base_step") == _AGILLM43_REPAIR_BASE_STEP
        and claim.get("repair_seed_sha256") == _AGILLM43_REPAIR_SEED_SHA256
        and payload.get("checkpoint_lineage_sha256") == claim.get("claim_sha256")
    )
    if not claim_valid:
        raise RuntimeError("pointer does not match its checkpoint-embedded lineage claim")
    if step == _AGILLM43_REPAIR_BASE_STEP:
        if (checkpoint["sha256"] != _AGILLM43_REPAIR_SEED_SHA256
                or claim.get("kind") != "pinned_seed"):
            raise RuntimeError("base-step pointer does not reference the pinned repair seed")
        return
    required = {
        "repair_schema": _AGILLM_REPAIR_SCHEMA,
        "repair_lineage_schema": _AGILLM_REPAIR_LINEAGE_SCHEMA,
        "repair_base_step": _AGILLM43_REPAIR_BASE_STEP,
        "repair_seed_sha256": _AGILLM43_REPAIR_SEED_SHA256,
        "repair_checkpoint_step": step,
        "repair_base_seen_tok": claim["repair_base_seen_tok"],
        "repair_target_commits": _AGILLM43_REPAIR_TARGET_COMMITS,
        "repair_target_step": _AGILLM43_REPAIR_TARGET_STEP,
        "repair_target_seen_tok": _AGILLM43_REPAIR_TARGET_SEEN_TOK,
        "repair_contract_sha256": claim["repair_contract_sha256"],
        "repair_dataset_sha256": claim["repair_dataset_sha256"],
        "repair_heldout_token_ids_sha256": claim["repair_heldout_token_ids_sha256"],
        "repair_heldout_manifest_sha256": claim["repair_heldout_manifest_sha256"],
        "repair_tokenizer_sidecar_sha256": claim["repair_tokenizer_sidecar_sha256"],
        "repair_tokenizer_backend_sha256": claim["repair_tokenizer_backend_sha256"],
        "repair_validation_state_sha256": claim["repair_validation_state_sha256"],
        "dblock_resume_schema": claim["dblock_resume_schema"],
        "dblock_resume_sha256": claim["dblock_resume_sha256"],
        "dblock_committed_step": step - _AGILLM43_REPAIR_BASE_STEP,
        "dblock_state_sha256": claim["dblock_state_sha256"],
    }
    for key, expected in required.items():
        actual = payload.get(key)
        if type(expected) is int and type(actual) is not int:
            raise RuntimeError(
                f"pointer lineage {key} must be an exact non-boolean integer"
            )
        if actual != expected:
            raise RuntimeError(f"pointer lineage {key} mismatch: {actual!r} != {expected!r}")
    validation = payload.get("repair_validation_state")
    if (not isinstance(validation, dict)
            or hashlib.sha256(_repair_canonical_json_bytes(validation)).hexdigest()
            != claim["repair_validation_state_sha256"]):
        raise RuntimeError("pointer validation state disagrees with embedded checkpoint")
    manifest_digest = str(payload.get("checkpoint_manifest_sha256") or "")
    if manifest_digest != checkpoint["sha256"]:
        raise RuntimeError("pointer checkpoint digest disagrees with repair payload")


def _repair_tokenizer_artifact(save_dir, checkpoint, tokenizer_payload):
    data = dict(tokenizer_payload or {})
    data.setdefault("tokenizer_payload_schema", 2)
    if int(data.get("tokenizer_payload_schema", -1) or -1) != 2:
        raise RuntimeError("pointer tokenizer payload schema mismatch")
    data["checkpoint_name"] = checkpoint["name"]
    data["checkpoint_path"] = checkpoint["path"]
    backend = data.get("tokenizer_json")
    if not isinstance(backend, str) or not backend:
        raise RuntimeError("pointer tokenizer payload has no exact tokenizer_json")
    backend_sha = hashlib.sha256(backend.encode("utf-8")).hexdigest()
    if backend_sha != _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256:
        raise RuntimeError(f"pointer tokenizer backend checksum mismatch: {backend_sha}")
    if str(data.get("tokenizer_id") or "") != _AGILLM43_REPAIR_TOKENIZER_ID:
        raise RuntimeError("pointer tokenizer_id mismatch")
    special = data.get("tokenizer_special")
    expected_special = {
        "vocab_size": _AGILLM43_REPAIR_VOCAB,
        "eos_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
        "pad_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
    }
    if not isinstance(special, dict):
        raise RuntimeError("pointer tokenizer special-token contract is missing")
    for key, expected in expected_special.items():
        if int(special.get(key, -1) or -1) != expected:
            raise RuntimeError(f"pointer tokenizer {key} mismatch")
    raw = _repair_canonical_json_bytes(data) + b"\n"
    digest = hashlib.sha256(raw).hexdigest()
    artifact_dir = Path(save_dir) / "pointer_artifacts" / "tokenizers"
    if artifact_dir.parent.is_symlink() or artifact_dir.is_symlink():
        raise RuntimeError("tokenizer artifact directory is a symlink")
    artifact_dir.mkdir(parents=True, exist_ok=True)
    _fsync_directory(Path(save_dir))
    _fsync_directory(artifact_dir.parent)
    safe_name = re.sub(r"[^A-Za-z0-9_.-]+", "_", checkpoint["name"])
    artifact = artifact_dir / f"{safe_name}.{digest}.tokenizer.json"
    if artifact.exists():
        if _sha256_file(artifact) != digest or artifact.read_bytes() != raw:
            raise RuntimeError(f"immutable tokenizer artifact collision: {artifact}")
    else:
        _atomic_write_bytes_fsync(artifact, raw)
    _fsync_directory(artifact_dir)
    return {
        "path": str(artifact.resolve()),
        "sha256": digest,
        "nbytes": len(raw),
        "backend_sha256": backend_sha,
        "checkpoint_path": checkpoint["path"],
    }


def _repair_pointer_record(payload, role, checkpoint_path, tokenizer_payload, save_dir):
    checkpoint = _repair_checkpoint_reference(checkpoint_path, save_dir=save_dir)
    _repair_test_crash_boundary(f"{role}_manifest")
    clean = dict(payload or {})
    for key in (
        "schema", "role", "checkpoint", "tokenizer", "record_sha256",
        "tokenizer_pointer_path", "tokenizer_pointer_sha256",
        "tokenizer_checkpoint_path",
    ):
        clean.pop(key, None)
    clean["path"] = checkpoint["path"]
    clean["checkpoint_path"] = checkpoint["path"]
    clean["checkpoint_name"] = checkpoint["name"]
    _repair_bind_pointer_lineage(clean, checkpoint)
    _repair_validate_lineage_fields(clean, checkpoint)
    tokenizer = _repair_tokenizer_artifact(save_dir, checkpoint, tokenizer_payload)
    record = clean
    record.update({
        "schema": _AGILLM43_POINTER_SCHEMA,
        "role": str(role),
        "checkpoint": checkpoint,
        "tokenizer": tokenizer,
        "published_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
    })
    record["record_sha256"] = _repair_pointer_record_sha256(record)
    return record


def _repair_validate_pointer_record(record, *, index_path=None, expected_role=None):
    if not isinstance(record, dict) or record.get("schema") != _AGILLM43_POINTER_SCHEMA:
        raise RuntimeError("pointer is not an atomic v2 commit record")
    if expected_role and record.get("role") != expected_role:
        raise RuntimeError(f"pointer role {record.get('role')!r} != {expected_role!r}")
    expected_record_sha = str(record.get("record_sha256") or "")
    if expected_record_sha != _repair_pointer_record_sha256(record):
        raise RuntimeError("pointer record checksum mismatch")
    checkpoint = record.get("checkpoint")
    tokenizer = record.get("tokenizer")
    if not isinstance(checkpoint, dict) or not isinstance(tokenizer, dict):
        raise RuntimeError("pointer lacks checkpoint/tokenizer references")
    path = Path(str(checkpoint.get("path") or "")).expanduser().resolve()
    if (str(record.get("path") or "") != str(path)
            or str(record.get("checkpoint_path") or "") != str(path)):
        raise RuntimeError("pointer compatibility path fields disagree with checkpoint reference")
    if not path.is_file() or path.name != checkpoint.get("name"):
        raise RuntimeError(f"pointer checkpoint path is unavailable: {path}")
    expected_checkpoint_sha = str(checkpoint.get("sha256") or "")
    if not re.fullmatch(r"[0-9a-f]{64}", expected_checkpoint_sha):
        raise RuntimeError("pointer checkpoint checksum is invalid")
    if int(path.stat().st_size) != int(checkpoint.get("nbytes", -1)):
        raise RuntimeError("pointer checkpoint size mismatch")
    manifest_unresolved = Path(
        str(checkpoint.get("manifest_path") or "")).expanduser()
    if manifest_unresolved.is_symlink():
        raise RuntimeError("pointer checkpoint manifest artifact is a symlink")
    manifest = manifest_unresolved.resolve()
    if not manifest.is_file():
        raise RuntimeError("pointer checkpoint manifest artifact is missing")
    expected_manifest_sha = str(checkpoint.get("manifest_sha256") or "")
    if (not re.fullmatch(r"[0-9a-f]{64}", expected_manifest_sha)
            or int(manifest.stat().st_size) != int(checkpoint.get("manifest_nbytes", -1))
            or _sha256_file(manifest) != expected_manifest_sha):
        raise RuntimeError("pointer checkpoint manifest artifact checksum mismatch")
    if not manifest.name.endswith(f".{expected_manifest_sha}.manifest.json"):
        raise RuntimeError("pointer checkpoint manifest is not content addressed")
    if index_path is not None:
        expected_root_unresolved = (
            Path(index_path).parent / "pointer_artifacts" / "manifests")
        if (expected_root_unresolved.parent.is_symlink()
                or expected_root_unresolved.is_symlink()):
            raise RuntimeError("pointer checkpoint manifest directory is a symlink")
        expected_root = expected_root_unresolved.resolve()
        if (manifest.parent != expected_root
                or manifest_unresolved.absolute().parent
                != expected_root_unresolved.absolute()):
            raise RuntimeError("pointer checkpoint manifest is outside its commit directory")
    try:
        package_receipt = json.loads(manifest.read_text(encoding="utf-8"))
    except Exception as exc:
        raise RuntimeError("pointer checkpoint manifest artifact is not valid JSON") from exc
    if (checkpoint.get("manifest_schema") != _AGILLM43_PACKAGE_RECEIPT_SCHEMA
            or checkpoint.get("manifest_receipt_sha256")
            != package_receipt.get("receipt_sha256")
            or checkpoint.get("package_receipt_sha256")
            != package_receipt.get("receipt_sha256")):
        raise RuntimeError("pointer checkpoint manifest receipt binding mismatch")
    validated_checkpoint = _repair_validate_package_receipt(package_receipt)
    for key in ("path", "name", "sha256", "nbytes"):
        if checkpoint.get(key) != validated_checkpoint.get(key):
            raise RuntimeError(f"pointer checkpoint manifest {key} binding mismatch")
    # The immutable, full-package-validated receipt is the sole lineage
    # authority. A record checksum is unkeyed and cannot authorize a copied,
    # recomputed checkpoint claim that differs from the receipt.
    if checkpoint.get("lineage") != package_receipt.get("lineage"):
        raise RuntimeError(
            "pointer checkpoint lineage differs from validated package receipt")
    if (checkpoint.get("package_format") != package_receipt.get("package_format")
            or int(checkpoint.get("package_shards", -1))
            != len(package_receipt.get("shards") or [])):
        raise RuntimeError("pointer checkpoint package summary mismatch")
    _repair_validate_lineage_fields(record, checkpoint)
    tok_unresolved = Path(str(tokenizer.get("path") or "")).expanduser()
    if tok_unresolved.is_symlink():
        raise RuntimeError("pointer tokenizer artifact is a symlink")
    tok_path = tok_unresolved.resolve()
    if (not tok_path.is_file()
            or int(tok_path.stat().st_size) != int(tokenizer.get("nbytes", -1))):
        raise RuntimeError("pointer tokenizer artifact is missing or has wrong size")
    if index_path is not None:
        expected_tok_root_unresolved = (
            Path(index_path).parent / "pointer_artifacts" / "tokenizers")
        if (expected_tok_root_unresolved.parent.is_symlink()
                or expected_tok_root_unresolved.is_symlink()):
            raise RuntimeError("pointer tokenizer directory is a symlink")
        expected_tok_root = expected_tok_root_unresolved.resolve()
        if (tok_path.parent != expected_tok_root
                or tok_unresolved.absolute().parent
                != expected_tok_root_unresolved.absolute()):
            raise RuntimeError("pointer tokenizer is outside its commit directory")
    expected_tok_sha = str(tokenizer.get("sha256") or "")
    if not tok_path.name.endswith(f".{expected_tok_sha}.tokenizer.json"):
        raise RuntimeError("pointer tokenizer artifact is not content addressed")
    tok_raw = tok_path.read_bytes()
    if hashlib.sha256(tok_raw).hexdigest() != expected_tok_sha:
        raise RuntimeError("pointer tokenizer artifact checksum mismatch")
    try:
        tok_payload = json.loads(tok_raw.decode("utf-8"))
    except Exception as exc:
        raise RuntimeError("pointer tokenizer artifact is not valid JSON") from exc
    try:
        tokenizer_schema = int(tok_payload.get("tokenizer_payload_schema", -1))
    except Exception:
        tokenizer_schema = -1
    if tokenizer_schema != 2:
        raise RuntimeError("pointer tokenizer payload schema mismatch")
    if str(tok_payload.get("tokenizer_id") or "") != _AGILLM43_REPAIR_TOKENIZER_ID:
        raise RuntimeError("pointer tokenizer_id mismatch")
    if (str(tok_payload.get("checkpoint_name") or "") != path.name
            or os.path.abspath(str(tok_payload.get("checkpoint_path") or ""))
            != os.path.abspath(str(path))
            or os.path.abspath(str(tokenizer.get("checkpoint_path") or ""))
            != os.path.abspath(str(path))):
        raise RuntimeError("pointer tokenizer is bound to a different checkpoint")
    special = tok_payload.get("tokenizer_special")
    expected_special = {
        "vocab_size": _AGILLM43_REPAIR_VOCAB,
        "eos_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
        "pad_token_id": _AGILLM43_REPAIR_EOS_PAD_ID,
    }
    if not isinstance(special, dict):
        raise RuntimeError("pointer tokenizer special-token contract is missing")
    for key, expected in expected_special.items():
        try:
            actual = int(special.get(key, -1))
        except Exception:
            actual = -1
        if actual != expected:
            raise RuntimeError(f"pointer tokenizer {key} mismatch")
    backend = tok_payload.get("tokenizer_json")
    backend_sha = hashlib.sha256(str(backend or "").encode("utf-8")).hexdigest()
    if (backend_sha != tokenizer.get("backend_sha256")
            or backend_sha != _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256):
        raise RuntimeError("pointer tokenizer backend binding mismatch")
    if index_path is not None:
        expected_name = (
            "training_latest.json" if record.get("role") == "training" else "latest.json")
        if Path(index_path).name != expected_name:
            raise RuntimeError("pointer role does not match its index filename")
    return record


def _repair_read_pointer_record(index_path, *, expected_role=None):
    import stat as _stat

    try:
        raw_index = os.fspath(index_path)
    except TypeError as exc:
        raise RuntimeError("atomic pointer path is not path-like") from exc
    if not isinstance(raw_index, str):
        raise RuntimeError("atomic pointer path must be text")
    expanded_index = os.path.expanduser(raw_index)
    spelling_parts = expanded_index.split(os.sep)
    if os.path.isabs(expanded_index):
        spelling_parts = spelling_parts[1:]
    if (not expanded_index
            or os.path.normpath(expanded_index) != expanded_index
            or any(part in {"", ".", ".."} for part in spelling_parts)):
        raise RuntimeError(
            f"atomic pointer path spelling is noncanonical: {raw_index!r}")
    index_unresolved = Path(expanded_index)
    expected_names = {
        "training": "training_latest.json",
        "public": "latest.json",
    }
    if expected_role is not None and expected_role not in expected_names:
        raise RuntimeError(f"unsupported atomic pointer role: {expected_role!r}")
    expected_name = expected_names.get(expected_role)
    if (expected_name is not None and index_unresolved.name != expected_name):
        raise RuntimeError(
            f"atomic pointer filename {index_unresolved.name!r} != {expected_name!r}")
    if expected_name is None and index_unresolved.name not in set(expected_names.values()):
        raise RuntimeError(
            f"atomic pointer has a noncanonical filename: {index_unresolved.name!r}")

    # Validate the unresolved directory entry before reading it. Path.read_text
    # follows symlinks, which would let a mutable latest/training_latest alias
    # escape the independently atomic commit directory.
    index = Path(os.path.abspath(os.fspath(index_unresolved)))
    try:
        index_lstat = os.lstat(index)
    except Exception as exc:
        raise RuntimeError(
            f"cannot lstat atomic pointer {index}: {type(exc).__name__}: {exc}") from exc
    if _stat.S_ISLNK(index_lstat.st_mode):
        raise RuntimeError(f"atomic pointer index is a symlink: {index}")
    if not _stat.S_ISREG(index_lstat.st_mode):
        raise RuntimeError(f"atomic pointer index is not a regular file: {index}")

    parent = index.parent
    try:
        parent_lstat = os.lstat(parent)
        parent_resolved = parent.resolve(strict=True)
    except Exception as exc:
        raise RuntimeError(
            f"cannot validate atomic pointer parent {parent}: "
            f"{type(exc).__name__}: {exc}") from exc
    if (_stat.S_ISLNK(parent_lstat.st_mode)
            or not _stat.S_ISDIR(parent_lstat.st_mode)
            or parent_resolved != parent):
        raise RuntimeError(f"atomic pointer parent path is noncanonical: {parent}")

    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    descriptor = -1
    try:
        descriptor = os.open(index, flags)
        with os.fdopen(descriptor, "r", encoding="utf-8") as handle:
            descriptor = -1
            opened = os.fstat(handle.fileno())
            # The descriptor pins either the complete old or complete new
            # regular file across a legitimate atomic replace. O_NOFOLLOW
            # rejects a final-entry symlink without introducing an inode race.
            if not _stat.S_ISREG(opened.st_mode):
                raise RuntimeError(
                    f"atomic pointer secure open is not a regular file: {index}")
            record = json.loads(handle.read())
    except Exception as exc:
        raise RuntimeError(
            f"cannot read atomic pointer {index}: {type(exc).__name__}: {exc}") from exc
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    return _repair_validate_pointer_record(
        record, index_path=index, expected_role=expected_role)


def _repair_select_pointer_record(save_dir, *, prefer_training=True):
    save = Path(save_dir)
    names = (
        (("training_latest.json", "training"), ("latest.json", "public"))
        if prefer_training else (("latest.json", "public"),)
    )
    for name, role in names:
        index = save / name
        if not index.is_file():
            continue
        # Existing-but-invalid is a stop condition: never mtime-fallback to a
        # structurally complete but quarantined checkpoint.
        return _repair_read_pointer_record(index, expected_role=role)
    return None
def _repair_publish_pointer_bundle_v1_unsafe(
    save_dir, training_payload, public_latest_payload, public_pointer,
    public_tokenizer_payload,
):
    raise RuntimeError("retired unsafe mutable pointer publisher")
    """Strictly publish tokenizer+training pointers, with latest.json last.

    All files live in the candidate save directory even when the quality gate
    selects a safe checkpoint from another directory. Staged digests are checked
    before publication and published files are rolled back on any exception.
    """
    save_dir = Path(save_dir)
    public_pointer = str(public_pointer)
    tokenizer_data = dict(public_tokenizer_payload or {})
    if tokenizer_data.get("tokenizer_json") and not tokenizer_data.get("tokenizer_payload_schema"):
        tokenizer_data["tokenizer_payload_schema"] = 2
    tokenizer_data.setdefault("tokenizer_payload_schema", 2)
    tokenizer_data["checkpoint_name"] = Path(public_pointer).name
    tokenizer_data["checkpoint_path"] = public_pointer
    tokenizer_bytes = json.dumps(
        tokenizer_data, ensure_ascii=False, sort_keys=True
    ).encode("utf-8")
    tokenizer_sha256 = hashlib.sha256(tokenizer_bytes).hexdigest()

    public_payload = dict(public_latest_payload)
    public_payload.update({
        "tokenizer_pointer_path": str(save_dir / "latest.tokenizer.json"),
        "tokenizer_pointer_sha256": tokenizer_sha256,
        "tokenizer_checkpoint_path": public_pointer,
    })
    training_bytes = (
        json.dumps(training_payload, indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    latest_bytes = (
        json.dumps(public_payload, indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    targets = (
        (save_dir / "latest.tokenizer.json", tokenizer_bytes),
        (save_dir / "training_latest.json", training_bytes),
        (save_dir / "latest.json", latest_bytes),
    )
    nonce = f"{os.getpid()}.{time.time_ns()}"
    staged = {}
    previous = {}
    published = []

    def _strict_stage(out, payload):
        tmp = out.with_name(out.name + f".tmp.{nonce}")
        with open(tmp, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        expected = hashlib.sha256(payload).hexdigest()
        if _sha256_file(tmp) != expected:
            raise RuntimeError(f"staged pointer checksum mismatch: {tmp}")
        staged[out] = (tmp, expected)

    def _strict_restore(out, prior):
        if prior is None:
            if out.exists():
                out.unlink()
            return
        rollback = out.with_name(out.name + f".rollback.{nonce}")
        with open(rollback, "wb") as handle:
            handle.write(prior)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(rollback, out)
        if _sha256_file(out) != hashlib.sha256(prior).hexdigest():
            raise RuntimeError(f"pointer rollback checksum mismatch: {out}")

    try:
        save_dir.mkdir(parents=True, exist_ok=True)
        for out, payload in targets:
            previous[out] = out.read_bytes() if out.exists() else None
            _strict_stage(out, payload)
        # Public latest is deliberately last. A failure restores every pointer.
        for out, _payload in targets:
            tmp, expected = staged[out]
            os.replace(tmp, out)
            published.append(out)
            if _sha256_file(out) != expected:
                raise RuntimeError(f"published pointer checksum mismatch: {out}")
    except Exception as exc:
        rollback_errors = []
        for out in reversed(published):
            try:
                _strict_restore(out, previous[out])
            except Exception as rollback_exc:
                rollback_errors.append(f"{out}: {rollback_exc}")
        detail = "" if not rollback_errors else "; rollback errors=" + " | ".join(rollback_errors)
        raise RuntimeError(f"repair pointer bundle publication failed: {exc}{detail}") from exc
    finally:
        for tmp, _expected in staged.values():
            try:
                tmp.unlink()
            except FileNotFoundError:
                pass
    return public_payload


def _repair_publish_pointer_bundle(
    save_dir, training_payload, training_pointer, training_tokenizer_payload,
    public_latest_payload, public_pointer, public_tokenizer_payload,
):
    """Publish independent crash-safe commits; public ``latest.json`` is last.

    Immutable tokenizer artifacts are durable before either pointer names them.
    There is intentionally no multi-file rollback assumption: after a crash at
    any boundary, every visible record remains independently complete.
    """
    save_dir = Path(save_dir)
    save_dir.mkdir(parents=True, exist_ok=True)
    _fsync_directory(save_dir.parent)
    import fcntl
    lock_path = save_dir / ".pointer.publish.lock"
    with open(lock_path, "a+b") as lock:
        lock.flush()
        os.fsync(lock.fileno())
        fcntl.flock(lock.fileno(), fcntl.LOCK_EX)
        _fsync_directory(save_dir)
        training_record = _repair_pointer_record(
            training_payload, "training", training_pointer,
            training_tokenizer_payload, save_dir,
        )
        _repair_test_crash_boundary("training_tokenizer")
        public_record = _repair_pointer_record(
            public_latest_payload, "public", public_pointer,
            public_tokenizer_payload, save_dir,
        )
        _repair_test_crash_boundary("public_tokenizer")
        training_bytes = (
            json.dumps(training_record, indent=2, sort_keys=True, allow_nan=False) + "\n"
        ).encode("utf-8")
        latest_bytes = (
            json.dumps(public_record, indent=2, sort_keys=True, allow_nan=False) + "\n"
        ).encode("utf-8")
        training_index = save_dir / "training_latest.json"
        latest_index = save_dir / "latest.json"
        _atomic_write_bytes_fsync(training_index, training_bytes)
        _repair_read_pointer_record(training_index, expected_role="training")
        _repair_test_crash_boundary("training_latest")
        # Sole public commit point: readers see the complete old or new record.
        _atomic_write_bytes_fsync(latest_index, latest_bytes)
        _repair_read_pointer_record(latest_index, expected_role="public")
        _repair_test_crash_boundary("latest")
        _fsync_directory(save_dir)
    return public_record


def _agillm43_quality_gate_latest_payload_v1_unsafe(path: Path, meta: dict, proposed: dict):
    raise RuntimeError("retired unsafe mtime/existence quality-gate fallback")
    """Keep latest.json pinned when a quality gate requires review of newer checkpoints."""
    gate_path = Path(os.environ.get("AGILLM43_QUALITY_GATE", "/workspace/agillm43_quality_gate.json"))
    if not gate_path.exists():
        if _AGILLM_REPAIR_ACTIVE:
            return None, f"quality gate is missing: {gate_path}"
        return proposed, None
    try:
        gate = json.loads(gate_path.read_text(encoding="utf-8"))
    except Exception as exc:
        if _AGILLM_REPAIR_ACTIVE:
            return None, f"could not read quality gate {gate_path}: {exc}"
        return proposed, f"could not read quality gate {gate_path}: {exc}; latest.json updated normally"
    if not isinstance(gate, dict) or not gate.get("require_auto_infer_ok", False):
        if _AGILLM_REPAIR_ACTIVE:
            return None, f"quality gate is inactive or invalid: {gate_path}"
        return proposed, None
    try:
        step = int(meta.get("step") or proposed.get("step") or 0)
    except Exception:
        step = 0
    try:
        max_promoted = int(gate.get("max_promoted_delta_step") or 0)
    except Exception:
        max_promoted = 0
    if max_promoted <= 0:
        if _AGILLM_REPAIR_ACTIVE:
            return None, f"quality gate has non-positive max_promoted_delta_step={max_promoted}"
        return proposed, None
    if step <= max_promoted:
        return proposed, None

    latest_file = path.parent / "latest.json"
    existing = {}
    if latest_file.exists():
        try:
            loaded = json.loads(latest_file.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                existing = loaded
        except Exception:
            existing = {}
    pinned = str(gate.get("pinned_delta") or gate.get("pinned_resume_delta") or "")
    promoted = str(gate.get("last_promoted_checkpoint") or gate.get("last_promoted_full_checkpoint") or "")
    safe = {}
    existing_path = Path(str(existing.get("path") or existing.get("checkpoint_path") or existing.get("raw_path") or ""))
    try:
        existing_step = int(existing.get("step") or 0)
    except Exception:
        existing_step = 0
    promoted_path = Path(promoted) if promoted else None
    if promoted_path is not None and promoted_path.exists() and existing_path != promoted_path:
        safe = dict(existing)
        safe["path"] = str(promoted_path)
        safe["checkpoint_path"] = str(promoted_path)
        safe["checkpoint_name"] = promoted_path.name
        safe["step"] = max_promoted
    elif existing_path.exists() and existing_step > 0 and existing_step <= max_promoted:
        safe = dict(existing)
    else:
        for value in (promoted, pinned):
            candidate = Path(value) if value else None
            if candidate is not None and candidate.exists():
                safe = dict(existing)
                safe["path"] = str(candidate)
                safe["checkpoint_path"] = str(candidate)
                safe["checkpoint_name"] = candidate.name
                safe["step"] = max_promoted
                break
    if not safe.get("path"):
        if _AGILLM_REPAIR_ACTIVE:
            return None, "quality gate required a pin but no safe checkpoint was available"
        return proposed, "quality gate wanted to pin latest.json, but no existing, promoted, or pinned checkpoint was available"
    safe.update({
        "candidate_under_review": str(path),
        "candidate_step": step,
        "candidate_block_reason": f"step {step} is above quality gate max_promoted_delta_step={max_promoted}",
        "updated_by": "agillm43_quality_gate_save_guard",
    })
    return safe, safe["candidate_block_reason"]


def _repair_cross_dir_public_payload(checkpoint_path):
    """Resolve only a pinned seed or a fully validated child public commit."""
    candidate = Path(checkpoint_path).expanduser().resolve()
    reference = _repair_checkpoint_reference(candidate)
    step = _repair_resume_step_from_path(candidate)
    if step == _AGILLM43_REPAIR_BASE_STEP:
        if reference["sha256"] != _AGILLM43_REPAIR_SEED_SHA256:
            raise RuntimeError("cross-directory base checkpoint is not the pinned seed")
        return {
            "path": str(candidate),
            "checkpoint_path": str(candidate),
            "checkpoint_name": candidate.name,
            "step": int(step),
            "repair_lineage_schema": _AGILLM_REPAIR_LINEAGE_SCHEMA,
            "repair_base_step": _AGILLM43_REPAIR_BASE_STEP,
            "repair_seed_sha256": _AGILLM43_REPAIR_SEED_SHA256,
            "repair_checkpoint_step": int(step),
            "checkpoint_manifest_sha256": reference["sha256"],
        }
    index = candidate.parent / "latest.json"
    record = _repair_read_pointer_record(index, expected_role="public")
    if os.path.abspath(record["checkpoint"]["path"]) != os.path.abspath(str(candidate)):
        raise RuntimeError("cross-directory public commit names a different checkpoint")
    return dict(record)


def _agillm43_quality_gate_latest_payload(path: Path, meta: dict, proposed: dict):
    """Return a fully validated public payload or fail closed."""
    gate_path = Path(os.environ.get(
        "AGILLM43_QUALITY_GATE", "/workspace/agillm43_quality_gate.json"))
    if not gate_path.exists():
        if _AGILLM_REPAIR_ACTIVE:
            return None, f"quality gate is missing: {gate_path}"
        return proposed, None
    try:
        gate = json.loads(gate_path.read_text(encoding="utf-8"))
    except Exception as exc:
        if _AGILLM_REPAIR_ACTIVE:
            return None, f"could not read quality gate {gate_path}: {exc}"
        return proposed, f"could not read quality gate {gate_path}: {exc}; latest.json updated normally"
    if not isinstance(gate, dict) or not gate.get("require_auto_infer_ok", False):
        if _AGILLM_REPAIR_ACTIVE:
            return None, f"quality gate is inactive or invalid: {gate_path}"
        return proposed, None
    try:
        step = int(meta.get("step") or proposed.get("step") or 0)
        max_promoted = int(gate.get("max_promoted_delta_step") or 0)
    except Exception:
        step, max_promoted = 0, 0
    if max_promoted <= 0:
        if _AGILLM_REPAIR_ACTIVE:
            return None, f"quality gate has non-positive max_promoted_delta_step={max_promoted}"
        return proposed, None
    if step <= max_promoted:
        return proposed, None

    latest_file = path.parent / "latest.json"
    safe = None
    if latest_file.is_file():
        try:
            existing = _repair_read_pointer_record(latest_file, expected_role="public")
        except Exception as exc:
            return None, f"existing public commit is invalid: {type(exc).__name__}: {exc}"
        if int(existing.get("step", 0) or 0) <= max_promoted:
            safe = dict(existing)
    if safe is None:
        promoted = str(gate.get("last_promoted_checkpoint") or gate.get("last_promoted_full_checkpoint") or "")
        pinned = str(gate.get("pinned_delta") or gate.get("pinned_resume_delta") or "")
        errors = []
        for raw in (promoted, pinned):
            if not raw:
                continue
            try:
                checked = _repair_cross_dir_public_payload(raw)
                if int(checked.get("step", 0) or 0) <= max_promoted:
                    safe = checked
                    break
                errors.append(f"{raw}: step exceeds max promoted")
            except Exception as exc:
                errors.append(f"{raw}: {type(exc).__name__}: {exc}")
        if safe is None:
            suffix = "" if not errors else "; " + " | ".join(errors)
            return None, "quality gate required a pin but no digest+lineage validated public checkpoint was available" + suffix
    safe.update({
        "candidate_under_review": str(path),
        "candidate_step": step,
        "candidate_block_reason": (
            f"step {step} is above quality gate max_promoted_delta_step={max_promoted}"),
        "updated_by": "agillm43_atomic_quality_gate_save_guard",
    })
    return safe, safe["candidate_block_reason"]


_AGILLM43_TRAINING_POINTER_SCHEMA = "agillm43.training.resume.v2"

def _agillm43_continuation_pointer_sha256(payload):
    body = dict(payload)
    body.pop("record_sha256", None)
    raw = json.dumps(
        body, ensure_ascii=False, sort_keys=True, separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()

def _agillm43_continuation_package_receipt(path, meta, checkpoint_tokenizer_payload):
    """Validate a completed long-training package without repair-endpoint limits."""
    import stat as _stat
    path = Path(path).expanduser().resolve()
    unresolved = Path(path)
    if unresolved.is_symlink() or not unresolved.is_file():
        raise RuntimeError(f"training checkpoint is unavailable or a symlink: {path}")
    st = path.stat()
    if not _stat.S_ISREG(st.st_mode) or int(st.st_size) <= 0:
        raise RuntimeError(f"training checkpoint is not a non-empty regular file: {path}")
    step = _dblock_require_exact_int(meta.get("step"), "training pointer step", minimum=0)
    seen_tok = _dblock_require_exact_int(
        meta.get("seen_tok"), "training pointer seen_tok", minimum=0)
    package_format = "single-file"
    shard_dir_value = ""
    shards = []
    manifest = torch.load(path, map_location="cpu", weights_only=False)
    if (isinstance(manifest, dict)
            and manifest.get(_AGILLM43_SHARDED_CODEC_MAGIC) == _AGILLM43_SHARDED_CODEC_MAGIC):
        package_format = "block-sharded"
        shard_dir_value = str(manifest.get("shard_dir") or "")
        if (not shard_dir_value or Path(shard_dir_value).name != shard_dir_value
                or shard_dir_value in {".", ".."}):
            raise RuntimeError("training checkpoint has a noncanonical shard directory")
        shard_dir = path.parent / shard_dir_value
        if shard_dir.is_symlink() or not shard_dir.is_dir():
            raise RuntimeError(f"training shard directory is unavailable or a symlink: {shard_dir}")
        entries = manifest.get("entries")
        if not isinstance(entries, list) or not entries:
            raise RuntimeError("training checkpoint has no shard manifest entries")
        seen_names = set()
        for entry in entries:
            if not isinstance(entry, dict):
                raise RuntimeError("training checkpoint shard entry is not an object")
            name = str(entry.get("shard") or "")
            if (not name or Path(name).name != name or name in {".", ".."}
                    or name in seen_names):
                raise RuntimeError(f"training checkpoint has an invalid shard name: {name!r}")
            seen_names.add(name)
            item = shard_dir / name
            if item.is_symlink() or not item.is_file():
                raise RuntimeError(f"training checkpoint shard is unavailable or a symlink: {item}")
            nbytes = _dblock_require_exact_int(
                entry.get("nbytes"), f"training shard {name} nbytes", minimum=1)
            digest = str(entry.get("sha256") or "")
            if not re.fullmatch(r"[0-9a-f]{64}", digest):
                raise RuntimeError(f"training shard {name} has no valid sha256")
            actual_size = int(item.stat().st_size)
            if actual_size != nbytes:
                raise RuntimeError(
                    f"training shard {name} size mismatch: {actual_size} != {nbytes}")
            shards.append({
                "name": name, "nbytes": nbytes, "sha256": digest,
                "path": str(item.resolve()),
            })
        skeleton = manifest.get("skeleton")
        if not isinstance(skeleton, dict):
            raise RuntimeError("training checkpoint has no sharded skeleton")
        manifest_step = _dblock_require_exact_int(
            skeleton.get("step"), "training checkpoint skeleton step", minimum=0)
        manifest_seen = _dblock_require_exact_int(
            skeleton.get("seen_tok"), "training checkpoint skeleton seen_tok", minimum=0)
        if manifest_step != step or manifest_seen != seen_tok:
            raise RuntimeError(
                f"training checkpoint counters disagree with save metadata: "
                f"step {manifest_step}/{step}, seen_tok {manifest_seen}/{seen_tok}")
    sidecar = Path(str(path) + ".tokenizer.json")
    if sidecar.is_symlink() or not sidecar.is_file():
        raise RuntimeError(f"training checkpoint tokenizer sidecar is unavailable: {sidecar}")
    sidecar_payload = json.loads(sidecar.read_text(encoding="utf-8"))
    if os.path.abspath(str(sidecar_payload.get("checkpoint_path") or "")) != os.path.abspath(str(path)):
        raise RuntimeError("training tokenizer sidecar is bound to a different checkpoint")
    runtime_backend = str(checkpoint_tokenizer_payload.get("tokenizer_json") or "")
    sidecar_backend = str(sidecar_payload.get("tokenizer_json") or "")
    if (not runtime_backend or runtime_backend != sidecar_backend
            or hashlib.sha256(runtime_backend.encode("utf-8")).hexdigest()
            != _AGILLM43_REPAIR_TOKENIZER_BACKEND_SHA256):
        raise RuntimeError("training checkpoint tokenizer backend binding mismatch")
    receipt = {
        "schema": _AGILLM43_TRAINING_POINTER_SCHEMA,
        "role": "training",
        "path": str(path),
        "checkpoint_path": str(path),
        "checkpoint_name": path.name,
        "step": step,
        "seen_tok": seen_tok,
        "checkpoint_main_nbytes": int(st.st_size),
        "checkpoint_main_sha256": _sha256_file(path),
        "package_format": package_format,
        "shard_dir": shard_dir_value,
        "shards": shards,
        "tokenizer_sidecar_path": str(sidecar.resolve()),
        "tokenizer_sidecar_nbytes": int(sidecar.stat().st_size),
        "tokenizer_sidecar_sha256": _sha256_file(sidecar),
        "quality_gate_used_for_training": False,
        "saved_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
    }
    continuation_state = meta.get("continuation_dblock_resume_state")
    if isinstance(continuation_state, dict):
        receipt.update({
            "continuation_state_schema": continuation_state.get("schema"),
            "continuation_state_sha256": continuation_state.get("sha256"),
            "dblock_committed_step": int(
                continuation_state.get("committed_step", 0) or 0
            ),
        })
    target_route = meta.get("continuation_dblock_target_route_state")
    if isinstance(target_route, dict):
        unsigned_route = {
            key: value for key, value in target_route.items() if key != "sha256"
        }
        if str(target_route.get("sha256") or "") != _dblock_target_route_digest(
            unsigned_route
        ):
            raise RuntimeError("training pointer target-route payload digest mismatch")
        route_state = target_route.get("state")
        if not isinstance(route_state, dict):
            raise RuntimeError("training pointer target-route state is missing")
        receipt.update({
            "dblock_target_route_schema": target_route.get("schema"),
            "dblock_target_route_payload_sha256": target_route.get("sha256"),
            "dblock_target_route_policy_id": target_route.get("policy_id"),
            "dblock_target_route_policy_sha256": target_route.get(
                "policy_sha256"
            ),
            "dblock_target_route_controller_source_sha256": target_route.get(
                "controller_source_sha256"
            ),
            "dblock_target_route_topology_sha256": target_route.get(
                "topology_sha256"
            ),
            "dblock_target_route_target_map_sha256": target_route.get(
                "target_map_sha256"
            ),
            "dblock_target_route_clock": int(
                route_state.get("route_commit_clock", 0) or 0
            ),
            "dblock_target_route_offset": int(
                route_state.get("route_offset", 0) or 0
            ),
            "dblock_target_route_pending_target": _dblock_json_copy(
                route_state.get("pending_target")
            ),
            "dblock_target_route_last_committed_target": _dblock_json_copy(
                route_state.get("last_committed_target")
            ),
        })
    validation_state = meta.get("quality_validation_state")
    if isinstance(validation_state, dict):
        receipt["quality_validation_checks"] = int(
            validation_state.get("checks", 0) or 0
        )
        receipt["quality_validation_bad_checks"] = int(
            validation_state.get("bad_checks", 0) or 0
        )
    return receipt

def _agillm43_publish_training_pointer(save_dir, path, meta, checkpoint_tokenizer_payload):
    """Commit the newest structurally complete crash-resume target independently."""
    import fcntl
    save_dir = Path(save_dir)
    save_dir.mkdir(parents=True, exist_ok=True)
    _fsync_directory(save_dir.parent)
    lock_path = save_dir / ".training.pointer.lock"
    with open(lock_path, "a+b") as lock:
        lock.flush()
        os.fsync(lock.fileno())
        fcntl.flock(lock.fileno(), fcntl.LOCK_EX)
        record = _agillm43_continuation_package_receipt(
            path, meta, checkpoint_tokenizer_payload)
        record["record_sha256"] = _agillm43_continuation_pointer_sha256(record)
        raw = (json.dumps(record, indent=2, sort_keys=True, allow_nan=False) + "\n").encode("utf-8")
        receipts = save_dir / "training_pointer_receipts"
        if receipts.is_symlink():
            raise RuntimeError("training pointer receipt directory is a symlink")
        receipts.mkdir(parents=True, exist_ok=True)
        _fsync_directory(save_dir)
        immutable = receipts / (
            f"step{int(record['step']):012d}.{record['record_sha256']}.json")
        if immutable.exists():
            if immutable.is_symlink() or immutable.read_bytes() != raw:
                raise RuntimeError(f"immutable training pointer receipt collision: {immutable}")
        else:
            _atomic_write_bytes_fsync(immutable, raw)
        _fsync_directory(receipts)
        latest = save_dir / "training_latest.json"
        previous = save_dir / "training_previous.json"
        if latest.is_file() and not latest.is_symlink():
            previous_raw = latest.read_bytes()
            try:
                previous_record = json.loads(previous_raw.decode("utf-8"))
                if (previous_record.get("schema") == _AGILLM43_TRAINING_POINTER_SCHEMA
                        and previous_record.get("record_sha256")
                        == _agillm43_continuation_pointer_sha256(previous_record)):
                    _atomic_write_bytes_fsync(previous, previous_raw)
            except Exception:
                pass
        _atomic_write_bytes_fsync(latest, raw)
        check = json.loads(latest.read_text(encoding="utf-8"))
        if (check.get("record_sha256") != record["record_sha256"]
                or check.get("record_sha256")
                != _agillm43_continuation_pointer_sha256(check)):
            raise RuntimeError("published training pointer failed checksum validation")
        _fsync_directory(save_dir)
        return record

def _agillm43_publish_serving_candidate(save_dir, candidate_payload, training_record):
    """Expose a serving candidate without allowing serving policy to block training."""
    payload = dict(candidate_payload or {})
    payload.update({
        "schema": "agillm43.serving.candidate.v1",
        "promotion_required": True,
        "training_pointer_schema": training_record["schema"],
        "training_pointer_sha256": training_record["record_sha256"],
        "quality_gate_used_for_training": False,
        "saved_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
    })
    raw = (json.dumps(payload, indent=2, sort_keys=True, allow_nan=False) + "\n").encode("utf-8")
    _atomic_write_bytes_fsync(Path(save_dir) / "serving_candidate.json", raw)
    _fsync_directory(Path(save_dir))
    return payload

def save_ckpt(path: pathlib.Path, core, ar_h, sat_h, nat_h, opt, scaler, meta, codec: str = "zstd", provenance=None):
    repair_manifest_sha256 = ""
    repair_pointer_block_reason = None
    if _AGILLM_REPAIR_ACTIVE:
        checkpoint_step = _dblock_require_exact_int(
            meta.get("step"), "repair save checkpoint step",
            minimum=_AGILLM43_REPAIR_BASE_STEP,
            maximum=_AGILLM43_REPAIR_TARGET_STEP,
        )
        path_step = _repair_resume_step_from_path(path)
        if path_step is None or path_step != checkpoint_step:
            raise ValueError(
                f"repair checkpoint filename step {path_step} != metadata step {checkpoint_step}")
        if str(meta.get("repair_lineage_schema") or "") != _AGILLM_REPAIR_LINEAGE_SCHEMA:
            raise ValueError("repair checkpoint is missing lineage schema")
        _dblock_require_exact_int(
            meta.get("repair_base_step"), "repair save base step",
            minimum=_AGILLM43_REPAIR_BASE_STEP,
            maximum=_AGILLM43_REPAIR_BASE_STEP,
        )
        if str(meta.get("repair_seed_sha256") or "") != _AGILLM43_REPAIR_SEED_SHA256:
            raise ValueError("repair checkpoint has wrong immutable seed digest")
        _dblock_require_exact_int(
            meta.get("repair_checkpoint_step"), "repair save metadata step",
            minimum=checkpoint_step, maximum=checkpoint_step,
        )
        for name, expected in (
            ("repair_target_commits", _AGILLM43_REPAIR_TARGET_COMMITS),
            ("repair_target_step", _AGILLM43_REPAIR_TARGET_STEP),
            ("repair_target_seen_tok", _AGILLM43_REPAIR_TARGET_SEEN_TOK),
        ):
            _dblock_require_exact_int(
                meta.get(name), f"repair save {name}",
                minimum=expected, maximum=expected,
            )
        contract = meta.get("repair_contract")
        contract_digest = str(meta.get("repair_contract_sha256") or "")
        if contract_digest != _repair_contract_sha256(contract):
            raise ValueError("repair checkpoint contract digest is inconsistent")
        _repair_validate_resolved_architecture(
            meta.get("cfg"), meta.get("tie_weights"),
            contract=contract, contract_sha256=contract_digest,
            receipt=meta.get("repair_resolved_architecture"),
            receipt_sha256=meta.get("repair_resolved_architecture_sha256"),
            require_receipt=True, context="checkpoint save",
        )
        _dblock_validate_resume_payload(
            meta.get("dblock_resume_state"), checkpoint_step)
        _repair_validate_token_clocks({
            "repair_base_seen_tok": meta.get("repair_base_seen_tok"),
            "seen_tok": meta.get("seen_tok"),
            "lr_schedule_origin_tok": _AGILLM_LR_SCHEDULE_ORIGIN_TOK,
        }, checkpoint_step)
        _repair_validate_validation_state(
            meta.get("repair_validation_state"), checkpoint_step,
            require_authoritative=True,
        )
        repair_pointer_block_reason = _repair_pointer_block_reason(meta, checkpoint_step)
        if provenance is not None:
            provenance = dict(provenance)
            base_seen = int(meta["repair_base_seen_tok"])
            seen_tok = int(meta.get("seen_tok", 0) or 0)
            provenance.update({
                "local_step": checkpoint_step - _AGILLM43_REPAIR_BASE_STEP,
                "global_origin_step": _AGILLM43_REPAIR_BASE_STEP,
                "warmstart_base_step": _AGILLM43_REPAIR_BASE_STEP,
                "effective_global_step": checkpoint_step,
                "global_origin_seen_tok": base_seen,
                "warmstart_base_seen_tok": base_seen,
                "effective_seen_tok": seen_tok,
                "repair_schema": _AGILLM_REPAIR_SCHEMA,
                "repair_contract_sha256": contract_digest,
            })
    path.parent.mkdir(exist_ok=True, parents=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tokenizer_payload = _tokenizer_payload()
    tokenizer_payload.setdefault("tokenizer_payload_schema", 2)
    state = {
        "core": _checkpoint_state_dict(core), "ar": _checkpoint_state_dict(ar_h), "sat": _checkpoint_state_dict(sat_h),
        "opt": opt.state_dict(), "scaler": scaler.state_dict(),
        "cfg": meta.get("cfg"),
        "alibi_mode": str(_AGILLM_ALIBI_MODE),
        "alibi_scale": float(_AGILLM_ALIBI_SCALE),
        "lr_schedule_origin_tok": int(_AGILLM_LR_SCHEDULE_ORIGIN_TOK),
        "repair_schema": _AGILLM_REPAIR_SCHEMA if _AGILLM_REPAIR_ACTIVE else "",
        **tokenizer_payload,
        "transformers_version": __import__("transformers").__version__,
        "tokenizers_version": __import__("tokenizers").__version__,
        "tie_weights": meta.get("tie_weights", False),
        **{k: v for k, v in meta.items() if k not in ("cfg", "tie_weights")}
    }
    state.update(_nat_mask_contract_payload())
    if nat_h is not None:
        state["nat"] = _checkpoint_state_dict(nat_h)
    ckpt_codec = str(codec or "off")
    state["agillm43_ckpt_codec"] = ckpt_codec
    if provenance is not None:
        try:
            provenance = dict(provenance)
        except Exception:
            provenance = {"raw_provenance_repr": repr(provenance)}
        provenance.update(_nat_mask_contract_payload())
        source_path = str(provenance.get("warmstart_source_path") or "")
        try:
            save_root = str(path.parent.resolve())
        except Exception:
            save_root = str(path.parent)
        if not source_path:
            warmstart_kind = "from_scratch"
        else:
            source_abs = os.path.abspath(source_path)
            save_abs = os.path.abspath(save_root)
            master_marker = f"{os.sep}agillm4_v100_master_ckpts{os.sep}"
            if master_marker in source_abs:
                warmstart_kind = "warmstarted_from_master"
            elif source_abs.startswith(save_abs + os.sep):
                warmstart_kind = "warmstarted_from_lane_checkpoint"
            else:
                warmstart_kind = "warmstarted_from_non_master_checkpoint"
        provenance["checkpoint_path"] = str(path)
        provenance["warmstart_kind"] = warmstart_kind
        provenance["created_from_scratch"] = warmstart_kind == "from_scratch"
        provenance["source_is_master_checkpoint"] = warmstart_kind == "warmstarted_from_master"
        provenance["source_is_lane_checkpoint"] = warmstart_kind == "warmstarted_from_lane_checkpoint"
        provenance["source_is_non_master_checkpoint"] = warmstart_kind == "warmstarted_from_non_master_checkpoint"
        state["agillm43_provenance"] = provenance
        state["agillm43_warmstart_kind"] = warmstart_kind
        state["agillm43_warmstart_source_path"] = source_path
        state["agillm43_checkpoint_summary"] = f"{warmstart_kind}; source={source_path or 'none'}; path={path}"
    info = _agillm43_save_pt(state, tmp, codec=ckpt_codec, zstd_level=1)
    _agillm43_finalize_pt_save(tmp, path, info)
    if _AGILLM_REPAIR_ACTIVE:
        repair_manifest_sha256 = _repair_write_manifest_sidecar(path)
    checkpoint_tokenizer_payload = {k: state.get(k) for k in ("tokenizer_payload_schema", "tokenizer_id", "tokenizer_json", "tokenizer_bundle", "tokenizer_special", "transformers_version", "tokenizers_version") if state.get(k) is not None}
    _write_tokenizer_sidecar(
        path, checkpoint_tokenizer_payload, write_latest=not _AGILLM_REPAIR_ACTIVE
    )
    if provenance is not None:
        if _AGILLM_REPAIR_ACTIVE:
            provenance_sidecar = path.with_suffix(".provenance.json")
            provenance_raw = (
                json.dumps(provenance, indent=2, sort_keys=True, allow_nan=False) + "\n"
            ).encode("utf-8")
            _atomic_write_bytes_fsync(provenance_sidecar, provenance_raw)
        else:
            try:
                globals().get("_agillm_provenance").write_sidecar(path, provenance)
            except Exception as exc:
                print(f"[provenance] WARNING: failed to write sidecar for {path}: {exc}")
    latest_payload = {
        "path": str(path), "step": meta["step"],
        "alibi_mode": str(_AGILLM_ALIBI_MODE),
        "alibi_scale": float(_AGILLM_ALIBI_SCALE),
        "lr_schedule_origin_tok": int(_AGILLM_LR_SCHEDULE_ORIGIN_TOK),
        "repair_schema": _AGILLM_REPAIR_SCHEMA if _AGILLM_REPAIR_ACTIVE else "",
    }
    if _AGILLM_REPAIR_ACTIVE:
        dblock_resume = meta["dblock_resume_state"]
        latest_payload.update({
            "repair_lineage_schema": meta["repair_lineage_schema"],
            "repair_base_step": int(meta["repair_base_step"]),
            "repair_seed_sha256": meta["repair_seed_sha256"],
            "repair_base_seen_tok": int(meta["repair_base_seen_tok"]),
            "repair_target_commits": int(meta["repair_target_commits"]),
            "repair_target_step": int(meta["repair_target_step"]),
            "repair_target_seen_tok": int(meta["repair_target_seen_tok"]),
            "repair_checkpoint_step": int(meta["repair_checkpoint_step"]),
            "repair_contract_sha256": meta["repair_contract_sha256"],
            "repair_resolved_architecture_sha256":
                meta["repair_resolved_architecture_sha256"],
            "checkpoint_manifest_sha256": repair_manifest_sha256,
            "dblock_resume_schema": dblock_resume["schema"],
            "dblock_resume_sha256": dblock_resume["sha256"],
            "dblock_committed_step": int(dblock_resume["committed_step"]),
            "repair_validation_state": meta["repair_validation_state"],
        })
    latest_payload.update(_nat_mask_contract_payload())
    if provenance is not None:
        latest_payload["agillm43_provenance"] = provenance
        latest_payload["warmstart_kind"] = provenance.get("warmstart_kind")
        latest_payload["warmstart_source_path"] = provenance.get("warmstart_source_path", "")
        latest_payload["checkpoint_summary"] = state.get("agillm43_checkpoint_summary")
    if meta.get("dataset_provenance"):
        latest_payload["dataset_provenance"] = meta.get("dataset_provenance")
        latest_payload["source_effective"] = meta.get("dataset_provenance", {}).get("source_effective", "")
    # A structurally complete but failed/stale-gate repair checkpoint is
    # quarantined for diagnosis and never becomes the automatic crash-resume target.
    if _AGILLM_REPAIR_ACTIVE and repair_pointer_block_reason:
        _write_quarantine_pointer(path, meta, latest_payload, repair_pointer_block_reason)
        return

    candidate_payload = dict(latest_payload)
    if not _AGILLM_REPAIR_ACTIVE:
        training_record = _agillm43_publish_training_pointer(
            path.parent, path, meta, checkpoint_tokenizer_payload
        )
        _agillm43_publish_serving_candidate(
            path.parent, candidate_payload, training_record
        )
        print(
            f"[training-pointer] committed step={training_record['step']} "
            f"seen_tok={training_record['seen_tok']} without a serving-quality veto",
            flush=True,
        )
        print(
            "[serving-gate] public latest unchanged; candidate recorded for independent promotion",
            flush=True,
        )
        if info.get("codec") == "zstd":
            print(f"\n✓ saved checkpoint {path.name} codec=zstd ratio={info.get('ratio', 0.0):.2f}x")
        elif info.get("codec") == "block-sharded":
            print(f"\n✓ saved checkpoint {path.name} codec=block-sharded shards={info.get('shards', 0)} dir={path.name}.shards")
        else:
            print(f"\n✓ saved checkpoint {path.name} codec=raw")
        return

    # Strict repair pointers remain fail-closed and endpoint-bounded.
    public_latest_payload, latest_gate_reason = _agillm43_quality_gate_latest_payload(
        path, meta, candidate_payload
    )
    if public_latest_payload is None:
        _write_quarantine_pointer(
            path, meta, candidate_payload,
            latest_gate_reason or "latest quality gate rejected candidate",
        )
        return

    public_pointer = str(
        public_latest_payload.get("path")
        or public_latest_payload.get("checkpoint_path")
        or ""
    )
    if not public_pointer:
        _write_quarantine_pointer(path, meta, candidate_payload, "approved latest payload has no checkpoint path")
        return
    if os.path.abspath(public_pointer) == os.path.abspath(str(path)):
        public_tokenizer_payload = checkpoint_tokenizer_payload
    else:
        public_tokenizer_payload = _read_tokenizer_sidecar(public_pointer)
        sidecar_checkpoint = str(public_tokenizer_payload.get("checkpoint_path") or "")
        if (not public_tokenizer_payload) or os.path.abspath(sidecar_checkpoint) != os.path.abspath(public_pointer):
            _write_quarantine_pointer(
                path, meta, candidate_payload,
                f"safe public checkpoint lacks matching tokenizer sidecar: {public_pointer}",
            )
            return

    training_payload = dict(candidate_payload)
    training_payload.update({
        "schema": "agillm43.training_latest.v1",
        "quality_approved": False,
        "saved_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
    })
    public_latest_payload = _repair_publish_pointer_bundle(
        path.parent, training_payload, str(path), checkpoint_tokenizer_payload,
        public_latest_payload, public_pointer, public_tokenizer_payload,
    )
    if latest_gate_reason:
        print(f"[quality-gate] kept latest.json pinned; candidate under review: {latest_gate_reason}", flush=True)
    if info.get("codec") == "zstd":
        print(f"\n✓ saved checkpoint {path.name} codec=zstd ratio={info.get('ratio', 0.0):.2f}x")
    elif info.get("codec") == "block-sharded":
        print(f"\n✓ saved checkpoint {path.name} codec=block-sharded shards={info.get('shards', 0)} dir={path.name}.shards")
    else:
        print(f"\n✓ saved checkpoint {path.name} codec=raw")

def load_ckpt(path, core, ar_h, sat_h, opt, scaler, nat_h=None,
              load_optimizer=True, meta_out=None, *,
              nat_mask_token_id=None,
              migrate_nat_mask_embedding=False,
              detachable_50m_runtime=None):
    p = _resolve_ckpt(path) or path
    skip_keys = {"opt", "scaler"} if not bool(load_optimizer) else None
    ck = _try_load(p, map_location="cpu", skip_keys=skip_keys)
    if ck is None: raise FileNotFoundError(f"No valid checkpoint at {p}")
    popup_manifest_present = isinstance(ck.get(_DET50_MANIFEST_KEY), dict)
    popup_state_present = any(key in ck for key in _DET50_STATE_KEYS)
    if popup_manifest_present != popup_state_present:
        raise RuntimeError(
            "detachable-50m manifest/state presence mismatch; refusing partial suite")
    popup_state_loaded = False
    if popup_manifest_present:
        if detachable_50m_runtime is None:
            raise RuntimeError(
                "checkpoint contains detachable-50m suite state but no popup runtime was allocated")
        detachable_50m_runtime.restore(ck)
        popup_state_loaded = True
    core.load_state_dict(_prepare_core_state_dict_for_load(core, ck["core"]))
    _load_module_state_compatible(ar_h, ck.get("ar", {}), "ar")
    _load_module_state_compatible(sat_h, ck.get("sat", {}), "sat")
    if nat_h is not None:
        if "nat" in ck:
            _load_module_state_compatible(nat_h, ck["nat"], "nat")
        else:
            print("[nat] Checkpoint has no NAT head; keeping fresh NAT initialization")
    _contract, _migration = _configure_nat_mask_contract(
        ck,
        explicit_id=nat_mask_token_id,
        optimizer_reset=not bool(load_optimizer),
        migration_requested=bool(migrate_nat_mask_embedding),
    )
    if _migration is not None:
        _migrate_nat_mask_embedding_row(core, *_migration)
    print(
        f"[nat-mask] schema={_contract['schema_version']} "
        f"id={_contract['token_id']} source={_contract['source']}",
        flush=True,
    )
    opt_state_loaded = False
    scaler_state_loaded = False
    optimizer_state_error = ""
    scaler_state_error = ""
    if not load_optimizer:
        print("[ckpt] optimizer/scaler reset requested for changed repair objective")
    elif opt.__class__.__name__ == "PowerStep":
        optimizer_state_error = "PowerStep child optimizer restore is unsupported"
        print("[ckpt] PowerStep optimizer selected; resetting checkpoint optimizer state")
    else:
        opt_state = _hc_adapt_opt_state(opt, ck.get("opt"))
        compatible, reason = _optimizer_state_compatibility_reason(opt_state, opt)
        if not compatible:
            optimizer_state_error = str(reason)
            print(f"[ckpt] WARNING: optimizer state incompatible; resetting optimizer ({reason})")
        else:
            try:
                opt.load_state_dict(opt_state)
                opt_state_loaded = True
            except Exception as exc:
                fused_opt = _fuse_legacy_qkv_optimizer_state(opt_state, opt, core, ar_h, sat_h, nat_h)
                if fused_opt is not None:
                    fused_compatible, fused_reason = _optimizer_state_compatibility_reason(fused_opt, opt)
                    if fused_compatible:
                        try:
                            opt.load_state_dict(fused_opt)
                            opt_state_loaded = True
                            print("[ckpt] Converted legacy q/k/v optimizer state to fused qkv layout")
                        except Exception as exc2:
                            optimizer_state_error = (
                                f"{type(exc).__name__}: {exc}; qkv remap failed: "
                                f"{type(exc2).__name__}: {exc2}")
                            print(f"[ckpt] WARNING: optimizer state incompatible; resetting optimizer ({optimizer_state_error})")
                    else:
                        optimizer_state_error = str(fused_reason)
                        print(f"[ckpt] WARNING: fused optimizer state incompatible; resetting optimizer ({fused_reason})")
                else:
                    optimizer_state_error = f"{type(exc).__name__}: {exc}"
                    print(f"[ckpt] WARNING: optimizer state incompatible; resetting optimizer ({type(exc).__name__}: {exc})")
    if opt_state_loaded:
        try:
            scaler.load_state_dict(ck["scaler"])
            scaler_state_loaded = True
        except Exception as exc:
            scaler_state_error = f"{type(exc).__name__}: {exc}"
            print(f"[ckpt] WARNING: scaler state incompatible; resetting scaler ({scaler_state_error})")
    else:
        if load_optimizer and not optimizer_state_error:
            optimizer_state_error = "optimizer state was absent or not loaded"
        print("[ckpt] scaler state reset with optimizer state")
    torch_rng_state_loaded = False
    cuda_rng_state_loaded = False
    python_rng_state_loaded = False
    numpy_rng_state_loaded = False
    try:
        if torch.is_tensor(ck.get("torch_rng_state")):
            torch.set_rng_state(ck["torch_rng_state"])
            torch_rng_state_loaded = True
        if torch.cuda.is_available() and ck.get("cuda_rng_state_all") is not None:
            torch.cuda.set_rng_state_all(ck["cuda_rng_state_all"])
            cuda_rng_state_loaded = True
        if ck.get("python_rng_state") is not None:
            random.setstate(ck["python_rng_state"])
            python_rng_state_loaded = True
        if ck.get("numpy_rng_state") is not None:
            np.random.set_state(ck["numpy_rng_state"])
            numpy_rng_state_loaded = True
    except Exception as exc:
        raise RuntimeError(
            f"checkpoint RNG state is incompatible: {type(exc).__name__}: {exc}"
        ) from exc
    # Restore tokenizer from checkpoint (embedded json preferred; never raises)
    _restore_tokenizer_from_ckpt(ck, p)
    # Warn if transformers version changed since checkpoint was saved
    if "transformers_version" in ck:
        import transformers as _tf
        if ck["transformers_version"] != _tf.__version__:
            print(f"[tokenizer] WARNING: checkpoint saved with transformers={ck['transformers_version']}, now running {_tf.__version__}")
    step = ck.get("step", 0)
    seen_tok = ck.get("seen_tok", 0)
    if _AGILLM_REPAIR_ACTIVE:
        wall_time = _repair_validate_checkpoint_wall_time(ck.get("wall_time"))
    else:
        wall_time = ck.get("wall_time", time.time())
    if meta_out is not None:
        meta_out.update({
            "checkpoint_step": ck.get("step"),
            "checkpoint_seen_tok": ck.get("seen_tok"),
            "checkpoint_wall_time": ck.get("wall_time"),
            "lr_schedule_origin_tok": ck.get("lr_schedule_origin_tok"),
            "repair_schema": ck.get("repair_schema", ""),
            "repair_lineage_schema": ck.get("repair_lineage_schema", ""),
            "repair_base_step": ck.get("repair_base_step"),
            "repair_seed_sha256": ck.get("repair_seed_sha256"),
            "repair_base_seen_tok": ck.get("repair_base_seen_tok"),
            "repair_target_commits": ck.get("repair_target_commits"),
            "repair_target_step": ck.get("repair_target_step"),
            "repair_target_seen_tok": ck.get("repair_target_seen_tok"),
            "repair_checkpoint_step": ck.get("repair_checkpoint_step"),
            "repair_contract": ck.get("repair_contract"),
            "repair_contract_sha256": ck.get("repair_contract_sha256"),
            "repair_dataset_contract": ck.get("repair_dataset_contract"),
            "repair_heldout_contract": ck.get("repair_heldout_contract"),
            "repair_tokenizer_contract": ck.get("repair_tokenizer_contract"),
            "repair_resolved_architecture": ck.get("repair_resolved_architecture"),
            "repair_resolved_architecture_sha256": ck.get("repair_resolved_architecture_sha256"),
            "dblock_resume_state": ck.get("dblock_resume_state"),
            "continuation_dblock_resume_state": ck.get(
                "continuation_dblock_resume_state"
            ),
            "continuation_dblock_router_state": copy.deepcopy(
                ck.get("continuation_dblock_router_state")
            ),
            "continuation_dblock_direct56_state": copy.deepcopy(
                ck.get("continuation_dblock_direct56_state")
            ),
            "continuation_dblock_target_route_state": copy.deepcopy(
                ck.get("continuation_dblock_target_route_state")
            ),
            "agillm43_training_profile": ck.get("agillm43_training_profile", ""),
            "agillm43_sat_variable_gate_feature_schema": ck.get(
                "agillm43_sat_variable_gate_feature_schema", ""
            ),
            "agillm43_sat_variable_gate_feature_migration": copy.deepcopy(
                ck.get("agillm43_sat_variable_gate_feature_migration")
            ),
            "agillm43_semantic_migration": copy.deepcopy(
                ck.get("agillm43_semantic_migration")
            ),
            "agillm5_matryoshka": copy.deepcopy(ck.get("agillm5_matryoshka")),
            "repair_validation_state": ck.get("repair_validation_state"),
            "quality_validation_state": ck.get("quality_validation_state"),
            "training_science": copy.deepcopy(ck.get("training_science")),
            "agillm43_provenance": ck.get("agillm43_provenance"),
            "cfg": ck.get("cfg"),
            "tie_weights": ck.get("tie_weights"),
            "alibi_mode": ck.get("alibi_mode"),
            "alibi_scale": ck.get("alibi_scale"),
            "optimizer_state_load_requested": bool(load_optimizer),
            "optimizer_state_loaded": bool(opt_state_loaded),
            "scaler_state_loaded": bool(scaler_state_loaded),
            "optimizer_state_error": str(optimizer_state_error),
            "scaler_state_error": str(scaler_state_error),
            "optimizer_class": opt.__class__.__name__,
            "scaler_enabled": bool(scaler.is_enabled()) if hasattr(scaler, "is_enabled") else None,
            "torch_rng_state_loaded": bool(torch_rng_state_loaded),
            "cuda_rng_state_loaded": bool(cuda_rng_state_loaded),
            "python_rng_state_loaded": bool(python_rng_state_loaded),
            "numpy_rng_state_loaded": bool(numpy_rng_state_loaded),
            _DET50_MANIFEST_KEY: copy.deepcopy(ck.get(_DET50_MANIFEST_KEY)),
            "detachable_50m_state_loaded": bool(popup_state_loaded),
            "detachable_50m_optimizer_loaded": bool(popup_state_loaded),
            "detachable_50m_scaler_loaded": bool(popup_state_loaded),
            "detachable_50m_rng_loaded": bool(popup_state_loaded),
            **_nat_mask_contract_payload(),
        })
    _agillm43_release_loaded_checkpoint(ck)
    return step, seen_tok, wall_time

def _safe_load_any(path: pathlib.Path, tgt: nn.Module, key: str | None = None):
    p = _resolve_ckpt(path) or path
    if not p.exists(): return 0
    ck = _try_load(p, map_location="cpu")
    if ck is None: return 0
    sd = ck.get(key, ck) if key else ck
    if isinstance(sd, dict) and "state_dict" in sd: sd = sd["state_dict"]
    if isinstance(tgt, Encoder) or key == "core":
        sd = _prepare_core_state_dict_for_load(tgt, sd)
    else:
        sd = _strip_orig_mod_prefix(sd)
        sd = _fuse_qkv_in_state_dict(dict(sd)) if isinstance(sd, dict) else sd
    if not isinstance(sd, dict):
        return 0
    tgt_sd = tgt.state_dict()
    filt = {k: v for k, v in sd.items() if k in tgt_sd and hasattr(v, "shape") and v.shape == tgt_sd[k].shape}
    if filt: tgt.load_state_dict(filt, strict=False)
    return len(filt)


def infer_cfg_from_ckpt(path: pathlib.Path, meta_out=None):
    p = _resolve_ckpt(path) or path
    if not p.exists():
        return None
    # The production block-sharded codec keeps cfg/manifest in the skeleton, so
    # architecture discovery does not need to read model or optimizer shards.
    sd = _try_load(
        p, map_location="cpu",
        skip_keys={"core", "ar", "sat", "nat", "opt", "scaler",
                   *_DET50_STATE_KEYS})
    if sd is None:
        return None
    if meta_out is not None:
        meta_out.update({
            "resolved_checkpoint_path": str(p),
            "agillm5_matryoshka": copy.deepcopy(sd.get("agillm5_matryoshka")),
            _DET50_MANIFEST_KEY: copy.deepcopy(sd.get(_DET50_MANIFEST_KEY)),
            "agillm43_provenance": copy.deepcopy(sd.get("agillm43_provenance")),
            "lr_schedule_origin_tok": sd.get("lr_schedule_origin_tok"),
            "alibi_mode": sd.get("alibi_mode"),
            "alibi_scale": sd.get("alibi_scale"),
            "tie_weights": sd.get("tie_weights"),
            "step": sd.get("step"),
            "seen_tok": sd.get("seen_tok"),
        })
    if "cfg" in sd:
        return dict(sd["cfg"])
    return None


def _infer_cfg_from_delta_checkpoint(sd: dict) -> tuple[dict, bool, str]:
    """Infer model config for weight-only delta checkpoints.

    Delta checkpoints intentionally omit optimizer/scaler and can omit cfg. Native
    inference still needs the original architecture. Recover it from provenance
    when possible, then validate/fill from tensor shapes.
    """
    weights = sd.get("weights") or {}
    core = weights.get("core") or {}
    ar = weights.get("ar") or {}
    emb = core.get("emb.weight")
    if not torch.is_tensor(emb) or emb.ndim != 2:
        raise ValueError("delta checkpoint missing core emb.weight; cannot infer cfg")
    d = int(emb.shape[1])
    layer_ids = []
    for key in core.keys():
        if not key.startswith("blocks."):
            continue
        parts = key.split(".")
        if len(parts) > 2 and parts[1].isdigit():
            layer_ids.append(int(parts[1]))
    if not layer_ids:
        raise ValueError("delta checkpoint has no block tensors; cannot infer layer count")
    layers = max(layer_ids) + 1
    u = core.get("blocks.0.mha.U")
    if not torch.is_tensor(u) or u.ndim != 2:
        raise ValueError("delta checkpoint missing blocks.0.mha.U; cannot infer attention rank")
    dk = int(u.shape[0])
    rank = int(u.shape[1])
    if dk <= 0 or d % dk != 0:
        raise ValueError(f"delta checkpoint incompatible d/dk: d={d} dk={dk}")
    heads = d // dk

    prov = sd.get("agillm43_provenance") or {}
    train_argv = str(prov.get("train_argv") or "") if isinstance(prov, dict) else ""
    tokens = train_argv.split()
    preset_name = ""
    if "--preset" in tokens:
        idx = tokens.index("--preset")
        if idx + 1 < len(tokens):
            preset_name = tokens[idx + 1]
    if not preset_name:
        for name in PRESETS.keys():
            if ("--preset " + name) in train_argv:
                preset_name = name
                break

    cfg = None
    source = "shapes"
    if preset_name in PRESETS:
        cand = dict(PRESETS[preset_name])
        if int(cand.get("d", -1)) == d and int(cand.get("layers", -1)) == layers and int(cand.get("rank", -1)) == rank:
            cfg = cand
            source = "provenance:" + preset_name
    if cfg is None:
        matches = []
        for name, cand in PRESETS.items():
            if int(cand.get("d", -1)) == d and int(cand.get("layers", -1)) == layers and int(cand.get("rank", -1)) == rank:
                matches.append((name, dict(cand)))
        if matches:
            source = "preset:" + matches[0][0]
            cfg = matches[0][1]
        else:
            cfg = {"d": d, "layers": layers, "heads": heads, "rank": rank}
    cfg["d"] = d
    cfg["layers"] = layers
    cfg["heads"] = heads
    cfg["rank"] = rank

    qkv = core.get("blocks.0.mha.qkv.weight")
    tie_kv = bool(torch.is_tensor(qkv) and int(qkv.shape[0]) == 2 * d)
    cfg["tie_kv"] = tie_kv

    router = core.get("blocks.0.ff.router.weight")
    moe_ffn = torch.is_tensor(router)
    cfg["moe_ffn"] = bool(moe_ffn)
    if moe_ffn:
        cfg["moe_experts"] = int(router.shape[0])
        cfg["moe_top_k"] = int(cfg.get("moe_top_k", 1) or 1)
        exp0 = core.get("blocks.0.ff.experts.0.0.weight")
        if torch.is_tensor(exp0) and exp0.ndim == 2:
            cfg["moe_mlp_mult"] = max(1, int(exp0.shape[0]) // d)
        shared_ids = set()
        for key in core.keys():
            if not key.startswith("blocks.0.ff.shared."):
                continue
            parts = key.split(".")
            if len(parts) > 4 and parts[4].isdigit():
                shared_ids.add(int(parts[4]))
        cfg["moe_shared_experts"] = len(shared_ids)
        shared0 = core.get("blocks.0.ff.shared.0.0.weight")
        if torch.is_tensor(shared0) and shared0.ndim == 2:
            cfg["moe_shared_mlp_mult"] = max(1, int(shared0.shape[0]) // d)
        else:
            cfg["moe_shared_mlp_mult"] = int(cfg.get("moe_shared_mlp_mult", 0) or 0)

    ar_weight = ar.get("proj.weight") if isinstance(ar, dict) else None
    ar_bias = ar.get("proj.bias") if isinstance(ar, dict) else None
    tie_weights = bool(sd.get("tie_weights", False))
    if not tie_weights:
        tie_weights = "--tie_weights" in train_argv
    if not tie_weights and torch.is_tensor(ar_weight) and tuple(ar_weight.shape) == tuple(emb.shape) and ar_bias is None:
        tie_weights = True
    return cfg, tie_weights, source


# ───────────────────────── Training Logic ─────────────────────────

def _load_infer_head_state(module: nn.Module, state: dict, name: str):
    """Load inference heads across small checkpoint/schema drifts.

    Some older AGILLM-4 full checkpoints were saved before the current SAT/NAT
    head bias fields existed. For inference, preserve the old behavior by
    explicitly zero-filling missing bias tensors, while still failing on missing
    non-bias weights or shape mismatches.
    """
    if not isinstance(state, dict):
        module.load_state_dict(state)
        return
    module_state = module.state_dict()
    patched = dict(state)
    zero_filled = []
    shape_mismatch = []
    for key, target in module_state.items():
        if key not in patched and key.endswith('.bias') and torch.is_tensor(target):
            patched[key] = torch.zeros_like(target)
            zero_filled.append(key)
    for key, value in list(patched.items()):
        target = module_state.get(key)
        if target is None or not torch.is_tensor(value) or not torch.is_tensor(target):
            continue
        if tuple(value.shape) != tuple(target.shape):
            shape_mismatch.append(f"{key}: ckpt={tuple(value.shape)} model={tuple(target.shape)}")
            patched.pop(key)
    if shape_mismatch:
        raise RuntimeError(f"{name} checkpoint shape mismatch: " + "; ".join(shape_mismatch[:6]))
    loaded = module.load_state_dict(patched, strict=False)
    missing = [key for key in loaded.missing_keys if key not in zero_filled]
    satvar_missing = [key for key in missing if _satvar_is_param_key(key)]
    missing = [key for key in missing if not _satvar_is_param_key(key)]
    conf_missing = [key for key in missing if key.startswith("gate_conf.")]
    missing = [key for key in missing if not key.startswith("gate_conf.")]
    if missing:
        raise RuntimeError(f"{name} checkpoint missing required keys: " + ", ".join(missing[:12]))
    if satvar_missing and hasattr(module, "satvar_init_"):
        # pre-v28 checkpoint: fresh deterministic init of the variable-block SAT tensors
        module.satvar_init_()
        print(f"[infer-compat] {name}: fresh v28 satvar init for " + ", ".join(satvar_missing[:4]), flush=True)
    if conf_missing:
        # v2 checkpoint under the v3 runtime: zero the legacy probe and seed the
        # confidence gate from the verified prefit, exactly as the trainer does.
        _agillm43_v3_zero_linear_gate(module)
        _receipt = _agillm43_v3_load_gate_conf_prefit(module)
        print(f"[infer-compat] {name}: v3 gate_conf absent in checkpoint; prefit applied="
              f"{_receipt.get('applied')} reason={_receipt.get('reason')!r}", flush=True)
    notes = []
    if zero_filled:
        notes.append("zero-filled " + ", ".join(zero_filled[:6]))
    if loaded.unexpected_keys:
        notes.append("ignored unexpected " + ", ".join(loaded.unexpected_keys[:6]))
    if notes:
        print(f"[infer-compat] {name}: " + "; ".join(notes), flush=True)


def _sat_head_mlp_from_state(sd: dict) -> bool:
    sat_sd = sd.get("sat", {})
    if sd.get("delta") and "weights" in sd:
        sat_sd = sd["weights"].get("sat", sat_sd)
    return any(str(key).startswith("proj.2.") for key in sat_sd)


def _parse_grow_plan(s: str) -> List[int]:
    return sorted(set([int(x.strip()) for x in s.split(",") if x.strip() and int(x.strip()) >= 128]))

def _count_enabled_params(*modules) -> int:
    seen_data_ptrs = set()
    total = 0
    for m in modules:
        if m is None:
            continue
        for p in m.parameters():
            if p.data_ptr() not in seen_data_ptrs:
                seen_data_ptrs.add(p.data_ptr())
                total += p.numel()
    return total

def _target_token_ratio(args) -> float:
    if getattr(args, "token_param_ratio", 0.0) and args.token_param_ratio > 0:
        return float(args.token_param_ratio)
    if str(getattr(args, "preset", "")).startswith("agillm4_"):
        return AGILLM4_TOKEN_PARAM_RATIO
    return 51.2 if args.chilla_max_double else 25.0

def _phase_freeze(core: nn.Module, *, freeze_core: bool, unfreeze_ln: bool, train_emb: bool):
    for p in core.parameters(): p.requires_grad = not freeze_core
    if freeze_core:
        if unfreeze_ln:
            for blk in core.blocks:
                for p in blk.ln1.parameters(): p.requires_grad = True
                for p in blk.ln2.parameters(): p.requires_grad = True
            for p in core.ln.parameters(): p.requires_grad = True
        if train_emb:
            for p in core.emb.parameters(): p.requires_grad = True

def _side_update_unique_path(directory: pathlib.Path, name: str) -> pathlib.Path:
    directory.mkdir(parents=True, exist_ok=True)
    dest = directory / name
    if not dest.exists():
        return dest
    stem, suffix = dest.stem, dest.suffix
    stamp = time.strftime("%Y%m%d-%H%M%S", time.gmtime())
    for idx in range(1000):
        candidate = directory / f"{stem}.{stamp}.{idx}{suffix}"
        if not candidate.exists():
            return candidate
    return directory / f"{stem}.{stamp}.{os.getpid()}{suffix}"

def _side_update_move(path: pathlib.Path, directory: pathlib.Path) -> pathlib.Path:
    dest = _side_update_unique_path(directory, path.name)
    try:
        path.replace(dest)
    except OSError:
        import shutil

        shutil.move(str(path), str(dest))
    return dest

def _apply_async_side_updates(core: nn.Module, cfg: dict, args, step: int) -> tuple[list[dict], list[dict]]:
    update_dir_s = str(getattr(args, "async_update_dir", "") or "").strip()
    alpha = float(getattr(args, "async_update_alpha", 1.0) or 0.0)
    if not update_dir_s or alpha <= 0.0:
        return [], []
    update_dir = pathlib.Path(update_dir_s)
    if not update_dir.exists():
        return [], []
    max_updates = max(1, int(getattr(args, "async_update_max_per_check", 1) or 1))
    max_age = float(getattr(args, "async_update_max_age_sec", 0.0) or 0.0)
    accepted_dir = pathlib.Path(getattr(args, "async_update_accepted_dir", "") or (update_dir.parent / "accepted"))
    rejected_dir = pathlib.Path(getattr(args, "async_update_rejected_dir", "") or (update_dir.parent / "rejected"))
    param_map = dict(core.named_parameters())
    buffer_map = dict(core.named_buffers())
    now = time.time()
    applied: list[dict] = []
    rejected: list[dict] = []
    candidates = sorted(
        [p for p in update_dir.glob("*.pt") if p.is_file() and not p.name.endswith(".tmp")],
        key=lambda p: p.stat().st_mtime,
    )
    for path in candidates[:max_updates]:
        reject_reason = ""
        try:
            if max_age > 0 and now - path.stat().st_mtime > max_age:
                reject_reason = f"stale update older than {max_age:g}s"
                raise ValueError(reject_reason)
            upd = _agillm43_load_pt(path, map_location="cpu", weights_only=False)
            kind = upd.get("kind")
            if kind not in {"agillm35_dblock_slice_update", "agillm4_dblock_slice_update", "agillm41_dblock_slice_update"}:
                raise ValueError(f"bad update kind {kind!r}")
            if dict(upd.get("cfg", {})) != dict(cfg):
                raise ValueError("cfg mismatch")
            update_mode = "state_lerp"
            block_state = upd.get("block_state")
            block_delta_state = upd.get("block_delta_state")
            if block_delta_state is not None:
                update_mode = "delta_add"
                block_codec = _agillm43_tensor_state_summary(block_delta_state)
                block_state = _agillm43_decode_tensor_state(block_delta_state)
            else:
                block_codec = _agillm43_tensor_state_summary(block_state)
                block_state = _agillm43_decode_tensor_state(block_state)
            if not isinstance(block_state, dict) or not block_state:
                raise ValueError("missing block_state or block_delta_state")
            changed = 0
            with torch.no_grad():
                for key, value in block_state.items():
                    target = param_map.get(key)
                    if target is None:
                        target = buffer_map.get(key)
                    if target is None:
                        raise KeyError(f"unknown core key {key}")
                    if tuple(value.shape) != tuple(target.shape):
                        raise ValueError(f"{key} shape mismatch update={tuple(value.shape)} target={tuple(target.shape)}")
                    src = value.to(device=target.device, dtype=target.dtype, non_blocking=True)
                    if update_mode == "delta_add":
                        if not target.is_floating_point():
                            raise ValueError(f"{key} delta update targets non-floating tensor")
                        target.add_(src, alpha=alpha)
                    elif alpha >= 1.0:
                        target.copy_(src)
                    else:
                        target.lerp_(src, alpha)
                    changed += 1
                    del src
            dest = _side_update_move(path, accepted_dir)
            rec = {
                "path": str(dest),
                "worker_id": upd.get("worker_id"),
                "block_id": upd.get("block_id"),
                "layers": upd.get("layers"),
                "tokens": int(upd.get("tokens") or 0),
                "tok_per_sec": float(upd.get("tok_per_sec") or 0.0),
                "alpha": alpha,
                "keys": changed,
                "block_codec": block_codec,
                "update_mode": update_mode,
            }
            applied.append(rec)
            print(json.dumps({"event": "async_side_update_applied", "step": step, **rec}), flush=True)
        except Exception as exc:
            try:
                dest = _side_update_move(path, rejected_dir)
            except Exception:
                dest = path
            err = reject_reason or str(exc)
            print(
                json.dumps(
                    {
                        "event": "async_side_update_rejected",
                        "step": step,
                        "path": str(dest),
                        "error": err,
                    }
                ),
                flush=True,
            )
            try:
                upd_partial = _agillm43_load_pt(dest, map_location="cpu", weights_only=False) if dest.exists() else {}
            except Exception:
                upd_partial = {}
            rejected.append({
                "path": str(dest),
                "worker_id": upd_partial.get("worker_id"),
                "block_id": upd_partial.get("block_id"),
                "layers": upd_partial.get("layers"),
                "error": err,
            })
    return applied, rejected

# ── HF federation dataset logging ─────────────────────────────────────────────
_HF_FED_UPDATES_REPO = "OpenTransformer/AGILLM-4.3-fed-updates"
_HF_FED_ROUNDS_REPO  = "OpenTransformer/AGILLM-4.3-fed-rounds"

def _hf_fed_log_rows_bg(repo_id: str, rows: list, step: int) -> None:
    """Append JSONL rows to an HF dataset repo in a fire-and-forget background thread."""
    if not rows:
        return
    token = os.environ.get("HF_TOKEN") or os.environ.get("HUGGING_FACE_HUB_TOKEN")
    if not token:
        return
    try:
        from huggingface_hub import HfApi
    except ImportError:
        return

    def _upload():
        try:
            api = HfApi(token=token)
            ts = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
            fname = f"data/{step:08d}-{ts}-{os.getpid()}.jsonl"
            content = "\n".join(json.dumps(r, separators=(",", ":")) for r in rows) + "\n"
            api.upload_file(
                path_or_fileobj=content.encode(),
                path_in_repo=fname,
                repo_id=repo_id,
                repo_type="dataset",
                commit_message=f"fed log step {step}",
            )
        except Exception as exc:
            print(f"[hf-fed-log] {repo_id} upload failed: {exc}", flush=True)

    threading.Thread(target=_upload, daemon=True).start()


def _hf_fed_log_side_updates(applied: list, rejected: list, step: int) -> None:
    """Log accepted/rejected side-updates to HF AGILLM-4.3-fed-updates."""
    ts = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    rows = []
    for rec in applied:
        rows.append({
            "ts_utc": ts, "step": step, "status": "accepted",
            "worker_id": rec.get("worker_id"), "block_id": rec.get("block_id"),
            "layers": rec.get("layers"), "tokens": rec.get("tokens"),
            "tok_per_sec": rec.get("tok_per_sec"), "alpha": rec.get("alpha"),
            "keys": rec.get("keys"), "update_mode": rec.get("update_mode"),
            "block_codec": rec.get("block_codec"),
        })
    for rec in rejected:
        rows.append({
            "ts_utc": ts, "step": step, "status": "rejected",
            "worker_id": rec.get("worker_id"), "block_id": rec.get("block_id"),
            "layers": rec.get("layers"), "tokens": None,
            "tok_per_sec": None, "alpha": None, "keys": None,
            "update_mode": None, "block_codec": None,
            "error": rec.get("error"),
        })
    _hf_fed_log_rows_bg(_HF_FED_UPDATES_REPO, rows, step)


def _hf_fed_log_round(step: int, seen_tok: int, loss: float, role_tag: str, origin_tag: str) -> None:
    """Log a delta-save event (federation round boundary) to HF AGILLM-4.3-fed-rounds."""
    row = {
        "ts_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "step": step,
        "seen_tok": int(seen_tok),
        "loss": round(float(loss), 6),
        "role_tag": role_tag,
        "origin_tag": origin_tag,
    }
    _hf_fed_log_rows_bg(_HF_FED_ROUNDS_REPO, [row], step)
# ── end HF federation dataset logging ─────────────────────────────────────────

def _optimizer_param_groups(args, core, ar_h, sat_h, lr_core: float, lr_head: float, nat_h=None):
    # Shared/tied vocab projections must appear in only one optimizer group.
    # VRAM-first AGILLM-4 uses one embedding/projection tensor for AR/SAT/NAT.
    seen: set[int] = set()
    groups = []
    def add(params, lr, role=""):
        unique = []
        for param in params:
            if not param.requires_grad:
                continue
            key = id(param)
            if key in seen:
                continue
            seen.add(key)
            unique.append(param)
        if unique:
            group = {"params": unique, "lr": lr, "base_lr": lr}
            if role:
                group["agillm43_role"] = str(role)
            groups.append(group)
    _hc_mod = getattr(core, "hc", None)
    _hc_ids = {id(p) for p in _hc_mod.parameters()} if _hc_mod is not None else set()
    _repo_params = [p for name, p in core.named_parameters() if ".mha.repo." in name]
    _repo_ids = {id(p) for p in _repo_params}
    _extension_ids = _hc_ids | _repo_ids
    if _extension_ids:
        add((p for _n, p in core.named_parameters() if id(p) not in _extension_ids), lr_core, "core")
    else:
        add(core.parameters(), lr_core, "core")
    add(ar_h.parameters(), lr_head, "ar_head")
    if getattr(sat_h, "gate", None) is None:
        add((p for n, p in sat_h.named_parameters() if not _satvar_is_param_key(n)), lr_head, "sat_head")
    else:
        # Keep the mature token projection at the head LR while giving the
        # previously frozen 1/2 admission gate a usable calibration rate.
        add(sat_h.proj.parameters(), lr_head, "sat_projection")
        gate_lr = (
            float(lr_head) if bool(getattr(args, "repair_mode", False))
            else float(getattr(args, "sat_variable_gate_lr", 1.0e-4))
        )
        add(sat_h.gate.parameters(), gate_lr, "sat_variable_gate")
    if nat_h is not None:
        add(nat_h.parameters(), lr_head, "nat_head")
    if _hc_mod is not None:
        # HC stays in its historical tail position.
        add(_hc_mod.parameters(), lr_core, "hc_core")
    if _repo_params:
        # RePo is LAST, so a NoPE checkpoint's optimizer indices remain unchanged.
        repo_lr = float(getattr(args, "repo_lr", 1.0e-5) or lr_core)
        add(_repo_params, repo_lr, "repo_core")
    if getattr(sat_h, "gate_conf", None) is not None:
        # v3 confidence gate is appended AFTER RePo so every historical optimizer
        # index is unchanged; a v2 checkpoint simply gains a fresh tail group.
        conf_lr = float(getattr(args, "sat_variable_gate_conf_lr", 3.0e-4) or 3.0e-4)
        add(sat_h.gate_conf.parameters(), conf_lr, "sat_variable_gate_conf")
    # v28 variable-block SAT tensors: appended after every historical group so a pre-v28
    # checkpoint's optimizer indices are unchanged (fresh moments via _hc_adapt_opt_state).
    _sv_shift = [p for n, p in sat_h.named_parameters() if n.startswith("shift_emb")]
    _sv_regret = [p for n, p in sat_h.named_parameters() if n.startswith("stride_regret.")]
    if _sv_shift:
        add(_sv_shift, float(getattr(args, "satvar_shift_lr", 1.0e-4) or 1.0e-4), "satvar_shift")
    if _sv_regret:
        add(_sv_regret, float(getattr(args, "satvar_regret_lr", 3.0e-4) or 3.0e-4), "satvar_regret")
    return groups


def _agillm43_exact_parameter_sha256(value):
    """Unconditional dtype/shape-bound digest of exact contiguous tensor bytes."""
    if not torch.is_tensor(value):
        raise TypeError("exact parameter digest requires a tensor")
    cpu = value.detach().to(device="cpu").contiguous()
    header = json.dumps(
        {"shape": [int(dim) for dim in cpu.shape], "dtype": str(cpu.dtype)},
        sort_keys=True, separators=(",", ":"), allow_nan=False,
    ).encode("utf-8") + b"\0"
    raw = cpu.view(torch.uint8).numpy().tobytes(order="C")
    return hashlib.sha256(header + raw).hexdigest()


def _agillm43_v24_reset_legacy_sat_gate_parameters(sat_h, *, reset=False):
    """Discard the legacy all-stride-two classifier without consuming RNG."""
    gate = getattr(sat_h, "gate", None)
    if gate is None or not hasattr(gate, "weight"):
        raise RuntimeError("intelligence-v25 requires a linear sat_h.gate")
    params = list(gate.parameters())
    if tuple(gate.weight.shape[:1]) != (2,) or gate.bias is None or tuple(gate.bias.shape) != (2,):
        raise RuntimeError(
            f"SAT-variable gate topology mismatch weight={tuple(gate.weight.shape)} "
            f"bias={None if gate.bias is None else tuple(gate.bias.shape)}"
        )
    torch_rng_before = torch.get_rng_state().clone()
    cuda_rng_before = (
        [value.clone() for value in torch.cuda.get_rng_state_all()]
        if torch.cuda.is_available() else []
    )
    before_weight_sha256 = _agillm43_exact_parameter_sha256(gate.weight)
    before_bias_sha256 = _agillm43_exact_parameter_sha256(gate.bias)
    before_weight_abs_max = float(
        gate.weight.detach().float().abs().max().cpu()
    ) if int(gate.weight.numel()) else 0.0
    before_bias = [
        float(value) for value in gate.bias.detach().float().cpu().tolist()
    ]
    expected_bias = torch.tensor(
        [2.0, -2.0], dtype=gate.bias.dtype, device=gate.bias.device
    )
    if reset:
        # Class 0 is stride one. The 1.8% stride-two prior is close to the first
        # live gold-teacher census, avoids negative-class domination, and keeps
        # positive examples at nearly full CE gradient.
        with torch.no_grad():
            gate.weight.zero_()
            gate.bias.copy_(expected_bias)
    after_weight_abs_max = float(
        gate.weight.detach().float().abs().max().cpu()
    ) if int(gate.weight.numel()) else 0.0
    after_bias = [
        float(value) for value in gate.bias.detach().float().cpu().tolist()
    ]
    after_weight_sha256 = _agillm43_exact_parameter_sha256(gate.weight)
    after_bias_sha256 = _agillm43_exact_parameter_sha256(gate.bias)
    rng_unchanged = torch.equal(torch_rng_before, torch.get_rng_state())
    if torch.cuda.is_available():
        cuda_rng_after = torch.cuda.get_rng_state_all()
        rng_unchanged = bool(
            rng_unchanged and len(cuda_rng_before) == len(cuda_rng_after)
            and all(torch.equal(left, right) for left, right in zip(cuda_rng_before, cuda_rng_after))
        )
    receipt = {
        "schema": "agillm43.sat-variable-gate.parameters.v1",
        "applied": bool(reset),
        "parameter_tensors": len(params),
        "weight_shape": [int(dim) for dim in gate.weight.shape],
        "bias_shape": [int(dim) for dim in gate.bias.shape],
        "initialization": "zero_weight_bias_2_minus2",
        "class_0": "stride1",
        "class_1": "stride2",
        "initial_stride2_probability": 0.01798620996209156,
        "serving_stride2_threshold": _AGILLM43_SAT_VARIABLE_STRIDE2_THRESHOLD,
        "rng_consumed": False,
        "rng_unchanged": bool(rng_unchanged),
        "reason": "discard_legacy_all_stride2_classifier",
        "before_weight_sha256": before_weight_sha256,
        "before_bias_sha256": before_bias_sha256,
        "after_weight_sha256": after_weight_sha256,
        "after_bias_sha256": after_bias_sha256,
        "before_weight_abs_max": before_weight_abs_max,
        "before_bias": before_bias,
        "after_weight_abs_max": after_weight_abs_max,
        "after_bias": after_bias,
    }
    if reset:
        if (after_weight_abs_max != 0.0
                or not torch.equal(gate.bias.detach(), expected_bias)
                or not rng_unchanged):
            raise RuntimeError(
                "SAT-variable gate migration failed its parameter/RNG invariants"
            )
    print(
        "[sat-variable-parameters] "
        + json.dumps(receipt, sort_keys=True, separators=(",", ":")),
        flush=True,
    )
    return receipt


def _agillm43_v24_configure_sat_gate_optimizer(
        opt, sat_h, gate_lr, *, reset_state=False):
    """Bind the dedicated gate LR and optionally remove obsolete moments."""
    gate = getattr(sat_h, "gate", None)
    if gate is None:
        raise RuntimeError("intelligence-v25 requires sat_h.gate")
    params = list(gate.parameters())
    param_ids = {id(param) for param in params}
    matched = []
    for group in opt.param_groups:
        group_ids = {id(param) for param in group.get("params", [])}
        if not (group_ids & param_ids):
            continue
        if group_ids - param_ids:
            raise RuntimeError(
                "SAT-variable gate shares an optimizer group with non-gate parameters"
            )
        matched.append(group)
    if len(matched) != 1:
        raise RuntimeError(
            f"expected one SAT-variable optimizer group, found {len(matched)}"
        )
    rate = float(gate_lr)
    if not math.isfinite(rate) or not (0.0 < rate <= 1.0e-3):
        raise ValueError(f"invalid SAT-variable gate learning rate {rate!r}")
    group = matched[0]
    group["lr"] = rate
    group["base_lr"] = rate
    group["agillm43_role"] = "sat_variable_gate"
    reset_entries = 0
    if reset_state:
        for param in params:
            if param in opt.state:
                opt.state.pop(param, None)
                reset_entries += 1
    receipt = {
        "schema": "agillm43.sat-variable-gate.optimizer.v1",
        "learning_rate": rate,
        "parameter_tensors": len(params),
        "optimizer_state_entries_reset": int(reset_entries),
        "obsolete_all_stride2_moments_removed": bool(reset_state),
    }
    print(
        "[sat-variable-optimizer] "
        + json.dumps(receipt, sort_keys=True, separators=(",", ":")),
        flush=True,
    )
    return receipt

def _agillm43_v25_validate_semantic_migration(receipt):
    if not isinstance(receipt, dict):
        raise RuntimeError("intelligence-v25 semantic migration receipt is missing")
    exact = {
        "schema": "agillm43.semantic-migration.v3",
        "from_profile": "intelligence-v23",
        "to_profile": "intelligence-v25-satvar-pretrain",
        "transition_step": 2383793,
        "transition_seen_tok": 226636697600,
        "source_checkpoint": (
            "/workspace/agillm43_production_v14/production_quality_v18_hard_spike_gates/"
            "checkpoints_continue400B_from200B/"
            "pretrain_step02383793_from02383792_20260825T2303Z.pt"
        ),
        "source_pointer_sha256": (
            "2eca009cd08a3ce0a67af6cbc2fd3920223bb0a06c2144cdbbde0a2084a4cbae"
        ),
        "source_continuation_sha256": (
            "e2863578125c09c87cb1ef0fe47d57f482f382830cc39c20f79a2a87cc6fb842"
        ),
        "parent_runtime_sha256": (
            "f6d3c5e863525ae238e4520f731a0ce929a618eebdaf980cb0ecc84ddd520293"
        ),
        "model_tensor_shapes_changed": False,
        "model_tensor_values_changed": True,
    }
    for key, expected in exact.items():
        if receipt.get(key) != expected:
            raise RuntimeError(
                f"intelligence-v25 migration receipt mismatch {key}: "
                f"{receipt.get(key)!r} != {expected!r}"
            )
    if not re.fullmatch(r"[0-9a-f]{64}", str(receipt.get("runtime_sha256") or "")):
        raise RuntimeError("intelligence-v25 migration runtime SHA is invalid")
    gate = receipt.get("gate_parameters")
    gate_exact = {
        "schema": "agillm43.sat-variable-gate.parameters.v1",
        "applied": True,
        "parameter_tensors": 2,
        "weight_shape": [2, 1280],
        "bias_shape": [2],
        "initialization": "zero_weight_bias_2_minus2",
        "class_0": "stride1",
        "class_1": "stride2",
        "initial_stride2_probability": 0.01798620996209156,
        # historical: the v25 receipt recorded the 0.95 threshold of its era
        "serving_stride2_threshold": 0.95,
        "rng_consumed": False,
        "rng_unchanged": True,
        "after_weight_abs_max": 0.0,
        "after_bias": [2.0, -2.0],
    }
    if not isinstance(gate, dict):
        raise RuntimeError("intelligence-v25 gate migration receipt is missing")
    for key, expected in gate_exact.items():
        if gate.get(key) != expected:
            raise RuntimeError(
                f"intelligence-v25 gate receipt mismatch {key}: "
                f"{gate.get(key)!r} != {expected!r}"
            )
    for key in (
            "before_weight_sha256", "before_bias_sha256",
            "after_weight_sha256", "after_bias_sha256"):
        if not re.fullmatch(r"[0-9a-f]{64}", str(gate.get(key) or "")):
            raise RuntimeError(f"intelligence-v25 gate receipt {key} is invalid")
    optimizer = receipt.get("optimizer")
    optimizer_exact = {
        "schema": "agillm43.sat-variable-gate.optimizer.v1",
        "learning_rate": 1.0e-4,
        "parameter_tensors": 2,
        "optimizer_state_entries_reset": 2,
        "obsolete_all_stride2_moments_removed": True,
    }
    if not isinstance(optimizer, dict):
        raise RuntimeError("intelligence-v25 optimizer migration receipt is missing")
    for key, expected in optimizer_exact.items():
        if optimizer.get(key) != expected:
            raise RuntimeError(
                f"intelligence-v25 optimizer receipt mismatch {key}: "
                f"{optimizer.get(key)!r} != {expected!r}"
            )
    policy = receipt.get("policy")
    if not isinstance(policy, dict) or any(
            policy.get(key) is not True for key in (
                "sat_variable_pretraining_required",
                "dblock_assignment_preserved",
                "hot_config_hash_pin_removed",
                "checkpoint_integrity_hashes_preserved",
            )):
        raise RuntimeError("intelligence-v25 migration policy receipt is incomplete")
    if policy.get("top_level_objective_keys") != ["ar", "sat", "nat"]:
        raise RuntimeError("intelligence-v25 objective-key contract changed")
    return copy.deepcopy(receipt)


class PowerStep(torch.optim.Optimizer):
    """Memory-efficient optimizer (arXiv:2605.10335): heavy-ball momentum + signed
    power transform, a SINGLE buffer (no Adam second moment). Update:
        m_t = gamma*m_{t-1} + g_t ;  theta -= lr * (sign(m)*|m|^beta + wd*theta)
    beta in (0,1) gives Adam-like coordinate adaptivity; beta=1 -> SGD-momentum,
    beta=0 -> signSGD-momentum. Half the optimizer state of Adam.

    Faithful AGILLM-4.2 dblock-step benchmark (small model, real EDM objective, bf16):
    converged faster and to a LOWER loss than AdamW/paged_adamw8bit (EMA 6.6 vs 8.7-9.5).
    Note: its update scale differs from Adam, so it needs its own LR (~1e-3 vs Adam's
    3e-4). The fp32 momentum buffer here lives in VRAM (~+3GB at 1B params); for the
    24GB 4090 a paged or int8-quantized buffer (per the paper) is the deployment path."""
    def __init__(self, params, lr=1e-3, momentum=0.9, beta=0.1, weight_decay=0.0,
                 int8=False, paged=False):
        if not 0.0 <= beta <= 1.0:
            raise ValueError(f"beta must be in [0,1], got {beta}")
        if int8 and paged:
            raise ValueError("choose at most one of PowerStep int8 / paged")
        # Memory modes for the single momentum buffer (VRAM is the constraint; RAM is cheap):
        #   default  -> fp32 buffer in VRAM (fastest).
        #   int8=True -> blockwise-int8 buffer in VRAM (paper's headline; ~1/4 VRAM).
        #   paged=True -> fp32 buffer in pinned CPU RAM (~0 persistent VRAM; spends RAM+PCIe).
        self._int8 = bool(int8); self._paged = bool(paged)
        if self._int8:
            import bitsandbytes.functional as _bnbF
            self._bnbF = _bnbF
        super().__init__(params, dict(lr=lr, momentum=momentum, beta=beta, weight_decay=weight_decay))

    @torch.no_grad()
    def step(self, closure=None):
        loss = None
        if closure is not None:
            with torch.enable_grad():
                loss = closure()
        EPS = 1e-12
        for group in self.param_groups:
            lr = group["lr"]; gamma = group["momentum"]; beta = group["beta"]; wd = group["weight_decay"]
            if self._int8 or self._paged:
                # Per-tensor path (blockwise-int8 in VRAM, or fp32 buffer in CPU RAM).
                for p in group["params"]:
                    if p.grad is None:
                        continue
                    g = p.grad
                    st = self.state[p]
                    if self._int8:
                        m = (torch.zeros_like(p, dtype=torch.float32) if "mq" not in st
                             else self._bnbF.dequantize_blockwise(st["mq"], st["mstate"]))
                        m.mul_(gamma).add_(g.float())
                        u = (m * (m.abs() + EPS).pow(beta - 1.0)).to(p.dtype)
                        st["mq"], st["mstate"] = self._bnbF.quantize_blockwise(m)
                    else:
                        if "m" not in st:
                            st["m"] = torch.zeros(p.shape, dtype=torch.float32,
                                                  pin_memory=torch.cuda.is_available())
                        m = st["m"].to(p.device, non_blocking=True)
                        m.mul_(gamma).add_(g.float())
                        u = (m * (m.abs() + EPS).pow(beta - 1.0)).to(p.dtype)
                        st["m"].copy_(m, non_blocking=True)
                    if wd != 0:
                        p.mul_(1.0 - lr * wd)
                    p.add_(u, alpha=-lr)
                continue
            # Fast multi-tensor (foreach) path for the default in-VRAM fp32 buffer:
            # batches the elementwise update across all params -> few kernel launches,
            # matching fused optimizers instead of one launch set per parameter.
            params, grads, ms = [], [], []
            for p in group["params"]:
                if p.grad is None:
                    continue
                st = self.state[p]
                if "m" not in st:
                    st["m"] = torch.zeros_like(p, memory_format=torch.preserve_format)
                params.append(p); grads.append(p.grad); ms.append(st["m"])
            if not params:
                continue
            # m = gamma*m + g
            torch._foreach_mul_(ms, gamma)
            torch._foreach_add_(ms, grads)
            # u = sign(m)*|m|^beta = m * (|m|+eps)^(beta-1)   (avoids a separate sign pass)
            absm = torch._foreach_abs(ms)
            torch._foreach_add_(absm, EPS)
            torch._foreach_pow_(absm, beta - 1.0)
            us = torch._foreach_mul(ms, absm)
            if wd != 0:
                torch._foreach_mul_(params, 1.0 - lr * wd)
            torch._foreach_add_(params, us, alpha=-lr)
        return loss


def make_optimizer(args, core, ar_h, sat_h, lr_core: float, lr_head: float, nat_h=None):
    groups = _optimizer_param_groups(args, core, ar_h, sat_h, lr_core, lr_head, nat_h)
    opt_name = getattr(args, "optimizer", "adamw")
    weight_decay = float(getattr(args, "weight_decay", 0.0) or 0.0)
    if not math.isfinite(weight_decay) or weight_decay < 0.0:
        raise ValueError(f"invalid optimizer weight_decay={weight_decay!r}")
    if opt_name == "adamw":
        return torch.optim.AdamW(groups, weight_decay=weight_decay)
    if opt_name == "powerstep":
        return PowerStep(groups,
                         momentum=float(getattr(args, "powerstep_momentum", 0.9)),
                         beta=float(getattr(args, "powerstep_beta", 0.1)),
                         weight_decay=float(getattr(args, "weight_decay", 0.0) or 0.0),
                         int8=bool(getattr(args, "powerstep_int8", False)),
                         paged=bool(getattr(args, "powerstep_paged", False)))
    if opt_name in {"adamw8bit", "paged_adamw8bit"}:
        try:
            import bitsandbytes as bnb
        except Exception as exc:
            raise RuntimeError(
                f"--optimizer {opt_name} requires bitsandbytes. Install it in the training env first."
            ) from exc
        if opt_name == "paged_adamw8bit":
            return bnb.optim.PagedAdamW8bit(groups, weight_decay=weight_decay)
        return bnb.optim.AdamW8bit(groups, weight_decay=weight_decay)
    raise ValueError(f"unknown optimizer: {opt_name}")

def _oom_backoff_state_path(args) -> pathlib.Path:
    configured = str(getattr(args, "oom_memory_path", "") or "").strip()
    if configured:
        return pathlib.Path(configured).expanduser()
    return pathlib.Path(args.save_dir) / "oom_backoff_state.json"


def _oom_backoff_now() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def _oom_backoff_cuda_info() -> Dict[str, Any]:
    info: Dict[str, Any] = {"device": str(DEV), "gpu_name": "cpu", "gpu_total_gb": 0.0}
    if DEV.type == "cuda":
        try:
            prop = torch.cuda.get_device_properties(DEV)
            info["gpu_name"] = str(prop.name)
            info["gpu_total_gb"] = round(float(prop.total_memory) / (1024 ** 3), 3)
        except Exception:
            pass
    return info


def _oom_backoff_signature(args, block: int) -> Dict[str, Any]:
    gpu = _oom_backoff_cuda_info()
    return {
        "preset": str(getattr(args, "preset", "")),
        "block": int(block),
        "amp": bool(getattr(args, "amp", False)),
        "optimizer": str(getattr(args, "optimizer", "")),
        "attn_backend": str(getattr(args, "attn_backend", "")),
        "grad_checkpoint": bool(getattr(args, "grad_checkpoint", False)),
        "dblock": bool(getattr(args, "dblock", False)),
                    "dblock_blocks": int(getattr(args, "dblock_blocks", 0) or 0),
                    "dblock_ar_prob": float(getattr(args, "dblock_ar_prob", 0.0) or 0.0),
                    "dblock_sat_prob": float(getattr(args, "dblock_sat_prob", 0.0) or 0.0),
                    "dblock_nat_prob": float(getattr(args, "dblock_nat_prob", 0.0) or 0.0),
                    "sat_every": int(getattr(args, "sat_every", 0) or 0),
                    "nat_every": int(getattr(args, "nat_every", 0) or 0),
                    "oom_auto_backoff": bool(getattr(args, "oom_auto_backoff", False)),
                    "ckpt_codec": str(getattr(args, "ckpt_codec", "") or ""),
                    "delta_codec": str(getattr(args, "delta_codec", "") or ""),
        "dblock_blocks": int(getattr(args, "dblock_blocks", 0) or 0),
        "dblock_forward_layers_per_update": int(getattr(args, "dblock_layers_per_update", 0) or 0),
        "dblock_train_layers_per_update": int(getattr(args, "dblock_train_layers_per_update", 0) or 0),
        "dblock_train_layer_policy": str(getattr(args, "dblock_train_layer_policy", "cyclic") or "cyclic"),
        "dblock_train_sublayers_per_update": int(getattr(args, "dblock_train_sublayers_per_update", 0) or 0),
        "dblock_train_sublayer_policy": str(getattr(args, "dblock_train_sublayer_policy", "cyclic") or "cyclic"),
        "dblock_router_train_layers_per_update": int(getattr(args, "dblock_router_train_layers_per_update", 0) or 0),
        "dblock_router_train_layer_policy": str(getattr(args, "dblock_router_train_layer_policy", "cyclic") or "cyclic"),
        "dblock_router_full_anchor_every": int(getattr(args, "dblock_router_full_anchor_every", 0) or 0),
        "dblock_checkpoint_stride": int(getattr(args, "dblock_checkpoint_stride", 1) or 0),
        "dblock_checkpoint_skip_tail": int(getattr(args, "dblock_checkpoint_skip_tail", 0) or 0),
        "dblock_activation_offload": bool(getattr(args, "dblock_activation_offload", False)),
        "dblock_objective_mode": str(getattr(args, "dblock_objective_mode", "")),
        "ar_only": bool(getattr(args, "ar_only", False)),
        "sat_every": int(getattr(args, "sat_every", 0) or 0),
        "nat_every": int(getattr(args, "nat_every", 0) or 0),
        "nat_max_tokens": int(getattr(args, "nat_max_tokens", 0) or 0),
        "moe_ffn": bool(getattr(args, "moe_ffn", False)),
        "moe_experts": int(getattr(args, "moe_experts", 0) or 0),
        "moe_top_k": int(getattr(args, "moe_top_k", 0) or 0),
        "gpu_name": gpu.get("gpu_name", "unknown"),
        "gpu_total_gb": gpu.get("gpu_total_gb", 0.0),
    }


def _oom_backoff_key(signature: Dict[str, Any]) -> str:
    raw = json.dumps(signature, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()[:20]


def _oom_backoff_load(path: pathlib.Path) -> Dict[str, Any]:
    try:
        if path.exists():
            data = json.loads(path.read_text())
            if isinstance(data, dict):
                data.setdefault("schema", "agillm.oom_backoff.v1")
                data.setdefault("entries", {})
                return data
    except Exception as exc:
        print(f"[oom-backoff] warning: failed to read {path}: {exc}", flush=True)
    return {"schema": "agillm.oom_backoff.v1", "entries": {}}


def _oom_backoff_save(path: pathlib.Path, state: Dict[str, Any]) -> None:
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        state["updated_utc"] = _oom_backoff_now()
        tmp = path.with_suffix(path.suffix + ".tmp")
        tmp.write_text(json.dumps(state, indent=2, sort_keys=True) + "\n")
        tmp.replace(path)
    except Exception as exc:
        print(f"[oom-backoff] warning: failed to write {path}: {exc}", flush=True)


def _oom_backoff_entry(state: Dict[str, Any], key: str, signature: Dict[str, Any]) -> Dict[str, Any]:
    entries = state.setdefault("entries", {})
    entry = entries.get(key)
    if not isinstance(entry, dict):
        entry = {}
        entries[key] = entry
    entry["signature"] = signature
    entry.setdefault("successes", 0)
    entry.setdefault("ooms", 0)
    entry.setdefault("events", [])
    return entry


def _oom_backoff_features(signature: Dict[str, Any], batch: int, block: int) -> List[float]:
    total_gb = float(signature.get("gpu_total_gb", 0.0) or 0.0)
    return [
        min(2.0, max(0.0, float(batch) / 128.0)),
        min(2.0, max(0.0, float(block) / 4096.0)),
        min(2.0, max(0.0, total_gb / 80.0)),
        1.0 if signature.get("dblock") else 0.0,
        min(2.0, max(0.0, float(signature.get("dblock_blocks", 0) or 0) / 32.0)),
        min(2.0, max(0.0, float(signature.get("dblock_checkpoint_stride", 1) or 0) / 8.0)),
        1.0 if signature.get("amp") else 0.0,
        1.0 if "8bit" in str(signature.get("optimizer", "")) else 0.0,
        1.0 / max(1.0, float(signature.get("sat_every", 1) or 1)),
        1.0 / max(1.0, float(signature.get("nat_every", 1) or 1)),
    ]


def _oom_mlp_init(entry: Dict[str, Any], key: str, n_features: int) -> Dict[str, Any]:
    mlp = entry.get("mlp")
    if isinstance(mlp, dict) and len(mlp.get("w1", [])) == 8:
        return mlp
    seed = int(hashlib.sha256(("oom-mlp:" + key).encode("utf-8")).hexdigest()[:8], 16)
    rng = random.Random(seed)
    hidden = 8
    mlp = {
        "w1": [[rng.uniform(-0.05, 0.05) for _ in range(n_features)] for _ in range(hidden)],
        "b1": [0.0 for _ in range(hidden)],
        "w2": [rng.uniform(-0.05, 0.05) for _ in range(hidden)],
        "b2": 0.0,
        "seen": 0,
    }
    entry["mlp"] = mlp
    return mlp


def _oom_mlp_forward(mlp: Dict[str, Any], features: List[float]) -> Tuple[float, List[float]]:
    hidden: List[float] = []
    for row, bias in zip(mlp.get("w1", []), mlp.get("b1", [])):
        z = float(bias) + sum(float(w) * float(x) for w, x in zip(row, features))
        hidden.append(math.tanh(z))
    logit = float(mlp.get("b2", 0.0)) + sum(float(w) * h for w, h in zip(mlp.get("w2", []), hidden))
    logit = max(-30.0, min(30.0, logit))
    prob = 1.0 / (1.0 + math.exp(-logit))
    return prob, hidden


def _oom_mlp_update(entry: Dict[str, Any], key: str, signature: Dict[str, Any], batch: int, block: int, label: int) -> float:
    features = _oom_backoff_features(signature, batch, block)
    mlp = _oom_mlp_init(entry, key, len(features))
    prob, hidden = _oom_mlp_forward(mlp, features)
    lr = 0.04
    dlogit = prob - float(label)
    old_w2 = [float(w) for w in mlp["w2"]]
    for j, h in enumerate(hidden):
        mlp["w2"][j] = float(mlp["w2"][j]) - lr * dlogit * h
    mlp["b2"] = float(mlp.get("b2", 0.0)) - lr * dlogit
    for j, h in enumerate(hidden):
        dh = dlogit * old_w2[j] * (1.0 - h * h)
        for i, x in enumerate(features):
            mlp["w1"][j][i] = float(mlp["w1"][j][i]) - lr * dh * float(x)
        mlp["b1"][j] = float(mlp["b1"][j]) - lr * dh
    mlp["seen"] = int(mlp.get("seen", 0) or 0) + 1
    return prob


def _oom_backoff_peak_gb() -> float:
    if DEV.type != "cuda":
        return 0.0
    try:
        return round(float(torch.cuda.max_memory_allocated()) / (1024 ** 3), 4)
    except Exception:
        return 0.0


def _oom_backoff_start(args, phase_name: str, block: int, requested_batch: int) -> Tuple[int, Dict[str, Any], pathlib.Path, str, Dict[str, Any]]:
    path = _oom_backoff_state_path(args)
    state = _oom_backoff_load(path)
    signature = _oom_backoff_signature(args, block)
    key = _oom_backoff_key(signature)
    entry = _oom_backoff_entry(state, key, signature)
    batch = int(requested_batch)
    reasons: List[str] = []
    safe = int(entry.get("safe_batch", 0) or 0)
    oom = int(entry.get("oom_batch", 0) or 0)
    if oom > 0 and batch >= oom:
        cap = max(1, int(math.floor(oom * float(getattr(args, "oom_backoff_safety", 0.92) or 0.92))))
        if safe > 0 and safe < oom:
            cap = min(cap, safe)
        batch = min(batch, cap)
        reasons.append(f"known OOM at B={oom}")
    try:
        threshold = float(getattr(args, "oom_predict_threshold", 0.70) or 0.70)
        mlp = _oom_mlp_init(entry, key, len(_oom_backoff_features(signature, batch, block)))
        if int(mlp.get("seen", 0) or 0) >= 6:
            while batch > 1:
                prob, _hidden = _oom_mlp_forward(mlp, _oom_backoff_features(signature, batch, block))
                if prob < threshold:
                    break
                nb = max(1, int(math.floor(batch * float(getattr(args, "oom_backoff_safety", 0.92) or 0.92))))
                if nb >= batch:
                    nb = batch - 1
                reasons.append(f"MLP p_oom={prob:.2f} at B={batch}")
                batch = nb
    except Exception as exc:
        print(f"[oom-backoff] predictor warning: {exc}", flush=True)
    if batch != requested_batch:
        print(
            f"[oom-backoff] {phase_name}: startup cap Batch {requested_batch} -> {batch} "
            f"({'; '.join(reasons) or 'persistent memory'}) state={path}",
            flush=True,
        )
    _oom_backoff_save(path, state)
    return int(batch), state, path, key, signature


def _oom_backoff_next_batch(args, entry: Dict[str, Any], current_batch: int) -> int:
    safe = int(entry.get("safe_batch", 0) or 0)
    factor = float(getattr(args, "oom_backoff_safety", 0.92) or 0.92)
    candidate = max(1, int(math.floor(current_batch * factor)))
    if candidate >= current_batch:
        candidate = current_batch - 1
    if safe > 0 and safe < current_batch:
        candidate = min(candidate, safe)
    return max(1, int(candidate))


def _oom_backoff_record(
    args,
    state: Dict[str, Any],
    path: pathlib.Path,
    key: str,
    signature: Dict[str, Any],
    *,
    outcome: str,
    batch: int,
    block: int,
    step: int,
    phase_name: str,
    peak_gb: float = 0.0,
) -> Dict[str, Any]:
    entry = _oom_backoff_entry(state, key, signature)
    label = 1 if outcome == "oom" else 0
    prob = _oom_mlp_update(entry, key, signature, int(batch), int(block), label)
    event = {
        "utc": _oom_backoff_now(),
        "outcome": outcome,
        "batch": int(batch),
        "block": int(block),
        "step": int(step),
        "phase": phase_name,
        "peak_gb": float(peak_gb or 0.0),
        "mlp_p_oom_before": round(float(prob), 4),
    }
    events = entry.setdefault("events", [])
    events.append(event)
    del events[:-64]
    if outcome == "oom":
        entry["ooms"] = int(entry.get("ooms", 0) or 0) + 1
        prior = int(entry.get("oom_batch", 0) or 0)
        entry["oom_batch"] = int(batch) if prior <= 0 else min(prior, int(batch))
        entry["last_oom_utc"] = event["utc"]
        entry["last_oom_peak_gb"] = float(peak_gb or 0.0)
    else:
        entry["successes"] = int(entry.get("successes", 0) or 0) + 1
        prior = int(entry.get("safe_batch", 0) or 0)
        entry["safe_batch"] = max(prior, int(batch))
        entry["last_safe_utc"] = event["utc"]
        entry["last_safe_peak_gb"] = float(peak_gb or 0.0)
    _oom_backoff_save(path, state)
    return entry


def _oom_backoff_enabled(args) -> bool:
    return bool(getattr(args, "oom_auto_backoff", True))



def _nat_ids_for_training(ids: torch.Tensor, max_tokens: int) -> torch.Tensor:
    if max_tokens and max_tokens > 0 and ids.size(1) > max_tokens:
        return ids[:, -max_tokens:]
    return ids


def _nat_span_len(T: int, ratio: float, max_tokens: int = 0) -> int:
    target = max(1, min(T, int(round(T * max(0.01, min(0.95, float(ratio)))))))
    hi = min(T, max(target, target * 2))
    if max_tokens and max_tokens > 0:
        hi = min(hi, int(max_tokens))
    lo = max(1, min(hi, target // 2 if target > 1 else 1))
    return random.randint(lo, hi)


def _nat_corruption_mask(
    ids: torch.Tensor, ratio: float, args, loss_mask: Optional[torch.Tensor] = None
) -> torch.Tensor:
    """EOS-delimited, supervision-filtered CMLM corruption for packed NAT."""
    B, T = ids.shape
    if loss_mask is not None and tuple(loss_mask.shape) != tuple(ids.shape):
        raise ValueError("NAT corruption loss mask shape differs from token IDs")
    ratio = max(0.05, min(0.95, float(ratio)))
    span_prob = max(0.0, min(1.0, float(getattr(args, "nat_span_mask_prob", 0.35) or 0.0)))
    suffix_prob = max(0.0, min(1.0, float(getattr(args, "nat_suffix_mask_prob", 0.20) or 0.0)))
    max_span = int(getattr(args, "nat_span_max_tokens", 0) or 0)
    boundary_aware = bool(getattr(args, "nat_document_boundary_aware", True))
    mask = torch.zeros((B, T), device=ids.device, dtype=torch.bool)

    if not boundary_aware:
        for b in range(B):
            r = random.random()
            if r < suffix_prob:
                row = torch.zeros((T,), device=ids.device, dtype=torch.bool)
                n = _nat_span_len(T, ratio, max_span)
                row[-n:] = True
            elif r < suffix_prob + span_prob:
                row = torch.zeros((T,), device=ids.device, dtype=torch.bool)
                n = _nat_span_len(T, ratio, max_span)
                start = random.randint(0, max(0, T - n))
                row[start:start + n] = True
            else:
                row = torch.rand((T,), device=ids.device) < ratio
            if not bool(row.any()):
                row[random.randrange(T)] = True
            mask[b] = row
        if loss_mask is not None:
            mask = mask & loss_mask.to(device=ids.device, dtype=torch.bool)
        return mask

    eos_pad_id, nat_mask_id = _nat_boundary_ids()
    if bool(ids.eq(nat_mask_id).any()):
        raise ValueError(
            "clean NAT training IDs contain the active NAT mask token"
        )

    def true_runs(row_mask, start, end):
        segment = row_mask[start:end]
        edge = torch.zeros((1,), device=segment.device, dtype=torch.bool)
        padded = torch.cat((edge, segment, edge))
        changes = torch.nonzero(
            padded[1:] != padded[:-1], as_tuple=False
        ).flatten().tolist()
        return [
            (start + int(changes[i]), start + int(changes[i + 1]))
            for i in range(0, len(changes), 2)
        ]

    for b in range(B):
        row_loss = None if loss_mask is None else loss_mask[b]
        documents = _nat_valid_intervals(
            ids[b], row_loss,
            eos_pad_id=eos_pad_id, nat_mask_id=nat_mask_id,
        )
        eligible = ids[b].ne(eos_pad_id)
        if row_loss is not None:
            eligible = eligible & row_loss.to(
                device=ids.device, dtype=torch.bool
            )
        document_specs = []
        for document_start, document_end in documents:
            content_count = int(document_end - document_start)
            runs = true_runs(
                eligible, int(document_start), int(document_end)
            )
            if content_count >= 2 and runs:
                document_specs.append({
                    "start": int(document_start),
                    "end": int(document_end),
                    "content_count": int(content_count),
                    "runs": runs,
                })
        if not document_specs:
            continue

        r = random.random()
        if r < suffix_prob:
            spec = document_specs[random.randrange(len(document_specs))]
            run_start, run_end = spec["runs"][-1]
            capacity = spec["content_count"] - 1
            n = min(
                run_end - run_start,
                capacity,
                _nat_span_len(run_end - run_start, ratio, max_span),
            )
            if n > 0:
                mask[b, run_end - n:run_end] = True
        elif r < suffix_prob + span_prob:
            spec = document_specs[random.randrange(len(document_specs))]
            run_start, run_end = spec["runs"][
                random.randrange(len(spec["runs"]))
            ]
            capacity = spec["content_count"] - 1
            n = min(
                run_end - run_start,
                capacity,
                _nat_span_len(run_end - run_start, ratio, max_span),
            )
            if n > 0:
                span_start = random.randint(run_start, run_end - n)
                mask[b, span_start:span_start + n] = True
        else:
            mask[b] = (
                torch.rand((T,), device=ids.device) < ratio
            ) & eligible
            for document_start, document_end in documents:
                if bool(mask[b, document_start:document_end].all()):
                    keep = random.randrange(document_start, document_end)
                    mask[b, keep] = False
            if not bool(mask[b].any()):
                spec = document_specs[random.randrange(len(document_specs))]
                eligible_positions = torch.nonzero(
                    eligible[spec["start"]:spec["end"]],
                    as_tuple=False,
                ).flatten()
                if int(eligible_positions.numel()) > 0:
                    relative = int(eligible_positions[
                        random.randrange(int(eligible_positions.numel()))
                    ].item())
                    mask[b, spec["start"] + relative] = True
    return mask


# AGILLM-LR-GOVERNOR 20260902 (owner-directed): hot-reloadable bounded LR override.
_AGILLM43_LR_OVERRIDE_PATH = os.environ.get("AGILLM43_LR_OVERRIDE_PATH") or "/workspace/agillm43_lr_override.json"
_AGILLM43_LR_OVERRIDE_MAX = 1.0e-3
_AGILLM43_LR_OVERRIDE_POLL_SEC = 10.0
_agillm43_lr_override_cache = {"mtime": None, "size": None, "data": None, "checked": 0.0, "last_logged": None}


def _agillm43_lr_override_value(seen_tok):
    """Return the override LR (float) or None when inert. Re-reads the JSON file at most every
    _AGILLM43_LR_OVERRIDE_POLL_SEC seconds and only when its mtime/size changed. Any error or
    malformed content leaves the previous value in place (a missing file disables the override)."""
    c = _agillm43_lr_override_cache
    now = time.monotonic()
    if now - c["checked"] >= _AGILLM43_LR_OVERRIDE_POLL_SEC:
        c["checked"] = now
        try:
            st = os.stat(_AGILLM43_LR_OVERRIDE_PATH)
            if (st.st_mtime, st.st_size) != (c["mtime"], c["size"]):
                with open(_AGILLM43_LR_OVERRIDE_PATH, "r", encoding="utf-8") as fh:
                    data = json.load(fh)
                c["data"] = data if isinstance(data, dict) else None
                c["mtime"], c["size"] = st.st_mtime, st.st_size
                print("[lr-governor] override reloaded: " + json.dumps(c["data"], sort_keys=True)[:400], flush=True)
        except FileNotFoundError:
            if c["data"] is not None:
                print("[lr-governor] override file removed; schedule LR restored", flush=True)
            c["data"] = None
            c["mtime"] = None
            c["size"] = None
        except Exception as exc:  # unreadable/partial write: keep previous value
            print(f"[lr-governor] override unreadable ({exc!r}); keeping previous value", flush=True)
    d = c["data"]
    if not d:
        return None
    try:
        lr = float(d.get("lr"))
        if not math.isfinite(lr) or lr <= 0.0:
            return None
        lr = min(lr, _AGILLM43_LR_OVERRIDE_MAX)
        since = float(d.get("since_seen_tok") or 0.0)
        ramp = float(d.get("ramp_tokens") or 0.0)
        if ramp > 0.0:
            frac = min(1.0, max(0.0, (float(seen_tok) - since) / ramp))
            lr = lr * frac
        if not math.isfinite(lr) or lr <= 0.0:
            return None
    except Exception:
        return None
    last = c["last_logged"]
    if last is None or abs(lr - last) > 0.01 * max(abs(last), 1e-30):
        c["last_logged"] = lr
        print(f"[lr-governor] effective override lr={lr:.3e} at seen_tok={int(seen_tok)}", flush=True)
    return lr


def _repair_lr_multiplier(args, seen_tok, total_tokens_needed):
    if getattr(args, "lr_decay", "none") != "cosine":
        return 1.0, max(0, int(seen_tok))
    horizon = float(getattr(args, "lr_decay_tokens", 0.0) or total_tokens_needed)
    origin = int(getattr(args, "_lr_schedule_origin_tok", 0) or 0)
    local_seen = max(0, int(seen_tok) - origin)
    frac = min(1.0, max(0.0, float(local_seen) / max(horizon, 1.0)))
    floor = min(1.0, max(0.0, float(getattr(args, "lr_min_mult", 0.10))))
    mult = floor + (1.0 - floor) * 0.5 * (1.0 + math.cos(math.pi * frac))
    warm_tokens = max(0.0, float(getattr(args, "lr_warmup_tokens", 0.0) or 0.0))
    if warm_tokens > 0.0 and local_seen < warm_tokens:
        warm_floor = min(1.0, max(0.0, float(getattr(args, "lr_warmup_min_mult", 0.10) or 0.10)))
        warm_mult = warm_floor + (1.0 - warm_floor) * (float(local_seen) / warm_tokens)
        mult = min(mult, warm_mult)
    return float(mult), int(local_seen)


def _train_phase(
    args, phase_name: str,
    core, ar_h, sat_h, nat_h, opt, scaler,
    start_step, seen_tok, resume_wall_time,
    cfg, source, steps, block_size, batch_size,
    chat_cfg: dict,
    max_ckpts: int,
    target_tokens_override: Optional[int] = None,
    tie_weights: bool = False,
    streaming: bool = True,
    lineage: Optional[Dict[str, Any]] = None,
    provenance_cache: Optional[Dict[str, Any]] = None
):
    BLOCK = block_size
    BATCH_REQUESTED = int(batch_size)
    BATCH = BATCH_REQUESTED
    oom_state: Dict[str, Any] = {}
    oom_state_path = pathlib.Path(args.save_dir) / "oom_backoff_state.json"
    oom_key = ""
    oom_signature: Dict[str, Any] = {}
    oom_good_steps = 0
    if _oom_backoff_enabled(args):
        BATCH, oom_state, oom_state_path, oom_key, oom_signature = _oom_backoff_start(args, phase_name, BLOCK, BATCH)
    if lineage is None:
        lineage = {}
    strict_repair = bool(getattr(args, "repair_mode", False))
    if target_tokens_override is not None:
        target_tokens = target_tokens_override
    else:
        ratio = _target_token_ratio(args)
        param_count = _count_enabled_params(core, ar_h, sat_h, nat_h)
        target_tokens = int(ratio * param_count)
        print(f"[{phase_name}] token_param_ratio={ratio:g} param_count={param_count:,} target_tokens={target_tokens:,}")
    if strict_repair:
        if type(steps) is not int or steps != _AGILLM43_REPAIR_TARGET_COMMITS:
            raise ValueError(
                "strict repair phase requires the exact 42-commit endpoint request"
            )
        if target_tokens_override is not None:
            raise ValueError(
                "strict repair phase forbids a mutable target_tokens override"
            )
        if type(BLOCK) is not int or BLOCK != 2048:
            raise ValueError("strict repair phase block size must be exactly 2048")
        if type(BATCH) is not int or BATCH != 24:
            raise ValueError("strict repair phase batch size must be exactly 24")
        endpoint_progress = _repair_endpoint_progress(start_step, seen_tok)
        phase_target_tokens = endpoint_progress["repair_remaining_tokens"]
        total_tokens_needed = _AGILLM43_REPAIR_TARGET_SEEN_TOK
    elif steps:
        phase_target_tokens = steps * BLOCK * BATCH
        total_tokens_needed = seen_tok + phase_target_tokens
    else:
        total_tokens_needed = target_tokens
        if total_tokens_needed <= seen_tok:
            print(f"[{phase_name}] target {total_tokens_needed} already reached.")
            return start_step, seen_tok, resume_wall_time
    if strict_repair:
        data_seed_receipt = _repair_effective_data_seed(args, start_step)
        data_seed = data_seed_receipt["data_seed_effective"]
        print(
            f"[data] strict resume stream seed {data_seed} "
            f"(contract={data_seed_receipt['data_seed_contract']} "
            f"committed_offset={data_seed_receipt['data_seed_committed_offset']})",
            flush=True,
        )
    else:
        data_seed_receipt = None
        data_seed = int(getattr(args, "data_seed", 42))
    if not strict_repair and data_seed < 0:
        # Streaming restarts from the dataset head with a fixed shuffle seed, so every
        # restart re-trains the same early data. Derive a per-resume seed instead:
        # deterministic for a given checkpoint, different across restarts.
        data_seed = 42 + int(start_step)
        print(f"[data] per-restart shuffle seed {data_seed} (derived from resume step)", flush=True)
    effective_source = (
        str(source or "").strip() if strict_repair
        else get_hot_datasets(source)
    )
    val_requested = str(getattr(args, "val_source", "") or "").strip()
    if val_requested and _looks_numeracy_only_sources(val_requested) and not _looks_numeracy_only_sources(effective_source):
        val_effective = effective_source
    else:
        val_effective = val_requested or effective_source
    dataset_meta = _dataset_provenance(
        phase_name, source, effective_source, args,
        use_hot_config=not strict_repair,
        val_requested=val_requested,
        val_effective=val_effective,
    )
    dataset_meta["hot_reload_capable"] = (
        not strict_repair and not bool(getattr(args, "sft_completion_only", False)))
    if strict_repair:
        dataset_meta.update(data_seed_receipt)
        dataset_meta.update(endpoint_progress)
        dataset_meta["repair_resume_checkpoint_step"] = int(start_step)

    sequence_prefetch_depth = 0

    def _on_dataset_hot_reload(new_effective, generation, old_effective):
        nonlocal dataset_meta
        if val_requested and _looks_numeracy_only_sources(val_requested) and not _looks_numeracy_only_sources(new_effective):
            new_val_effective = new_effective
        else:
            new_val_effective = val_requested or new_effective
        refreshed = _dataset_provenance(
            phase_name, source, new_effective, args,
            use_hot_config=True,
            val_requested=val_requested,
            val_effective=new_val_effective,
        )
        refreshed.update({
            "hot_reload_capable": True,
            "hot_reload_generation": int(generation),
            "hot_reload_previous_source": str(old_effective or ""),
            "hot_reloaded_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        })
        refreshed["sequence_prefetch_depth"] = int(sequence_prefetch_depth)
        dataset_meta = refreshed
        print(
            f"[dataset-hotload] provenance updated generation={generation} "
            f"source_count={dataset_meta['source_count']}",
            flush=True,
        )

    print(
        f"[dataset-policy] phase={phase_name} sources={dataset_meta['source_count']} "
        f"language_mix={dataset_meta['has_language_mix']} numeracy={dataset_meta['has_numeracy']}",
        flush=True,
    )
    requested_val_block = int(getattr(args, "val_block", 0) or 0)
    val_block = BLOCK if requested_val_block <= 0 else max(66, min(BLOCK, requested_val_block))
    if strict_repair:
        val_block = BLOCK
    # AGILLM43-PERMANENT-CALLSITE-GUARD-20260817
    # Structural guarantee: heldout telemetry can never abort training startup.
    # The in-function handlers cannot catch failures raised before/outside their
    # own try (val path + sha resolution, _sha256_file OSError, legacy rebuild).
    try:
        val_batches = _build_val_set(effective_source, chat_cfg, args, val_block)
    except Exception as _val_exc:
        if strict_repair:
            raise
        print(
            f"[val] heldout telemetry unavailable at startup "
            f"({type(_val_exc).__name__}: {_val_exc}); training continues without heldout",
            flush=True,
        )
        val_batches = []
    if val_batches:
        print(
            f"[val] telemetry graph block={val_block} training_block={BLOCK} "
            f"batches={len(val_batches)} gate={'on' if bool(getattr(args, 'quality_validation_before_save', False)) else 'off'}",
            flush=True,
        )
    if bool(getattr(args, "repair_mode", False)):
        _repair_preflight(
            args,
            stage="validation",
            loaded_step=start_step,
            val_batches=val_batches,
            loaded_meta=getattr(args, "_repair_loaded_meta", None),
        )
    last_val_mono = time.monotonic()
    last_val_step = int(start_step)
    completion_only = bool(getattr(args, "sft_completion_only", False))
    if completion_only:
        stream = None
        sft_stream = completion_only_sequence_stream(effective_source, BLOCK, data_seed, args, streaming=streaming)
        print(
            f"[{phase_name}] completion-only SFT enabled: prompt_field={getattr(args, 'sft_prompt_field', 'prompt')} "
            f"completion_field={getattr(args, 'sft_completion_field', 'completion')}",
            flush=True,
        )
    else:
        sft_stream = None
        if strict_repair:
            stream = token_stream(
                effective_source, total_tokens_needed, seed=data_seed,
                chat=chat_cfg.get("chat", False),
                chat_messages_key=chat_cfg.get("key", "messages"),
                sft_add_generation_prompt=chat_cfg.get("gen_prompt", False),
                dataset_field_text=chat_cfg.get("text_field", "text"),
                streaming=streaming,
                use_hot_config=False,
                immutable_repair=True,
            )
        else:
            stream = hot_reloadable_token_stream(
                source, total_tokens_needed, seed=data_seed,
                chat=chat_cfg.get("chat", False),
                chat_messages_key=chat_cfg.get("key", "messages"),
                sft_add_generation_prompt=chat_cfg.get("gen_prompt", False),
                dataset_field_text=chat_cfg.get("text_field", "text"),
                streaming=streaming,
                initial_effective=effective_source,
                on_reload=_on_dataset_hot_reload,
            )
    sequence_stream = None
    if (not completion_only) and stream is not None:
        try:
            sequence_prefetch_depth = max(
                0, int(os.environ.get("AGILLM43_SEQUENCE_PREFETCH_DEPTH", "64") or 0)
            )
        except Exception:
            sequence_prefetch_depth = 64
        if sequence_prefetch_depth > 0:
            sequence_stream = _agillm43_prefetched_block_sequences(
                stream, BLOCK, sequence_prefetch_depth
            )
            dataset_meta["sequence_prefetch_depth"] = int(sequence_prefetch_depth)
            print(
                f"[data-prefetch] block_sequences={sequence_prefetch_depth} "
                f"block={BLOCK} max_tokens={sequence_prefetch_depth * BLOCK}",
                flush=True,
            )
    ce_tok = nn.CrossEntropyLoss(label_smoothing=0.1)
    ce_gate = nn.CrossEntropyLoss()
    ctc = nn.CTCLoss(blank=NAT_MASK_ID, zero_infinity=True)
    pbar = SafeProgress(total=total_tokens_needed, initial=seen_tok, unit="tok", initial_step=start_step)
    if start_step or seen_tok:
        print(f"[{phase_name}] resume counters: step={int(start_step)} seen_tok={int(seen_tok)} current_B={int(BATCH)} current_L={int(BLOCK)}", flush=True)
    grow_plan = _parse_grow_plan(args.grow_plan) if args.auto_grow else []
    buf: list[int] = []
    batch_accum: list[list[int]] = []
    mask_accum: list[list[bool]] = []
    step = start_step
    steps_since_last_grow = 0
    oom_retries = 0
    MAX_OOM_RETRIES = int(getattr(args, "oom_retries_before_backoff", 0) or 0)
    now_wall = time.time()
    resume_save_age = now_wall - (resume_wall_time or now_wall)
    if strict_repair:
        if not math.isfinite(float(resume_save_age)):
            raise ValueError("repair resume checkpoint age is non-finite")
        # A clock-skewed or re-signed wall_time may neither postpone the next
        # crash-safe save nor manufacture unbounded elapsed age.
        max_resume_save_age = max(
            0.0, float(getattr(args, "save_every_sec", 0) or 0.0)
        )
        resume_save_age = min(
            max(0.0, float(resume_save_age)), max_resume_save_age
        )
    last_save_mono = time.monotonic() - resume_save_age
    last_delta_step = start_step
    last_delta_mono = last_save_mono
    last_heartbeat_mono = time.monotonic()
    _disk_hygiene(pathlib.Path(args.save_dir), phase_name, args, reason="startup")
    # Derive origin tag from warmstart path for checkpoint naming
    _ws_path = getattr(args, "warmstart_from", None) or getattr(args, "resume", None) or getattr(args, "resume_delta", None) or ""
    _ws_m = re.search(r"step(\d+)", pathlib.Path(_ws_path).name) if _ws_path else None
    _origin_tag = f"_from{int(_ws_m.group(1)):08d}" if _ws_m else ""
    _role_tag = f"_{getattr(args, 'ckpt_role', '').strip()}" if getattr(args, "ckpt_role", "").strip() else ""

    _saved_repair_val_state = getattr(args, "_repair_validation_state", None)
    _saved_quality_val_state = getattr(args, "_quality_validation_state", None)
    _saved_validation_state = (
        _saved_repair_val_state
        if bool(getattr(args, "repair_mode", False))
        else _saved_quality_val_state
    )
    if isinstance(_saved_validation_state, dict):
        repair_val_state = copy.deepcopy(_saved_validation_state)
        print(
            f"[quality-validation] restored checks={int(repair_val_state.get('checks', 0) or 0)} "
            f"bad_checks={int(repair_val_state.get('bad_checks', 0) or 0)}",
            flush=True,
        )
    else:
        repair_val_state = {
            "baseline": None, "best": None, "last": None,
            "checks": 0, "bad_checks": 0, "families": {},
        }
    _initial_ce = None
    if val_batches:
        _initial_ce = _run_validation(
            core, ar_h, val_batches, args, step, sat_h=sat_h, nat_h=nat_h
        )
        if (_initial_ce is None and bool(
                getattr(args, "quality_validation_before_save", False))):
            raise RuntimeError(
                "quality continuation startup validation did not complete"
            )
        _initial_stop = _repair_update_validation(args, repair_val_state, _initial_ce, step)
        if _initial_stop and bool(getattr(args, "repair_fail_fast", False)):
            _repair_write_fail(args, "initial_validation", message=_initial_stop, step=int(step))
            raise RuntimeError("repair fail-fast: initial validation unsafe")

    def _repair_authoritative_validation_before_save(reason):
        nonlocal last_val_mono, last_val_step
        quality_pre_save = bool(
            getattr(args, "quality_validation_before_save", False)
        )
        if not strict_repair and not quality_pre_save:
            return
        if not val_batches:
            if strict_repair:
                raise RuntimeError(
                    "authoritative pre-save validation requested without frozen batches"
                )
            print(
                "[val] pre-save authoritative validation skipped: no frozen heldout batches",
                flush=True,
            )
            return
        repeats = max(1, int(
            getattr(args, "quality_validation_repeats_before_save", 1) or 1
        ))
        if strict_repair and repeats != 1:
            raise RuntimeError(
                "strict repair requires exactly one authoritative validation repeat"
            )
        for repeat_index in range(repeats):
            ce = _run_validation(
                core, ar_h, val_batches, args, step,
                sat_h=sat_h, nat_h=nat_h,
            )
            if ce is None:
                raise RuntimeError(
                    "authoritative pre-save validation did not complete"
                )
            stop = _repair_update_validation(args, repair_val_state, ce, step)
            last_val_mono = time.monotonic()
            last_val_step = int(step)
            if stop and (strict_repair or bool(getattr(args, "repair_fail_fast", False))):
                _repair_write_fail(
                    args, "authoritative_pre_save_validation", message=stop,
                    step=int(step), reason=str(reason), repeat=int(repeat_index + 1),
                    validation=repair_val_state,
                )
                raise RuntimeError("authoritative pre-save validation unsafe")
        required = max(2, int(getattr(args, "repair_val_min_checks", 2) or 2))
        checks = int(repair_val_state.get("checks", 0) or 0)
        if checks < required:
            _repair_write_fail(
                args, "insufficient_pre_save_validation", step=int(step),
                reason=str(reason), checks=checks, required=required,
            )
            raise RuntimeError(
                f"repair save refused: authoritative validation checks {checks} < {required}"
            )
        repair_val_state["last_authoritative_step"] = int(step)
        repair_val_state["last_authoritative_reason"] = str(reason)
        repair_val_state["validation_file"] = str(
            pathlib.Path(getattr(args, "val_file", "")).expanduser().resolve()
        )
        repair_val_state["validation_sha256"] = str(
            getattr(args, "val_sha256", "") or ""
        ).lower()

    print(f"[{phase_name}] Starting. Goal: {total_tokens_needed:,} tokens. Batch={BATCH}, Block={BLOCK}")
    print(
        f"[{phase_name}] AR_ONLY={args.ar_only}, SAT_EVERY={args.sat_every}, "
        f"NAT_EVERY={args.nat_every}, TIE_WEIGHTS={tie_weights}, STREAMING={streaming}"
    )
    _flush_flag = [False]
    _terminate_after_flush = [False]

    def _signal_name(signum):
        try:
            return signal.Signals(signum).name
        except Exception:
            return str(signum)

    def _on_flush_signal(signum, frame):
        _flush_flag[0] = True
        print(f"\n[{phase_name}] flush signal received ({_signal_name(signum)}); will checkpoint at next step")

    def _on_terminate_signal(signum, frame):
        _flush_flag[0] = True
        _terminate_after_flush[0] = True
        print(f"\n[{phase_name}] {_signal_name(signum)} received; will checkpoint at next step and exit cleanly")

    try:
        signal.signal(signal.SIGUSR1, _on_flush_signal)
        for _term_sig in (getattr(signal, "SIGTERM", None), getattr(signal, "SIGINT", None), getattr(signal, "SIGHUP", None)):
            if _term_sig is not None:
                signal.signal(_term_sig, _on_terminate_signal)
        print(f"[{phase_name}] on-demand flush ready: kill -USR1 {os.getpid()}  or  touch {pathlib.Path(args.save_dir) / 'FLUSH_NOW'}")
        print(f"[{phase_name}] graceful termination flush ready: SIGTERM/SIGINT/SIGHUP will save a checkpoint then exit")
    except (ValueError, OSError):
        pass
    _DBS = _dblock_init(core, args) if getattr(args,'dblock',False) else None
    _training_science_init(args, core, phase_name, start_step, seen_tok)
    if _initial_ce is not None:
        _training_science_on_validation(args, _initial_ce, step)
    if bool(getattr(args, "repair_mode", False)):
        args._repair_dblock_state_ref = _DBS

    def _phase_checkpoint_meta(save_step, save_seen_tok):
        payload = {
            "cfg": cfg,
            "step": int(save_step),
            "seen_tok": int(save_seen_tok),
            "wall_time": time.time(),
            "tie_weights": tie_weights,
            "dataset_provenance": dataset_meta,
            "torch_rng_state": torch.get_rng_state(),
            "cuda_rng_state_all": (
                torch.cuda.get_rng_state_all()
                if torch.cuda.is_available() else None
            ),
            "python_rng_state": random.getstate(),
            "numpy_rng_state": np.random.get_state(),
            "training_science": _training_science_snapshot(args),
        }
        _weight_accel_meta = _weight_accel_checkpoint_metadata(args)
        if _weight_accel_meta is not None:
            payload["weight_trajectory_accelerator"] = _weight_accel_meta
        if not bool(getattr(args, "repair_mode", False)):
            payload["agillm43_training_profile"] = "intelligence-v25-satvar-pretrain"
            payload["agillm44_satvar_schema"] = SATVAR_SCHEMA
            payload["agillm43_sat_variable_gate_feature_schema"] = (
                _AGILLM43_SAT_VARIABLE_GATE_FEATURE_SCHEMA
            )
            payload["agillm43_sat_variable_gate_feature_migration"] = copy.deepcopy(
                getattr(args, "_agillm43_sat_variable_gate_feature_migration", None)
            )
            payload["agillm43_semantic_migration"] = copy.deepcopy(
                getattr(args, "_agillm43_semantic_migration", None)
            )
            payload["continuation_dblock_resume_state"] = (
                _continuation_dblock_state_payload(_DBS, int(save_step))
                if _DBS is not None else None
            )
            payload["continuation_dblock_router_state"] = (
                _dblock_router_checkpoint_payload(_DBS, args, int(save_step))
                if _DBS is not None else None
            )
            payload["continuation_dblock_direct56_state"] = (
                _dblock_direct56_checkpoint_payload(_DBS, args, int(save_step))
                if _DBS is not None else None
            )
            payload["continuation_dblock_target_route_state"] = (
                _dblock_target_route_checkpoint_payload(_DBS, args, int(save_step))
                if _DBS is not None else None
            )
        _matryoshka_meta = _matryoshka_checkpoint_payload(
            args, cfg, save_seen_tok, _DBS)
        if _matryoshka_meta is not None:
            payload["agillm5_matryoshka"] = _matryoshka_meta
        payload.update(_det50_checkpoint_payload(args))
        payload.update(_repair_checkpoint_metadata(
            args, save_step, save_seen_tok, _DBS, repair_val_state))
        return payload

    def _publish_authoritative_run_state(status, checkpoint_name):
        if status not in {"completed", "terminated"}:
            raise ValueError(f"invalid authoritative training status {status!r}")
        if _prov_loss is None or not math.isfinite(float(_prov_loss)):
            raise RuntimeError("authoritative run-state requires a finite final loss")
        endpoint = _repair_endpoint_progress(step, seen_tok)
        if status == "completed" and endpoint["repair_remaining_commits"] != 0:
            raise RuntimeError(
                "completed run-state is forbidden before the immutable endpoint"
            )
        checkpoint_path = pathlib.Path(args.save_dir) / str(checkpoint_name)
        checkpoint_receipt = _agillm43_final_checkpoint_receipt(
            checkpoint_path, step, seen_tok, _DBS, repair_val_state
        )
        dblock_payload = _dblock_resume_payload(_DBS, step)
        payload = {
            "schema": "agillm.run_state.v2",
            "model": "AGILLM4.3",
            "status": str(status),
            "phase": str(status),
            "trainer_phase": str(phase_name),
            "authoritative": True,
            "checkpoint_finalized": True,
            "publication_stage": "post_checkpoint_and_pointer_finalization",
            "pid": int(os.getpid()),
            "step": _dblock_require_exact_int(
                step, "authoritative run-state step",
                minimum=_AGILLM43_REPAIR_BASE_STEP,
            ),
            "seen_tok": _dblock_require_exact_int(
                seen_tok, "authoritative run-state seen_tok",
                minimum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
            ),
            "loss": float(_prov_loss),
            "batch_size": int(BATCH),
            "requested_batch_size": int(BATCH_REQUESTED),
            "block": int(BLOCK),
            "dblock": True,
            "dblock_blocks": int(getattr(args, "dblock_blocks", 0) or 0),
            "dblock_forward_layers_per_update": int(getattr(args, "dblock_layers_per_update", 0) or 0),
            "dblock_train_layers_per_update": int(getattr(args, "dblock_train_layers_per_update", 0) or 0),
            "dblock_train_layer_policy": str(getattr(args, "dblock_train_layer_policy", "cyclic") or "cyclic"),
            "dblock_train_sublayers_per_update": int(getattr(args, "dblock_train_sublayers_per_update", 0) or 0),
            "dblock_train_sublayer_policy": str(getattr(args, "dblock_train_sublayer_policy", "cyclic") or "cyclic"),
            "dblock_router_train_layers_per_update": int(getattr(args, "dblock_router_train_layers_per_update", 0) or 0),
            "dblock_router_train_layer_policy": str(getattr(args, "dblock_router_train_layer_policy", "cyclic") or "cyclic"),
            "dblock_router_full_anchor_every": int(getattr(args, "dblock_router_full_anchor_every", 0) or 0),
            "granularity_label": str(getattr(args, "granularity_label", "") or ""),
            "dblock_last_forward_layers": list(((_DBS or {}).get("training_science_last_receipt") or {}).get("forward_layers", []) or []),
            "dblock_last_train_layers": list(((_DBS or {}).get("training_science_last_receipt") or {}).get("train_layers", []) or []),
            "dblock_last_train_sublayers": list(((_DBS or {}).get("training_science_last_receipt") or {}).get("train_sublayers", []) or []),
            "dblock_router_internal_layer_counts": list(((_DBS or {}).get("router_internal_layer_counts", []) or [])),
            "dblock_router_internal_full_anchor_updates": int(((_DBS or {}).get("router_internal_full_anchor_updates", 0) or 0)),
            "dblock_router_last_internal_update": _dblock_json_copy(((_DBS or {}).get("router_last_internal_update"))),
            "dblock_committed_step": int(dblock_payload["committed_step"]),
            "dblock_attempt_step": int(dblock_payload["state"]["attempt_step"]),
            "dblock_resume_schema": str(dblock_payload["schema"]),
            "dblock_resume_sha256": str(dblock_payload["sha256"]),
            "dblock_counts": list(dblock_payload["state"]["counts"]),
            "dblock_attempt_counts": list(
                dblock_payload["state"]["attempt_counts"]
            ),
            "dblock_local_objective_last": _dblock_json_copy(
                (_DBS or {}).get("local_objective_last", {})
            ),
            "fullstack_anchor_last": _dblock_json_copy(
                (_DBS or {}).get("fullstack_anchor_last", {})
            ),
            "fullstack_sat_anchor_last": _dblock_json_copy(
                (_DBS or {}).get("fullstack_sat_anchor_last", {})
            ),
            "fullstack_nat_anchor_last": _dblock_json_copy(
                (_DBS or {}).get("fullstack_nat_anchor_last", {})
            ),
            "repair_mode": True,
            "repair_schema": _AGILLM_REPAIR_SCHEMA,
            "repair_validation": _repair_validate_validation_state(
                repair_val_state, step, require_authoritative=True
            ),
            "repair_base_seen_tok": _AGILLM43_REPAIR_BASE_SEEN_TOK,
            "repair_target_commits": _AGILLM43_REPAIR_TARGET_COMMITS,
            "repair_target_step": _AGILLM43_REPAIR_TARGET_STEP,
            "repair_target_seen_tok": _AGILLM43_REPAIR_TARGET_SEEN_TOK,
            "repair_committed_before_phase": endpoint[
                "repair_committed_before_phase"
            ],
            "repair_remaining_commits": endpoint[
                "repair_remaining_commits"
            ],
            "data_seed_contract": dataset_meta.get("data_seed_contract"),
            "data_seed_effective": dataset_meta.get("data_seed_effective"),
            "data_seed_derivation": dataset_meta.get("data_seed_derivation"),
            "lr_schedule_origin_tok": _dblock_require_exact_int(
                getattr(args, "_lr_schedule_origin_tok", None),
                "authoritative run-state LR origin",
                minimum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
                maximum=_AGILLM43_REPAIR_BASE_SEEN_TOK,
            ),
            "checkpoint": checkpoint_receipt,
            "dataset_provenance": _dblock_json_copy(dataset_meta),
            "warmstart": _dblock_json_copy(lineage),
            "training_science": _training_science_snapshot(args),
            "updated_utc": time.strftime(
                "%Y-%m-%dT%H:%M:%SZ", time.gmtime()
            ),
        }
        publication = _agillm43_publish_run_state(
            args.save_dir, payload, authoritative=True
        )
        print(
            f"[run-state] authoritative status={status} step={step} "
            f"seen_tok={seen_tok} checkpoint={checkpoint_path.name} "
            f"sha256={checkpoint_receipt['sha256']}",
            flush=True,
        )
        return publication

    if DEV.type == "cuda":
        try:
            torch.cuda.empty_cache()
            torch.cuda.reset_peak_memory_stats()
            print(
                f"[vram] training-start cache cleared: "
                f"alloc={torch.cuda.memory_allocated() / (1024**3):.2f}GB "
                f"reserved={torch.cuda.memory_reserved() / (1024**3):.2f}GB "
                f"structured_masks={use_structured_masks(args)}",
                flush=True,
            )
        except Exception:
            pass
    _prov_loss = None
    if strict_repair and seen_tok == _AGILLM43_REPAIR_TARGET_SEEN_TOK:
        prior_loss = (
            provenance_cache.get("loss")
            if isinstance(provenance_cache, dict) else None
        )
        if (isinstance(prior_loss, bool)
                or not isinstance(prior_loss, (int, float))
                or not math.isfinite(float(prior_loss))):
            raise RuntimeError(
                "endpoint resume requires a finite prior checkpoint loss"
            )
        _prov_loss = float(prior_loss)
    while seen_tok < total_tokens_needed:
        _science_step_started = time.monotonic()
        # AGILLM-LR-DECAY 20260706: cosine multiplier from seen_tok; no-op when lr_decay=none
        if getattr(args, "lr_decay", "none") == "cosine":
            _lrmult, _lr_seen = _repair_lr_multiplier(args, seen_tok, total_tokens_needed)
            args._lr_schedule_seen_tok = int(_lr_seen)
            for _lrg in opt.param_groups:
                _lr_base = float(_lrg.get("base_lr", _lrg["lr"]))
                if str(_lrg.get("agillm43_role") or "") in ("sat_variable_gate", "sat_variable_gate_conf", "satvar_shift", "satvar_regret"):
                    # The 1-vs-2 gate was introduced/reset late in training and
                    # has its own calibration LR.  Do not decay that fresh
                    # classifier on the mature core's 400B-token cosine clock.
                    _lrg["lr"] = _lr_base
                else:
                    _lrg["lr"] = _lr_base * _lrmult
        # AGILLM-LR-GOVERNOR 20260902 (owner-directed): hot-reloadable, bounded LR override.
        # Inert unless /workspace/agillm43_lr_override.json exists with a finite positive "lr".
        # It can only RAISE the effective LR above the schedule value (never below it), ramps in
        # linearly over ramp_tokens from since_seen_tok, and is hard-clamped to <= 1e-3.
        # Never touches the sat_variable_gate group; never alters optimizer or checkpoint state.
        _lrov = _agillm43_lr_override_value(seen_tok)
        if _lrov is not None:
            for _lrg in opt.param_groups:
                if str(_lrg.get("agillm43_role") or "") in ("sat_variable_gate", "sat_variable_gate_conf", "satvar_shift", "satvar_regret"):
                    continue
                _lrg["lr"] = max(float(_lrg["lr"]), float(_lrov))
        _profile_batch = _DBS is not None and int(getattr(args, "profile_steps", 0) or 0) > 0 and int(_DBS.get("profile_n", 0)) < int(getattr(args, "profile_steps", 0) or 0)
        _data_t = time.perf_counter() if _profile_batch else None
        loss_mask = None
        if completion_only:
            try:
                while len(batch_accum) < BATCH:
                    seq, mseq = next(sft_stream)
                    batch_accum.append(seq)
                    mask_accum.append(mseq)
            except StopIteration:
                break
        else:
            try:
                if sequence_stream is not None:
                    seq = next(sequence_stream)
                else:
                    while len(buf) < BLOCK:
                        buf.append(next(stream))
                    seq = buf[:BLOCK]
                    buf = buf[BLOCK:]
            except StopIteration:
                break
            if _profile_batch:
                try:
                    _db_prof = _agillm41_sys.modules[__name__]
                    _db_prof._profile_add(_DBS, "data_stream", time.perf_counter() - _data_t)
                except Exception:
                    pass
            batch_accum.append(seq)
        if len(batch_accum) < BATCH:
            continue
        _tensor_t = time.perf_counter() if _profile_batch else None
        ids = torch.tensor(batch_accum, device=DEV)
        if completion_only:
            loss_mask = torch.tensor(mask_accum, dtype=torch.bool, device=DEV)
        if _profile_batch:
            if DEV.type == "cuda":
                try:
                    torch.cuda.synchronize()
                except Exception:
                    pass
            try:
                _db_prof = _agillm41_sys.modules[__name__]
                _db_prof._profile_add(_DBS, "tensor", time.perf_counter() - _tensor_t)
            except Exception:
                pass
        batch_accum = []
        if completion_only:
            mask_accum = []
        tgt_ar = ids.clone()
        try:
            if getattr(args, "dblock", False):
                loss_value = _dblock_step(core, ar_h, sat_h, nat_h, opt, scaler, args, ids, _DBS, loss_mask=loss_mask)
                _prov_loss = float(loss_value)
            else:
                with amp(args.amp):
                    h_ar = core(ids, causal_mask(ids.size(1), structured=use_structured_masks(args)))
                    logits_ar = ar_h(h_ar)[:, :-1]
                    if loss_mask is not None:
                        _lm = loss_mask[:, 1:].reshape(-1)
                        _logits_flat = logits_ar.reshape(-1, VOCAB)
                        _targets_flat = tgt_ar[:, 1:].reshape(-1)
                        loss_ar = ce_tok(_logits_flat[_lm], _targets_flat[_lm])
                    else:
                        loss_ar = ce_tok(logits_ar.reshape(-1, VOCAB), tgt_ar[:, 1:].reshape(-1))
                loss_value = float(loss_ar.detach().item())
                _aux = _collect_moe_aux(core, getattr(args,'moe_aux_coef',0.0), getattr(args,'moe_z_coef',0.0))
                if torch.is_tensor(_aux):
                    loss_ar = loss_ar + _aux.to(loss_ar.dtype)
                scaler.scale(loss_ar).backward()
                del h_ar, logits_ar, loss_ar
                do_sat = (not args.ar_only) and (args.sat_every <= 1 or ((step + 1) % args.sat_every == 0))
                if do_sat:
                    # Same AR+SAT objective as a summed loss, but sequential backward keeps
                    # only one core-forward activation graph live at a time on 24GB cards.
                    with amp(args.amp):
                        h_sat = core(ids, sat_mask(ids.size(1), structured=use_structured_masks(args)))
                        sat_ctx = h_sat[:, :-SAT_BLOCK]
                        tgt_sat = ids[:, SAT_BLOCK:]
                        if sat_ctx.size(1) == 0 or sat_ctx.size(1) != tgt_sat.size(1):
                            sat_ctx = h_sat[:, :-1]
                            tgt_sat = ids[:, 1:]
                        logits_sat = sat_h.proj(sat_ctx)
                        if loss_mask is not None:
                            _sat_lm = loss_mask[:, SAT_BLOCK:] if sat_ctx.size(1) == loss_mask[:, SAT_BLOCK:].size(1) else loss_mask[:, 1:]
                            loss_sat = ce_tok(logits_sat.reshape(-1, VOCAB)[_sat_lm.reshape(-1)], tgt_sat.reshape(-1)[_sat_lm.reshape(-1)])
                        else:
                            loss_sat = ce_tok(logits_sat.reshape(-1, VOCAB), tgt_sat.reshape(-1))
                        # Ordinary SAT pretraining trains token prediction only.
                        # Variable 1/2-token gate labels are verifier-derived and
                        # trained only by the bounded ORPO admission-gate path.
                    loss_value += float(loss_sat.detach().item())
                    _aux = _collect_moe_aux(core, getattr(args,'moe_aux_coef',0.0), getattr(args,'moe_z_coef',0.0))
                    if torch.is_tensor(_aux):
                        loss_sat = loss_sat + _aux.to(loss_sat.dtype)
                    scaler.scale(loss_sat).backward()
                    del h_sat, logits_sat, loss_sat
                do_nat = (
                    nat_h is not None
                    and (not args.ar_only)
                    and args.nat_every > 0
                    and (args.nat_every <= 1 or ((step + 1) % args.nat_every == 0))
                )
                if do_nat:
                    nat_ids = _nat_ids_for_training(ids, args.nat_max_tokens)
                    with amp(args.amp):
                        # Mask-predict (CMLM) objective: corrupt a fraction of positions
                        # with BLANK and reconstruct them from surrounding context. The
                        # old CTC objective fed the clean target as input, so the head
                        # only learned to copy and collapsed at inference on all-BLANK
                        # input. This conditions on real context and cannot collapse.
                        nat_in = nat_ids.clone()
                        ratio = min(max(float(args.nat_mask_ratio), 0.05), 0.95)
                        _nat_lm = (
                            loss_mask[:, -nat_ids.size(1):]
                            if loss_mask is not None else None
                        )
                        try:
                            mask = _nat_corruption_mask(
                                nat_ids, ratio, args, loss_mask=_nat_lm
                            )
                        except ValueError as exc:
                            opt.zero_grad(set_to_none=True)
                            _dblock_clear_moe_aux_stash(core)
                            eos_pad_id, nat_mask_id = _nat_boundary_ids()
                            reason = (
                                "nat_corruption_clean_mask_id"
                                if bool(nat_ids.eq(nat_mask_id).any())
                                else "nat_corruption_invalid_input"
                            )
                            diagnostics = {
                                "batch_sha256": _dblock_tensor_sha256(
                                    nat_ids
                                ),
                                "batch_shape": [
                                    int(nat_ids.size(0)),
                                    int(nat_ids.size(1)),
                                ],
                                "eos_pad_count": int(
                                    nat_ids.eq(eos_pad_id).sum().item()
                                ),
                                "nat_mask_count": int(
                                    nat_ids.eq(nat_mask_id).sum().item()
                                ),
                                "error": str(exc),
                            }
                            if bool(getattr(args, "repair_mode", False)) or bool(
                                getattr(args, "repair_fail_fast", False)
                            ):
                                _repair_write_fail(
                                    args, reason, step=int(step),
                                    diagnostics=diagnostics,
                                )
                            raise RuntimeError(
                                "NAT corruption rejected invalid clean "
                                f"input: {exc}"
                            ) from exc
                        if not bool(mask.any()):
                            diagnostics = {
                                "batch_sha256": _dblock_tensor_sha256(nat_ids),
                                "batch_shape": [
                                    int(nat_ids.size(0)), int(nat_ids.size(1))
                                ],
                            }
                            if bool(getattr(args, "repair_mode", False)):
                                _repair_write_fail(
                                    args, "nat_corruption_no_valid_targets",
                                    step=int(step), diagnostics=diagnostics,
                                )
                            raise RuntimeError(
                                "NAT corruption has no eligible targets"
                            )
                        nat_in[mask] = NAT_MASK_ID
                        h_nat = core(nat_in, None)
                        logits_nat = nat_h(h_nat)
                        loss_nat = F.cross_entropy(logits_nat[mask].float(), nat_ids[mask])
                        loss_nat = float(args.nat_loss_weight) * loss_nat
                    loss_value += float(loss_nat.detach().item())
                    _aux = _collect_moe_aux(core, getattr(args,'moe_aux_coef',0.0), getattr(args,'moe_z_coef',0.0))
                    if torch.is_tensor(_aux):
                        loss_nat = loss_nat + _aux.to(loss_nat.dtype)
                    scaler.scale(loss_nat).backward()
                    del nat_ids, nat_in, mask, h_nat, logits_nat, loss_nat
                _prov_loss = float(loss_value)
                scaler.unscale_(opt)
                nn.utils.clip_grad_norm_([p for group in opt.param_groups for p in group["params"]], 1.0)
                scaler.step(opt)
                scaler.update()
                opt.zero_grad(set_to_none=True)
        except RuntimeError as e:
            msg = str(e).lower()
            if "out of memory" in msg or "cuda error" in msg:
                _dblock_route_oom = False
                if getattr(args, "dblock", False) and isinstance(_DBS, dict):
                    route_runtime = _DBS.get("target_route")
                    route_receipt = _DBS.get("training_science_last_receipt")
                    if (
                        isinstance(route_runtime, dict)
                        and isinstance(route_runtime.get("pending_target"), dict)
                        and not bool(
                            (route_receipt or {}).get(
                                "_target_route_audit_emitted", False
                            )
                        )
                    ):
                        if not isinstance(route_receipt, dict):
                            raise RuntimeError(
                                "xor-fold56-v1 OOM lost its attempt receipt"
                            ) from e
                        _dblock_route_oom = True
                        route_receipt["route_outcome"] = "cuda_oom_or_error"
                        _dblock_emit_target_route_receipt(_DBS, args)
                batch_accum = []
                try:
                    del ids, tgt_ar, loss_mask
                except Exception:
                    pass
                opt.zero_grad(set_to_none=True)
                scaler = GradScaler(enabled=(args.amp and _needs_grad_scaler()))
                peak_gb = _oom_backoff_peak_gb()
                if DEV.type == "cuda":
                    try:
                        torch.cuda.empty_cache()
                    except Exception:
                        pass
                    try:
                        torch.cuda.synchronize()
                    except Exception:
                        pass
                if _oom_backoff_enabled(args):
                    _oom_backoff_record(args, oom_state, oom_state_path, oom_key, oom_signature, outcome="oom", batch=BATCH, block=BLOCK, step=step, phase_name=phase_name, peak_gb=peak_gb)
                if bool(getattr(args, "repair_fail_fast", False)):
                    _repair_write_fail(
                        args, "cuda_oom_or_error", message=str(e)[:1200], step=int(step),
                        batch=int(BATCH), block=int(BLOCK), peak_gb=float(peak_gb),
                    )
                    raise RuntimeError("repair fail-fast CUDA failure") from e
                oom_retries += 1
                if oom_retries <= MAX_OOM_RETRIES:
                    print(f"\n[{phase_name} OOM] Retry {oom_retries}/{MAX_OOM_RETRIES} at Batch={BATCH}, clearing VRAM...")
                    time.sleep(2)
                else:
                    oom_retries = 0
                    if BATCH > 1:
                        entry = _oom_backoff_entry(oom_state, oom_key, oom_signature) if _oom_backoff_enabled(args) else {}
                        if _oom_backoff_enabled(args):
                            _nb = _oom_backoff_next_batch(args, entry, BATCH)
                        else:
                            _known_safe = max(0, int(getattr(args, "oom_known_safe_batch", 0) or 0))
                            _nb = _known_safe if 0 < _known_safe < BATCH else max(1, int(BATCH * 0.85))
                        if _nb >= BATCH:
                            _nb = BATCH - 1
                        print(f"\n[{phase_name} OOM] Reducing Batch: {BATCH} -> {_nb} (persistent learned backoff, state={oom_state_path})")
                        BATCH = _nb
                        oom_good_steps = 0
                        time.sleep(2)
                    else:
                        new_block = max(128, int(BLOCK * 0.8))
                        new_block = max(128, (new_block // 128) * 128)
                        if new_block >= BLOCK:
                            new_block = max(128, BLOCK - 128)
                        print(f"\n[{phase_name} OOM] Reducing Block: {BLOCK} -> {new_block}")
                        BLOCK = new_block
                        oom_good_steps = 0
                        if _oom_backoff_enabled(args):
                            BATCH, oom_state, oom_state_path, oom_key, oom_signature = _oom_backoff_start(args, phase_name, BLOCK, BATCH)
                        time.sleep(2)
                steps_since_last_grow = 0
                if not _dblock_route_oom:
                    continue
                # The policy-owned attempt clock was advanced before CUDA work.
                # Fall through to the common rejected-attempt heartbeat/flush
                # path so a persistent OOM cannot starve a requested checkpoint.
                _prior_loss = _prov_loss
                if (
                    (isinstance(_prior_loss, bool) or not isinstance(
                        _prior_loss, (int, float)
                    ) or not math.isfinite(float(_prior_loss)))
                    and isinstance(provenance_cache, dict)
                ):
                    _prior_loss = provenance_cache.get("loss")
                loss_value = (
                    float(_prior_loss)
                    if not isinstance(_prior_loss, bool)
                    and isinstance(_prior_loss, (int, float))
                    and math.isfinite(float(_prior_loss))
                    else float("nan")
                )
            else:
                raise
        _dblock_attempt_rejected = bool(
            getattr(args, "dblock", False)
            and not bool(_DBS.get("last_update_trained", False))
        )
        if _dblock_attempt_rejected:
            _attempt_clock = int(_DBS.get("attempt_step", 0))
            print(
                f"[{phase_name}] skipped DBlock attempt did not advance "
                "global step/tokens/LR "
                f"(attempt={_attempt_clock}); servicing heartbeat/flush "
                "at the committed state",
                flush=True,
            )
        else:
            step += 1
            _det50_after_mature_commit(
                args, ids, _DBS, step, loss_value, loss_mask=loss_mask)
            _weight_accel_maybe_apply(
                core, ar_h, sat_h, nat_h, opt, args, _DBS, val_batches, step
            )
            # Periodic tokenizer spot-check: verify training data has spaces
            if step % 1000 == 0:
                try:
                    sample_text = tok.decode(ids[0][:50].tolist(), skip_special_tokens=True)
                    if len(sample_text) > 20 and " " not in sample_text:
                        print(f"\n[tokenizer] ALERT step {step}: decoded batch has NO SPACES!")
                        print(f"  Sample: {repr(sample_text[:80])}")
                        print("  Check transformers version!")
                except Exception:
                    pass
            oom_retries = 0
            if _oom_backoff_enabled(args):
                oom_good_steps += 1
                good_every = max(1, int(getattr(args, "oom_warmup_good_steps", 16) or 16))
                if oom_good_steps in (1, good_every) or (oom_good_steps % max(1, good_every * 4) == 0):
                    _oom_backoff_record(args, oom_state, oom_state_path, oom_key, oom_signature, outcome="success", batch=BATCH, block=BLOCK, step=step, phase_name=phase_name, peak_gb=_oom_backoff_peak_gb())
            toks_processed = BLOCK * BATCH
            seen_tok += toks_processed
            _science_committed = (
                bool((_DBS or {}).get("last_update_trained", False))
                if _DBS is not None else True
            )
            _science_stop_reason = _training_science_step(
                args, step=step, seen_tok=seen_tok, raw_tokens=toks_processed,
                elapsed_seconds=time.monotonic() - _science_step_started,
                committed=_science_committed, dblock_state=_DBS,
                loss_value=loss_value, batch_size=BATCH, block_size=BLOCK,
            )
            _science_live = _training_science_snapshot(args)
            pbar.set_postfix(
                loss=f"{loss_value:.3f}", B=BATCH, L=BLOCK,
                eq_s=f"{float(_science_live.get('ema_full_stack_equiv_tok_per_sec', 0.0) or 0.0):.2f}",
                lupd_s=f"{float(_science_live.get('ema_layer_token_updates_per_sec', 0.0) or 0.0):.2f}",
            )
            pbar.update(toks_processed)
            if _science_stop_reason:
                print(
                    f"[{phase_name}] {_science_stop_reason}; flushing controlled experiment endpoint",
                    flush=True,
                )
                _flush_flag[0] = True
                _terminate_after_flush[0] = True
            dblock_stop_after = int(
                getattr(args, "dblock_stop_after_commits", 0) or 0
            )
            if (dblock_stop_after > 0 and _DBS is not None
                    and int(_DBS.get("step", 0) or 0) >= dblock_stop_after):
                print(
                    f"[{phase_name}] reached requested DBlock commit stop "
                    f"{int(_DBS.get('step', 0))}/{dblock_stop_after}; "
                    "flushing an authoritative checkpoint",
                    flush=True,
                )
                _flush_flag[0] = True
                _terminate_after_flush[0] = True
            async_every = int(getattr(args, "async_update_every_steps", 0) or 0)
            if async_every > 0 and (step % async_every) == 0:
                _hf_fed_log_side_updates(*_apply_async_side_updates(core, cfg, args, step), step)
            cuda_max_reserved_mib = int(
                getattr(args, "cuda_max_reserved_mib", 0) or 0
            )
            if DEV.type == "cuda" and cuda_max_reserved_mib > 0:
                cuda_peak_reserved_mib = int(
                    torch.cuda.max_memory_reserved() // (1024 * 1024)
                )
                if cuda_peak_reserved_mib > cuda_max_reserved_mib:
                    raise RuntimeError(
                        "CUDA peak-reserved safety ceiling breached for a committed "
                        f"update: {cuda_peak_reserved_mib} MiB > "
                        f"{cuda_max_reserved_mib} MiB"
                    )
            empty_cache_every = int(getattr(args, "empty_cache_every_steps", 0) or 0)
            if DEV.type == "cuda" and empty_cache_every > 0 and (step % empty_cache_every) == 0:
                try:
                    torch.cuda.empty_cache()
                except Exception:
                    pass
            cuda_min_free_mib = int(
                getattr(args, "cuda_min_free_mib", 0) or 0
            )
            if DEV.type == "cuda" and cuda_min_free_mib > 0:
                cuda_free, cuda_total = torch.cuda.mem_get_info()
                cuda_free_mib = int(cuda_free // (1024 * 1024))
                if cuda_free_mib < cuda_min_free_mib:
                    raise RuntimeError(
                        "CUDA free-memory safety floor breached after cache reclaim "
                        "for a committed update: "
                        f"{cuda_free_mib} MiB < {cuda_min_free_mib} MiB "
                        f"(total={int(cuda_total // (1024 * 1024))} MiB)"
                    )
        heartbeat_every = int(getattr(args, "heartbeat_every_sec", 300) or 0)
        now_mono = time.monotonic()
        if heartbeat_every > 0 and now_mono - last_heartbeat_mono >= heartbeat_every:
            mem = ""
            if DEV.type == "cuda":
                try:
                    mem = (
                        f" gpu_alloc={torch.cuda.memory_allocated() / (1024**3):.2f}GB"
                        f" gpu_reserved={torch.cuda.memory_reserved() / (1024**3):.2f}GB"
                        f" gpu_peak={torch.cuda.max_memory_allocated() / (1024**3):.2f}GB"
                    )
                except Exception:
                    mem = ""
            try:
                science_snapshot = _training_science_snapshot(args)
                heartbeat_payload = {
                    "schema": "agillm.run_state.v1",
                    "model": "AGILLM4.3",
                    "phase": "training",
                    "trainer_phase": phase_name,
                    "pid": int(os.getpid()),
                    "step": int(step),
                    "seen_tok": int(seen_tok),
                    "loss": float(loss_value),
                    "training_science": science_snapshot,
                    "batch_size": int(BATCH),
                    "requested_batch_size": int(BATCH_REQUESTED),
                    "block": int(BLOCK),
                    "oom_backoff": {
                        "enabled": bool(_oom_backoff_enabled(args)),
                        "state_path": str(oom_state_path),
                        "key": str(oom_key),
                    },
                    "dblock": bool(getattr(args, "dblock", False)),
                    "dblock_blocks": int(getattr(args, "dblock_blocks", 0) or 0),
                    "dblock_forward_layers_per_update": int(getattr(args, "dblock_layers_per_update", 0) or 0),
                    "dblock_train_layers_per_update": int(getattr(args, "dblock_train_layers_per_update", 0) or 0),
                    "dblock_train_layer_policy": str(getattr(args, "dblock_train_layer_policy", "cyclic") or "cyclic"),
                    "dblock_train_sublayers_per_update": int(getattr(args, "dblock_train_sublayers_per_update", 0) or 0),
                    "dblock_train_sublayer_policy": str(getattr(args, "dblock_train_sublayer_policy", "cyclic") or "cyclic"),
                    "dblock_router_train_layers_per_update": int(getattr(args, "dblock_router_train_layers_per_update", 0) or 0),
                    "dblock_router_train_layer_policy": str(getattr(args, "dblock_router_train_layer_policy", "cyclic") or "cyclic"),
                    "dblock_router_full_anchor_every": int(getattr(args, "dblock_router_full_anchor_every", 0) or 0),
                    "granularity_label": str(getattr(args, "granularity_label", "") or ""),
                    "dblock_last_forward_layers": list(((_DBS or {}).get("training_science_last_receipt") or {}).get("forward_layers", []) or []),
                    "dblock_last_train_layers": list(((_DBS or {}).get("training_science_last_receipt") or {}).get("train_layers", []) or []),
                    "dblock_last_train_sublayers": list(((_DBS or {}).get("training_science_last_receipt") or {}).get("train_sublayers", []) or []),
                    "dblock_router_internal_layer_counts": list(((_DBS or {}).get("router_internal_layer_counts", []) or [])),
                    "dblock_router_internal_full_anchor_updates": int(((_DBS or {}).get("router_internal_full_anchor_updates", 0) or 0)),
                    "dblock_router_last_internal_update": _dblock_json_copy(((_DBS or {}).get("router_last_internal_update"))),
                    "dblock_ar_prob": float(getattr(args, "dblock_ar_prob", 0.0) or 0.0),
                    "dblock_sat_prob": float(getattr(args, "dblock_sat_prob", 0.0) or 0.0),
                    "dblock_nat_prob": float(getattr(args, "dblock_nat_prob", 0.0) or 0.0),
                    "dblock_fullstack_ar_offset": int(getattr(args, "dblock_fullstack_ar_offset", 0) or 0),
                    "dblock_fullstack_ar_every": int(getattr(args, "dblock_fullstack_ar_every", 0) or 0),
                    "dblock_fullstack_ar_tokens": int(getattr(args, "dblock_fullstack_ar_tokens", 0) or 0),
                    "dblock_fullstack_ar_weight": float(getattr(args, "dblock_fullstack_ar_weight", 0.0) or 0.0),
                    "dblock_fullstack_sat_every": int(getattr(args, "dblock_fullstack_sat_every", 0) or 0),
                    "dblock_fullstack_sat_offset": int(getattr(args, "dblock_fullstack_sat_offset", 4) or 0),
                    "dblock_fullstack_sat_tokens": int(getattr(args, "dblock_fullstack_sat_tokens", 0) or 0),
                    "dblock_fullstack_sat_weight": float(getattr(args, "dblock_fullstack_sat_weight", 0.0) or 0.0),
                    "dblock_fullstack_nat_every": int(getattr(args, "dblock_fullstack_nat_every", 0) or 0),
                    "dblock_fullstack_nat_offset": int(getattr(args, "dblock_fullstack_nat_offset", 20) or 0),
                    "dblock_fullstack_nat_tokens": int(getattr(args, "dblock_fullstack_nat_tokens", 0) or 0),
                    "dblock_fullstack_nat_weight": float(getattr(args, "dblock_fullstack_nat_weight", 0.0) or 0.0),
                    "dblock_fullstack_nat_mask_id": int(getattr(args, "dblock_fullstack_nat_mask_id", -1)),
                    "nat_document_boundary_aware": bool(getattr(args, "nat_document_boundary_aware", False)),
                    "dblock_fullstack_anchor_deterministic_eval": bool(getattr(args, "dblock_fullstack_anchor_deterministic_eval", False)),
                    "dblock_fullstack_nat_no_valid_crop_limit": int(getattr(args, "dblock_fullstack_nat_no_valid_crop_limit", 0) or 0),
                    "dblock_fullstack_anchor_spike_retry_limit": int(getattr(args, "dblock_fullstack_anchor_spike_retry_limit", 0) or 0),
                    "dblock_local_spike_retry_limit": int(getattr(args, "dblock_local_spike_retry_limit", 0) or 0),
                    "dblock_local_aux_warn_ce": float(getattr(args, "dblock_local_aux_warn_ce", 0.0) or 0.0),
                    "dblock_local_aux_max_ce": float(getattr(args, "dblock_local_aux_max_ce", 0.0) or 0.0),
                    "fullstack_anchor_spike_consecutive_by_family": dict((_DBS or {}).get("fullstack_anchor_spike_consecutive_by_family", {})),
                    "local_spike_consecutive_by_objective_block": dict((_DBS or {}).get("local_spike_consecutive_by_objective_block", {})),
                    "fullstack_nat_anchor_no_valid_crop_consecutive": int((_DBS or {}).get("fullstack_nat_anchor_no_valid_crop_consecutive", 0) or 0),
                    "fullstack_nat_anchor_no_valid_crop_total": int((_DBS or {}).get("fullstack_nat_anchor_no_valid_crop_total", 0) or 0),
                    "supervised_targets": dict((_DBS or {}).get("supervised_targets", {})),
                    "supervised_targets_by_block": dict((_DBS or {}).get("supervised_targets_by_block", {})),
                    "committed_objective_steps": dict((_DBS or {}).get("committed_objective_steps", {})),
                    "committed_objective_steps_by_block": dict((_DBS or {}).get("committed_objective_steps_by_block", {})),
                    "fullstack_anchor_attempts": int((_DBS or {}).get("fullstack_anchor_attempts", 0) or 0),
                    "fullstack_anchor_runs": int((_DBS or {}).get("fullstack_anchor_runs", 0) or 0),
                    "fullstack_anchor_skipped_empty_mask": int((_DBS or {}).get("fullstack_anchor_skipped_empty_mask", 0) or 0),
                    "fullstack_anchor_last": dict((_DBS or {}).get("fullstack_anchor_last", {})),
                    "fullstack_sat_anchor_attempts": int((_DBS or {}).get("fullstack_sat_anchor_attempts", 0) or 0),
                    "fullstack_sat_anchor_runs": int((_DBS or {}).get("fullstack_sat_anchor_runs", 0) or 0),
                    "fullstack_sat_anchor_last": dict((_DBS or {}).get("fullstack_sat_anchor_last", {})),
                    "fullstack_nat_anchor_attempts": int((_DBS or {}).get("fullstack_nat_anchor_attempts", 0) or 0),
                    "fullstack_nat_anchor_runs": int((_DBS or {}).get("fullstack_nat_anchor_runs", 0) or 0),
                    "fullstack_nat_anchor_last": dict((_DBS or {}).get("fullstack_nat_anchor_last", {})),
                    "optimizer_overflow_skips": int((_DBS or {}).get("optimizer_overflow_skips", 0) or 0),
                    "repair_validation": dict(repair_val_state),
                    "repair_mode": bool(getattr(args, "repair_mode", False)),
                    "repair_schema": _AGILLM_REPAIR_SCHEMA if bool(getattr(args, "repair_mode", False)) else "",
                    "repair_target_commits": (
                        _AGILLM43_REPAIR_TARGET_COMMITS if strict_repair else None
                    ),
                    "repair_target_step": (
                        _AGILLM43_REPAIR_TARGET_STEP if strict_repair else None
                    ),
                    "repair_target_seen_tok": (
                        _AGILLM43_REPAIR_TARGET_SEEN_TOK if strict_repair else None
                    ),
                    "data_seed_contract": dataset_meta.get("data_seed_contract"),
                    "data_seed_effective": dataset_meta.get("data_seed_effective"),
                    "repair_dataset_schema": _AGILLM43_REPAIR_DATASET_SCHEMA,
                    "example_boundary_policy": _AGILLM43_EXAMPLE_BOUNDARY_POLICY,
                    "dblock_attempt_rejected": bool(_dblock_attempt_rejected),
                    "alibi_mode": str(_AGILLM_ALIBI_MODE),
                    "alibi_scale": float(_AGILLM_ALIBI_SCALE),
                    "lr_schedule_origin_tok": int(getattr(args, "_lr_schedule_origin_tok", 0) or 0),
                    "lr_schedule_seen_tok": int(getattr(args, "_lr_schedule_seen_tok", 0) or 0),
                    "sat_every": int(getattr(args, "sat_every", 0) or 0),
                    "nat_every": int(getattr(args, "nat_every", 0) or 0),
                    "oom_auto_backoff": bool(getattr(args, "oom_auto_backoff", False)),
                    "ckpt_codec": str(getattr(args, "ckpt_codec", "") or ""),
                    "delta_codec": str(getattr(args, "delta_codec", "") or ""),
                    "structured_masks": bool(use_structured_masks(args)),
                    "device": str(DEV),
                    "save_dir": str(args.save_dir),
                    "dataset_provenance": dataset_meta,
                    "warmstart": lineage,
                    "warmstart_source_path": lineage.get("source_path", ""),
                    "warmstart_kind": lineage.get("warmstart_kind", ""),
                    "warmstart_base_step": int(lineage.get("warmstart_base_step", 0) or 0),
                    "global_origin_step": int(lineage.get("global_origin_step", 0) or 0),
                    "effective_global_step": int((int(lineage.get("global_origin_step", 0) or 0) + int(step)) if int(lineage.get("global_origin_step", 0) or 0) > 0 else int(step)),
                    "warmstart_base_seen_tok": int(lineage.get("warmstart_base_seen_tok", 0) or 0),
                    "global_origin_seen_tok": int(lineage.get("global_origin_seen_tok", 0) or 0),
                    "effective_seen_tok": int(int(lineage.get("global_origin_seen_tok", 0) or 0) + int(seen_tok)),
                    "updated_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                }
                if DEV.type == "cuda":
                    try:
                        heartbeat_payload["gpu"] = {
                            "allocated_gb": round(torch.cuda.memory_allocated() / (1024**3), 4),
                            "reserved_gb": round(torch.cuda.memory_reserved() / (1024**3), 4),
                            "peak_allocated_gb": round(torch.cuda.max_memory_allocated() / (1024**3), 4),
                        }
                    except Exception:
                        pass
                hb_path = pathlib.Path(args.save_dir) / "run_state.json"
                hb_tmp = hb_path.with_suffix(".json.tmp")
                hb_tmp.write_text(json.dumps(heartbeat_payload, sort_keys=True) + "\n")
                hb_tmp.replace(hb_path)
                top_path = pathlib.Path(args.save_dir).parent / "agillm43_run_state.json"
                merged = {}
                if top_path.exists():
                    try:
                        merged = json.loads(top_path.read_text())
                    except Exception:
                        merged = {}
                if isinstance(merged, dict):
                    merged.update(heartbeat_payload)
                    merged["phase"] = "training"
                    merged["destructive_actions_allowed"] = False
                    top_tmp = top_path.with_suffix(".json.tmp")
                    top_tmp.write_text(json.dumps(merged, indent=2, sort_keys=True) + "\n")
                    top_tmp.replace(top_path)
            except Exception as exc:
                print(f"[heartbeat-json] warning: {exc}", flush=True)
            _science_hb = _training_science_snapshot(args)
            print(
                f"[heartbeat] phase={phase_name} pid={os.getpid()} step={step} "
                f"seen_tok={seen_tok} loss={loss_value:.3f} lr={opt.param_groups[0].get('lr'):.2e} B={BATCH} L={BLOCK} "
                f"raw_tok_s={float(_science_hb.get('ema_raw_tok_per_sec', 0.0) or 0.0):.1f} "
                f"fullstack_equiv_tok_s={float(_science_hb.get('ema_full_stack_equiv_tok_per_sec', 0.0) or 0.0):.1f} "
                f"layer_updates_s={float(_science_hb.get('ema_layer_token_updates_per_sec', 0.0) or 0.0):.1f} "
                f"dblock={bool(getattr(args, 'dblock', False))} structured_masks={use_structured_masks(args)}{mem}",
                flush=True,
            )
            last_heartbeat_mono = now_mono
        _val_due_time = (
            int(getattr(args, "val_every_sec", 0) or 0) > 0
            and (time.monotonic() - last_val_mono) >= int(args.val_every_sec)
        )
        _generic_val_every_steps = int(getattr(args, "val_every_steps", 0) or 0)
        _repair_val_every_steps = int(getattr(args, "repair_val_every_steps", 0) or 0)
        _val_due_step = (
            (_generic_val_every_steps > 0
             and (int(step) - int(last_val_step)) >= _generic_val_every_steps)
            or
            (strict_repair and _repair_val_every_steps > 0
             and (int(step) - int(last_val_step)) >= _repair_val_every_steps)
        )
        if (not _dblock_attempt_rejected) and val_batches and (_val_due_time or _val_due_step):
            _val_ce = _run_validation(
                core, ar_h, val_batches, args, step, sat_h=sat_h, nat_h=nat_h
            )
            _val_stop = _repair_update_validation(args, repair_val_state, _val_ce, step)
            last_val_mono = time.monotonic()
            last_val_step = int(step)
            if _val_stop and bool(getattr(args, "repair_fail_fast", False)):
                _repair_write_fail(args, "validation_regression", message=_val_stop, step=int(step), validation=repair_val_state)
                _flush_flag[0] = True
                _terminate_after_flush[0] = True
        _flush_sentinel = pathlib.Path(args.save_dir) / "FLUSH_NOW"
        if _flush_flag[0] or _flush_sentinel.exists():
            def _perform_on_demand_flush():
                nonlocal last_save_mono, last_delta_step, last_delta_mono
                nonlocal last_val_mono, last_val_step
                validation_snapshot = copy.deepcopy(repair_val_state)
                prior_last_val_mono = last_val_mono
                prior_last_val_step = last_val_step
                prior_last_save_mono = last_save_mono
                prior_last_delta_step = last_delta_step
                prior_last_delta_mono = last_delta_mono
                try:
                    _repair_authoritative_validation_before_save("on_demand")
                    ck_name = _repair_unique_on_demand_checkpoint_name(
                        phase_name, step, _origin_tag, _role_tag
                    )
                    _flush_delta()
                    _disk_hygiene(
                        pathlib.Path(args.save_dir), phase_name, args,
                        reason="pre-flush-save",
                    )
                    _prune_checkpoints(
                        pathlib.Path(args.save_dir), phase_name, max_ckpts
                    )
                    prov = _agillm_provenance.collect(
                        args,
                        step=step, seen_tok=seen_tok, loss=_prov_loss,
                        batch_size=BATCH_REQUESTED, block_size=BLOCK,
                        warmstart_source_path=(
                            getattr(args, "warmstart_from", None)
                            or getattr(args, "resume", None)
                            or getattr(args, "resume_delta", None)
                        ),
                        warmstart_source_provenance=provenance_cache,
                        dataset_provenance=dataset_meta,
                        lane=phase_name or "",
                    )
                    save_ckpt(
                        pathlib.Path(args.save_dir) / ck_name,
                        core, ar_h, sat_h, nat_h, opt, scaler,
                        meta=_phase_checkpoint_meta(step, seen_tok),
                        codec=getattr(args, "ckpt_codec", "zstd3"),
                        provenance=prov,
                    )
                    _prune_checkpoints(
                        pathlib.Path(args.save_dir), phase_name, max_ckpts
                    )
                    last_save_mono = time.monotonic()
                    _prune_deltas(
                        pathlib.Path(args.save_dir), phase_name,
                        args.delta_max_keep,
                    )
                    last_delta_step = step
                    last_delta_mono = time.monotonic()
                    return ck_name
                except Exception:
                    repair_val_state.clear()
                    repair_val_state.update(validation_snapshot)
                    last_val_mono = prior_last_val_mono
                    last_val_step = prior_last_val_step
                    last_save_mono = prior_last_save_mono
                    last_delta_step = prior_last_delta_step
                    last_delta_mono = prior_last_delta_mono
                    raise

            _flush_result = _repair_service_on_demand_flush_request(
                _flush_flag, _terminate_after_flush, _flush_sentinel,
                args, step, _perform_on_demand_flush,
            )
            _ck_name = _flush_result["result"]
            print(
                f"[{phase_name}] ON-DEMAND flush saved {_ck_name} "
                f"at committed step {step}"
            )
            if _flush_result["terminate"]:
                if strict_repair:
                    # The flush action has returned only after save_ckpt has
                    # durably written and verified the checkpoint and its
                    # authoritative pointer.  Publish termination after that
                    # boundary; any publication error is deliberately fatal.
                    _publish_authoritative_run_state("terminated", _ck_name)
                setattr(args, "_agillm_terminate_after_flush", True)
                print(
                    f"[{phase_name}] termination checkpoint complete; "
                    "stopping training loop cleanly",
                    flush=True,
                )
                return step, seen_tok, time.time()
        if _dblock_attempt_rejected:
            continue
        _save_sec = (
            args.save_every_sec if strict_repair
            else get_hot_config().get("save_every_sec", args.save_every_sec)
        )
        try: _save_sec = float(_save_sec)
        except Exception: _save_sec = args.save_every_sec
        if _save_sec > 0:
            now_mono = time.monotonic()
            if now_mono - last_save_mono >= _save_sec:
                _repair_authoritative_validation_before_save("timed")
                ck_name = f"{phase_name}_step{step:08d}{_origin_tag}{time.strftime('_%Y%m%dT%H%MZ', time.gmtime())}{_role_tag}.pt"
                _flush_delta()  # wait for any in-flight delta before full save
                _disk_hygiene(pathlib.Path(args.save_dir), phase_name, args, reason="pre-save")
                _prune_checkpoints(pathlib.Path(args.save_dir), phase_name, max_ckpts)
                _prov = _agillm_provenance.collect(args,
                    step=step, seen_tok=seen_tok, loss=_prov_loss,
                    batch_size=BATCH_REQUESTED, block_size=BLOCK,
                    warmstart_source_path=getattr(args, 'warmstart_from', None) or getattr(args, 'resume', None) or getattr(args, 'resume_delta', None),
                    warmstart_source_provenance=provenance_cache,
                    dataset_provenance=dataset_meta, lane=phase_name or "",)
                save_ckpt(pathlib.Path(args.save_dir) / ck_name, core, ar_h, sat_h, nat_h, opt, scaler,
                          meta=_phase_checkpoint_meta(step, seen_tok),
                          codec=getattr(args, "ckpt_codec", "zstd3"),
                          provenance=_prov)
                _prune_checkpoints(pathlib.Path(args.save_dir), phase_name, max_ckpts)
                last_save_mono = now_mono
                # Prune old deltas after a full save (they're superseded)
                _prune_deltas(pathlib.Path(args.save_dir), phase_name, args.delta_max_keep)
                last_delta_step = step  # reset delta counter after full save
                last_delta_mono = now_mono
        # ── Delta checkpoint (time-based preferred, optional step fallback, weight-only, async) ──
        hot_cfg = {} if strict_repair else get_hot_config()
        _delta_steps = hot_cfg.get("delta_every_steps", args.delta_every_steps)
        try: _delta_steps = int(_delta_steps)
        except Exception: _delta_steps = args.delta_every_steps
        _delta_sec = hot_cfg.get("delta_every_sec", args.delta_every_sec)
        try: _delta_sec = float(_delta_sec)
        except Exception: _delta_sec = args.delta_every_sec
        now_mono = time.monotonic()
        _delta_due_by_steps = _delta_steps > 0 and (step - last_delta_step) >= _delta_steps
        _delta_due_by_time = _delta_sec > 0 and (now_mono - last_delta_mono) >= _delta_sec
        if _delta_due_by_steps or _delta_due_by_time:
            save_root = pathlib.Path(args.save_dir)
            # AGILLM4 production runs on small rented disks. When keep=1, prune
            # old deltas before the async writer creates the next multi-GB file.
            if args.delta_max_keep and args.delta_max_keep > 0:
                _flush_delta()
                _prune_delta_files_to_count(save_root, phase_name, args.delta_max_keep - 1)
            _delta_prov = _agillm_provenance.collect(args,
                step=step, seen_tok=seen_tok, loss=_prov_loss,
                batch_size=BATCH_REQUESTED, block_size=BLOCK,
                warmstart_source_path=getattr(args, 'warmstart_from', None) or getattr(args, 'resume', None) or getattr(args, 'resume_delta', None),
                warmstart_source_provenance=provenance_cache,
                dataset_provenance=dataset_meta, lane=phase_name or "",
                checkpoint_type="delta")
            save_delta(core, ar_h, sat_h, nat_h, step, seen_tok, save_root, phase_name, getattr(args, "delta_codec", "zstd3"), provenance=_delta_prov, origin_tag=_origin_tag, dt_tag=time.strftime("_%Y%m%dT%H%MZ", time.gmtime()), role_tag=_role_tag)
            last_delta_step = step
            last_delta_mono = now_mono
            _hf_fed_log_round(step, seen_tok, loss_value, _role_tag, _origin_tag)
        if args.auto_grow:
            steps_since_last_grow += 1
            if steps_since_last_grow >= args.grow_every_steps:
                steps_since_last_grow = 0
                try:
                    idx = grow_plan.index(BLOCK)
                    if idx + 1 < len(grow_plan):
                        BLOCK = grow_plan[idx + 1]
                        print(f"[{phase_name} Grow] Block -> {BLOCK}")
                        if DEV.type == "cuda": torch.cuda.empty_cache()
                except ValueError:
                    grow_plan = sorted(set(grow_plan + [BLOCK]))
    pbar.close()
    _flush_delta()  # ensure any in-flight delta completes before final save
    if phase_name != "sft":
        _repair_authoritative_validation_before_save("final")
        _prov = _agillm_provenance.collect(args,
            step=step, seen_tok=seen_tok, loss=_prov_loss,
            batch_size=BATCH_REQUESTED, block_size=BLOCK,
            warmstart_source_path=getattr(args, 'warmstart_from', None) or getattr(args, 'resume', None) or getattr(args, 'resume_delta', None),
            warmstart_source_provenance=provenance_cache,
            dataset_provenance=dataset_meta, lane=phase_name or "",)
        _phase_final_name = (
            f"{phase_name}_step{step:08d}{_origin_tag}_final.pt"
            if bool(getattr(args, "repair_mode", False))
            else f"{phase_name}_final.pt"
        )
        save_ckpt(pathlib.Path(args.save_dir) / _phase_final_name, core, ar_h, sat_h, nat_h, opt, scaler,
                  meta=_phase_checkpoint_meta(step, seen_tok),
                  codec=getattr(args, "ckpt_codec", "zstd3"),
                  provenance=_prov)
        if strict_repair:
            # save_ckpt returns only after checkpoint/manifest/pointer
            # finalization.  This final authority write must fail closed.
            _publish_authoritative_run_state("completed", _phase_final_name)
    else:
        print("[sft] Skipping duplicate sft_final.pt; final.pt will contain the SFT result.")
    return step, seen_tok, time.time()



