    dh.add_argument("--config", default=str(DATASET_HOTLOAD_CONFIG_PATH))
    dh.add_argument("--append", action="append", default=[], help="Dataset spec or comma-separated specs to add/update")
    dh.add_argument("--remove", action="append", default=[], help="Dataset source or comma-separated sources to remove")
    dh.add_argument("--set-datasets", action="append", default=None, help="Set the optional datasets field; repeatable")
    dh.add_argument("--min-fraction", action="append", default=[], help="SOURCE_PATTERN=FRACTION; repeatable")
    dh.add_argument("--clear-append", action="store_true")
