    det_export.add_argument("--checkpoint", required=True)
    det_export.add_argument("--output", required=True)
    det_export.add_argument(
        "--training-receipt", default="",
        help="External held-out receipt bound to the exact v2 source checkpoint; "
             "v2 export fails closed without it")
    det_export.add_argument("--codec", default="zstd3")
    if len(sys.argv) == 1:
        sys.argv.extend([
            "supervise",
            "--save_dir", "/workspace/agillm43_production_v14/production_quality_v18_hard_spike_gates/checkpoints_continue400B_from200B",
            "--log", "/workspace/agillm43_production_v14/production_quality_v18_hard_spike_gates/logs/singlefile_intelligence_v25_satvar_pretrain.log",
            "--sleep_sec", "15",
        ])
    args = ap.parse_args()
    if args.cmd == "train":
        _agillm43_training_lock_handle = _orpo_acquire_exclusive_lock(_AGILLM43_TRAINING_LOCK)
        _orpo_refuse_live_trainers()
        train(args)
    elif args.cmd == "infer":
        if not getattr(args, "server", False) and not getattr(args, "prompt", ""):
            ap.error("infer requires --prompt unless --server is set")
        infer_server(args) if getattr(args, "server", False) else infer(args)
    elif args.cmd == "supervise": raise SystemExit(supervise_agillm43(args))
    elif args.cmd == "hotpatch": raise SystemExit(hotpatch_agillm43(args))
    elif args.cmd == "dataset-hotload": raise SystemExit(dataset_hotload_cli(args))
    elif args.cmd == "status": raise SystemExit(_emit_status(Path(args.log), Path(args.save_dir), args.json_output))
    elif args.cmd == "export-detachable-50m":
        raise SystemExit(0 if export_detachable_50m_checkpoint(
            args.checkpoint, args.output, args.codec,
            args.training_receipt) else 1)
    else: raise SystemExit(f"unknown command: {args.cmd}")


