# Folded module: det50_teacher_packet_all_fullstack_overlay
_AGILLM_SF_SOURCE = '"""Emit detachable-50M teacher packets on SAT/NAT fullstack anchors too.\n\nRoot cause (live Vast 47086549): AR fullstack alone stashed teacher-packet.v2.\nFullstack round-robin is AR/SAT/NAT every=3 offsets 0/1/2, while\ntrain_after_commit runs after every mature commit. Exact miss ratio:\nteacher_packet_missing_skips ~= 2 * eligible_teacher_packets.\n\nv27.6.1b emitted hidden-only packets (teacher_logits=None,\nteacher_logits_pre_parent_commit=False). Posthoc v27.6 train_after_commit\nunconditionally requires 3-D stop-grad teacher_logits with\nteacher_logits_pre_parent_commit=True and matching teacher_vocab_size;\notherwise it rewrites schema to bad-logits → teacher_stale.\n\nv27.6.1c attaches pre-commit head logits from the captured fullstack hidden\n(same contract as the AR fullstack emit path) so SAT/NAT packets are accepted.\n"""\nfrom __future__ import annotations\n\nFIX_ID = "v27.16.8-ar-packet-precedence-student-rows-20260906"\nTEACHER_PACKET_SCHEMA = "agillm5.detachable-50m.teacher-packet.v2"\n\n\ndef install(ns):\n    if ns.get("_DET50_TEACHER_PACKET_ALL_FULLSTACK_INSTALLED"):\n        # Allow soft-reload upgrades: if an older fix_id is present, rewrap.\n        prior = ns.get("_DET50_TEACHER_PACKET_ALL_FULLSTACK_FIX_ID")\n        if prior == FIX_ID:\n            return\n    torch = ns["torch"]\n    F = ns.get("F") or torch.nn.functional\n    base_sat = ns.get("_DET50_TEACHER_PACKET_ALL_FULLSTACK_BASE_SAT") or ns[\n        "_dblock_fullstack_sat_anchor"\n    ]\n    base_nat = ns.get("_DET50_TEACHER_PACKET_ALL_FULLSTACK_BASE_NAT") or ns[\n        "_dblock_fullstack_nat_anchor"\n    ]\n    ns["_DET50_TEACHER_PACKET_ALL_FULLSTACK_BASE_SAT"] = base_sat\n    ns["_DET50_TEACHER_PACKET_ALL_FULLSTACK_BASE_NAT"] = base_nat\n\n    def _emit(args, state, step, anchor_ids, anchor_loss_mask, h, representation,\n              attempts_key, head):\n        runtime = getattr(args, "_detachable_50m_runtime", None)\n        if runtime is None or h is None or not torch.is_tensor(h):\n            return False\n        if head is None or getattr(head, "proj", None) is None:\n            return False\n        if not torch.is_tensor(anchor_ids) or anchor_ids.ndim != 2:\n            return False\n        _eos_id, _active_mask_id = (int(v) for v in ns["_nat_boundary_ids"]())\n\n        def _current_clean_packet(prior):\n            prior_ids = prior.get("anchor_ids") if isinstance(prior, dict) else None\n            prior_logits = prior.get("teacher_logits") if isinstance(prior, dict) else None\n            return bool(\n                isinstance(prior, dict)\n                and prior.get("schema") == TEACHER_PACKET_SCHEMA\n                and int(prior.get("expected_dblock_commit_step", -1)) == int(step) + 1\n                and prior.get("teacher_logits_pre_parent_commit") is True\n                and torch.is_tensor(prior_ids)\n                and prior_ids.ndim == 2\n                and not bool(prior_ids.eq(_active_mask_id).any())\n                and torch.is_tensor(prior_logits)\n                and prior_logits.ndim == 3\n            )\n\n        # v27.16.8: the AR full-stack anchor\'s causal packet (ar_h logits, first\n        # student rows) is the canonical teacher for every student mode and it is\n        # emitted earlier in the same mature commit. A SAT/NAT capture must never\n        # replace a current, clean, valid packet; SAT/NAT packets only fill the\n        # steps on which no AR packet exists.\n        if _current_clean_packet(state.get("_det50_teacher_packet")):\n            state["det50_teacher_packet_precedence_kept"] = int(\n                state.get("det50_teacher_packet_precedence_kept", 0)\n            ) + 1\n            return False\n        # Fail closed on SAT/NAT full-stack captures that are not clean token IDs.\n        # In particular the parent NAT anchor forwards masked input IDs; feeding\n        # those back into the detachable NAT objective violates its clean-ID\n        # contract and caused contained RuntimeError/error_skipped events.\n        if bool(anchor_ids.eq(_active_mask_id).any()):\n            state["det50_teacher_packet_reject_masked_ids"] = int(\n                state.get("det50_teacher_packet_reject_masked_ids", 0)\n            ) + 1\n            # No current clean packet exists here (checked above); anything\n            # stale/invalid remains fail-closed and is discarded.\n            state.pop("_det50_teacher_packet", None)\n            return False\n        if tuple(anchor_ids.shape[:2]) != tuple(h.shape[:2]):\n            return False\n        # v27.16.8: emit exactly the rows the student trains on (train_after_commit\n        # caps chosen_ids at schedule["batch"]); the consumer\'s AR contract requires\n        # teacher_logits.size(0) == ids.size(0), and a 16-crop capture otherwise\n        # stashes a ~530 MB logits transient on the GPU for nothing.\n        student_rows = max(1, int((runtime.manifest.get("schedule") or {}).get("batch", 1) or 1))\n        if int(anchor_ids.size(0)) > student_rows:\n            anchor_ids = anchor_ids[:student_rows]\n            h = h[:student_rows]\n            if anchor_loss_mask is not None and torch.is_tensor(anchor_loss_mask):\n                anchor_loss_mask = anchor_loss_mask[:student_rows]\n        teacher_every = max(1, int(getattr(args, "detachable_50m_teacher_every", 1) or 1))\n        # Family attempt counters are incremented inside the base anchors before\n        # return; after a successful run they are the capture index.\n        capture = int(state.get(attempts_key, 0) or 0)\n        if capture <= 0:\n            capture = int(state.get("det50_fullstack_teacher_capture_index", 0)) + 1\n            state["det50_fullstack_teacher_capture_index"] = capture\n        if capture % teacher_every:\n            return False\n        mapping = runtime.peek_mapping(args)\n        loss_mask = None\n        if anchor_loss_mask is not None and torch.is_tensor(anchor_loss_mask):\n            loss_mask = anchor_loss_mask.detach().clone()\n\n        kd_schedule = ((runtime.manifest.get("schedule") or {}).get(\n            "logit_distillation") or {})\n        teacher_logits = None\n        teacher_logit_positions = 0\n        teacher_vocab_size = int(head.proj.weight.size(0))\n        if bool(kd_schedule.get("enabled", True)):\n            teacher_logit_positions = min(\n                max(1, int(kd_schedule.get("max_tokens", 64) or 64)),\n                max(1, int(h.size(1)) - 1),\n            )\n            with torch.no_grad():\n                proj_w = head.proj.weight.detach()\n                proj_b = None if head.proj.bias is None else head.proj.bias.detach()\n                teacher_logits = F.linear(\n                    h[:, :teacher_logit_positions].detach(),\n                    proj_w,\n                    proj_b,\n                ).detach()\n            if teacher_logits.requires_grad or teacher_logits.grad_fn is not None:\n                raise RuntimeError(\n                    "detachable-50m SAT/NAT teacher logits are not stop-gradient"\n                )\n            if (\n                teacher_logits.ndim != 3\n                or int(teacher_logits.size(-1)) != teacher_vocab_size\n            ):\n                raise RuntimeError(\n                    "detachable-50m SAT/NAT teacher logits contract is invalid"\n                )\n\n        packet = {\n            "schema": TEACHER_PACKET_SCHEMA,\n            "direction": "mature_1p1b_to_detachable_50m",\n            "teacher_stop_gradient": True,\n            "teacher_representation": str(representation),\n            "dblock_step_before": int(step),\n            "expected_dblock_commit_step": int(step) + 1,\n            "teacher_capture_index": int(capture),\n            "popup_layer": int(mapping["layer"]),\n            "popup_sublayer": str(mapping["sublayer"]),\n            "popup_mode": str(mapping.get("popup_mode", "ar") or "ar"),\n            "anchor_ids": anchor_ids.detach().clone(),\n            "anchor_loss_mask": loss_mask,\n            "teacher_hidden": h.detach(),\n            "teacher_hidden_shape": [int(v) for v in h.shape],\n            "teacher_logits": teacher_logits,\n            "teacher_logits_shape": (\n                None if teacher_logits is None\n                else [int(v) for v in teacher_logits.shape]\n            ),\n            "teacher_logit_positions": int(teacher_logit_positions),\n            "teacher_logits_dtype": (\n                None if teacher_logits is None else str(teacher_logits.dtype)\n            ),\n            # Posthoc v27.6 rejects unless this is exactly True with valid logits.\n            "teacher_logits_pre_parent_commit": True,\n            "teacher_vocab_size": teacher_vocab_size,\n            "anchor_ids_sha256": ns["_dblock_tensor_sha256"](anchor_ids),\n            "fix_id": FIX_ID,\n        }\n        if packet["teacher_hidden"].requires_grad or packet["teacher_hidden"].grad_fn is not None:\n            raise RuntimeError("detachable-50m SAT/NAT teacher hidden is not stop-gradient")\n        if teacher_logits is None:\n            # Consumer cannot accept hidden-only; refuse to stash a doomed packet.\n            return False\n        state["_det50_teacher_packet"] = packet\n        return True\n\n    def sat_anchor(core, sat_h, scaler, args, ids, state, loss_mask=None,\n                   batch_diagnostics=None):\n        captured = {}\n        real_hidden = ns["_dblock_fullstack_hidden"]\n\n        def hooked(core_, input_ids, attention_mask, args_):\n            h = real_hidden(core_, input_ids, attention_mask, args_)\n            captured["h"] = h\n            captured["ids"] = input_ids\n            return h\n\n        ns["_dblock_fullstack_hidden"] = hooked\n        try:\n            out = base_sat(\n                core, sat_h, scaler, args, ids, state,\n                loss_mask=loss_mask, batch_diagnostics=batch_diagnostics,\n            )\n        finally:\n            ns["_dblock_fullstack_hidden"] = real_hidden\n        if out.get("ran") and "h" in captured:\n            emitted = _emit(\n                args, state, int(state.get("step", 0)),\n                captured["ids"], None, captured["h"],\n                "mature_fullstack_sat_final_hidden",\n                "fullstack_sat_anchor_attempts",\n                sat_h,\n            )\n            if emitted:\n                state["det50_teacher_packet_emits_sat"] = int(\n                    state.get("det50_teacher_packet_emits_sat", 0)\n                ) + 1\n        return out\n\n    def nat_anchor(core, nat_h, scaler, args, ids, state, loss_mask=None):\n        captured = {}\n        real_hidden = ns["_dblock_fullstack_hidden"]\n\n        def hooked(core_, input_ids, attention_mask, args_):\n            h = real_hidden(core_, input_ids, attention_mask, args_)\n            captured["h"] = h\n            captured["ids"] = input_ids\n            return h\n\n        ns["_dblock_fullstack_hidden"] = hooked\n        try:\n            out = base_nat(core, nat_h, scaler, args, ids, state, loss_mask=loss_mask)\n        finally:\n            ns["_dblock_fullstack_hidden"] = real_hidden\n        if out.get("ran") and "h" in captured:\n            emitted = _emit(\n                args, state, int(state.get("step", 0)),\n                captured["ids"], None, captured["h"],\n                "mature_fullstack_nat_final_hidden",\n                "fullstack_nat_anchor_attempts",\n                nat_h,\n            )\n            if emitted:\n                state["det50_teacher_packet_emits_nat"] = int(\n                    state.get("det50_teacher_packet_emits_nat", 0)\n                ) + 1\n        return out\n\n    ns["_dblock_fullstack_sat_anchor"] = sat_anchor\n    ns["_dblock_fullstack_nat_anchor"] = nat_anchor\n    ns["_DET50_TEACHER_PACKET_ALL_FULLSTACK_INSTALLED"] = True\n    ns["_DET50_TEACHER_PACKET_ALL_FULLSTACK_FIX_ID"] = FIX_ID\n    print("[detachable-50m-teacher-packet-all-fullstack] installed " + FIX_ID, flush=True)\n'
_agillm_sf_module = _agillm_sf_types.ModuleType('det50_teacher_packet_all_fullstack_overlay')
_agillm_sf_module.__file__ = __file__ + '#det50_teacher_packet_all_fullstack_overlay.py'
