AGILLM_SINGLEFILE_MANIFEST = {'schema': 'agillm.live-singlefile.v1', 'source_sha256': '6d703a8a4241607a15122a202bf8ce0f5b0949598c99d81c10ec70d039b076c7', 'resource_sha256': {'sat_gate_v27_13_seed.npz': '9262ea3fc5cc7e4d3dc5d14aac125bd5459ce314cac05c3c11de45224e14dd94'}, 'modules': {'det50_multimode_v26_overlay': {'source_sha256': '5e702e37aaaa9e76061a15ce3fe6a44e67d54d0b0aaa2ca34e6d861595ddcf40', 'embedded_sha256': '954d64189a52d79d6e9d2f2d08ea8ee981c92fd271ed8ea067d889d303e48769'}, 'det50_posthoc_matryoshka_v27_6_overlay': {'source_sha256': '2f8e4687c7445b79803aa340c2575812bfa875e2573f75704c008f52cc971bda', 'embedded_sha256': '2f8e4687c7445b79803aa340c2575812bfa875e2573f75704c008f52cc971bda'}, 'det50_sat_gate_v27_13_overlay': {'source_sha256': 'ef9f353d529a36e727f802d8d55420418954cf62116666f7ccd7c63a686ef630', 'embedded_sha256': '2b1d128458e0e6add0e599a6583509443dba959ae5a811a309df59a5c9e762a3'}, 'det50_teacher_packet_all_fullstack_overlay': {'source_sha256': '167354827aa9c3b5035e000ce5ee0924c478044e155a0818265e509d4ff7e2d6', 'embedded_sha256': '167354827aa9c3b5035e000ce5ee0924c478044e155a0818265e509d4ff7e2d6'}}, 'behavior_change': 'Only seed resource I/O changes from sibling file to embedded bytes; training code and install order preserved.'}
