# --- v27.15 detachable-50M SAT gate neutral recalibration overlay ---
_AGILLM_SF_SOURCE = '"""v27.15 detachable-50M SAT gate state recalibration.\n\nv27.14 corrected the loss from inverse-frequency weighted CE to unweighted CE,\nbut intentionally preserved the already saturated 514-parameter gate and its\noptimizer moments. This additive migration resets only that gate to neutral zero\nlogits, clears only its optimizer state, resets only gate-era calibration\ntelemetry, and leaves the 50M student core, parent, and lifetime mode clocks\nuntouched. The repaired gate must then re-earn the fresh v27.15 qualification.\n"""\nfrom __future__ import annotations\n\nimport copy\nimport hashlib\nimport json\nimport math\nimport os\nimport re\n\nEXTENSION_KEY = "agillm5_detachable_50m_sat_gate_recalibration_v27_15"\nEXTENSION_SCHEMA = "agillm5.detachable-50m.sat-gate-recalibration-v27.15.v1"\nCOUNTERS_KEY = "sat_gate_recalibration_v27_15"\nCOUNTERS_SCHEMA = "agillm5.detachable-50m.sat-gate-recalibration-v27.15-counters.v1"\nMIGRATION_SCHEMA = "agillm5.detachable-50m.sat-gate-recalibration-v27.15-migration.v1"\nFIX_ID = "v27.15-det50-sat-gate-neutral-reset-unweighted-ce-20260912"\nSOURCE_FIX_ID = "v27.14-det50-sat-gate-calibrated-ce-no-reweighting-20260912"\nSOURCE_CHECKPOINT_SHA_ENV = "AGILLM43_DETACHABLE50M_POST_FIX_START_CHECKPOINT_SHA256"\nQUALIFICATION_KEY = "agillm5_detachable_50m_post_fix_qualification"\nGATE_PARAMETERS = 514\n\n\ndef install(ns):\n    if ns.get("_DET50_SAT_GATE_RECALIBRATION_V27_15_INSTALLED"):\n        return\n\n    torch = ns["torch"]\n    nn = ns["nn"]\n    BaseRuntime = ns["Detachable50MRuntime"]\n    base_manifest = ns["_det50_manifest"]\n    base_validate_manifest = ns["_det50_validate_manifest"]\n\n    def _gate_state(runtime):\n        return {\n            "export_sat_gate.weight": runtime.bridge.export_sat_gate.weight.detach(),\n            "export_sat_gate.bias": runtime.bridge.export_sat_gate.bias.detach(),\n        }\n\n    def _empty_gate_counters(bins, threshold):\n        return {\n            "blocks": 0, "stride1_labels": 0, "stride2_labels": 0,\n            "predicted_stride1": 0, "predicted_stride2": 0,\n            "correct": 0, "false_accepts": 0, "false_rejects": 0,\n            "brier_sum": 0.0, "probability_stride2_sum": 0.0,\n            "calibration_bins": [\n                {"count": 0, "probability_sum": 0.0, "label_sum": 0}\n                for _ in range(int(bins))\n            ],\n            "last_class_weights": [1.0, 1.0],\n            "last_threshold": float(threshold),\n        }\n\n    def _optimizer_state_sha256(optimizer, parameters):\n        digest = hashlib.sha256(b"agillm5.det50.optimizer-subset.v1\\\\0")\n        for position, parameter in enumerate(parameters):\n            digest.update(position.to_bytes(8, "big"))\n            state = optimizer.state.get(parameter, {})\n            if not isinstance(state, dict):\n                raise RuntimeError("detachable-50m optimizer state is malformed")\n            for key in sorted(state, key=str):\n                digest.update(str(key).encode("utf-8") + b"\\\\0")\n                value = state[key]\n                if torch.is_tensor(value):\n                    tensor = value.detach().to(device="cpu").contiguous()\n                    digest.update(str(tensor.dtype).encode("ascii") + b"\\\\0")\n                    digest.update(json.dumps(list(tensor.shape), separators=(",", ":")).encode("ascii"))\n                    digest.update(b"\\\\0")\n                    digest.update(tensor.view(torch.uint8).numpy().tobytes(order="C"))\n                elif isinstance(value, (bool, int, float, str)):\n                    digest.update(json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8"))\n                elif value is None:\n                    digest.update(b"null")\n                else:\n                    raise RuntimeError("detachable-50m optimizer state contains unsupported value")\n                digest.update(b"\\\\0")\n        return digest.hexdigest()\n\n    def extension_contract(schedule):\n        mm = schedule["multimode"]\n        value = {\n            "schema": EXTENSION_SCHEMA,\n            "fix_id": FIX_ID,\n            "source_fix_id": SOURCE_FIX_ID,\n            "method": "deterministic_zero_logits_then_unweighted_ce_relearn",\n            "gate_parameters": GATE_PARAMETERS,\n            "gate_initialization": "zeros_weight_and_bias",\n            "gate_optimizer_state_reset": True,\n            "student_core_weights_reset": False,\n            "student_core_optimizer_state_preserved": True,\n            "parent_weights_reset": False,\n            "sat_variable_class_reweighting": "disabled_equal_weights_1_1",\n            "sat_variable_calibration_term": float(mm["sat_variable_calibration_weight"]),\n            "sat_variable_stride2_threshold": float(mm["sat_variable_stride2_threshold"]),\n            "gate_telemetry_epoch": FIX_ID,\n            "release_policy": "fresh_v27_15_qualification_plus_heldout_gate_receipt",\n        }\n        value["contract_sha256"] = ns["_det50_json_sha256"](value)\n        return value\n\n    def validate_extension(value, schedule):\n        expected = extension_contract(schedule)\n        if value != expected:\n            raise RuntimeError("detachable-50m v27.15 gate recalibration contract changed")\n        return copy.deepcopy(value)\n\n    def manifest(optimizer_name, alibi_mode, alibi_scale, schedule):\n        value = base_manifest(optimizer_name, alibi_mode, alibi_scale, schedule)\n        value[EXTENSION_KEY] = extension_contract(value["schedule"])\n        value.pop("manifest_sha256", None)\n        value["manifest_sha256"] = ns["_det50_json_sha256"](value)\n        return value\n\n    def validate_manifest(value):\n        validated = base_validate_manifest(value)\n        extension = validated.get(EXTENSION_KEY)\n        if extension is not None:\n            validated[EXTENSION_KEY] = validate_extension(extension, validated["schedule"])\n        return validated\n\n    def _validate_counter(value):\n        if (not isinstance(value, dict)\n                or value.get("schema") != COUNTERS_SCHEMA\n                or value.get("fix_id") != FIX_ID\n                or value.get("source_fix_id") != SOURCE_FIX_ID\n                or value.get("gate_initialization") != "deterministic_zero_logits"\n                or value.get("class_weights") != [1.0, 1.0]):\n            raise RuntimeError("detachable-50m v27.15 gate recalibration counters changed")\n        for key in ("activation_parent_step", "activation_popup_commit",\n                    "sat_fixed_gate_commits", "sat_variable_gate_commits",\n                    "gate_optimizer_states_cleared"):\n            if type(value.get(key)) is not int or int(value[key]) < 0:\n                raise RuntimeError(f"invalid detachable-50m v27.15 counter {key}")\n        for key in ("activation_source_checkpoint_sha256", "old_gate_state_sha256",\n                    "reset_gate_state_sha256", "student_core_state_sha256",\n                    "student_core_optimizer_state_sha256"):\n            if not re.fullmatch(r"[0-9a-f]{64}", str(value.get(key) or "")):\n                raise RuntimeError(f"invalid detachable-50m v27.15 digest {key}")\n        expected = str(value.get("last_checkpoint_gate_state_sha256") or "")\n        if expected and not re.fullmatch(r"[0-9a-f]{64}", expected):\n            raise RuntimeError("invalid detachable-50m v27.15 last gate digest")\n        return value\n\n    class GateRecalibrationV2715Runtime(BaseRuntime):\n        def restore(self, checkpoint):\n            raw_manifest = checkpoint.get(ns["_DET50_MANIFEST_KEY"])\n            source_validated = base_validate_manifest(raw_manifest)\n            source_has_extension = EXTENSION_KEY in source_validated\n            raw_counters = checkpoint.get(ns["_DET50_COUNTERS_KEY"])\n            raw_qualification = (raw_counters or {}).get(QUALIFICATION_KEY) if isinstance(raw_counters, dict) else None\n            source_fix_id = str((raw_qualification or {}).get("fix_id") or "") if isinstance(raw_qualification, dict) else ""\n            if source_has_extension:\n                validate_extension(source_validated[EXTENSION_KEY], source_validated["schedule"])\n            elif source_fix_id != SOURCE_FIX_ID:\n                raise RuntimeError(\n                    "detachable-50m v27.15 migration requires exact v27.14 qualification source")\n\n            super().restore(checkpoint)\n\n            if not source_has_extension:\n                source_checkpoint_sha = str(os.environ.get(SOURCE_CHECKPOINT_SHA_ENV, "") or "")\n                if not re.fullmatch(r"[0-9a-f]{64}", source_checkpoint_sha):\n                    raise RuntimeError("detachable-50m v27.15 migration requires exact " + SOURCE_CHECKPOINT_SHA_ENV)\n                qualification = self.counters.get(QUALIFICATION_KEY) or {}\n                activation = qualification.get("activation_checkpoint_binding") or {}\n                if (qualification.get("fix_id") != FIX_ID\n                        or activation.get("source_checkpoint_sha256") != source_checkpoint_sha):\n                    raise RuntimeError("detachable-50m v27.15 fresh qualification binding mismatch")\n\n                gate_parameters = list(self.bridge.export_sat_gate.parameters())\n                if sum(int(p.numel()) for p in gate_parameters) != GATE_PARAMETERS:\n                    raise RuntimeError("detachable-50m v27.15 gate parameter count changed")\n                group0 = list(self.optimizer.param_groups[0]["params"])\n                group1 = list(self.optimizer.param_groups[1]["params"])\n                if (len(group1) != 2 or {id(p) for p in group1} != {id(p) for p in gate_parameters}\n                        or {id(p) for p in group0} & {id(p) for p in gate_parameters}):\n                    raise RuntimeError("detachable-50m v27.15 optimizer gate isolation changed")\n                core_optimizer_before = _optimizer_state_sha256(self.optimizer, group0)\n                old_gate_sha = ns["_det50_state_dict_sha256"](_gate_state(self))\n                old_gate_telemetry = copy.deepcopy(self.counters.get("sat_variable_gate"))\n\n                with torch.no_grad():\n                    nn.init.zeros_(self.bridge.export_sat_gate.weight)\n                    nn.init.zeros_(self.bridge.export_sat_gate.bias)\n                cleared = 0\n                for parameter in gate_parameters:\n                    parameter.grad = None\n                    if parameter in self.optimizer.state:\n                        del self.optimizer.state[parameter]\n                        cleared += 1\n                if any(parameter in self.optimizer.state for parameter in gate_parameters):\n                    raise RuntimeError("detachable-50m v27.15 gate optimizer state survived reset")\n                core_optimizer_after = _optimizer_state_sha256(self.optimizer, group0)\n                if core_optimizer_before != core_optimizer_after:\n                    raise RuntimeError("detachable-50m v27.15 changed student-core optimizer state")\n\n                reset_gate_sha = ns["_det50_state_dict_sha256"](_gate_state(self))\n                model_sha = ns["_det50_state_dict_sha256"](self.model.state_dict())\n                if model_sha != activation.get("model_state_sha256"):\n                    raise RuntimeError("detachable-50m v27.15 changed student-core weights")\n                if any(bool(torch.count_nonzero(p.detach()).item()) for p in gate_parameters):\n                    raise RuntimeError("detachable-50m v27.15 neutral gate is not exactly zero")\n\n                mm = self.manifest["schedule"]["multimode"]\n                bins = int(mm["sat_variable_calibration_bins"])\n                threshold = float(mm["sat_variable_stride2_threshold"])\n                self.counters["sat_variable_gate"] = _empty_gate_counters(bins, threshold)\n                counter = {\n                    "schema": COUNTERS_SCHEMA,\n                    "fix_id": FIX_ID,\n                    "source_fix_id": SOURCE_FIX_ID,\n                    "activation_source_checkpoint_sha256": source_checkpoint_sha,\n                    "activation_parent_step": int(self.counters.get("last_parent_step", 0)),\n                    "activation_popup_commit": int(self.counters.get("popup_commits", 0)),\n                    "gate_initialization": "deterministic_zero_logits",\n                    "gate_parameters": GATE_PARAMETERS,\n                    "gate_optimizer_states_cleared": int(cleared),\n                    "class_weights": [1.0, 1.0],\n                    "old_gate_state_sha256": old_gate_sha,\n                    "reset_gate_state_sha256": reset_gate_sha,\n                    "student_core_state_sha256": model_sha,\n                    "student_core_optimizer_state_sha256": core_optimizer_after,\n                    "pre_reset_gate_telemetry": old_gate_telemetry,\n                    "sat_fixed_gate_commits": 0,\n                    "sat_variable_gate_commits": 0,\n                    "last_checkpoint_gate_state_sha256": "",\n                }\n                self.counters[COUNTERS_KEY] = counter\n                migration = self.counters.setdefault("resume_migration", {})\n                migration["sat_gate_recalibration_v27_15"] = {\n                    "schema": MIGRATION_SCHEMA,\n                    "from_fix_id": SOURCE_FIX_ID,\n                    "to_fix_id": FIX_ID,\n                    "source_checkpoint_sha256": source_checkpoint_sha,\n                    "old_gate_state_sha256": old_gate_sha,\n                    "reset_gate_state_sha256": reset_gate_sha,\n                    "gate_initialization": "deterministic_zero_logits",\n                    "gate_optimizer_states_cleared": int(cleared),\n                    "class_weights": [1.0, 1.0],\n                    "student_core_weights_reset": False,\n                    "student_core_optimizer_state_preserved": True,\n                    "parent_weights_reset": False,\n                    "historical_gate_telemetry_preserved_in": COUNTERS_KEY + ".pre_reset_gate_telemetry",\n                    "fresh_gate_telemetry_reset": True,\n                }\n            else:\n                counter = _validate_counter(self.counters.get(COUNTERS_KEY))\n                expected = str(counter.get("last_checkpoint_gate_state_sha256") or "")\n                observed = ns["_det50_state_dict_sha256"](_gate_state(self))\n                if expected and observed != expected:\n                    raise RuntimeError("detachable-50m v27.15 restored gate state digest mismatch")\n\n            schedule = ns["_det50_validate_schedule"](self.manifest["schedule"])\n            parent = self.manifest["parent_contract"]\n            self.manifest = manifest(\n                self.manifest["optimizer"]["name"], parent["alibi_mode"],\n                parent["alibi_scale"], schedule)\n            self.resume_migration = copy.deepcopy(self.counters.get("resume_migration"))\n            self.restored = True\n            print("[detachable-50m-sat-gate-v27.15-contract] " + json.dumps({\n                "schema": EXTENSION_SCHEMA, "fix_id": FIX_ID,\n                "source_fix_id": SOURCE_FIX_ID, "gate_parameters": GATE_PARAMETERS,\n                "gate_initialization": "deterministic_zero_logits",\n                "gate_optimizer_state_reset": True, "class_weights": [1.0, 1.0],\n                "student_core_weights_reset": False,\n                "student_core_optimizer_state_preserved": True,\n                "parent_weights_reset": False,\n            }, sort_keys=True, separators=(",", ":")), flush=True)\n\n        def _commit_mode_metrics(self, mode, objective):\n            super()._commit_mode_metrics(mode, objective)\n            if mode in {"sat_fixed", "sat_variable"} and objective.get("gate_info"):\n                counter = _validate_counter(self.counters.get(COUNTERS_KEY))\n                counter[f"{mode}_gate_commits"] += 1\n\n        def checkpoint_payload(self):\n            counter = _validate_counter(self.counters.get(COUNTERS_KEY))\n            counter["last_checkpoint_gate_state_sha256"] = ns["_det50_state_dict_sha256"](\n                _gate_state(self))\n            payload = super().checkpoint_payload()\n            payload[EXTENSION_KEY] = copy.deepcopy(counter)\n            return payload\n\n    ns["_det50_manifest_pre_sat_gate_recalibration_v27_15"] = base_manifest\n    ns["_det50_validate_manifest_pre_sat_gate_recalibration_v27_15"] = base_validate_manifest\n    ns["_det50_manifest"] = manifest\n    ns["_det50_validate_manifest"] = validate_manifest\n    ns["_DET50_SAT_GATE_RECALIBRATION_V27_15_KEY"] = EXTENSION_KEY\n    ns["_DET50_SAT_GATE_RECALIBRATION_V27_15_SCHEMA"] = EXTENSION_SCHEMA\n    ns["Detachable50MRuntime"] = GateRecalibrationV2715Runtime\n    ns["_DET50_SAT_GATE_RECALIBRATION_V27_15_INSTALLED"] = True\n'
_AGILLM_SF_MOD = __import__('types').ModuleType('det50_sat_gate_recalibration_v27_15_overlay')
_AGILLM_SF_MOD.__file__ = __file__ + '#det50_sat_gate_recalibration_v27_15_overlay'
exec(compile(_AGILLM_SF_SOURCE, _AGILLM_SF_MOD.__file__, 'exec'), _AGILLM_SF_MOD.__dict__)
_AGILLM_SF_MOD.install(globals())
del _AGILLM_SF_MOD, _AGILLM_SF_SOURCE

if __name__ == "__main__":
    main()

